*{
  box-sizing:border-box;
}

.reports-title-row,
.reports-header-actions,
.reports-screen-flow,
.reports-panel,
.reports-kpi-card {
  min-width: 0;
}

.reports-title-row h2 {
  font-size: var(--font-size-xl, 22px);
  line-height: 1.15;
}

.reports-overview-panel,
.reports-quick-panel,
.reports-summary-panel {
  grid-column: 1 / -1;
}

.reports-kpi-slide {
  grid-column: span 3;
}

.reports-chart-panel {
  grid-column: span 8;
}

.reports-category-panel {
  grid-column: span 4;
}

.reports-kpi-slide .reports-kpi-card {
  width: 100%;
  height: 100%;
  min-height: 76px;
}

.reports-panel-header {
  flex-wrap: wrap;
}

.reports-panel-header > * {
  min-width: 0;
}

.reports-panel-header .btn {
  width: auto;
  max-width: 100%;
  white-space: nowrap;
}

.reports-quick-grid {
  grid-template-columns: repeat(5, minmax(0, 1fr));
}

@media (max-width: 1024px) {
  .reports-kpi-slide {
    grid-column: span 6;
  }

  .reports-chart-panel,
  .reports-category-panel {
    grid-column: 1 / -1;
  }

  .reports-quick-grid {
    grid-template-columns: repeat(3, minmax(0, 1fr));
  }
}

@media (max-width: 640px) {

  .reports-title-row h2 {
    font-size: 18px;
  }

  .reports-screen-flow > .reports-panel,
  .reports-kpi-slide,
  .reports-chart-panel,
  .reports-category-panel,
  .reports-overview-panel,
  .reports-quick-panel,
  .reports-summary-panel {
    grid-column: 1;
    width: 100%;
    height: auto !important;
    min-height: 0;
    overflow: hidden !important;
  }

  .reports-period-tabs {
    width: 100%;
    overflow-x: auto;
    overscroll-behavior-x: contain;
    scroll-snap-type: x proximity;
  }

  .reports-period-chip {
    flex: 0 0 auto;
    scroll-snap-align: start;
  }

  .reports-kpi-slide .reports-kpi-card {
    min-height: 64px !important;
  }

  .reports-quick-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr)) !important;
  }

  .reports-panel-header {
    align-items: center;
    margin-bottom: 8px;
  }

  .reports-panel-header h3 {
    font-size: 14px;
  }

  .reports-panel-header strong {
    font-size: 19px;
  }

  .reports-panel-header .btn {
    min-height: 34px;
    padding: 6px 9px;
    font-size: 11px;
  }

  .reports-period-row {
    grid-template-columns: minmax(0, 1fr) auto;
  }
}

html,
body{
  font-size:16px;
  width:100%;
  max-width:100%;
  overflow-x:hidden;
  overscroll-behavior-x:none;
  overscroll-behavior-y:contain;
}

body.mobile-mode,
body[data-ui-profile="android_apk"],
body[data-ui-profile="web_pwa"]{
  overscroll-behavior:none;
  overscroll-behavior-x:none;
  touch-action:pan-y;
}

#app,
.mobile-home,
.mobile-panel,
.mobile-panel-content,
.app-content{
  width:100%;
  max-width:100%;
  overflow-x:hidden;
  overscroll-behavior-x:none;
  touch-action:pan-y;
}

