.app-shell{
  position:relative;
  width:100%;
  min-height:var(--app-viewport-height, 100dvh);
  isolation:isolate;
  background:var(--bg-primary);
  color:var(--text-primary);
}

/* Phase 1 responsive structure. The document owns vertical scrolling; panels
   only scroll internally when they are overlays. */
html,
body,
#app-shell{
  min-height:100%;
}

body{
  margin:0;
  scrollbar-gutter:stable;
}

.app-shell,
.app-content-shell{
  min-height:100vh;
  min-height:100dvh;
}

.app-content-shell,
#app,
.desktop-shell,
.desktop-main,
.page-container,
.card,
.grid-item,
.desktop-dashboard-grid > *,
.dashboard-kpis > *{
  min-width:0;
}

#app{
  width:min(100%, var(--layout-content-max));
  margin-inline:auto;
  padding-inline:var(--layout-page-padding);
}

.desktop-shell{
  width:100%;
  max-width:var(--layout-content-max);
  margin-inline:auto;
}

.desktop-grid,
.dashboard-kpis,
.desktop-dashboard-metrics{
  grid-template-columns:repeat(auto-fit, minmax(min(100%, 13.5rem), 1fr));
}

.app-modal-stage,
.modal-card,
.side-drawer,
.bottom-sheet{
  max-width:calc(100vw - (var(--layout-page-padding) * 2));
  max-height:calc(100vh - (var(--layout-page-padding) * 2));
  max-height:calc(100dvh - (var(--layout-page-padding) * 2));
}

.modal-card,
.side-drawer,
.bottom-sheet,
.form-scroll-area{
  overscroll-behavior:contain;
  scroll-padding-bottom:8rem;
}

input,
select,
textarea,
.form-field{
  scroll-margin-block:6rem 8rem;
}

@media(max-width:767px){
  #app{
    padding-bottom:calc(var(--layout-bottom-nav-height) + var(--safe-area-bottom-offset) + var(--keyboard-inset) + 1rem);
  }

  .mobile-bottom-nav{
    min-height:calc(var(--layout-bottom-nav-height) + var(--safe-area-bottom-offset));
    padding-bottom:max(7px, var(--safe-area-bottom-offset));
    z-index:var(--z-sticky, 120);
  }

  button,
  [role="button"],
  .mobile-bottom-nav-button{
    min-height:var(--touch-target-min);
  }

  .desktop-dashboard-span-3,
  .desktop-dashboard-span-4,
  .desktop-dashboard-span-6,
  .desktop-dashboard-span-8,
  .desktop-dashboard-span-12{
    grid-column:1 / -1;
  }
}

/* Calculator headings not repeated by the final mobile contrast authority. */
@media(max-width:767px){
  body.mobile-mode .mobile-panel-calculator :is(h1,h2,h3,strong,label,.calc-section-title,.calc-option-header span){color:#14212b !important}
}

.calc-time-card,
.calc-extra-fee-card{
  min-height:96px;
}

.calc-time-split{
  display:grid;
  grid-template-columns:minmax(0, 1fr) auto minmax(0, 1fr);
  align-items:center;
  gap:8px;
}

.calc-time-split > label{
  min-width:0;
  display:grid;
  gap:3px;
}

.calc-time-split input{
  width:100%;
  min-width:0;
  height:48px;
  padding:6px 8px;
  text-align:center;
  font-size:24px;
  font-weight:800;
}

.calc-time-split b{
  font-size:28px;
  line-height:1;
  pointer-events:none;
}

.calc-time-split small{
  color:var(--text-muted);
  text-align:center;
  font-size:10px;
}

.calc-extra-fee-head{
  display:flex;
  align-items:center;
  justify-content:space-between;
  gap:8px;
}

.calc-custom-fee-toggle{
  display:inline-flex;
  align-items:center;
  gap:5px;
  min-height:30px;
  cursor:pointer;
}

.calc-custom-fee-toggle input{
  width:18px;
  height:18px;
  margin:0;
}

.calc-extra-fee-control{
  display:grid;
  grid-template-columns:minmax(0, 1fr) 78px;
  align-items:center;
  gap:10px;
}

.calc-extra-fee-control > input[type="range"]{
  width:100%;
  min-width:0;
  accent-color:var(--primary);
}

.calc-extra-fee-control > label{
  position:relative;
  display:block;
}

.calc-extra-fee-control > label input{
  width:100%;
  min-width:0;
  height:44px;
  padding:6px 8px 6px 28px;
  text-align:right;
  font-weight:800;
}

.calc-extra-fee-control > label i{
  position:absolute;
  left:8px;
  top:50%;
  z-index:1;
  transform:translateY(-50%);
  color:var(--text-muted);
  font-style:normal;
  pointer-events:none;
}

@media(max-width:380px){
  .calc-modern-grid{
    grid-template-columns:minmax(0, 1fr) !important;
  }

  .calc-weight-card{
    grid-column:auto !important;
  }
}

/* Mobile navigation renders the home shell and the selected panel together.
   Only one routed screen may participate in layout at a time. */
body.mobile-mode:has(#app > .mobile-panel) #app > .mobile-home{
  display:none !important;
}

body.mobile-mode:has(#app > .mobile-panel) #app{
  min-height:100vh;
  min-height:100dvh;
}

.search-autocomplete-host{
  position:relative;
  overflow:visible !important;
}

.search-autocomplete-panel{
  position:absolute;
  top:calc(100% + 6px);
  left:0;
  right:0;
  z-index:var(--z-dropdown, 400);
  min-width:min(22rem, calc(100vw - 1.5rem));
  max-height:min(22rem, 50dvh);
  overflow-y:auto;
  padding:6px;
  border:1px solid var(--border-primary);
  border-radius:var(--radius-md);
  background:var(--color-modal, var(--surface));
  box-shadow:var(--shadow-lg);
  backdrop-filter:blur(14px);
}

.search-autocomplete-panel button{
  width:100%;
  min-height:var(--touch-target-min);
  display:grid;
  gap:3px;
  padding:9px 10px;
  color:var(--text-primary);
  text-align:left;
  border:0;
  border-radius:var(--radius-sm, 8px);
  background:transparent;
}

.search-autocomplete-panel button:hover,
.search-autocomplete-panel button:focus-visible{
  background:var(--surface-hover);
  outline:none;
}

.search-autocomplete-panel strong,
.search-autocomplete-panel small{
  overflow:hidden;
  text-overflow:ellipsis;
  white-space:nowrap;
}

.search-autocomplete-panel small{
  color:var(--text-muted);
}

@media(max-width:520px){
  .search-autocomplete-panel{
    position:fixed;
    top:auto;
    left:var(--layout-page-padding);
    right:var(--layout-page-padding);
    bottom:calc(var(--layout-bottom-nav-height) + var(--safe-area-bottom-offset) + .75rem);
    min-width:0;
    max-height:min(18rem, 44dvh);
  }
}

.app-content-shell{
  position:relative;
  z-index:var(--z-base);
  width:100%;
  max-width:100%;
  min-height:var(--app-viewport-height, 100dvh);
  overflow-x:hidden;
  overscroll-behavior-x:none;
  touch-action:pan-y;
}

.app-shell-slot:empty,
.app-layer:empty{
  display:none;
}

.app-sidebar-slot,
.app-topbar-slot{
  display:none;
}

.app-layer{
  position:fixed;
  inset:0;
  pointer-events:none;
}

.app-layer > *{
  pointer-events:auto;
}

.app-modal-layer.is-active{
  display:flex;
  align-items:center;
  justify-content:center;
  padding:var(--space-lg);
}

.app-modal-stage{
  width:min(100%, var(--size-modal-width));
  max-height:calc(100dvh - (var(--space-lg) * 2));
  display:grid;
  place-items:center;
  pointer-events:auto;
}

.app-modal-stage.app-modal-size-wide{
  width:min(100%, 760px);
}

.app-drawer-layer.is-active{
  display:block;
}

.app-drawer-layer .side-drawer-backdrop{
  position:absolute;
  inset:0;
  z-index:auto;
  background:transparent;
  pointer-events:none;
}

.app-drawer-layer .side-drawer{
  pointer-events:auto;
}

.app-overlay-scrim{
  position:absolute;
  inset:0;
  background:var(--color-overlay);
  pointer-events:auto;
}

.app-overlay-layer{
  z-index:var(--z-overlay);
}

.app-drawer-layer{
  z-index:var(--z-drawer);
}

.app-modal-layer{
