body.mobile-mode .order-mini-summary strong,
body[data-ui-profile="android_apk"] .order-mini-summary strong,
body[data-ui-profile="web_pwa"].mobile-mode .order-mini-summary strong{
  font-size:15px;
  line-height:1.12;
}

body.mobile-mode .order-mini-summary span,
body[data-ui-profile="android_apk"] .order-mini-summary span,
body[data-ui-profile="web_pwa"].mobile-mode .order-mini-summary span{
  font-size:11px;
  line-height:1.16;
}

body.mobile-mode .order-step-panel,
body[data-ui-profile="android_apk"] .order-step-panel,
body[data-ui-profile="web_pwa"].mobile-mode .order-step-panel{
  gap:8px;
  padding:9px;
  border-radius:16px;
}

body.mobile-mode .order-step-title,
body[data-ui-profile="android_apk"] .order-step-title,
body[data-ui-profile="web_pwa"].mobile-mode .order-step-title{
  gap:7px;
}

body.mobile-mode .order-step-title > span,
body[data-ui-profile="android_apk"] .order-step-title > span,
body[data-ui-profile="web_pwa"].mobile-mode .order-step-title > span{
  width:22px;
  height:22px;
  font-size:11px;
}

body.mobile-mode .order-step-title strong,
body[data-ui-profile="android_apk"] .order-step-title strong,
body[data-ui-profile="web_pwa"].mobile-mode .order-step-title strong{
  font-size:16px;
  line-height:1.1;
}

body.mobile-mode .order-summary-grid,
body.mobile-mode .order-item-edit-grid,
body[data-ui-profile="android_apk"] .order-summary-grid,
body[data-ui-profile="android_apk"] .order-item-edit-grid,
body[data-ui-profile="web_pwa"].mobile-mode .order-summary-grid,
body[data-ui-profile="web_pwa"].mobile-mode .order-item-edit-grid{
  gap:8px;
}

body{
  margin:0;
  font-family:Arial, Helvetica, sans-serif;
  font-size:var(--base-font-size);
  background:var(--app-body-background,
    radial-gradient(circle at 18% 0%, rgba(13,189,184,.16), transparent 33%),
    radial-gradient(circle at 88% 12%, rgba(255,148,28,.10), transparent 30%),
    linear-gradient(180deg, #0b1620 0%, var(--bg) 46%, #050a0f 100%));
  color:var(--text);
  line-height:1.5;
}

@keyframes softViewIn{
  from{
    opacity:.72;
    transform:translateY(5px);
    filter:blur(1.5px);
  }
  to{
    opacity:1;
    transform:translateY(0);
    filter:blur(0);
  }
}

@keyframes softValuePulse{
  0%{
    transform:scale(.985);
    color:#bffcf8;
  }
  55%{
    transform:scale(1.018);
    color:#45e0aa;
  }
  100%{
    transform:scale(1);
  }
}

@keyframes premiumScreenIn{
  from{
    opacity:0;
    transform:translate3d(0, 14px, 0) scale(.985);
  }
  to{
    opacity:1;
    transform:translate3d(0, 0, 0) scale(1);
  }
}

@keyframes premiumScreenBackIn{
  from{
    opacity:0;
    transform:translate3d(0, -8px, 0) scale(.99);
  }
  to{
    opacity:1;
    transform:translate3d(0, 0, 0) scale(1);
  }
}

@keyframes premiumStaggerIn{
  from{
    opacity:0;
    transform:translate3d(0, 10px, 0) scale(.985);
  }
  to{
    opacity:1;
    transform:translate3d(0, 0, 0) scale(1);
  }
}

@keyframes premiumLineDraw{
  from{ stroke-dashoffset:1; opacity:.35; }
  to{ stroke-dashoffset:0; opacity:1; }
}

.desktop-focus > .card,
.desktop-main > .card,
.mobile-home > .card,
.mobile-panel-content > .card{
  animation:none;
  will-change:auto;
}

.modal-card{
  animation:softViewIn .22s var(--motion-ease) both;
  will-change:opacity, transform;
}

.order-list-card,
.order-detail-panel,
.order-item-card,
.premium-order-item{
  animation:none;
}

.desktop-main,
.mobile-home,
.mobile-panel,
.modal-card,
.popup-box{
  transform-origin:center top;
  backface-visibility:hidden;
}

body.motion-forward .desktop-main,
body.motion-forward .mobile-panel,
body.motion-forward .mobile-home{
  animation:premiumScreenIn var(--motion-duration) var(--motion-ease-emphasis) both;
}

body.motion-back .desktop-main,
body.motion-back .mobile-panel,
body.motion-back .mobile-home{
  animation:premiumScreenBackIn 330ms var(--motion-ease) both;
}

.motion-stagger-item{
  animation:premiumStaggerIn 420ms var(--motion-ease-emphasis) both;
  animation-delay:calc(min(var(--motion-index, 0), 14) * 28ms);
  will-change:opacity, transform;
}

.card,
.kpi-card,
.plan-card,
.chart-card,
.order-list-card,
.order-item-card,
.dashboard-window{
  contain:layout paint style;
}

.card,
.kpi-card,
.plan-card,
.chart-card,
.order-list-card,
.order-item-card,
.action-tile,
.mobile-bottom-nav-button,
.side-nav-button,
.btn,
.icon-button{
  -webkit-tap-highlight-color:transparent;
}

.value-updated{
  display:inline-block;
  animation:softValuePulse .24s ease-out both;
}

@media (prefers-reduced-motion: reduce){
  .desktop-focus > .card,
  .desktop-main > .card,
  .mobile-home > .card,
  .mobile-panel-content > .card,
  .modal-card,
  .order-list-card,
  .order-detail-panel,
  .order-item-card,
  .premium-order-item,
  .value-updated{
    animation:none !important;
  }
}

.intro-overlay{
  position:fixed;
  inset:0;
  z-index:var(--z-critical);
  display:grid;
  place-items:center;
  overflow:hidden;
  background:#051c26;
  opacity:1;
  transition:opacity .35s ease;
}

.intro-overlay.is-hidden{
  opacity:0;
  pointer-events:none;
}

.intro-test-banner{
  position:absolute;
  top:max(12px, var(--safe-area-inset-top, env(safe-area-inset-top, 0px)));
  left:50%;
  transform:translateX(-50%);
  z-index:2;
  width:min(calc(100% - 24px), 560px);
  min-height:44px;
  display:flex;
  align-items:center;
  justify-content:center;
  gap:10px;
  padding:8px 14px;
  border:1px solid rgba(255,255,255,.24);
  border-radius:8px;
  background:rgba(7,59,75,.9);
  color:#fff;
  box-shadow:0 10px 26px rgba(0,0,0,.24);
  text-align:center;
}

.intro-test-banner strong{
  flex:0 0 auto;
  font-size:.875rem;
}

.intro-test-banner span{
  min-width:0;
  font-size:.8125rem;
  line-height:1.3;
}

.intro-video-frame{
  width:min(100vw, 95.4064dvh);
  height:min(100dvh, 104.8148vw);
  max-width:100vw;
  max-height:100dvh;
  aspect-ratio:2160 / 2264;
  display:grid;
  place-items:center;
  overflow:hidden;
  background:#051c26;
}

.intro-video{
  display:block;
  width:100%;
  height:100%;
  max-width:100%;
  max-height:100%;
  object-fit:contain !important;
  object-position:center !important;
  background:#051c26;
}

@supports not (height: 100dvh){
  .intro-video-frame{
    width:min(100vw, 95.4064vh);
    height:min(100vh, 104.8148vw);
    max-height:100vh;
  }
}

.intro-play,
.intro-skip{
  position:absolute;
  min-width:72px;
  height:40px;
  padding:0 14px;
  border-radius:8px;
  border:1px solid rgba(255,255,255,.28);
  background:rgba(7,59,75,.78);
  color:#fff;
  font-weight:700;
  box-shadow:0 10px 24px rgba(0,0,0,.28);
  backdrop-filter:blur(10px);
}

.intro-play{
  left:50%;
  top:50%;
  display:none;
  transform:translate(-50%, -50%);
}

.intro-overlay.needs-action .intro-play{
  display:flex;
  align-items:center;
  justify-content:center;
}

.intro-skip{
  inset-inline:auto;
  left:50vw;
  right:auto;
  position:fixed;
  width:max-content;
  bottom:max(28px, calc(env(safe-area-inset-bottom, 0px) + 18px));
  display:inline-flex;
  align-items:center;
  justify-content:center;
  transform:translateX(-50%);
  z-index:calc(var(--z-critical, 1000) + 2);
}

body[data-ui-profile="android_apk"] .intro-skip{
  inset-inline:auto !important;
  left:50vw !important;
  right:auto !important;
  width:max-content !important;
  bottom:max(30px, calc(var(--app-safe-bottom, 0px) + 18px)) !important;
  transform:translate3d(-50%, 0, 0) !important;
}

.intro-play:focus-visible,
.intro-skip:focus-visible{
  outline:2px solid var(--primary-2);
  outline-offset:2px;
}

@media (max-width:520px){
  .intro-test-banner{
    align-items:flex-start;
    flex-direction:column;
    gap:2px;
    text-align:left;
  }
}

header{
  position:sticky;
  top:0;
  z-index:20;
  display:none;
  grid-template-columns:40px minmax(0, 1fr) 40px;
  align-items:center;
  gap:8px;
  background:linear-gradient(180deg, rgba(10,13,19,.96), rgba(8,10,15,.92));
  padding:8px 12px;
  text-align:center;
  border-bottom:1px solid var(--line);
  box-shadow:0 10px 24px rgba(0,0,0,.22);
  backdrop-filter:blur(14px);
}

header h1{
  margin:0;
  font-size:var(--font-xl);
  letter-spacing:0;
  min-width:0;
  display:flex;
  align-items:center;
  justify-content:center;
  gap:8px;
  overflow:hidden;
}

.app-logo{
  width:32px;
  height:32px;
  border-radius:8px;
  object-fit:cover;
  object-position:center;
  border:1px solid var(--line);
  background:var(--panel-2);
  flex:0 0 auto;
}

#appTitleText{
  min-width:0;
  overflow:hidden;
  text-overflow:ellipsis;
  white-space:nowrap;
}

.header-menu-button{
  width:40px;
  min-width:40px;
  height:40px;
  min-height:40px;
  display:flex;
  align-items:center;
  justify-content:center;
  background:var(--card-gradient);
  color:var(--text);
  border:1px solid var(--card-border);
  border-radius:var(--radius);
  font-size:var(--font-lg);
  box-shadow:var(--shadow-soft);
}

body.auth-screen-active .header-menu-button,
body.visitor-public-screen .header-menu-button{
  display:none;
}

.header-spacer{
  width:40px;
  min-width:40px;
}

#app{
  min-height:100vh;
  padding:var(--gap);
  padding-bottom:calc(var(--floating-button-size) + var(--gap) * 2);
}

.desktop-grid{
  width:100%;
  display:grid;
  grid-template-columns:repeat(auto-fit, minmax(min(100%, var(--desktop-card-min)), 1fr));
  gap:var(--gap);
  align-items:start;
}

.desktop-shell{
  width:min(var(--desktop-max-width), 100%);
  margin:0 auto;
  display:grid;
  grid-template-columns:var(--desktop-sidebar-width) minmax(0, 1fr);
  gap:var(--gap);
  align-items:start;
  transition:grid-template-columns .18s ease;
}

.desktop-shell.sidebar-collapsed{
  grid-template-columns:64px minmax(0, 1fr);
}

.desktop-main{
  min-width:0;
  display:grid;
  gap:var(--gap);
}

.topbar{
  min-height:64px;
  display:grid;
  grid-template-columns:minmax(180px, 1fr) auto auto;
  align-items:center;
  gap:var(--gap);
  padding:12px;
  border:1px solid var(--card-border);
  border-radius:var(--radius-lg);
  background:rgba(10,16,24,.72);
  box-shadow:var(--shadow);
  backdrop-filter:blur(var(--glass-blur));
}

.topbar > div{
  min-width:0;
  display:grid;
  gap:2px;
}

.topbar-search{
  height:40px;
  display:flex;
  align-items:center;
  gap:8px;
  padding:0 12px;
  border:1px solid var(--card-border);
  border-radius:999px;
  background:rgba(8,13,20,.66);
  box-shadow:inset 0 1px 0 rgba(255,255,255,.03);
}

.topbar-search.search-compact,
.dashboard-search.search-compact{
  padding:0;
  border-color:transparent;
  background:transparent;
  box-shadow:none;
}

.topbar-search input{
  width:100%;
  min-width:0;
  border:0;
  outline:0;
  color:var(--text);
  background:transparent;
}

.search-compact{
  width:44px;
  max-width:44px;
  justify-self:end;
  cursor:pointer;
  overflow:hidden;
  transition:width .22s ease, max-width .22s ease, border-color .18s ease, box-shadow .18s ease, transform .18s ease;
}

.search-compact input{
  opacity:0;
  pointer-events:none;
  transition:opacity .16s ease;
}

.search-action-button{
  width:34px;
  height:34px;
  flex:0 0 34px;
  display:inline-flex;
  align-items:center;
  justify-content:center;
  padding:0;
  border:0;
  border-radius:0;
  color:#00ffe1;
  background:transparent;
  box-shadow:none;
  cursor:pointer;
  filter:drop-shadow(0 1px 0 #001014) drop-shadow(0 0 5px rgba(0,255,225,.55));
}

.search-action-button:hover,
.search-action-button:focus-visible{
  color:#ffffff;
  outline:none;
  filter:drop-shadow(0 1px 0 #001014) drop-shadow(0 0 8px rgba(0,255,225,.95));
}

.search-action-button > span:not(.search-lens-icon):last-child{
  display:none;
}

.search-lens-icon{
  display:grid;
  place-items:center;
  width:24px;
  height:24px;
  font-size:0;
  line-height:1;
  filter:none;
}

.search-lens-icon svg{
  width:21px;
  height:21px;
  stroke-width:2.5;
}

.smart-suggestion-card{
  display:flex;
  align-items:center;
  justify-content:space-between;
  gap:10px;
  padding:10px 12px;
  border:1px solid rgba(134,240,255,.18);
  border-radius:var(--radius);
  background:linear-gradient(145deg, rgba(11,76,92,.22), rgba(255,255,255,.04));
  box-shadow:var(--shadow-soft);
}

.smart-suggestion-card span{
  display:block;
  color:var(--muted);
  font-size:var(--font-xs);
}

.smart-suggestion-card strong{
  display:block;
  font-size:var(--font-md);
}

.smart-suggestion-actions{
  display:flex;
  gap:8px;
  flex-wrap:wrap;
}

.smart-suggestion-actions .btn{
  width:auto;
}

.smart-top-card{
  display:flex;
  align-items:center;
  justify-content:space-between;
  gap:10px;
  padding:12px;
  border:1px solid rgba(13,189,184,.24);
  border-radius:18px;
  background:linear-gradient(145deg, rgba(13,189,184,.12), rgba(9,16,24,.84));
  box-shadow:var(--shadow-soft);
}

.smart-top-card span{
  display:block;
  color:#0ff2e7;
  font-size:var(--font-xs);
  font-weight:900;
}

.smart-top-card strong{
  display:block;
  margin-top:2px;
  font-size:var(--font-md);
}

.smart-highlight{
  box-shadow:0 0 0 2px rgba(255,148,28,.28), 0 10px 24px rgba(255,148,28,.14);
}

.search-compact.is-expanded,
.search-compact:focus-within{
  width:min(520px, 100%);
  max-width:min(520px, 100%);
  padding:0 12px;
  border-color:var(--card-border);
  background:rgba(8,13,20,.66);
  box-shadow:inset 0 1px 0 rgba(255,255,255,.03);
}

.search-compact.is-expanded input,
.search-compact:focus-within input{
  opacity:1;
  pointer-events:auto;
}

.topbar-search.search-compact.is-expanded,
.topbar-search.search-compact:focus-within{
  width:min(420px, 42vw);
  max-width:min(420px, 42vw);
}

.topbar-user{
  justify-items:end;
  text-align:right;
}

.desktop-focus{
  width:min(900px, 100%);
}

.side-menu{
  position:sticky;
  top:12px;
  display:grid;
  gap:10px;
  padding:10px;
  border-radius:22px;
  background:
    radial-gradient(circle at 18% 0%, rgba(56,189,248,.16), transparent 30%),
    linear-gradient(180deg, rgba(15,24,34,.88), rgba(7,11,17,.92));
  border:1px solid rgba(255,255,255,.14);
  box-shadow:var(--shadow);
  backdrop-filter:blur(var(--glass-blur));
  transition:width .18s ease, padding .18s ease;
}

.side-brand{
  display:grid;
  grid-template-columns:auto 38px minmax(0, 1fr) auto;
  align-items:center;
  gap:8px;
  padding:10px;
  border-radius:18px;
  background:rgba(255,255,255,.055);
  border:1px solid var(--card-border);
  box-shadow:var(--shadow-soft);
}

.side-brand-logo{
  width:38px;
  height:38px;
  border-radius:8px;
  object-fit:cover;
  object-position:center;
  border:1px solid var(--line);
  background:var(--panel);
}

.side-menu-toggle{
  width:34px;
  min-width:34px;
  height:34px;
  min-height:34px;
  border-radius:12px;
  font-size:var(--font-md);
}

.side-brand-text{
  min-width:0;
  display:grid;
  gap:3px;
}

.side-brand strong{
  font-size:var(--font-lg);
  overflow-wrap:anywhere;
}

.side-plan-pill{
  max-width:92px;
  min-height:24px;
  display:inline-flex;
  align-items:center;
  justify-content:center;
  padding:3px 8px;
  border-radius:999px;
  color:#fff;
  font-size:var(--font-xs);
  font-weight:800;
  overflow:hidden;
  text-overflow:ellipsis;
  white-space:nowrap;
  border:1px solid rgba(255,255,255,.16);
  background:rgba(255,255,255,.08);
}

.side-brand span,
.side-section > span,
.side-profile-meta small{
  color:var(--muted);
  font-size:var(--font-xs);
}

.side-profile-card{
  min-height:94px;
  display:grid;
  grid-template-columns:46px minmax(0, 1fr) auto;
  gap:10px 12px;
  align-items:start;
  position:relative;
  overflow:hidden;
  padding:11px;
  color:var(--text);
  text-align:left;
  border:1px solid rgba(255,255,255,.14);
  border-radius:20px;
  background:
    linear-gradient(145deg, rgba(11,76,92,.30), rgba(255,255,255,.045)),
    rgba(3,8,14,.34);
  box-shadow:var(--shadow-soft);
}

.side-profile-card::before{
  content:"";
  position:absolute;
  inset:0;
  pointer-events:none;
  border-radius:inherit;
  background:
    linear-gradient(90deg, transparent, rgba(134,240,255,.28), transparent) -120% 0 / 55% 100% no-repeat,
    linear-gradient(180deg, rgba(255,255,255,.07), transparent 48%);
  opacity:.75;
  transition:background-position .35s ease;
}

.side-profile-card:hover::before,
.side-profile-card:focus-visible::before{
  background-position:180% 0, 0 0;
}

.side-profile-avatar{
  width:46px;
  height:46px;
  min-width:46px;
  display:grid;
  place-items:center;
  border-radius:50%;
  object-fit:cover;
  color:#fff;
  font-weight:900;
  border:1px solid rgba(255,255,255,.22);
  background:linear-gradient(145deg, rgba(255,148,28,.82), rgba(11,76,92,.95));
  box-shadow:0 14px 24px rgba(0,0,0,.25), 0 0 0 4px rgba(255,255,255,.045);
}

.side-profile-meta{
  min-width:0;
  display:grid;
  gap:3px;
  align-self:center;
}

.side-profile-meta strong,
.side-profile-meta small{
  overflow:hidden;
  text-overflow:ellipsis;
  white-space:nowrap;
}

.side-profile-card .status-badge{
  min-width:0;
  min-height:24px;
  padding:3px 8px;
}

.side-profile-account{
  grid-column:3;
  grid-row:1;
  min-width:74px;
  display:grid;
  justify-items:end;
  gap:5px;
  align-self:start;
  position:relative;
  z-index:1;
}

.side-account-type{
  max-width:104px;
  min-height:22px;
  display:inline-flex;
  align-items:center;
  justify-content:center;
  padding:3px 8px;
  border-radius:999px;
  color:var(--text);
  font-size:10px;
  font-weight:800;
  line-height:1;
  white-space:nowrap;
  overflow:hidden;
  text-overflow:ellipsis;
  border:1px solid rgba(255,255,255,.14);
  background:rgba(255,255,255,.075);
}

.side-section{
  display:grid;
  gap:6px;
}

.side-menu.is-collapsed{
  padding:8px;
}

.side-menu.is-collapsed .side-brand{
  grid-template-columns:1fr;
  justify-items:center;
  padding:8px;
}

.side-menu.is-collapsed .side-brand-text,
.side-menu.is-collapsed .side-brand-logo,
.side-menu.is-collapsed .side-profile-meta,
.side-menu.is-collapsed .side-profile-card .status-badge,
.side-menu.is-collapsed .side-profile-account,
.side-menu.is-collapsed .side-plan-pill,
.side-menu.is-collapsed .side-section > span,
.side-menu.is-collapsed .side-nav-button strong{
  display:none;
}

.side-menu.is-collapsed .side-profile-card{
  min-height:54px;
  grid-template-columns:1fr;
  justify-items:center;
  padding:8px;
  border-radius:16px;
}

.side-menu.is-collapsed .side-nav-button{
  grid-template-columns:1fr;
  justify-items:center;
  padding:8px;
}

.side-nav-button{
  min-height:calc(var(--control-height) + 2px);
  display:grid;
  grid-template-columns:30px minmax(0, 1fr);
  align-items:center;
  gap:8px;
  padding:8px 9px;
  background:rgba(255,255,255,.018);
  color:var(--text);
  text-align:left;
  border:1px solid transparent;
  border-radius:15px;
  transition:background 220ms var(--motion-ease), border-color 200ms ease, transform 200ms var(--motion-ease), filter 180ms ease, box-shadow 220ms var(--motion-ease);
}

.side-nav-button:hover,
.side-nav-button:focus-visible{
  background:rgba(255,255,255,.06);
  border-color:rgba(134,240,255,.18);
  outline:none;
}

.side-nav-button:active{
  transform:scale(.96);
}

.side-nav-button span{
  width:30px;
  height:30px;
  display:inline-flex;
  align-items:center;
  justify-content:center;
  border-radius:11px;
  background:rgba(13,189,184,.09);
  text-align:center;
  font-size:var(--font-md);
  color:#18eee5;
}

.side-nav-button span svg,
.quick-action span svg,
.mobile-bottom-nav-button span svg,
.menu-button span svg,
.more-item span svg,
.window-title .nav-symbol svg{
  width:20px;
  height:20px;
  display:block;
}

.side-nav-button strong{
  font-size:var(--font-sm);
  font-weight:700;
  overflow:hidden;
  text-overflow:ellipsis;
  white-space:nowrap;
}

.side-nav-button.active{
  background:linear-gradient(90deg, rgba(13,189,184,.16), rgba(255,148,28,.08));
  border-color:rgba(13,189,184,.34);
  box-shadow:inset 3px 0 0 rgba(13,189,184,.86), 0 10px 22px rgba(0,0,0,.16);
}

.side-nav-button.active span{
  background:rgba(13,189,184,.20);
  color:#33fff3;
  transform:scale(1.05);
}

.mobile-home{
  display:flex;
  flex-direction:column;
  gap:var(--gap);
}

.mobile-mode .mobile-home{
  padding-bottom:calc(118px + env(safe-area-inset-bottom));
}

.card{
  display:block;
  width:100%;
  break-inside:avoid;
  margin:0;
  position:relative;
  overflow:hidden;
  background:var(--card-gradient);
  border:1px solid var(--card-border);
  border-radius:var(--radius);
  padding:var(--card-padding);
  box-shadow:var(--shadow);
  backdrop-filter:blur(var(--glass-blur));
  vertical-align:top;
  transition:transform 240ms var(--motion-ease), border-color 220ms ease, box-shadow 260ms var(--motion-ease);
}

.card::before,
.kpi-card::before,
.plan-card::before,
.chart-card::before,
.history-item::before,
.user-row::before,
.order-item::before,
.list-row::before,
.stock-row::before,
.cash-row::before,
.client-admin-row::before,
.payment-row::before{
  content:"";
  position:absolute;
  inset:0;
  pointer-events:none;
  border-radius:inherit;
  background:linear-gradient(180deg, rgba(255,255,255,.055), transparent 46%);
}

.card::after,
.kpi-card::after,
.plan-card::after,
.quick-action::after{
  content:"";
  position:absolute;
  inset:0;
  pointer-events:none;
  border-radius:inherit;
  padding:1px;
  background:linear-gradient(135deg, rgba(134,240,255,.36), transparent 34%, rgba(255,148,28,.24));
  opacity:.18;
  -webkit-mask:linear-gradient(#000 0 0) content-box, linear-gradient(#000 0 0);
  -webkit-mask-composite:xor;
  mask-composite:exclude;
  transition:opacity .18s ease;
}

.card:hover::after,
.kpi-card:hover::after,
.plan-card:hover::after,
.quick-action:hover::after{
  opacity:.55;
}

@media (hover:hover){
  .card:hover,
  .kpi-card:hover,
  .plan-card:hover,
  .chart-card:hover,
  .order-list-card:hover{
    transform:translate3d(0, -2px, 0);
    box-shadow:0 15px 30px rgba(0,0,0,.26), 0 0 0 1px rgba(13,189,184,.08), inset 0 1px 0 rgba(255,255,255,.06);
  }
}

.dashboard-pro{
  display:grid;
  gap:12px;
  align-content:start;
  max-width:1180px;
  width:100%;
  margin-inline:auto;
}

.premium-dashboard{
  gap:12px;
}

.home-premium-header{
  display:grid;
  grid-template-columns:minmax(0, 1fr) auto;
  align-items:center;
  gap:14px;
  padding:14px;
  overflow:hidden;
  border:1px solid var(--glass-border);
  border-radius:var(--radius-lg);
  background:
    linear-gradient(135deg, rgba(11,76,92,.36), rgba(15,23,34,.78)),
    rgba(7,11,17,.72);
  box-shadow:var(--shadow);
  backdrop-filter:blur(var(--glass-blur));
}

.home-brand-lockup{
  display:grid;
  grid-template-columns:52px minmax(0, 1fr);
  gap:12px;
  align-items:center;
