}

.home-brand-logo{
  width:52px;
  height:52px;
  border-radius:16px;
  object-fit:cover;
  border:1px solid rgba(255,255,255,.16);
  box-shadow:0 12px 24px rgba(0,0,0,.26);
}

.eyebrow{
  display:block;
  margin-bottom:4px;
  color:#86f0ff;
  font-size:var(--font-xs);
  font-weight:800;
