  text-transform:uppercase;
}

.home-brand-lockup h1{
  margin:0;
  font-size:clamp(20px, 4vw, 30px);
  line-height:1;
  overflow-wrap:anywhere;
}

.home-brand-lockup p{
  margin:5px 0 0;
  color:var(--muted);
  font-size:var(--font-sm);
}

.home-account-strip{
  display:flex;
  align-items:center;
  justify-content:flex-end;
  gap:10px;
}

.home-account-strip > div{
  min-width:88px;
