  border:1px solid rgba(255,255,255,.10);
  border-radius:var(--radius-sm);
  background:rgba(3,8,13,.42);
}

.home-account-strip span{
  display:block;
  color:var(--muted);
  font-size:var(--font-xs);
}

.home-account-strip strong{
  display:block;
  margin-top:2px;
  max-width:150px;
  overflow:hidden;
  text-overflow:ellipsis;
  white-space:nowrap;
  font-size:var(--font-sm);
}

.home-avatar{
  width:46px;
  height:46px;
  min-width:46px;
  display:grid;
  place-items:center;
  border-radius:50%;
  object-fit:cover;
  color:#fff;
  font-weight:900;
  border:1px solid rgba(255,255,255,.22);
  background:linear-gradient(145deg, rgba(255,148,28,.78), rgba(11,76,92,.92));
  box-shadow:0 14px 24px rgba(0,0,0,.28);
}

.dashboard-profile-button{
  width:46px;
  height:46px;
  display:inline-grid;
  place-items:center;
  padding:0;
  border:0;
  border-radius:50%;
  background:transparent;
  color:inherit;
  cursor:pointer;
}

.dashboard-profile-button .home-avatar{
  margin:0;
}

.dashboard-profile-button:active{
  transform:scale(.96);
}

.home-menu-button{
  border-radius:50%;
  background:rgba(255,255,255,.08);
}

.menu-handle-icon{
  width:18px;
  height:18px;
  display:block;
}

.dashboard-search-row{
  display:grid;
  grid-template-columns:1fr;
  gap:10px;
  align-items:center;
}

.dashboard-menu-trigger{
  display:none;
}

.dashboard-search{
  width:100%;
  min-height:48px;
  display:flex;
  align-items:center;
  gap:10px;
  padding:0 14px;
  border:1px solid var(--glass-border);
  border-radius:999px;
  background:rgba(8,13,20,.64);
