}

.mobile-mode .dashboard-search-row{
  grid-template-columns:44px minmax(48px, 1fr);
}

.mobile-mode .dashboard-menu-trigger{
  display:flex;
  width:40px;
  min-width:40px;
  height:40px;
  min-height:40px;
  border-radius:14px;
  background:rgba(8,13,20,.68);
  border:1px solid var(--glass-border);
  box-shadow:var(--shadow-soft);
  backdrop-filter:blur(12px);
}

.dashboard-menu-trigger .menu-handle-icon,
.home-menu-button .menu-handle-icon,
.mobile-panel-menu-button .menu-handle-icon{
  width:16px;
  height:16px;
}

.dashboard-search input{
  min-height:44px;
  padding:0;
  border:0;
  background:transparent;
  box-shadow:none;
}

.dashboard-search:focus-within{
  border-color:rgba(134,240,255,.36);
  box-shadow:0 16px 30px rgba(0,0,0,.26), 0 0 0 3px rgba(56,189,248,.08);
  transform:translateY(-1px);
}

.technical-glass-panel{
  display:grid;
  gap:14px;
  padding:16px;
  overflow:hidden;
  min-width:0;
  max-width:100%;
  border:1px solid rgba(134,240,255,.20);
  border-radius:var(--radius-lg);
  background:
    radial-gradient(circle at 15% 18%, rgba(56,189,248,.20), transparent 32%),
    radial-gradient(circle at 82% 8%, rgba(255,148,28,.13), transparent 30%),
    linear-gradient(145deg, rgba(16,31,43,.82), rgba(7,11,17,.92));
  box-shadow:var(--shadow);
  backdrop-filter:blur(var(--glass-blur));
}

.infographic-panel,
.infographic-panel *{
  min-width:0;
}

.infographic-hero{
  display:grid;
  grid-template-columns:minmax(0, 1fr) 116px;
  gap:12px;
  align-items:center;
}

.infographic-hero h2{
  margin:0;
  font-size:clamp(30px, 7vw, 48px);
  line-height:1;
}

.infographic-hero p{
  margin:8px 0 0;
  color:var(--muted);
  max-width:520px;
}

.infographic-ring{
  width:112px;
  height:112px;
  display:grid;
  place-items:center;
  align-content:center;
  border-radius:50%;
  background:
    radial-gradient(circle at center, #101722 55%, transparent 57%),
    conic-gradient(#86f0ff var(--value), rgba(255,255,255,.10) 0);
  box-shadow:inset 0 10px 20px rgba(0,0,0,.24), 0 16px 28px rgba(0,0,0,.28);
}

.infographic-ring strong{
  font-size:24px;
  line-height:1;
}

.infographic-ring span{
  color:var(--muted);
  font-size:var(--font-xs);
}

.infographic-ring.is-empty{
  background:
    radial-gradient(circle at center, #101722 55%, transparent 57%),
    conic-gradient(rgba(255,255,255,.16) 0 100%);
}

.infographic-ring.is-empty strong{
  color:var(--muted);
}

.infographic-flow{
  position:relative;
  display:grid;
  grid-template-columns:repeat(4, minmax(0, 1fr));
  gap:10px;
  padding:14px;
  border:1px solid rgba(255,255,255,.08);
  border-radius:20px;
  background:rgba(0,0,0,.16);
  max-width:100%;
}

.infographic-flow::before,
.infographic-flow::after{
  content:"";
  position:absolute;
  left:8%;
  right:8%;
  top:50%;
  height:3px;
  pointer-events:none;
  border-radius:999px;
}

.infographic-flow::before{
  background:rgba(255,255,255,.10);
}

.infographic-flow::after{
  width:calc(var(--flow) * .84);
  right:auto;
  background:linear-gradient(90deg, #38bdf8, #ff941c);
  box-shadow:0 0 18px rgba(56,189,248,.24);
}

.infographic-node{
  min-height:118px;
  position:relative;
  z-index:1;
  display:grid;
  align-content:center;
  justify-items:center;
  gap:5px;
  padding:12px 8px;
  color:var(--text);
  text-align:center;
  border:1px solid rgba(255,255,255,.12);
  border-radius:18px;
  background:linear-gradient(145deg, rgba(18,29,41,.92), rgba(6,11,17,.92));
  box-shadow:var(--shadow-soft);
  transition:transform .16s ease, border-color .16s ease;
}

.infographic-node:active{
  transform:scale(.98);
}

.infographic-node .node-icon{
  width:36px;
  height:36px;
  display:grid;
  place-items:center;
  border-radius:14px;
  background:rgba(255,255,255,.08);
  color:#86f0ff;
  font-weight:900;
}

.infographic-node strong{
  max-width:100%;
  font-size:clamp(17px, 4.5vw, 22px);
  line-height:1;
  overflow-wrap:anywhere;
}

.infographic-node small{
  color:var(--muted);
  font-size:var(--font-xs);
}

.node-orange{
  border-color:rgba(255,148,28,.28);
}

.node-green{
  border-color:rgba(69,224,143,.28);
}

.node-red{
  border-color:rgba(255,82,82,.32);
}

.infographic-insights{
  display:grid;
  grid-template-columns:repeat(4, minmax(0, 1fr));
  gap:8px;
  max-width:100%;
}

.insight-card{
  min-height:84px;
  display:grid;
  align-content:center;
  gap:5px;
  position:relative;
  overflow:hidden;
  padding:10px;
  border:1px solid rgba(255,255,255,.09);
  border-radius:16px;
  background:rgba(255,255,255,.045);
}

.insight-card span,
.insight-card small{
  color:var(--muted);
  font-size:var(--font-xs);
}

.insight-card strong{
  font-size:var(--font-lg);
  overflow-wrap:anywhere;
}

.insight-card i{
  height:5px;
  width:var(--w);
  min-width:18px;
  border-radius:999px;
  background:linear-gradient(90deg, #38bdf8, #86f0ff);
  box-shadow:0 0 14px rgba(56,189,248,.24);
}

.insight-card.warning{
  border-color:rgba(255,148,28,.26);
  background:rgba(255,148,28,.08);
}

.dashboard-hero{
  display:grid;
  gap:var(--gap);
}

.dashboard-kpis{
  display:grid;
  grid-template-columns:repeat(auto-fit, minmax(150px, 1fr));
  gap:8px;
}

.kpi-card{
  min-height:76px;
  display:grid;
  grid-template-columns:32px minmax(0, 1fr);
  gap:8px;
  align-items:start;
  position:relative;
  padding:12px;
  overflow:hidden;
  border:1px solid var(--card-border);
  border-radius:var(--radius);
  background:var(--card-gradient-strong);
  box-shadow:var(--shadow-soft);
  backdrop-filter:blur(10px);
  transition:transform .18s ease, border-color .18s ease, box-shadow .18s ease;
}

.kpi-card-button{
  width:100%;
  color:inherit;
  text-align:left;
  cursor:pointer;
  border-color:var(--line);
}

.kpi-card-button:hover,
.kpi-card-button:focus-visible{
  transform:translateY(-1px);
  border-color:rgba(255,148,28,.58);
  box-shadow:0 18px 34px rgba(0,0,0,.34), 0 0 0 1px rgba(255,148,28,.12);
  outline:none;
}

.kpi-icon{
  width:32px;
  height:32px;
  display:grid;
  place-items:center;
  border-radius:12px;
  background:rgba(8,11,16,.72);
  border:1px solid rgba(255,148,28,.26);
  box-shadow:inset 0 1px 0 rgba(255,255,255,.05);
}

.kpi-teal{
  border-color:rgba(56,189,248,.28);
}

.kpi-green{
  border-color:rgba(69,224,143,.28);
}

.kpi-orange{
  border-color:rgba(255,148,28,.34);
}

.kpi-red{
  border-color:rgba(255,82,82,.34);
}

.kpi-card div{
  min-width:0;
  display:grid;
  gap:6px;
}

.kpi-card span:not(.kpi-icon){
  color:var(--muted);
  font-size:var(--font-sm);
}

.kpi-card strong{
  font-size:clamp(17px, 3vw, 22px);
  line-height:1;
  overflow-wrap:anywhere;
}

.kpi-card .status-badge{
  position:absolute;
  right:8px;
  bottom:8px;
}

.dashboard-split{
  display:grid;
  grid-template-columns:repeat(auto-fit, minmax(min(100%, 360px), 1fr));
  gap:var(--gap);
}

.stock-row{
  grid-template-columns:minmax(0, 1fr) auto auto;
  align-items:center;
}

.stock-actions{
  display:flex;
  justify-content:flex-end;
  gap:7px;
}

.filter-chip-row{
  display:flex;
  flex-wrap:wrap;
  align-items:center;
  gap:8px;
  margin-bottom:var(--gap);
}

.card-header,
.modal-header,
.mobile-panel-bar{
  display:flex;
  align-items:center;
  justify-content:space-between;
  gap:8px;
  margin-bottom:10px;
  padding-bottom:8px;
  border-bottom:1px solid rgba(255,255,255,.08);
}

.card h2,
.mobile-panel-bar h2,
.modal-header h2{
  flex:1;
  margin:0;
  font-size:var(--font-lg);
  line-height:1.2;
  overflow-wrap:anywhere;
}

.muted{
  color:var(--muted);
  font-size:var(--font-xs);
  line-height:1.4;
}

.metrics{
  display:grid;
  grid-template-columns:repeat(2, minmax(0, 1fr));
  gap:8px;
}

.metric{
  min-height:var(--metric-min-height);
  padding:10px;
  position:relative;
  overflow:hidden;
  border-radius:var(--radius);
  background:linear-gradient(145deg, rgba(43,49,63,.9), rgba(20,24,32,.92));
  border:1px solid var(--card-border);
  box-shadow:var(--shadow-soft);
}

.metric span{
  display:block;
  color:var(--muted);
  font-size:var(--font-xs);
  margin-bottom:6px;
}

.metric strong{
  display:block;
  font-size:var(--font-lg);
  line-height:1.2;
  overflow-wrap:anywhere;
}

.summary-card .metrics{
  grid-template-columns:repeat(2, minmax(0, 1fr));
  gap:1px;
  padding:1px;
  border-radius:var(--radius);
  background:rgba(255,255,255,.09);
  overflow:hidden;
}

.summary-card .metric{
  min-height:var(--summary-metric-min-height);
  border:0;
  border-radius:0;
  box-shadow:none;
}

.field{
  display:flex;
  flex-direction:column;
  gap:4px;
  margin-bottom:8px;
}

.field span{
  color:var(--muted);
  font-size:var(--font-xs);
}

input,
select,
textarea{
  width:100%;
  min-height:var(--control-height);
  padding:9px 10px;
  border-radius:var(--radius);
  border:1px solid var(--card-border);
  background:var(--input-bg, rgba(8,11,16,.72));
  color:var(--input-text, var(--text));
  font-size:var(--base-font-size);
  outline:none;
  box-shadow:inset 0 1px 0 rgba(255,255,255,.03);
}

input::placeholder{
  color:var(--input-placeholder, var(--muted));
}

input:focus,
select:focus,
textarea:focus{
  border-color:rgba(255,148,28,.62);
  box-shadow:0 0 0 3px rgba(255,148,28,.10), inset 0 1px 0 rgba(255,255,255,.03);
}

button{
  min-height:var(--control-height);
  border:0;
  border-radius:var(--radius);
  cursor:pointer;
  font:inherit;
  -webkit-tap-highlight-color:transparent;
  user-select:none;
}

button:disabled{
  cursor:not-allowed;
  opacity:.5;
}

.btn{
  width:auto;
  max-width:100%;
  align-self:flex-start;
  min-height:40px;
  display:inline-flex;
  align-items:center;
  justify-content:center;
  gap:8px;
  padding:8px 12px;
  background:linear-gradient(145deg, #0fd0cb, var(--premium-teal-dark));
  color:#fff;
  font-size:var(--font-sm);
  font-weight:800;
  letter-spacing:0;
  line-height:1.15;
  border:1px solid rgba(255,255,255,.12);
  box-shadow:0 10px 20px rgba(0,0,0,.20), inset 0 1px 0 rgba(255,255,255,.18);
  transition:transform 180ms var(--motion-ease), filter 180ms ease, border-color 180ms ease, background 180ms ease, box-shadow 220ms var(--motion-ease);
  transform:translateZ(0);
}

.btn:hover,
.icon-button:hover,
.menu-button:hover,
.side-nav-button:hover,
.quick-action:hover,
.tab-button:hover,
.mobile-bottom-nav-button:hover{
  filter:brightness(1.08);
}

.btn:active,
.icon-button:active,
.action-tile:active,
.quick-action:active,
.side-nav-button:active,
.mobile-bottom-nav-button:active{
  transform:scale(.96);
}

.btn.secondary{
  color:#dffcff;
  background:linear-gradient(145deg, rgba(13,189,184,.12), rgba(13,189,184,.04));
  border-color:rgba(13,189,184,.48);
  box-shadow:inset 0 1px 0 rgba(255,255,255,.08);
}

.btn.warning{
  background:linear-gradient(145deg, rgba(255,158,11,.95), rgba(255,122,0,.86));
  color:#111827;
  border-color:rgba(255,255,255,.16);
}

.btn.danger{
  color:#ffdada;
  background:linear-gradient(145deg, rgba(239,68,68,.16), rgba(127,29,29,.18));
  border-color:rgba(239,68,68,.52);
  box-shadow:inset 0 1px 0 rgba(255,255,255,.06);
}

.btn.ghost{
  background:rgba(255,255,255,.035);
  border:1px solid var(--card-border);
  color:#d7e4eb;
  box-shadow:inset 0 1px 0 rgba(255,255,255,.05);
}

.actions{
  display:grid;
  grid-template-columns:repeat(auto-fit, minmax(128px, 1fr));
  gap:8px;
  margin-top:10px;
  align-items:center;
}

.actions.single{
  grid-template-columns:max-content;
}

.actions .btn,
.legal-actions .btn,
.modal-card .actions .btn,
.order-bottom-bar .btn{
  width:100%;
}

.actions.single .btn,
.actions:has(> .btn:only-child) .btn,
.card > .btn:only-child{
  width:auto;
  min-width:136px;
}

.icon-button{
  width:calc(var(--icon-button-size) - 2px);
  min-width:calc(var(--icon-button-size) - 2px);
  height:calc(var(--icon-button-size) - 2px);
  min-height:calc(var(--icon-button-size) - 2px);
  display:inline-flex;
  align-items:center;
  justify-content:center;
  border-radius:13px;
  background:linear-gradient(145deg, rgba(255,255,255,.075), rgba(255,255,255,.025));
  border:1px solid var(--card-border);
  color:var(--text);
  font-size:var(--font-md);
  box-shadow:0 10px 18px rgba(0,0,0,.18), inset 0 1px 0 rgba(255,255,255,.08);
  transition:transform .16s ease, filter .16s ease, border-color .16s ease, background .16s ease;
}

.icon-button.danger{
  background:rgba(217,67,67,.18);
  border-color:rgba(217,67,67,.45);
}

.icon-action-button{
  width:38px;
  min-width:38px;
  height:38px;
  min-height:38px;
  display:inline-grid;
  place-items:center;
  padding:0;
  border-radius:13px;
  color:#c9fffb;
  background:linear-gradient(145deg, rgba(255,255,255,.07), rgba(255,255,255,.025));
  border:1px solid rgba(255,255,255,.12);
  box-shadow:0 10px 18px rgba(0,0,0,.18), inset 0 1px 0 rgba(255,255,255,.08);
  transition:transform .16s ease, filter .16s ease, border-color .16s ease;
}

.icon-action-button svg{
  width:19px;
  height:19px;
}

.icon-action-button:active{
  transform:scale(.96);
}

.icon-action-button.danger{
  color:#ff8c8c;
  background:linear-gradient(145deg, rgba(239,68,68,.16), rgba(127,29,29,.14));
  border-color:rgba(239,68,68,.42);
}

.icon-action-button.primary{
  color:#042f2e;
  background:linear-gradient(135deg, #2dd4bf, #0f766e);
  border-color:rgba(45,212,191,.5);
  box-shadow:0 12px 22px rgba(15,118,110,.26), inset 0 1px 0 rgba(255,255,255,.22);
}

.password-row .icon-button[title*="senha"],
.password-row .icon-button[title*="Senha"]{
  font-size:0;
  color:#d8eef3;
}

.password-row .icon-button[title*="senha"]::before,
.password-row .icon-button[title*="Senha"]::before{
  content:"";
  width:20px;
  height:20px;
