    width:42px;
    height:42px;
  }

  .dashboard-day-grid{
    grid-template-columns:repeat(3, minmax(0, 1fr));
    gap:7px;
  }

  .dashboard-day-card{
    min-height:116px;
    padding:10px;
  }

  .dashboard-day-card strong{
    font-size:clamp(17px, 4.6vw, 23px);
  }

