    radial-gradient(circle at 18% 8%, rgba(34,197,94,.22), transparent 34%),
    linear-gradient(145deg, rgba(3,61,33,.78), rgba(8,15,18,.96));
}

.plan-tier-start{
  --plan-accent:#8b5cf6;
  --plan-accent-soft:rgba(139,92,246,.18);
  border-color:rgba(139,92,246,.56);
  background:
    radial-gradient(circle at 18% 8%, rgba(139,92,246,.25), transparent 34%),
    linear-gradient(145deg, rgba(43,20,81,.82), rgba(11,12,28,.96));
}

.plan-tier-pro{
  --plan-accent:#f6b51d;
  --plan-accent-soft:rgba(246,181,29,.18);
  border-color:rgba(246,181,29,.62);
  background:
    radial-gradient(circle at 18% 8%, rgba(246,181,29,.22), transparent 34%),
    linear-gradient(145deg, rgba(24,24,22,.96), rgba(4,6,9,.98));
}

.plan-tier-card:hover,
.plan-tier-card:focus-visible{
  border-color:var(--plan-accent);
  box-shadow:0 22px 60px color-mix(in srgb, var(--plan-accent) 28%, transparent), inset 0 1px 0 rgba(255,255,255,.10);
}

.plan-tier-avatar{
  width:68px;
  height:68px;
  display:grid;
  place-items:center;
  flex:0 0 auto;
  border-radius:50%;
  color:#fff;
  font-size:34px;
  font-weight:950;
  letter-spacing:0;
  background:
    radial-gradient(circle at 30% 18%, rgba(255,255,255,.44), transparent 32%),
    linear-gradient(145deg, var(--plan-accent), rgba(0,0,0,.34));
  border:1px solid color-mix(in srgb, var(--plan-accent) 70%, rgba(255,255,255,.22));
  box-shadow:0 18px 34px color-mix(in srgb, var(--plan-accent) 28%, transparent), inset 0 -10px 20px rgba(0,0,0,.22);
}

.plan-tier-badge{
  position:absolute;
  top:14px;
  right:14px;
  z-index:1;
  display:inline-flex;
  align-items:center;
  min-height:28px;
  padding:6px 10px;
  border-radius:999px;
  color:#fff;
  background:linear-gradient(145deg, var(--plan-accent), color-mix(in srgb, var(--plan-accent) 64%, #000));
  border:1px solid color-mix(in srgb, var(--plan-accent) 64%, rgba(255,255,255,.28));
  box-shadow:0 12px 26px color-mix(in srgb, var(--plan-accent) 26%, transparent);
  font-size:11px;
  font-weight:900;
}

.plan-tier-price{
  display:flex;
  align-items:flex-end;
  gap:6px;
  color:#fff;
}

.plan-tier-price small{
  padding-bottom:10px;
  color:rgba(255,255,255,.86);
  font-size:16px;
  font-weight:800;
}

.plan-tier-price strong{
  font-size:clamp(42px, 4.8vw, 64px);
  line-height:.92;
  font-weight:950;
}

.plan-tier-price span{
  padding-bottom:8px;
  color:rgba(255,255,255,.76);
  font-weight:800;
}

.plan-tier-highlights{
  display:grid;
  grid-template-columns:repeat(3, minmax(0, 1fr));
  gap:8px;
}

.plan-tier-highlights b{
  display:grid;
  place-items:center;
  min-height:54px;
  padding:8px;
  border-radius:14px;
  color:#fff;
  text-align:center;
  font-size:12px;
  line-height:1.25;
  background:rgba(255,255,255,.055);
  border:1px solid rgba(255,255,255,.12);
}

.plan-tier-section{
  display:grid;
  gap:10px;
  padding-top:14px;
  border-top:1px solid rgba(255,255,255,.12);
}

.plan-tier-section > strong{
  color:#fff;
  font-size:14px;
}

.plan-tier-list{
  display:grid;
  gap:9px;
  margin:0;
  padding:0;
  list-style:none;
}

.plan-tier-list li{
  display:grid;
  grid-template-columns:22px minmax(0, 1fr);
  gap:10px;
  align-items:start;
  color:rgba(255,255,255,.90);
  line-height:1.35;
}

.plan-tier-list li::before{
  content:"✓";
  display:grid;
  place-items:center;
  width:20px;
  height:20px;
  margin-top:0;
  border-radius:50%;
  color:#07130d;
  background:var(--plan-accent);
  font-size:12px;
  font-weight:950;
}

.plan-tier-list.blocked li{
  color:rgba(255,255,255,.70);
}

.plan-tier-list.blocked li::before{
  content:"×";
  color:#ffe4e6;
  background:rgba(239,68,68,.28);
  border:1px solid rgba(248,113,113,.50);
}

.plan-tier-note{
  padding:14px;
  border-radius:16px;
  color:rgba(255,255,255,.86);
  background:var(--plan-accent-soft);
  border:1px solid color-mix(in srgb, var(--plan-accent) 38%, rgba(255,255,255,.14));
  line-height:1.45;
}

.plan-tier-button{
  width:100%;
  min-height:50px;
  margin-top:auto;
  color:#061016;
  background:linear-gradient(145deg, color-mix(in srgb, var(--plan-accent) 92%, #fff), var(--plan-accent));
  border-color:color-mix(in srgb, var(--plan-accent) 70%, #fff);
  box-shadow:0 16px 34px color-mix(in srgb, var(--plan-accent) 24%, transparent);
}

.plan-tier-card.current .plan-tier-button,
.plan-tier-button:disabled{
  color:rgba(255,255,255,.82);
  background:rgba(255,255,255,.10);
  border-color:rgba(255,255,255,.16);
  box-shadow:none;
}

body.theme-light .plans-pricing-hero > div:first-child,
body.theme-light .plans-pricing-note{
  color:var(--color-text-primary);
  background:
    radial-gradient(circle at 16% 0, color-mix(in srgb, var(--color-primary) 10%, transparent), transparent 42%),
    linear-gradient(145deg, var(--color-surface), var(--color-surface-soft)) !important;
  border-color:var(--color-border);
}

body.theme-light .plans-pricing-hero p,
body.theme-light .plans-pricing-note span{
  color:var(--color-text-secondary);
}

body.theme-light .plan-tier-card{
  color:#f8fafc;
}

@media(max-width:1180px){
  .plans-pricing-grid{
    grid-template-columns:1fr;
  }
}

@media(max-width:760px){
  .plans-pricing-screen{
    max-width:100%;
  }

  .plans-pricing-hero{
    grid-template-columns:1fr;
  }

  .plans-pricing-hero > div:first-child,
  .plans-pricing-note,
  .plan-tier-card{
    border-radius:20px;
    padding:16px;
  }

  .plans-pricing-grid .plan-tier-card{
    gap:14px;
    padding:18px;
    border-radius:22px;
  }

  .plans-pricing-hero h2{
    font-size:32px;
  }

  .plan-tier-card .row-title{
    display:grid;
    grid-template-columns:56px minmax(0, 1fr);
    align-items:start;
    gap:12px;
    padding-right:0;
  }

  .plan-tier-card .row-title > div{
    min-width:0;
  }

  .plan-tier-card .row-title .plan-modern-badge{
    grid-column:1 / -1;
    justify-self:start;
    min-height:34px;
  }

  .plans-pricing-grid .plan-tier-card .row-title .plan-modern-badge{
    grid-column:auto;
    justify-self:end;
    align-self:start;
    min-width:72px;
  }

  .plan-tier-card .row-title h3,
  .plan-tier-card .row-title p{
    overflow-wrap:anywhere;
  }

  .plan-tier-avatar{
    width:56px;
    height:56px;
    font-size:28px;
  }

  .plan-tier-badge{
    position:static;
    justify-self:start;
    width:max-content;
    max-width:100%;
    margin-bottom:2px;
    white-space:normal;
  }

  .plan-current-ribbon{
    position:static;
    justify-self:start;
    width:max-content;
    max-width:100%;
    min-height:28px;
    margin-bottom:0;
    padding:6px 10px;
    border-radius:999px;
  }

  .plan-tier-highlights{
    grid-template-columns:1fr;
  }

  .plans-pricing-grid .plan-tier-highlights{
    gap:10px;
  }

  .plans-pricing-grid .plan-tier-highlights b{
    min-height:44px;
    border-radius:14px;
  }

  .plans-pricing-grid .plan-tier-note{
    border-radius:14px;
  }
}

/* Telefones em paisagem: preserva a largura útil e reduz elementos fixos que
   disputam a pouca altura disponível. */
@media (orientation:landscape) and (max-height:600px) and (max-width:1000px){
  body.mobile-mode{
    --layout-bottom-nav-height:52px;
    --mobile-bottom-nav-height:52px;
  }

  body.mobile-mode #app-content[data-ui-scroll-owner="app-content"]{
    scroll-padding-bottom:calc(52px + env(safe-area-inset-bottom, 0px) + 12px);
  }

  body.mobile-mode .mobile-bottom-nav{
    min-height:52px;
    height:52px;
    padding-block:3px;
  }

  body.mobile-mode .mobile-bottom-nav-button{
    min-height:44px;
    padding:3px 8px;
  }

  body.mobile-mode .mobile-bottom-nav-button span{
    width:24px;
    height:24px;
  }

  body.mobile-mode .mobile-bottom-nav-button small{
    font-size:9px;
    line-height:1;
  }

  body.mobile-mode .ui3-orders{
    padding:10px 14px calc(64px + env(safe-area-inset-bottom, 0px)) !important;
    gap:10px !important;
  }

  body.mobile-mode .ui3-orders .order-filter-chips{
    padding-bottom:4px;
  }

  body.mobile-mode .ui3-orders .order-detail-panel{
    padding:12px;
  }

  body.mobile-mode .ui3-orders .order-detail-total,
  body.mobile-mode .ui3-orders .order-financial-summary.compact{
    grid-template-columns:repeat(2,minmax(0,1fr));
  }

  body.mobile-mode .ui3-orders .order-status-action-strip{
    grid-template-columns:repeat(4,minmax(0,1fr)) !important;
  }

  body.mobile-mode .modal-backdrop{
    align-items:flex-start;
    overflow-y:auto;
    padding:8px max(12px,env(safe-area-inset-right,0px)) 64px max(12px,env(safe-area-inset-left,0px));
  }

  body.mobile-mode .modal-card{
    max-height:none;
    margin:auto;
  }
}

@media(max-width:767px){
  .card.plans-screen{
    display:grid;
  }

  .plans-grid{
    grid-template-columns:1fr;
  }

  .plans-screen .actions{
    grid-template-columns:1fr;
  }
}

.more-group{
  display:grid;
  gap:8px;
}

.more-group h3{
  margin:0;
  color:var(--muted);
  font-size:var(--font-sm);
  font-weight:700;
}

.more-grid{
  grid-template-columns:repeat(auto-fit, minmax(118px, 1fr));
}

.more-item{
  min-height:62px;
  display:flex;
  align-items:center;
  gap:10px;
  padding:10px;
  text-align:left;
  color:var(--text);
  background:linear-gradient(145deg, rgba(255,255,255,.06), rgba(255,255,255,.025));
  border:1px solid var(--card-border);
  border-radius:16px;
  box-shadow:var(--shadow-soft);
  transition:transform .16s ease, border-color .16s ease, filter .16s ease;
}

.more-item:active{
  transform:scale(.975);
}

.more-item span{
  width:32px;
  height:32px;
  display:grid;
  place-items:center;
  border-radius:11px;
  background:rgba(13,189,184,.12);
  border:1px solid rgba(13,189,184,.18);
  color:#21eee5;
}

.account-profile{
  grid-template-columns:auto minmax(0, 1fr) auto;
  align-items:center;
}

.account-profile h2{
  margin:0 0 4px;
}

.account-profile strong,
.account-profile span{
  display:block;
  overflow-wrap:anywhere;
}

.account-avatar{
  width:52px;
  height:52px;
  display:grid;
  place-items:center;
  border-radius:50%;
  background:linear-gradient(135deg, rgba(7,59,75,.92), rgba(255,148,28,.28));
  border:1px solid rgba(255,255,255,.16);
  color:#fff;
  font-weight:800;
  font-size:var(--font-xl);
}

.legal-page-content{
  max-height:none;
  overflow:visible;
}

.metric-button{
  text-align:left;
  border:1px solid var(--line);
  color:var(--text);
  cursor:pointer;
}

.metric-button:hover{
  border-color:var(--primary);
  transform:translateY(-1px);
}

.superadmin-panel{
  max-width:1440px;
}

.superadmin-hero{
  display:flex;
  align-items:flex-start;
  justify-content:space-between;
  gap:14px;
  padding:14px;
  border-radius:20px;
  border:1px solid rgba(13,189,184,.18);
  background:
    radial-gradient(circle at 18% 8%, rgba(13,189,184,.18), transparent 36%),
    linear-gradient(145deg, rgba(14,28,39,.82), rgba(7,11,17,.90));
  box-shadow:var(--shadow-soft);
}

.superadmin-hero h2{
  margin:3px 0 5px;
  font-size:clamp(20px, 3vw, 28px);
}

.superadmin-tabs{
  display:flex;
  gap:8px;
  overflow:auto;
  padding:4px 0 10px;
  scrollbar-width:thin;
}

.tab-button{
  min-height:36px;
  padding:0 13px;
  border-radius:999px;
  border:1px solid var(--card-border);
  background:rgba(255,255,255,.035);
  color:var(--muted);
  font-weight:800;
  font-size:var(--font-xs);
  white-space:nowrap;
  box-shadow:inset 0 1px 0 rgba(255,255,255,.05);
  transition:transform .16s ease, background .16s ease, border-color .16s ease, color .16s ease;
}

.tab-button.active,
.tab-button:hover{
  color:#edffff;
  border-color:rgba(13,189,184,.50);
  background:linear-gradient(145deg, rgba(13,189,184,.18), rgba(7,59,75,.20));
}

.superadmin-content{
  display:grid;
  gap:12px;
}

.chart-grid{
  display:grid;
  grid-template-columns:repeat(2, minmax(0, 1fr));
  gap:12px;
}

.chart-card{
  min-width:0;
  display:grid;
  gap:10px;
  padding:12px;
  position:relative;
  overflow:hidden;
  border-radius:var(--radius);
  border:1px solid var(--card-border);
  background:var(--card-gradient);
  box-shadow:var(--shadow-soft);
}

.chart-svg{
  width:100%;
  min-height:150px;
  display:block;
  background:linear-gradient(180deg, rgba(255,255,255,.04), transparent);
  border-radius:var(--radius);
}

.bar-chart,
.legend-list{
  display:grid;
  gap:8px;
}

.bar-item{
  display:grid;
  grid-template-columns:minmax(70px, .8fr) minmax(120px, 1.5fr) minmax(58px, auto);
  gap:8px;
  align-items:center;
  font-size:var(--font-sm);
}

.bar-track{
  height:10px;
  border-radius:999px;
  background:rgba(255,255,255,.08);
  overflow:hidden;
}

.bar-track i{
  display:block;
  height:100%;
  border-radius:inherit;
  background:linear-gradient(90deg, var(--primary), var(--accent));
}

.pie-chart{
  width:min(170px, 56vw);
  aspect-ratio:1;
  border-radius:50%;
  border:1px solid var(--line);
  box-shadow:inset 0 0 0 18px rgba(0,0,0,.18);
  justify-self:center;
}

.legend-list span{
  display:flex;
  gap:8px;
  align-items:center;
  color:var(--muted);
  font-size:var(--font-sm);
}

.legend-list i{
  width:10px;
  height:10px;
  border-radius:50%;
  flex:0 0 auto;
}

.payment-table{
  display:grid;
  gap:8px;
}

.payment-row{
  display:grid;
  grid-template-columns:repeat(6, minmax(0, 1fr));
  gap:8px;
  align-items:center;
  padding:10px;
  position:relative;
  overflow:hidden;
  border:1px solid var(--card-border);
  border-radius:var(--radius);
  background:var(--card-gradient);
  box-shadow:var(--shadow-soft);
}

.payment-row > *{
  min-width:0;
  overflow-wrap:anywhere;
}

.admin-table .payment-row{
  grid-template-columns:minmax(110px, 1fr) minmax(90px, .7fr) minmax(90px, .8fr) minmax(90px, .7fr) minmax(120px, 1fr) auto;
}

.telemetry-table .payment-row{
  grid-template-columns:minmax(150px, 1.4fr) repeat(8, minmax(70px, .75fr)) minmax(110px, .8fr);
}

.telemetry-table small{
  display:block;
  color:var(--muted);
  font-size:var(--font-xs);
  margin-top:4px;
}

.diagnostics-codex-report{
  width:100%;
  min-height:18rem;
  resize:vertical;
  font-family:ui-monospace,SFMono-Regular,Menlo,Consolas,monospace;
  font-size:var(--font-sm);
  line-height:1.55;
  color:var(--text-primary);
  background:var(--surface-primary);
  border:1px solid var(--border-soft);
  border-radius:var(--radius-lg);
  padding:var(--space-lg);
}

.comparison-grid{
  display:grid;
  grid-template-columns:repeat(4, minmax(0, 1fr));
  gap:8px;
}

.client-admin-row{
  display:grid;
  grid-template-columns:minmax(180px, 1.4fr) auto auto auto minmax(110px, .6fr) minmax(220px, 1fr);
  gap:10px;
  align-items:center;
  padding:10px;
  margin-top:8px;
  position:relative;
  overflow:hidden;
  cursor:pointer;
  touch-action:pan-y;
  background:var(--card-gradient);
  border:1px solid var(--card-border);
  border-radius:var(--radius);
  box-shadow:var(--shadow-soft);
}

.client-admin-row:hover,
.client-admin-row.selected{
  border-color:rgba(255,148,28,.58);
  box-shadow:0 0 0 1px rgba(255,148,28,.16), var(--shadow-soft);
}

.client-admin-row strong,
.client-admin-row span{
  overflow-wrap:anywhere;
}

.client-admin-row > *{
  position:relative;
  z-index:1;
}

.client-admin-row .row-actions{
  cursor:default;
}

.client-meta{
  display:grid;
  gap:3px;
  color:var(--muted);
  font-size:var(--font-sm);
}

.modal-backdrop{
  position:fixed;
  inset:0;
  z-index:var(--z-modal);
  display:grid;
  place-items:center;
  padding:18px;
  background:rgba(0,0,0,.55);
}

.modal-card{
  width:min(460px, 100%);
  display:grid;
  gap:12px;
  padding:14px;
  border-radius:var(--radius);
  background:var(--card-gradient-strong);
  border:1px solid var(--card-border);
  box-shadow:0 24px 70px rgba(0,0,0,.42), inset 0 1px 0 rgba(255,255,255,.05);
}

.modal-card .muted{
  white-space:pre-line;
}

.limit-modal .actions{
  grid-template-columns:repeat(2, minmax(0, 1fr));
}

.legal-modal{
  width:min(720px, 100%);
  max-height:min(86vh, 760px);
  grid-template-rows:auto minmax(0, 1fr) auto;
}

.legal-content{
  min-height:0;
  overflow:auto;
  display:grid;
  gap:12px;
  padding-right:4px;
}

.legal-section{
  display:grid;
  gap:6px;
  padding:10px;
  border-radius:var(--radius);
  background:var(--panel-2);
  border:1px solid var(--line);
}

.legal-section h3{
  margin:0;
  font-size:var(--font-md);
}

.legal-section ul{
  margin:0;
  padding-left:18px;
  color:var(--muted);
  font-size:var(--font-sm);
  line-height:1.45;
}

.legal-section li + li{
  margin-top:5px;
}

.legal-actions{
  grid-template-columns:repeat(2, minmax(0, 1fr));
}

.onboarding-card .actions{
  grid-template-columns:repeat(3, minmax(0, 1fr));
}

.progress-steps{
  display:flex;
  gap:8px;
  margin:8px 0 4px;
}

.progress-steps span{
  display:block;
  height:6px;
  flex:1;
  border-radius:999px;
  background:rgba(148,163,184,.22);
}

.progress-steps span.active{
  background:var(--accent);
}

.badge-pendente,
.badge-atrasado,
.badge-overdue{
  background:rgba(245,158,11,.16);
  color:#fbbf24;
}

.badge-blocked,
.badge-bloqueado,
.badge-cancelled,
.badge-cancelado{
  background:rgba(239,68,68,.16);
  color:#fca5a5;
}

@media (max-width: 900px){
  .dashboard-kpis{
    grid-template-columns:repeat(2, minmax(0, 1fr));
  }

  .kpi-card{
    min-height:104px;
    grid-template-columns:34px minmax(0, 1fr);
    gap:8px;
    padding:10px;
  }

  .kpi-icon{
    width:34px;
    height:34px;
  }

  .kpi-card strong{
    font-size:24px;
  }

  .client-admin-row,
  .comparison-grid{
    grid-template-columns:1fr;
  }

  .onboarding-card .actions,
  .limit-modal .actions{
    grid-template-columns:1fr;
  }
}

.device-list{
  display:grid;
  gap:8px;
  margin-top:10px;
  padding:10px;
  border-radius:var(--radius);
  background:var(--panel-2);
  border:1px solid var(--line);
}

.device-row{
  display:grid;
  grid-template-columns:minmax(0, 1fr) auto;
  gap:8px;
  align-items:center;
  padding:8px;
  border-radius:8px;
  background:var(--panel);
  border:1px solid var(--line);
}

.device-row strong,
.device-row span{
  display:block;
  overflow-wrap:anywhere;
}

.admin-grid,
.sync-grid{
  display:grid;
  grid-template-columns:repeat(2, minmax(0, 1fr));
  gap:8px;
}

.sync-grid{
  margin-top:10px;
