.toast-area{
  position:fixed;
  right:16px;
  bottom:16px;
  z-index:var(--z-toast);
  display:grid;
  gap:8px;
  width:min(360px, calc(100vw - 32px));
  pointer-events:none;
}

.app-toast{
  display:flex;
  align-items:center;
  gap:10px;
  padding:12px 14px;
  border:1px solid rgba(255,255,255,.12);
  border-radius:10px;
  background:rgba(8,20,28,.96);
  box-shadow:0 18px 40px rgba(0,0,0,.28);
  color:var(--text);
  animation:toast-in .18s ease-out;
}

.app-toast.leaving{
  animation:toast-out .22s ease-in forwards;
}

.toast-icon{
  display:grid;
  place-items:center;
  width:24px;
  height:24px;
  border-radius:50%;
  font-weight:800;
  background:rgba(255,255,255,.08);
}

.toast-sucesso .toast-icon{
  background:rgba(34,197,94,.18);
  color:#4ade80;
}

.toast-erro .toast-icon{
  background:rgba(239,68,68,.18);
  color:#f87171;
}

.toast-warning .toast-icon{
  background:rgba(255,148,28,.18);
  color:#ffb15f;
}

.toast-loading .toast-icon{
  color:#ffb15f;
  animation:pulse-dots 1s infinite;
}

.sync-indicator{
  position:fixed;
  right:calc(18px + env(safe-area-inset-right));
  bottom:calc(96px + env(safe-area-inset-bottom));
  z-index:9998;
  display:inline-flex;
  align-items:center;
  gap:8px;
  min-height:34px;
  padding:7px 11px;
  border:1px solid rgba(255,255,255,.12);
  border-radius:999px;
  background:rgba(5,18,25,.88);
  color:#e9fbff;
  box-shadow:0 14px 34px rgba(0,0,0,.26);
  backdrop-filter:blur(12px);
  -webkit-backdrop-filter:blur(12px);
  opacity:1;
  transform:translateY(0);
  transition:opacity .18s ease, transform .18s ease;
  pointer-events:none;
}

.sync-indicator.is-hidden{
  opacity:0;
  transform:translateY(6px);
}

.sync-indicator strong{
  font-size:12px;
  font-weight:700;
  letter-spacing:0;
}

.sync-spinner{
  width:14px;
  height:14px;
  border-radius:50%;
  border:2px solid rgba(255,255,255,.22);
  border-top-color:#39d4d8;
  animation:sync-spin .78s linear infinite;
}

.sync-success .sync-spinner{
  border-color:rgba(63,220,139,.35);
  background:#3fdc8b;
  animation:none;
  box-shadow:0 0 14px rgba(63,220,139,.32);
}

.sync-error .sync-spinner,
.sync-pending .sync-spinner{
  border-top-color:#ffb15f;
}

.sync-pending{
  border-color:color-mix(in srgb, var(--color-warning, #ffb15f) 32%, var(--color-border, rgba(255,255,255,.12)));
}

.sync-error{
  border-color:color-mix(in srgb, var(--color-danger, #f87171) 34%, var(--color-border, rgba(255,255,255,.12)));
}

@keyframes sync-spin{
  to{transform:rotate(360deg)}
}

@keyframes toast-in{
  from{opacity:0; transform:translateY(8px)}
  to{opacity:1; transform:translateY(0)}
}

@keyframes toast-out{
  to{opacity:0; transform:translateY(8px)}
}

@keyframes pulse-dots{
  0%,100%{opacity:.45}
  50%{opacity:1}
}

