  background:rgba(7,13,20,.84);
  border-top:1px solid rgba(255,255,255,.10);
  padding:6px 5px calc(6px + env(safe-area-inset-bottom));
  box-shadow:0 -14px 30px rgba(0,0,0,.34);
  backdrop-filter:blur(12px);
}

.menu-button{
  min-height:52px;
  display:flex;
  flex-direction:column;
  align-items:center;
  justify-content:center;
  gap:2px;
  background:transparent;
  color:var(--muted);
  border:1px solid transparent;
  border-radius:17px;
  transition:transform .16s ease, background .16s ease, border-color .16s ease, color .16s ease, filter .16s ease;
}

.menu-button span{
  width:28px;
  height:24px;
  display:inline-flex;
  align-items:center;
  justify-content:center;
  font-size:var(--font-md);
  line-height:1;
  color:#b8c6d2;
}

.menu-button small{
  font-size:calc(var(--font-xs) - 2px);
  line-height:1;
}

.menu-button.active{
  color:#0ff2e7;
  background:rgba(13,189,184,.12);
  border-color:rgba(13,189,184,.20);
  box-shadow:0 10px 20px rgba(0,0,0,.18), inset 0 1px 0 rgba(255,255,255,.08);
}

.menu-button.active span{
  color:#0ff2e7;
}

.mobile-bottom-nav{
  position:fixed;
  left:12px;
  right:12px;
  bottom:10px;
  z-index:54;
  display:none;
  grid-template-columns:repeat(4, minmax(0, 1fr));
  gap:4px;
  padding:7px 8px calc(7px + env(safe-area-inset-bottom));
  border:1px solid rgba(255,255,255,.12);
  border-radius:26px;
  background:rgba(7,13,20,.76);
  box-shadow:0 18px 38px rgba(0,0,0,.38), inset 0 1px 0 rgba(255,255,255,.08);
  backdrop-filter:blur(12px);
  transform:translateZ(0);
}

.mobile-bottom-nav-button{
  position:relative;
  min-height:50px;
  display:flex;
  flex-direction:column;
  align-items:center;
  justify-content:center;
  gap:3px;
  padding:5px 2px;
  color:var(--muted);
  background:transparent;
  border:1px solid transparent;
  border-radius:18px;
  overflow:hidden;
  transition:transform 200ms var(--motion-ease), background 240ms var(--motion-ease), color 200ms ease, border-color 200ms ease, box-shadow 240ms var(--motion-ease);
}

.mobile-bottom-nav-button::before{
  content:"";
  position:absolute;
  inset:7px 10px auto;
  height:3px;
  border-radius:999px;
  background:linear-gradient(90deg, transparent, #0ff2e7, transparent);
  opacity:0;
  transform:scaleX(.45);
  transition:opacity 260ms ease, transform 320ms var(--motion-ease-emphasis);
}

.mobile-bottom-nav-button span{
  width:26px;
  height:24px;
  display:inline-flex;
  align-items:center;
  justify-content:center;
  font-size:18px;
  line-height:1;
  color:#c0c8d2;
  transition:transform 260ms var(--motion-ease-emphasis), color 200ms ease;
}

.mobile-bottom-nav-button small{
  max-width:100%;
  overflow:hidden;
  text-overflow:ellipsis;
  white-space:nowrap;
  font-size:10px;
  line-height:1.1;
  opacity:.76;
  transform:translateY(1px);
  transition:opacity 220ms ease, transform 260ms var(--motion-ease);
}

.mobile-bottom-nav-button.active{
  color:#0ff2e7;
  background:rgba(13,189,184,.12);
  border-color:rgba(13,189,184,.20);
  box-shadow:0 10px 20px rgba(0,0,0,.22), inset 0 1px 0 rgba(255,255,255,.10);
}

.mobile-bottom-nav-button.active::before{
  opacity:.9;
  transform:scaleX(1);
}

.mobile-bottom-nav-button.active span{
  color:#0ff2e7;
  transform:translateY(-2px) scale(1.08);
}

.mobile-bottom-nav-button.active small{
  opacity:1;
  transform:translateY(0);
}

.mobile-bottom-nav-button:active{
  transform:scale(.96);
}

.calc-float-ball{
  position:fixed;
  right:14px;
  bottom:calc(18px + env(safe-area-inset-bottom));
  z-index:60;
  width:var(--floating-button-size);
  min-width:var(--floating-button-size);
  height:var(--floating-button-size);
  min-height:var(--floating-button-size);
  display:flex;
  align-items:center;
  justify-content:center;
  border-radius:50%;
  background:var(--info);
  color:#fff;
  border:1px solid color-mix(in srgb, var(--info) 70%, #fff);
  box-shadow:0 14px 32px rgba(0,0,0,.32);
  font-size:var(--font-xl);
}

.calc-float-ball span{
  line-height:1;
}

.calc-widget-window{
  position:fixed;
  z-index:72;
  min-width:280px;
  min-height:320px;
  display:flex;
  flex-direction:column;
  overflow:hidden;
  background:var(--panel);
  border:1px solid var(--line);
  border-radius:var(--radius);
  box-shadow:0 22px 60px rgba(0,0,0,.45);
}

.calc-widget-window.is-moving,
.calc-widget-window.is-resizing{
  user-select:none;
  opacity:.96;
  border-color:var(--primary);
}

.calc-widget-titlebar{
  min-height:38px;
  display:flex;
  align-items:center;
  justify-content:space-between;
  gap:8px;
  padding:5px 6px 5px 10px;
  background:var(--chrome);
  border-bottom:1px solid var(--line);
  cursor:grab;
  touch-action:none;
}

.calc-widget-titlebar:active{
  cursor:grabbing;
}

.calc-widget-content{
  min-height:0;
  flex:1;
  overflow:auto;
  padding:var(--card-padding);
}

.calc-widget-resize{
  position:absolute;
  right:0;
  bottom:0;
  width:20px;
  height:20px;
  cursor:nwse-resize;
  touch-action:none;
}

.calc-widget-resize::after{
  content:"";
  position:absolute;
  right:4px;
  bottom:4px;
  width:10px;
  height:10px;
  border-right:2px solid var(--muted);
  border-bottom:2px solid var(--muted);
  opacity:.85;
}

.mobile-panel{
  position:fixed;
  inset:0;
  z-index:35;
  display:flex;
  flex-direction:column;
  background:linear-gradient(180deg, #111720 0%, var(--bg) 42%, #07090d 100%);
  padding-bottom:var(--safe-area-inset-bottom, env(safe-area-inset-bottom));
}

.mobile-panel-bar{
  min-height:calc(var(--mobile-header-height) + var(--safe-area-inset-top, env(safe-area-inset-top)));
  margin:0;
  padding:calc(var(--safe-area-inset-top, env(safe-area-inset-top)) + 8px) 10px 8px;
  background:linear-gradient(180deg, rgba(10,13,19,.96), rgba(8,10,15,.92));
  border-bottom:1px solid var(--line);
  box-shadow:0 10px 24px rgba(0,0,0,.22);
  backdrop-filter:blur(10px);
}

.mobile-panel-content{
  flex:1;
  overflow:auto;
  padding:var(--gap);
  padding-bottom:calc(96px + var(--safe-area-inset-bottom, env(safe-area-inset-bottom)));
}

.popup{
  position:fixed;
  inset:0;
  z-index:var(--z-modal);
  display:flex;
  align-items:center;
  justify-content:center;
  padding:14px;
  background:rgba(0,0,0,.72);
}

.side-drawer-backdrop{
  position:fixed;
  inset:0;
  z-index:var(--z-drawer);
  display:flex;
  align-items:stretch;
  justify-content:flex-start;
  padding:10px;
  background:rgba(0,0,0,.58);
}

.side-drawer{
  position:relative;
  top:auto;
  width:min(340px, calc(100vw - 20px));
  max-height:calc(100dvh - 20px);
  overflow:auto;
  animation:drawerIn .16s ease-out;
}

.side-drawer .side-brand{
  position:sticky;
  top:0;
  z-index:2;
}

@keyframes drawerIn{
  from{
    transform:translateX(-14px);
    opacity:.6;
  }
  to{
    transform:translateX(0);
    opacity:1;
  }
}

.popup-box{
  width:min(480px, 100%);
  max-height:90vh;
  overflow:auto;
  background:var(--card-gradient-strong);
  border:1px solid var(--card-border);
  border-radius:var(--radius);
  padding:var(--card-padding);
  box-shadow:0 22px 60px rgba(0,0,0,.46), inset 0 1px 0 rgba(255,255,255,.05);
}

.menu-popup-box{
  width:min(620px, 100%);
}

.menu-popup-section{
  display:grid;
  gap:8px;
  margin-top:10px;
}

.menu-popup-section > span{
  color:var(--muted);
  font-size:var(--font-xs);
}

.menu-popup-grid{
  display:grid;
  grid-template-columns:repeat(3, minmax(0, 1fr));
  gap:8px;
}

.popup-nav-button{
  min-height:var(--popup-nav-min-height);
  display:grid;
  align-content:center;
  justify-items:start;
  gap:6px;
  padding:10px;
  background:var(--card-gradient);
  color:var(--text);
  border:1px solid var(--card-border);
  text-align:left;
  box-shadow:var(--shadow-soft);
}

.popup-nav-button span{
  font-size:var(--font-xl);
  color:var(--primary-2);
}

.popup-nav-button strong{
  font-size:var(--font-sm);
  overflow-wrap:anywhere;
}

.popup-nav-button.active{
  border-color:rgba(255,148,28,.58);
  background:linear-gradient(145deg, rgba(255,148,28,.18), rgba(7,59,75,.24));
}

.calc-grid{
  display:grid;
  grid-template-columns:repeat(2, minmax(0, 1fr));
  gap:8px;
}

.calc-material-row{
  display:grid;
  grid-template-columns:minmax(0, 1fr);
  gap:8px;
}

.calc-stock-hint{
  margin-top:-4px;
  font-size:var(--font-xs);
}

.material-color-palette{
  display:flex;
  flex-wrap:wrap;
  gap:7px;
  margin-top:8px;
}

.material-color-chip{
  display:inline-flex;
  align-items:center;
  gap:6px;
  min-height:34px;
  padding:6px 9px;
  border-radius:999px;
  border:1px solid var(--line);
  background:rgba(255,255,255,.045);
  color:var(--text);
  font-size:var(--font-xs);
  cursor:pointer;
  transition:transform .16s ease, border-color .16s ease, background .16s ease;
}

.material-color-chip:hover,
.material-color-chip.active{
  transform:translateY(-1px);
  border-color:rgba(255,148,28,.55);
  background:rgba(255,148,28,.12);
}

.material-color-dot{
  width:15px;
  height:15px;
  border-radius:50%;
  border:1px solid rgba(255,255,255,.55);
  box-shadow:0 0 0 1px rgba(0,0,0,.12);
  flex:0 0 auto;
}

.result-box{
  margin-top:8px;
  padding:10px;
  border-radius:var(--radius);
  background:var(--result-bg, #111419);
  border:1px solid var(--line);
  color:var(--text);
  line-height:1.5;
}

.calc-modern-screen{
  max-width:920px;
  display:grid;
  gap:12px;
  background:
    radial-gradient(circle at 12% 0%, rgba(13,189,184,.18), transparent 36%),
    linear-gradient(145deg, rgba(12,24,34,.92), rgba(5,11,17,.96));
}

.calc-toolbar,
.calc-section-title,
.calc-primary-actions{
  display:flex;
  align-items:center;
  justify-content:space-between;
  gap:10px;
}

.calc-toolbar strong{
  font-size:var(--font-xl);
  letter-spacing:0;
}

.calc-active-profile,
.calc-smart-tip,
.calc-input-panel,
.calc-summary-card,
.calc-secondary-actions{
  border:1px solid rgba(134,240,255,.14);
  border-radius:20px;
  background:linear-gradient(145deg, rgba(18,31,42,.86), rgba(7,14,22,.90));
  box-shadow:var(--shadow-soft);
}

.calc-active-profile{
  display:grid;
  grid-template-columns:84px minmax(0, 1fr) auto;
  gap:14px;
  align-items:center;
  padding:14px;
  border-color:rgba(13,189,184,.34);
}

.calc-printer-art{
  width:84px;
  height:84px;
  display:grid;
  place-items:center;
  border-radius:20px;
  background:
    radial-gradient(circle at 65% 70%, rgba(13,189,184,.42), transparent 42%),
    rgba(255,255,255,.06);
  color:#eaffff;
}

.calc-printer-art svg{
  width:42px;
  height:42px;
}

.calc-active-profile span,
.calc-smart-tip strong{
  color:#0ff2e7;
  font-weight:900;
}

.calc-active-profile strong{
  display:block;
  margin:3px 0;
  font-size:24px;
  line-height:1.1;
}

.calc-active-profile small,
.calc-active-profile em,
.calc-smart-tip small{
  display:block;
  color:var(--muted);
  font-style:normal;
}

.calc-smart-tip{
  display:grid;
  grid-template-columns:42px minmax(0, 1fr) auto 36px;
  gap:10px;
  align-items:center;
  padding:10px 12px;
}

.calc-tip-icon{
  width:42px;
  height:42px;
  display:grid;
  place-items:center;
  border-radius:50%;
  color:#ffe9a8;
  background:rgba(255,171,0,.14);
  border:1px solid rgba(255,171,0,.24);
}

.calc-input-panel{
  display:grid;
  gap:12px;
  padding:14px;
}

.calc-section-title strong{
  display:inline-flex;
  align-items:center;
  gap:8px;
  font-size:var(--font-lg);
}

.calc-section-title svg{
  width:20px;
  height:20px;
}

.calc-modern-grid{
  display:grid;
  grid-template-columns:repeat(2, minmax(0, 1fr));
  gap:10px;
}

.calc-batch-toggle{
  min-height:48px;
  display:flex;
  align-items:center;
  gap:10px;
  padding:10px 12px;
  border:1px solid var(--border-primary);
  border-radius:var(--radius-card);
  background:var(--card-bg);
  cursor:pointer;
}

.calc-batch-toggle input{
  width:18px;
  height:18px;
  margin:0;
  accent-color:var(--accent-primary);
}

.calc-batch-toggle span{
  display:grid;
  gap:2px;
}

.calc-batch-toggle small,
.calc-batch-fields > small{
  color:var(--text-muted);
  font-size:var(--font-xs);
}

.calc-batch-fields{
  display:grid;
  grid-template-columns:minmax(180px, 240px) minmax(0, 1fr);
  align-items:center;
  gap:10px;
}

.calc-batch-fields[hidden]{
  display:none !important;
}

.calc-batch-fields .calc-field-card{
  width:100%;
}

.calc-field-card{
  position:relative;
  min-height:118px;
  margin:0;
  padding:14px;
  justify-content:space-between;
  border:1px solid rgba(255,255,255,.12);
  border-radius:16px;
  background:rgba(5,12,19,.54);
}

.calc-field-card.wide{
  grid-column:1 / -1;
}

.calc-field-card input,
.calc-field-card select{
  min-height:42px;
  padding:0;
  border:0;
  border-radius:0;
  background:transparent;
  box-shadow:none;
  font-size:24px;
  font-weight:900;
}

.calc-field-card select{
  font-size:20px;
}

.calc-field-card select,
.calc-material-select{
  color:var(--color-text-primary);
  background:color-mix(in srgb, var(--color-input) 92%, transparent);
}

.calc-field-card select option,
.calc-material-select option{
  color:var(--color-text-primary);
  background:var(--color-input);
}

body:not(.theme-light) .calc-field-card select,
body:not(.theme-light) .calc-material-select,
body:not(.theme-light) .calc-field-card select option,
body:not(.theme-light) .calc-material-select option,
body.theme-light .calc-field-card select,
body.theme-light .calc-material-select,
body.theme-light .calc-field-card select option,
body.theme-light .calc-material-select option{
  color:var(--color-text-primary);
  background:var(--color-input);
}

.calc-field-card i{
  position:absolute;
  right:14px;
  bottom:16px;
  display:grid;
  place-items:center;
  min-width:34px;
  height:34px;
  padding:0 8px;
  border-radius:10px;
  color:var(--muted);
  background:rgba(255,255,255,.07);
  font-style:normal;
  font-weight:900;
}

.calc-quick-fees{
  display:grid;
  grid-template-columns:repeat(5, minmax(0, 1fr));
  gap:8px;
}

.calc-quick-fees button{
  min-height:38px;
  border-radius:12px;
  border:1px solid rgba(255,255,255,.12);
  background:rgba(255,255,255,.04);
  color:var(--muted);
  font-weight:800;
}

.calc-quick-fees button:focus-visible,
.calc-quick-fees button:hover{
  color:#0ff2e7;
  border-color:rgba(13,189,184,.58);
  outline:none;
}

.calc-result-modern{
  padding:0;
  border:0;
  background:transparent;
}

.calc-summary-card{
  display:grid;
  gap:10px;
  padding:14px;
}

.calc-summary-head,
.calc-final-row{
  display:flex;
  align-items:center;
  justify-content:space-between;
  gap:10px;
}

.calc-summary-head strong{
  display:inline-flex;
  align-items:center;
  gap:8px;
  font-size:var(--font-lg);
}

.calc-summary-lines{
  display:grid;
  grid-template-columns:minmax(0, 1fr) auto;
  gap:8px 12px;
  padding-bottom:10px;
  border-bottom:1px solid rgba(255,255,255,.10);
}

.calc-summary-lines.is-collapsed{
  display:none;
}

.calc-summary-lines span,
.calc-margin-status{
  color:var(--muted);
}

.calc-final-row span{
  font-size:var(--font-lg);
  font-weight:900;
}

.calc-final-row strong{
  color:#0ff2c7;
  font-size:34px;
  line-height:1;
}

.calc-main-action{
  flex:1;
  min-height:70px;
  justify-content:center;
  gap:12px;
  font-size:var(--font-lg);
}

.calc-main-action svg{
  width:28px;
  height:28px;
}

.calc-main-action span{
  display:grid;
  text-align:left;
}

.calc-main-action small{
  color:rgba(255,255,255,.72);
  font-size:var(--font-sm);
}

.calc-save-action{
  width:188px;
  min-height:70px;
}

.calc-secondary-actions{
  display:grid;
  grid-template-columns:repeat(4, minmax(0, 1fr));
  gap:1px;
  overflow:hidden;
}

.calc-secondary-actions .action-tile{
  border:0;
  border-left:1px solid rgba(255,255,255,.08);
  border-radius:0;
  background:transparent;
}

.calc-settings-grid{
  display:grid;
  grid-template-columns:repeat(2, minmax(0, 1fr));
  gap:10px;
}

.dashboard-grid{
  display:grid;
  grid-template-columns:repeat(12, minmax(0, 1fr));
  align-items:stretch;
}

.window-workspace{
  position:relative;
  min-width:0;
  width:100%;
  overflow:auto;
  border:1px solid var(--card-border);
  border-radius:var(--radius);
  background:
    linear-gradient(rgba(255,255,255,.045) 1px, transparent 1px),
    linear-gradient(90deg, rgba(255,255,255,.045) 1px, transparent 1px),
    color-mix(in srgb, var(--panel) 82%, #000 18%);
  background-size:24px 24px;
  box-shadow:var(--shadow);
}

.tile-workspace{
  display:grid;
  grid-template-columns:repeat(12, minmax(0, 1fr));
  grid-auto-rows:minmax(260px, 1fr);
  grid-auto-flow:dense;
  gap:var(--gap);
  align-items:stretch;
  align-content:start;
  padding:var(--gap);
  overflow:visible;
}

.dashboard-window{
  position:absolute;
  min-width:280px;
  min-height:230px;
  display:flex;
  flex-direction:column;
  overflow:hidden;
  background:var(--card-gradient);
  border:1px solid var(--card-border);
  border-radius:var(--radius);
  box-shadow:var(--shadow);
}

.tile-workspace .dashboard-window{
  position:relative;
  left:auto;
  top:auto;
  width:auto;
  height:100%;
  min-width:0;
  min-height:var(--window-min-height);
  grid-column:span 4;
}

.tile-workspace .dashboard-window.window-size-s{
  grid-column:span 4;
}

.tile-workspace .dashboard-window.window-size-m{
  grid-column:span 5;
}

.tile-workspace .dashboard-window.window-size-l{
  grid-column:span 7;
}

.tile-workspace .dashboard-window.window-size-xl{
  grid-column:1 / -1;
}

.dashboard-window.is-moving,
.dashboard-window.is-resizing{
  user-select:none;
  opacity:.94;
  border-color:var(--primary);
}

.window-titlebar{
  min-height:36px;
  display:flex;
  align-items:center;
  justify-content:space-between;
  gap:8px;
  padding:4px 6px 4px 10px;
  background:linear-gradient(180deg, rgba(9,12,18,.94), rgba(13,16,23,.94));
  border-bottom:1px solid rgba(255,255,255,.08);
  cursor:grab;
  touch-action:none;
}

.tile-workspace .window-titlebar{
  cursor:grab;
}

.window-titlebar:active{
  cursor:grabbing;
}

.window-title{
  min-width:0;
  display:flex;
  align-items:center;
  gap:7px;
  font-size:var(--font-sm);
}

.window-title strong{
  overflow:hidden;
  text-overflow:ellipsis;
  white-space:nowrap;
}

.window-actions{
  display:flex;
  gap:4px;
}

.window-actions .icon-button{
  width:28px;
  min-width:28px;
  height:28px;
  min-height:28px;
  border-radius:7px;
