/* Premium motion system: reusable, transform/opacity only for Android/PWA performance. */
@keyframes fadeInPremium{from{opacity:0}to{opacity:1}}
@keyframes slideUpPremium{from{opacity:0;transform:translate3d(0,14px,0)}to{opacity:1;transform:translate3d(0,0,0)}}
@keyframes scaleInPremium{from{opacity:0;transform:scale(.96)}to{opacity:1;transform:scale(1)}}
@keyframes shimmerPremium{from{background-position:-160% 0}to{background-position:160% 0}}
@keyframes barRisePremium{from{transform:scaleY(.05);opacity:.45}to{transform:scaleY(1);opacity:1}}
@keyframes lineDrawPremium{from{stroke-dashoffset:620}to{stroke-dashoffset:0}}

.fade-in{animation:fadeInPremium .22s ease both}
.slide-up{animation:slideUpPremium .28s ease both}
.scale-in,.modal-enter{animation:scaleInPremium .26s ease both}
.glass-pop{animation:scaleInPremium .28s cubic-bezier(.2,.8,.2,1) both}
.card-enter{animation:slideUpPremium .28s ease both}
.chart-enter{animation:slideUpPremium .36s ease both}
.skeleton-loading{
  min-height:72px;
  border-radius:var(--radius);
  background:linear-gradient(90deg, rgba(255,255,255,.045), rgba(255,255,255,.10), rgba(255,255,255,.045));
  background-size:220% 100%;
  animation:shimmerPremium 1.1s linear infinite;
}

body[data-motion="low"] *{
  animation-duration:.01ms !important;
  animation-iteration-count:1 !important;
  transition-duration:.01ms !important;
  scroll-behavior:auto !important;
}

body[data-motion="low"]{
  --glass-blur:0px;
  --shadow:0 8px 18px rgba(0,0,0,.22), inset 0 1px 0 rgba(255,255,255,.04);
  --shadow-soft:0 5px 12px rgba(0,0,0,.18), inset 0 1px 0 rgba(255,255,255,.035);
}

@media (prefers-reduced-motion: reduce){
  *{
    animation-duration:.01ms !important;
    animation-iteration-count:1 !important;
    transition-duration:.01ms !important;
    scroll-behavior:auto !important;
  }
}

