.drawer-gesture-rail{
  position:fixed;
  left:28px;
  top:calc(74px + var(--safe-area-inset-top, env(safe-area-inset-top, 0px)));
  bottom:calc(108px + env(safe-area-inset-bottom));
  z-index:34;
  width:18px;
  border-radius:999px;
  touch-action:pan-y;
  background:linear-gradient(180deg, rgba(134,240,255,.08), rgba(255,148,28,.05));
  opacity:.10;
  pointer-events:none;
}

.drawer-gesture-rail:active{
  opacity:.42;
}

.drawer-gesture-hint{
  --drawer-hint-progress:0;
  --drawer-hint-hue:142;
  --drawer-hint-alpha:.10;
  position:fixed;
  left:0;
  top:0;
  bottom:0;
  z-index:calc(var(--z-drawer) - 1);
  width:min(46vw, 180px);
  pointer-events:none;
  opacity:0;
  transform:translateX(-18px);
  transition:opacity 120ms ease, transform 120ms ease;
}

.drawer-gesture-hint::before{
  content:"";
  position:absolute;
  inset:0;
  background:
    radial-gradient(ellipse at left center,
      hsla(var(--drawer-hint-hue), 78%, 58%, var(--drawer-hint-alpha)) 0%,
      hsla(var(--drawer-hint-hue), 78%, 58%, calc(var(--drawer-hint-alpha) * .58)) 28%,
      transparent 72%);
  filter:blur(10px);
  transform:scaleX(calc(.55 + var(--drawer-hint-progress) * .7));
  transform-origin:left center;
}

.drawer-gesture-hint::after{
  content:"";
  position:absolute;
  left:24px;
  top:calc(50% - 40px);
  width:4px;
  height:80px;
  border-radius:999px;
  background:hsla(var(--drawer-hint-hue), 78%, 58%, calc(var(--drawer-hint-alpha) * 1.55));
  box-shadow:0 0 20px hsla(var(--drawer-hint-hue), 78%, 58%, calc(var(--drawer-hint-alpha) * 1.6));
  opacity:.62;
}

.drawer-gesture-hint.is-active{
  opacity:1;
  transform:translateX(0);
}

.drawer-gesture-hint.is-ready::after{
  opacity:.82;
}

