/* SuperAdmin/Admin polish: compact cards, consistent icons and action grids */
.superadmin-panel{
  width:100%;
  max-width:1180px;
  margin:0 auto;
  display:grid;
  gap:14px;
}

.superadmin-titlebar{
  display:grid;
  grid-template-columns:42px minmax(0, 1fr) auto;
  align-items:center;
  gap:12px;
  padding:4px 0 12px;
  border-bottom:1px solid rgba(255,255,255,.08);
}

.superadmin-brand{
  display:flex;
  align-items:center;
  gap:10px;
  min-width:0;
  font-size:var(--font-title);
}

.superadmin-crown,
.superadmin-kpi-icon{
  width:38px;
  height:38px;
  display:grid;
  place-items:center;
  border-radius:13px;
  color:#9b6cff;
  background:linear-gradient(145deg, rgba(126,76,255,.26), rgba(74,31,158,.18));
  border:1px solid rgba(155,108,255,.42);
  box-shadow:0 10px 24px rgba(89,55,190,.22), inset 0 1px 0 rgba(255,255,255,.10);
}

.superadmin-crown svg,
.superadmin-kpi-icon svg,
.admin-modern-panel .btn svg,
.clients-saas-panel .card-header svg{
  width:20px;
  height:20px;
}

.superadmin-titlebar .icon-action-button{
  width:40px;
  min-width:40px;
  height:40px;
  min-height:40px;
  border-radius:14px;
  color:#f5f7ff;
}

.superadmin-titlebar .superadmin-feedback-button{
  width:auto;
  max-width:none;
  padding:0 10px;
  display:inline-flex;
  align-items:center;
  gap:6px;
  font-size:11px;
  font-weight:800;
}

.superadmin-hero{
  display:grid;
  grid-template-columns:minmax(0, 1fr) auto;
  align-items:center;
  gap:12px;
  padding:14px 0 4px;
  border:0;
  background:none;
  box-shadow:none;
}

.superadmin-hero h2{
  margin:0 0 4px;
  font-size:clamp(21px, 3vw, 30px);
}

.superadmin-date-filter{
  width:auto !important;
  min-width:110px;
  min-height:44px;
  display:inline-flex;
  align-items:center;
  gap:8px;
  border-radius:13px;
}

.superadmin-date-filter svg{
  width:18px;
  height:18px;
}

.superadmin-tabs{
  gap:8px;
  padding:2px 0 6px;
}

.superadmin-tabs .tab-button{
  flex:0 0 auto !important;
  width:auto !important;
  min-width:max-content;
  max-width:none !important;
}

.superadmin-kpi-grid{
  display:grid;
  grid-template-columns:repeat(4, minmax(0, 1fr));
  gap:12px;
}

.superadmin-kpi-card,
.superadmin-plan-card,
.superadmin-recent-row{
  position:relative;
  min-width:0;
  overflow:hidden;
  border:1px solid rgba(255,255,255,.09);
  color:var(--text);
  background:
    radial-gradient(circle at 18% 12%, rgba(126,76,255,.14), transparent 32%),
    linear-gradient(145deg, rgba(28,31,52,.72), rgba(10,13,27,.92));
  box-shadow:var(--shadow-soft), inset 0 1px 0 rgba(255,255,255,.05);
}

.superadmin-kpi-card{
  min-height:128px;
  display:grid;
  justify-items:start;
  gap:6px;
  padding:16px;
  border-radius:18px;
  text-align:left;
  cursor:pointer;
}

.superadmin-kpi-card strong{
  font-size:clamp(24px, 4vw, 34px);
  line-height:1;
}

.superadmin-kpi-card small{
  font-weight:800;
}

.superadmin-kpi-card.green .superadmin-kpi-icon,
.superadmin-kpi-card.green small{
  color:#43f16a;
}

.superadmin-kpi-card.amber .superadmin-kpi-icon,
.superadmin-kpi-card.amber small{
  color:#ffad25;
}

.superadmin-kpi-card.red .superadmin-kpi-icon,
.superadmin-kpi-card.red small{
  color:#ff5964;
}

.superadmin-overview-card{
  display:grid;
  gap:12px;
  padding:18px;
  border-radius:20px;
  border:1px solid rgba(255,255,255,.09);
  background:
    radial-gradient(circle at 12% 12%, rgba(255,255,255,.08), transparent 34%),
    linear-gradient(145deg, rgba(28,31,52,.78), rgba(10,13,27,.94));
  box-shadow:var(--shadow-soft);
}

.superadmin-overview-card .row-title{
  align-items:center;
}

.superadmin-overview-card .row-title strong{
  display:block;
  font-size:var(--font-subtitle);
}

.superadmin-overview-card .row-title .btn{
  width:auto;
  min-height:42px;
  padding:0 14px;
}

.superadmin-overview-body{
  display:grid;
  grid-template-columns:minmax(180px, .9fr) minmax(220px, 1.2fr);
  gap:18px;
  align-items:center;
}

.superadmin-donut{
  width:min(260px, 62vw);
  aspect-ratio:1;
  justify-self:center;
  display:grid;
  place-items:center;
  border-radius:50%;
  box-shadow:inset 0 0 0 1px rgba(255,255,255,.08), 0 18px 50px rgba(0,0,0,.24);
}

.superadmin-donut span{
  width:47%;
  aspect-ratio:1;
  display:grid;
  place-items:center;
  align-content:center;
  border-radius:50%;
  background:linear-gradient(145deg, #111429, #090c18);
  box-shadow:0 0 0 1px rgba(255,255,255,.08);
}

.superadmin-donut strong{
  font-size:clamp(24px, 5vw, 34px);
}

.superadmin-donut small{
  color:var(--muted);
  font-weight:800;
}

.superadmin-status-legend{
  display:grid;
  gap:10px;
}

.superadmin-status-legend button{
  display:grid;
  grid-template-columns:14px minmax(0, 1fr) auto;
  align-items:center;
  gap:12px;
  min-height:40px;
  padding:0;
  color:var(--muted);
  background:transparent;
  border:0;
  text-align:left;
}

.superadmin-status-legend i{
  width:14px;
  height:14px;
  border-radius:50%;
}

.superadmin-status-legend strong{
  color:#dfe8f2;
}

.superadmin-section-head{
  display:flex;
  align-items:center;
  justify-content:space-between;
  gap:12px;
}

.superadmin-section-head h3{
  margin:0;
  font-size:var(--font-subtitle);
}

.superadmin-plan-grid{
  display:grid;
  grid-template-columns:repeat(3, minmax(0, 1fr));
  gap:12px;
}

.superadmin-plan-card{
  display:grid;
  gap:4px;
  padding:14px;
  min-height:126px;
  border-radius:16px;
  text-align:left;
  cursor:pointer;
}

.superadmin-plan-card > strong{
  font-size:clamp(22px, 3vw, 30px);
}

.superadmin-plan-card i,
.status-badge.plan-free,
.status-badge.plan-pro,
.status-badge.plan-trial{
  display:inline-grid;
  place-items:center;
  min-height:22px;
  padding:0 8px;
  border-radius:8px;
  font-style:normal;
  font-size:11px;
  font-weight:900;
}

.superadmin-plan-card small{
  margin-top:12px;
  color:#d8d3ff;
}

.plan-free{
  color:#a985ff;
  background:rgba(122,77,255,.16);
  border-color:rgba(122,77,255,.34);
}

.plan-pro{
  color:#6ab7ff;
  background:rgba(38,98,255,.16);
  border-color:rgba(38,98,255,.34);
}

.plan-trial{
  color:#ffcc37;
  background:rgba(255,179,0,.16);
  border-color:rgba(255,179,0,.34);
}

.superadmin-recent-list{
  display:grid;
  overflow:hidden;
  border:1px solid rgba(255,255,255,.09);
  border-radius:18px;
  background:linear-gradient(145deg, rgba(28,31,52,.70), rgba(10,13,27,.92));
}

.superadmin-recent-row{
  display:grid;
  grid-template-columns:42px minmax(0, 1.3fr) auto .7fr .7fr 28px;
  align-items:center;
  gap:12px;
  min-height:58px;
  padding:10px 14px;
  border:0;
  border-radius:0;
  text-align:left;
  background:transparent;
  box-shadow:none;
  cursor:pointer;
}

.superadmin-recent-row + .superadmin-recent-row{
  border-top:1px solid rgba(255,255,255,.07);
}

.superadmin-user-avatar{
  width:36px;
  height:36px;
  display:grid;
  place-items:center;
  border-radius:50%;
  color:#b49cff;
  background:rgba(126,76,255,.18);
  font-weight:900;
}

.sa-online,
.sa-ok{
  color:#42ec69;
}

.sa-offline{
  color:#95a0ba;
}

.sa-late{
  color:#ff5964;
}

.admin-modern-panel .card-header h2,
.clients-saas-panel .card-header h2{
  display:flex;
  align-items:center;
  gap:8px;
}

.admin-action-grid{
  grid-template-columns:repeat(auto-fit, minmax(132px, 1fr));
}

.admin-action-grid .btn,
.superadmin-panel .row-actions .btn,
.clients-saas-panel .row-actions .btn{
  min-height:38px;
  padding:0 10px;
  border-radius:12px;
  font-size:var(--font-button);
}

.admin-action-grid .btn,
.admin-modern-panel .btn{
  display:inline-flex;
  align-items:center;
  justify-content:center;
  gap:7px;
}

.admin-modern-panel .admin-grid,
.clients-compact-metrics{
  grid-template-columns:repeat(4, minmax(0, 1fr));
  gap:10px;
}

.admin-modern-panel .metric,
.clients-saas-panel .metric{
  min-height:94px;
  padding:12px;
  border-radius:16px;
}

.admin-user-row{
  grid-template-columns:minmax(0, 1.2fr) auto minmax(220px, .9fr);
}

.admin-user-row .row-actions,
.client-admin-row .row-actions,
.superadmin-row .row-actions{
  display:grid;
  grid-template-columns:repeat(3, minmax(74px, 1fr));
  gap:6px;
  justify-content:end;
}

.admin-user-row .row-actions .btn,
.client-admin-row .row-actions .btn,
.superadmin-row .row-actions .btn{
  width:auto;
  flex:0 0 auto;
}

.superadmin-action-menu{
  min-width:0;
}

.superadmin-action-menu-trigger{
  width:100% !important;
  min-width:0;
  display:flex;
  align-items:center;
  justify-content:space-between;
  gap:8px;
  white-space:nowrap;
}

.superadmin-action-menu[open] .superadmin-action-menu-trigger > span:last-child{
  transform:rotate(180deg);
}

.superadmin-action-menu-panel{
  min-width:250px;
}

.superadmin-action-menu-panel .btn{
  width:100% !important;
  min-height:40px;
  justify-content:flex-start;
  white-space:normal;
}

.admin-user-row .icon-action-button{
  width:38px;
  min-width:38px;
  height:38px;
  min-height:38px;
  justify-self:end;
}

.client-admin-row{
  grid-template-columns:minmax(190px, 1.55fr) auto auto auto minmax(88px, .42fr) minmax(260px, .95fr);
  gap:8px;
  padding:9px 10px;
  border-radius:15px;
}

.client-admin-main{
  display:grid;
  gap:2px;
}

.client-admin-main strong{
  font-size:var(--font-sm);
}

.client-admin-main .muted,
.client-meta{
  font-size:var(--font-xs);
}

.client-admin-tech{
  opacity:.72;
}

.clients-saas-panel .sync-grid{
  grid-template-columns:repeat(4, minmax(0, 1fr));
  gap:8px;
}

.superadmin-profile-panel{
  max-width:620px;
}

.superadmin-profile-screen{
  display:grid;
  gap:14px;
  padding-bottom:calc(86px + env(safe-area-inset-bottom));
}

.superadmin-profile-hero{
  display:grid;
  grid-template-columns:96px minmax(0, 1fr);
  align-items:center;
  gap:18px;
}

.superadmin-profile-avatar{
  position:relative;
  width:94px;
  height:94px;
  display:grid;
  place-items:center;
  border-radius:50%;
  overflow:visible;
  background:linear-gradient(145deg, rgba(126,76,255,.28), rgba(10,13,27,.92));
  border:1px solid rgba(255,255,255,.12);
  box-shadow:0 18px 46px rgba(0,0,0,.24);
}

.superadmin-profile-avatar img{
  width:100%;
  height:100%;
  object-fit:cover;
  border-radius:inherit;
}

.superadmin-profile-avatar span{
  font-size:28px;
  font-weight:900;
  color:#d8cdff;
}

.superadmin-profile-avatar i{
  position:absolute;
  right:4px;
  bottom:10px;
  width:21px;
  height:21px;
  border-radius:50%;
  background:#7b849a;
  border:3px solid #0b0e1e;
}

.superadmin-profile-avatar i.online{
  background:#22d861;
}

.superadmin-profile-hero h2{
  margin:0 0 4px;
  font-size:22px;
}

.superadmin-profile-hero .status-badge{
  margin-top:8px;
}

.superadmin-profile-status-grid{
  display:grid;
  grid-template-columns:repeat(4, minmax(0, 1fr));
  gap:8px;
  padding:12px;
  border-radius:17px;
  border:1px solid rgba(255,255,255,.09);
  background:linear-gradient(145deg, rgba(28,31,52,.72), rgba(10,13,27,.93));
  box-shadow:var(--shadow-soft);
}

.superadmin-profile-status-grid div{
  min-width:0;
  display:grid;
  justify-items:center;
  gap:5px;
  text-align:center;
}

.superadmin-profile-status-grid strong{
  font-size:var(--font-xs);
}

.superadmin-profile-status-grid small{
  color:var(--muted);
  font-size:11px;
}

.profile-status-dot,
.profile-status-icon{
  width:24px;
  height:24px;
  display:grid;
  place-items:center;
  border-radius:8px;
  color:#aab4cc;
  background:rgba(255,255,255,.06);
}

.profile-status-dot{
  border-radius:50%;
}

.profile-status-dot.online{
  background:#22d861;
  box-shadow:0 0 20px rgba(34,216,97,.32);
}

.profile-status-icon svg{
  width:16px;
  height:16px;
}

.profile-status-icon.amber{
  color:#ffad25;
}

.profile-status-icon.purple{
  color:#9b6cff;
}

.superadmin-profile-card{
  overflow:hidden;
  border-radius:17px;
  border:1px solid rgba(255,255,255,.09);
  background:
    radial-gradient(circle at 14% 8%, rgba(255,255,255,.06), transparent 34%),
    linear-gradient(145deg, rgba(28,31,52,.74), rgba(10,13,27,.94));
  box-shadow:var(--shadow-soft);
}

.superadmin-profile-card h3{
  margin:0;
  padding:14px 16px;
  font-size:var(--font-md);
  border-bottom:1px solid rgba(255,255,255,.07);
}

.superadmin-profile-row{
  min-height:48px;
  display:grid;
  grid-template-columns:minmax(0, 1fr) auto 16px;
  align-items:center;
  gap:8px;
  padding:0 16px;
  border-top:1px solid rgba(255,255,255,.055);
}

.superadmin-profile-row:first-of-type{
  border-top:0;
}

.superadmin-profile-row[role="button"]{
  cursor:pointer;
}

.superadmin-profile-row span{
  color:#edf3ff;
}

.superadmin-profile-row strong{
  color:#dfe7f4;
  font-size:var(--font-sm);
  font-weight:700;
  text-align:right;
}

.profile-row-arrow{
  color:#aeb8cc;
  font-size:24px;
  line-height:1;
}

.superadmin-profile-row.progress-row{
  grid-template-columns:minmax(0, 1fr) auto minmax(84px, 110px) auto;
}

.profile-mini-progress{
  height:5px;
  border-radius:999px;
  background:rgba(255,255,255,.10);
  overflow:hidden;
}

.profile-mini-progress em{
  display:block;
  height:100%;
  border-radius:inherit;
  background:linear-gradient(90deg, #9b6cff, #6737ff);
}

.superadmin-profile-actions-card{
  display:grid;
}

.profile-action-row{
  min-height:52px;
  display:grid;
  grid-template-columns:24px minmax(0, 1fr);
  align-items:center;
  gap:12px;
  padding:0 16px;
  color:#eef4ff;
  background:transparent;
  border:0;
  border-top:1px solid rgba(255,255,255,.055);
  text-align:left;
}

.profile-action-row svg{
  width:20px;
  height:20px;
  color:#9b6cff;
}

.profile-action-row.warning svg{
  color:#ffad25;
}

.profile-action-row.highlight svg{
  color:#5ea1ff;
}

.profile-action-row.danger svg{
  color:#ff5964;
}

.superadmin-profile-danger{
  min-height:52px;
  border-radius:14px;
  border:1px solid rgba(255,77,87,.28);
  color:#ff5964;
  background:rgba(255,77,87,.055);
  font-weight:800;
}

.superadmin-profile-danger-zone{
  display:grid;
  gap:10px;
  padding:0 0 14px;
  border-color:rgba(220,38,38,.22) !important;
  background:
    linear-gradient(180deg, rgba(254,242,242,.72), rgba(255,255,255,.96)),
    var(--sa-surface) !important;
}

.superadmin-profile-danger-zone h3{
  color:#991b1b;
}

.superadmin-profile-danger-zone p{
  margin:0;
  padding:0 16px;
}

.superadmin-profile-danger-zone .superadmin-profile-danger{
  width:calc(100% - 32px);
  margin:0 16px;
  color:#991b1b;
  background:#fff1f2;
  border-color:rgba(220,38,38,.34);
}

.superadmin-profile-empty{
  display:grid;
  gap:12px;
}

.mobile-home-underlay-hidden{
  display:none !important;
}

body.mobile-mode .mobile-panel:has(.superadmin-platform-shell){
  inset:0;
  z-index:75;
  border-radius:0;
}

body.mobile-mode .mobile-panel:has(.superadmin-platform-shell) .mobile-panel-content{
  padding:0;
  overflow:hidden;
}

body.mobile-mode .mobile-panel:has(.superadmin-platform-shell) .mobile-panel-bar{
  position:absolute;
  z-index:80;
  top:8px;
  left:8px;
  right:8px;
  min-height:44px;
  border:0;
  background:transparent;
  pointer-events:none;
}

body.mobile-mode .mobile-panel:has(.superadmin-platform-shell) .mobile-panel-bar .icon-button{
  pointer-events:auto;
  color:#123a42;
  background:rgba(255,255,255,.92);
  border:1px solid rgba(23,53,59,.14);
  box-shadow:0 8px 20px rgba(15,23,42,.10);
}

body.mobile-mode .mobile-panel:has(.superadmin-platform-shell) .mobile-panel-bar h2,
body.mobile-mode .mobile-panel:has(.superadmin-platform-shell) .mobile-panel-menu-button{
  display:none;
}

@media (max-width: 900px){
  .superadmin-kpi-grid,
  .admin-modern-panel .admin-grid,
  .clients-compact-metrics{
    grid-template-columns:repeat(2, minmax(0, 1fr));
  }

  .superadmin-overview-body,
  .client-admin-row,
  .admin-user-row{
    grid-template-columns:1fr;
  }

  .superadmin-plan-grid{
    grid-template-columns:repeat(3, minmax(0, 1fr));
    overflow:auto;
    padding-bottom:4px;
  }

  .superadmin-plan-card{
    min-width:178px;
  }

  .superadmin-recent-row{
    grid-template-columns:34px minmax(0, 1fr) auto;
    gap:8px;
  }

  .superadmin-recent-row .sa-online,
  .superadmin-recent-row .sa-offline,
  .superadmin-recent-row .sa-ok,
  .superadmin-recent-row .sa-late,
  .superadmin-recent-row small{
    display:none;
  }

  .clients-saas-panel .sync-grid{
    grid-template-columns:repeat(2, minmax(0, 1fr));
  }

  .superadmin-profile-panel{
    max-width:680px;
  }
}

@media (max-width: 640px){
  .superadmin-panel{
    gap:10px;
  }

  .superadmin-titlebar{
    grid-template-columns:40px minmax(0, 1fr) auto;
  }

  .superadmin-hero{
    grid-template-columns:1fr auto;
    gap:8px;
    padding:6px 0 2px;
  }

  .superadmin-hero h2{
    font-size:20px;
  }

  .superadmin-hero p{
    margin:2px 0 0;
    font-size:11px;
  }

  .superadmin-date-filter{
    min-width:78px;
    min-height:36px;
    padding:0 10px;
    font-size:11px;
  }

  .superadmin-tabs{
    gap:6px;
    padding:0 0 4px;
  }

  .superadmin-tabs .tab-button{
    min-height:34px;
    padding:0 11px;
  }

  .superadmin-kpi-card{
    min-height:88px;
    gap:4px;
    padding:10px;
    border-radius:14px;
  }

  .superadmin-kpi-card strong{
    font-size:22px;
  }

  .superadmin-kpi-icon{
    width:30px;
    height:30px;
    border-radius:10px;
  }

  .superadmin-overview-card{
    padding:12px;
  }

  .superadmin-donut{
    width:min(180px, 48vw);
  }

  .superadmin-overview-card .row-title{
    align-items:flex-start;
    flex-direction:column;
  }

  .superadmin-status-legend button{
    grid-template-columns:12px minmax(0, 1fr) auto;
    min-height:34px;
    font-size:var(--font-sm);
  }

  .superadmin-plan-grid{
    grid-template-columns:1fr;
    overflow:visible;
  }

  .superadmin-plan-card{
    min-width:0;
    min-height:88px;
    padding:12px;
  }

  .superadmin-recent-row{
    min-height:50px;
    padding:8px 10px;
  }

  .superadmin-content{
    gap:10px;
  }

  .admin-action-grid{
    grid-template-columns:repeat(2, minmax(0, 1fr)) !important;
  }

  .admin-action-grid .btn{
    min-width:0;
    width:100%;
  }

  .admin-user-row .row-actions,
  .client-admin-row .row-actions,
  .superadmin-row .row-actions{
    grid-template-columns:repeat(2, minmax(0, 1fr));
  }

  .clients-saas-panel .sync-grid{
    grid-template-columns:1fr;
  }

  .client-admin-row{
    padding:9px;
  }

  .client-admin-tech{
    display:none;
  }

  .superadmin-profile-screen{
    gap:12px;
  }

  .superadmin-profile-hero{
    grid-template-columns:90px minmax(0, 1fr);
    gap:14px;
  }

  .superadmin-profile-avatar{
    width:86px;
    height:86px;
  }

  .superadmin-profile-status-grid{
    grid-template-columns:repeat(4, minmax(0, 1fr));
    gap:6px;
    padding:10px 8px;
  }

  .superadmin-profile-status-grid strong{
    font-size:11px;
  }

  .superadmin-profile-status-grid small{
    font-size:10px;
  }

  .superadmin-profile-row{
    min-height:46px;
    padding:0 14px;
  }

  .superadmin-profile-row.progress-row{
    grid-template-columns:minmax(0, 1fr) auto minmax(70px, 90px) auto;
  }
}

/* Superadmin Platform mode - isolated shell for internal management */
.superadmin-only-main,
.superadmin-mobile-only{
  --sa-bg:#eef5f5;
  --sa-surface:#ffffff;
  --sa-surface-soft:#f7fbfb;
  --sa-border:rgba(23,53,59,.14);
  --sa-text:#17353b;
  --sa-muted:#62787d;
  --sa-primary:#0f5c64;
  --sa-secondary:#2563eb;
  --sa-success:#16a34a;
  --sa-warning:#d97706;
  --sa-danger:#dc2626;
  width:100%;
  min-height:var(--viewport-height, 100vh);
  padding:0 !important;
  margin:0 !important;
  overflow:hidden;
  background:#eef5f5;
}

.superadmin-only-main .superadmin-platform-shell,
.superadmin-mobile-only .superadmin-platform-shell{
  min-height:var(--viewport-height, 100vh);
  border:0;
  border-radius:0;
}

.superadmin-platform-shell{
  --sa-bg:#eef5f5;
  --sa-surface:#ffffff;
  --sa-surface-soft:#f7fbfb;
  --sa-border:rgba(23,53,59,.14);
  --sa-text:#17353b;
  --sa-muted:#62787d;
  --sa-primary:#0f5c64;
  --sa-secondary:#2563eb;
  --sa-success:#16a34a;
  --sa-warning:#d97706;
  --sa-danger:#dc2626;
  width:100%;
  min-height:calc(var(--viewport-height, 100vh) - 20px);
  display:grid;
  grid-template-columns:272px minmax(0, 1fr);
  color:var(--sa-text);
  background:
    linear-gradient(180deg, rgba(255,255,255,.52), rgba(238,245,245,.86)),
    var(--sa-bg);
  border:1px solid var(--sa-border);
  border-radius:22px;
  overflow:hidden;
  box-shadow:0 18px 54px rgba(15,23,42,.10);
}

body.theme-dark .superadmin-only-main,
body.theme-dark .superadmin-mobile-only,
body.theme-dark .superadmin-platform-shell{
  --sa-bg:#0b1117;
  --sa-surface:#151d26;
  --sa-surface-soft:#1b2631;
  --sa-border:rgba(226,232,240,.22);
  --sa-text:#f8fafc;
  --sa-muted:#cbd5e1;
  --sa-primary:#63d7cf;
  background:var(--sa-bg);
  color:var(--sa-text);
}

body.theme-dark .superadmin-platform-shell{
  background:var(--sa-bg);
}

body.theme-dark .superadmin-platform-sidebar{
  background:linear-gradient(180deg, var(--sa-surface), var(--sa-bg));
}

body.theme-dark .superadmin-platform-topbar,
body.theme-dark .superadmin-platform-nav-item,
body.theme-dark .superadmin-sidebar-action,
body.theme-dark .superadmin-platform-search{
  color:var(--sa-text);
  background:var(--sa-surface);
  border-color:var(--sa-border);
}

body.theme-dark .superadmin-platform-nav-item:hover,
body.theme-dark .superadmin-platform-nav-item:focus-visible,
body.theme-dark .superadmin-platform-nav-item.active{
  color:#f8fafc;
  background:color-mix(in srgb, var(--sa-primary) 18%, var(--sa-surface));
  border-color:color-mix(in srgb, var(--sa-primary) 46%, var(--sa-border));
}

body.theme-dark .superadmin-platform-nav-item > span,
body.theme-dark .superadmin-sidebar-action > span,
body.theme-dark .superadmin-secondary-shortcuts button > span,
body.theme-dark .superadmin-company-metric > span,
body.theme-dark .superadmin-system-row > span{
  color:var(--sa-primary);
  background:color-mix(in srgb, var(--sa-primary) 16%, var(--sa-surface-soft));
}

body.theme-dark .superadmin-platform-nav-item.active > span{
  color:#071316;
  background:var(--sa-primary);
}

body.theme-dark .superadmin-platform-page-title em,
body.theme-dark .superadmin-platform-search-clear:hover,
body.theme-dark .superadmin-platform-search-clear:focus-visible{
  color:var(--sa-primary);
  background:color-mix(in srgb, var(--sa-primary) 14%, var(--sa-surface));
}

body.theme-dark .superadmin-maintenance-banner{
  color:#fde68a;
  background:linear-gradient(135deg, #3f2d12, #292013);
  border-color:rgba(251,191,36,.42);
}

.superadmin-priority-strip{
  display:grid;
  grid-template-columns:repeat(3, minmax(0, 1fr));
  gap:10px;
  margin-bottom:14px;
}

.superadmin-priority-card{
  min-width:0;
  display:grid;
  grid-template-columns:38px auto minmax(0, 1fr);
  align-items:center;
  gap:10px;
  padding:12px;
  border:1px solid var(--sa-border);
  border-radius:14px;
  color:var(--sa-text);
  background:var(--sa-surface);
  text-align:left;
}

.superadmin-priority-card > span{
  width:38px;
  height:38px;
  display:grid;
  place-items:center;
  border-radius:12px;
  color:var(--sa-primary);
  background:color-mix(in srgb, var(--sa-primary) 16%, var(--sa-surface));
}

.superadmin-priority-card strong{font-size:24px;color:var(--sa-text)}
.superadmin-priority-card small{color:var(--sa-muted)}
.superadmin-priority-card.danger > span{color:var(--sa-danger)}
.superadmin-priority-card.success > span{color:var(--sa-success)}

.superadmin-email-disabled{
  display:grid;
  grid-template-columns:52px minmax(0, 1fr) auto;
  align-items:center;
  gap:16px;
  padding:22px;
  color:var(--sa-text);
  background:var(--sa-surface);
  border-color:var(--sa-border);
}

.superadmin-email-disabled > span:first-child{
  width:52px;
  height:52px;
  display:grid;
  place-items:center;
  border-radius:16px;
  color:var(--sa-muted);
  background:var(--sa-surface-soft);
}

.superadmin-email-disabled h2{margin:0 0 6px;color:var(--sa-text)}
.superadmin-email-disabled p{margin:0;color:var(--sa-muted);line-height:1.5}

.superadmin-email-layout{display:grid;grid-template-columns:minmax(0, 1.35fr) minmax(300px, .65fr);gap:14px}
.superadmin-email-compose,.superadmin-email-history{color:var(--sa-text);background:var(--sa-surface);border-color:var(--sa-border)}
.superadmin-email-compose{display:grid;gap:14px}
.superadmin-email-recipients{display:grid;gap:8px}
.superadmin-email-recipients > div{max-height:260px;overflow:auto;display:grid;gap:6px;padding:8px;border:1px solid var(--sa-border);border-radius:12px}
.superadmin-email-recipients label{display:flex;align-items:center;gap:10px;padding:8px;border-radius:10px;background:var(--sa-surface-soft)}
.superadmin-email-recipients label span{display:grid;gap:2px}.superadmin-email-recipients small{color:var(--sa-muted)}

.superadmin-access-row{
  grid-template-columns:42px minmax(0, 1fr) auto minmax(120px, auto);
}

body.theme-dark .superadmin-platform-shell :where(.superadmin-attention-row,.superadmin-system-row,.superadmin-maintenance-summary span){
  color:var(--sa-text);
  background:var(--sa-surface-soft);
}

@media(max-width:720px){
  .superadmin-priority-strip{grid-template-columns:1fr}
  .superadmin-access-row{grid-template-columns:38px minmax(0, 1fr);}
  .superadmin-access-row > :where(span:not(.superadmin-user-avatar),small){grid-column:2}
  .superadmin-email-disabled{grid-template-columns:44px minmax(0, 1fr)}
  .superadmin-email-disabled > .status-badge{grid-column:2;justify-self:start}
  .superadmin-email-layout{grid-template-columns:1fr}
}

.superadmin-platform-sidebar{
  min-width:0;
  display:grid;
  grid-template-rows:auto minmax(0, 1fr) auto;
  gap:16px;
  padding:18px 14px;
  background:linear-gradient(180deg, #ffffff, #f4faf9);
  color:var(--sa-text);
  border-right:1px solid var(--sa-border);
}

.superadmin-platform-brand{
  min-height:58px;
  display:grid;
  grid-template-columns:42px minmax(0, 1fr);
  align-items:center;
  gap:12px;
  padding:0 6px 14px;
  border-bottom:1px solid var(--sa-border);
}

.superadmin-platform-brand > span{
  width:42px;
  height:42px;
  display:grid;
  place-items:center;
  border-radius:14px;
  color:var(--sa-primary);
  background:#e2f6f3;
  border:1px solid #c3e8e4;
}

.superadmin-platform-brand svg,
.superadmin-platform-mark svg,
.superadmin-platform-nav-item svg,
.superadmin-platform-mobile-nav svg,
.superadmin-platform-search svg{
  width:20px;
  height:20px;
}

.superadmin-platform-brand strong{
  display:block;
  font-size:15px;
}

.superadmin-platform-brand small{
  display:block;
  color:var(--sa-muted);
  font-size:12px;
}

.superadmin-platform-nav{
  min-height:0;
  display:grid;
  align-content:start;
  gap:6px;
  overflow-x:hidden;
  overflow-y:auto;
  scrollbar-width:thin;
  scrollbar-color:var(--sa-border) transparent;
  padding-right:2px;
}

.superadmin-platform-nav-group{
  position:sticky;
  top:0;
  z-index:1;
  display:block;
  margin:8px 4px 2px;
  padding:5px 6px;
  color:var(--sa-muted);
  background:color-mix(in srgb, var(--sa-surface) 94%, transparent);
  font-size:10px;
  font-weight:900;
  letter-spacing:.08em;
  text-transform:uppercase;
}

.superadmin-platform-nav-group:first-child{
  margin-top:0;
}

.superadmin-platform-nav-item{
  min-height:52px;
  display:grid;
  grid-template-columns:34px minmax(0, 1fr);
  grid-template-areas:"icon title" "icon desc";
  align-items:center;
  gap:2px 10px;
  padding:8px 10px;
  border:1px solid transparent;
  border-radius:14px;
  color:var(--sa-text);
  background:rgba(255,255,255,.62);
  text-align:left;
}

.superadmin-platform-nav-item > span{
  grid-area:icon;
  width:34px;
  height:34px;
  display:grid;
  place-items:center;
  border-radius:11px;
  color:var(--sa-primary);
  background:#e7f4f2;
}

.superadmin-platform-nav-item strong{
  grid-area:title;
  min-width:0;
  overflow:hidden;
  color:inherit;
  text-overflow:ellipsis;
  white-space:nowrap;
}

.superadmin-platform-nav-item small{
  grid-area:desc;
  min-width:0;
  overflow:hidden;
  color:var(--sa-muted);
  font-size:11px;
  text-overflow:ellipsis;
  white-space:nowrap;
}

.superadmin-platform-nav-item.active,
.superadmin-platform-nav-item:hover,
.superadmin-platform-nav-item:focus-visible{
  color:#0d3f46;
  background:#e2f6f3;
  border-color:#b9e7e2;
  box-shadow:0 8px 20px rgba(15,92,100,.08);
}

.superadmin-platform-nav-item.active > span{
  color:#ffffff;
  background:var(--sa-primary);
}

.superadmin-sidebar-actions{
  display:grid;
  gap:8px;
  padding-top:12px;
  border-top:1px solid var(--sa-border);
}

.superadmin-sidebar-action{
  min-width:0;
  min-height:58px;
  display:grid;
  grid-template-columns:34px minmax(0, 1fr);
  grid-template-areas:"icon title" "icon text";
  align-items:center;
  gap:2px 10px;
  padding:9px 10px;
  border:1px solid var(--sa-border);
  border-radius:14px;
  color:var(--sa-text);
  background:#ffffff;
  text-align:left;
  box-shadow:0 8px 18px rgba(15,23,42,.05);
}

.superadmin-sidebar-action.primary{
  color:#ffffff;
  background:linear-gradient(135deg, #0f5c64, #16737b);
  border-color:rgba(15,92,100,.42);
}

.superadmin-sidebar-action > span{
  grid-area:icon;
  width:34px;
  height:34px;
  display:grid;
  place-items:center;
  border-radius:11px;
  color:var(--sa-primary);
  background:#e2f6f3;
}

.superadmin-sidebar-action.primary > span{
  color:#0f5c64;
  background:#ffffff;
}

.superadmin-sidebar-action strong,
.superadmin-sidebar-action small{
  min-width:0;
  overflow:hidden;
  text-overflow:ellipsis;
  white-space:nowrap;
}

.superadmin-sidebar-action strong{
  grid-area:title;
}

.superadmin-sidebar-action small{
  grid-area:text;
  color:var(--sa-muted);
  font-size:11px;
}

.superadmin-sidebar-action.primary small{
  color:rgba(255,255,255,.78);
}

.superadmin-platform-main{
  min-width:0;
  display:grid;
  grid-template-rows:auto minmax(0, 1fr);
}

.superadmin-platform-topbar{
  min-width:0;
  min-height:76px;
  display:grid;
  grid-template-columns:minmax(230px, .9fr) minmax(220px, 1.1fr) auto auto;
  align-items:center;
  gap:14px;
  padding:14px 18px;
  background:rgba(255,255,255,.82);
  border-bottom:1px solid var(--sa-border);
}

.superadmin-platform-page-title{
  min-width:0;
  display:flex;
  align-items:center;
  gap:12px;
}

.superadmin-platform-page-title h2{
  margin:0;
  color:var(--sa-text);
  font-size:20px;
}

.superadmin-platform-page-title small{
  display:block;
  color:var(--sa-muted);
  font-weight:800;
  text-transform:uppercase;
  font-size:11px;
}

.superadmin-platform-page-title em{
  display:inline-flex;
  min-height:28px;
  align-items:center;
  padding:0 10px;
  border-radius:999px;
  color:#0f5c64;
  background:#dff7f3;
  font-size:11px;
  font-style:normal;
  font-weight:900;
  white-space:nowrap;
}

.superadmin-platform-mark{
  width:42px;
  height:42px;
  display:grid;
  place-items:center;
  border-radius:14px;
  color:#ffffff;
  background:linear-gradient(145deg, var(--sa-primary), #123a42);
  box-shadow:0 12px 28px rgba(15,92,100,.22);
}

.superadmin-platform-search{
  min-width:0;
  min-height:44px;
  display:grid;
  grid-template-columns:22px minmax(0, 1fr) 30px;
  align-items:center;
  gap:8px;
  padding:0 12px;
  border:1px solid var(--sa-border);
  border-radius:14px;
  color:var(--sa-muted);
  background:#f8fbfb;
}

.superadmin-platform-search input{
  min-width:0;
  height:100%;
  padding:0;
  border:0 !important;
  color:var(--sa-text);
  background:transparent !important;
  box-shadow:none !important;
}

.superadmin-platform-search-clear{
  width:30px;
  height:30px;
  min-width:30px;
  display:grid;
  place-items:center;
  border:0;
  border-radius:10px;
  color:var(--sa-muted);
  background:rgba(15,92,100,.08);
  font-size:20px;
  line-height:1;
}

.superadmin-platform-search-clear:hover,
.superadmin-platform-search-clear:focus-visible{
  color:var(--sa-primary);
  background:#dff7f3;
}

.superadmin-platform-actions{
  display:flex;
  align-items:center;
  justify-content:flex-end;
  gap:10px;
}

.superadmin-platform-back,
.superadmin-platform-erp{
  width:auto;
