  white-space:nowrap;
}

.superadmin-platform-user{
  display:flex;
  align-items:center;
  gap:8px;
  min-width:0;
  color:var(--sa-text);
}

.superadmin-maintenance-banner{
  display:flex;
  align-items:center;
  justify-content:space-between;
  gap:14px;
  margin:12px 18px 0;
  padding:12px 14px;
  border:1px solid rgba(217,119,6,.28);
  border-radius:12px;
  color:#7c2d12;
  background:linear-gradient(135deg, #fff7ed, #fffbeb);
  box-shadow:0 10px 24px rgba(146,64,14,.12);
}

.superadmin-maintenance-banner strong,
.superadmin-maintenance-banner span{
  display:block;
}

.superadmin-maintenance-banner strong{
  font-size:.92rem;
}

.superadmin-maintenance-banner span{
  margin-top:2px;
  font-size:.82rem;
  color:#9a3412;
}

.superadmin-platform-avatar{
  width:34px;
  height:34px;
  border-radius:50%;
}

.superadmin-platform-content{
  min-width:0;
  min-height:0;
  display:grid;
  align-content:start;
  gap:16px;
  padding:18px;
  overflow:auto;
}

.superadmin-platform-section-header{
  display:flex;
  align-items:flex-end;
  justify-content:space-between;
  gap:16px;
  padding:18px;
  border:1px solid var(--sa-border);
  border-radius:18px;
  background:var(--sa-surface);
  box-shadow:0 10px 26px rgba(15,23,42,.06);
}

.superadmin-platform-section-header h1{
  margin:4px 0 6px;
  color:var(--sa-text);
  font-size:clamp(24px, 3vw, 34px);
  line-height:1.08;
}

.superadmin-platform-section-header p{
  max-width:720px;
  margin:0;
  color:var(--sa-muted);
}

.superadmin-platform-module{
  max-width:none;
}

.superadmin-platform-shell .superadmin-kpi-card,
.superadmin-platform-shell .superadmin-plan-card,
.superadmin-platform-shell .superadmin-recent-row,
.superadmin-platform-shell .superadmin-overview-card,
.superadmin-platform-shell .superadmin-recent-list,
.superadmin-platform-shell .card,
.superadmin-platform-shell .metric,
.superadmin-platform-shell .history-item,
.superadmin-platform-shell .payment-row{
  color:var(--sa-text);
