  background:#e4f6f4;
  border-color:#bce5e2;
  box-shadow:none;
}

.superadmin-platform-shell .superadmin-donut span{
  color:var(--sa-text);
  background:var(--sa-surface);
}

.superadmin-platform-shell .superadmin-status-legend strong{
  color:var(--sa-text);
}

.superadmin-module-placeholder{
  display:grid;
  gap:16px;
  padding:20px;
  border:1px solid var(--sa-border);
  border-radius:18px;
  background:var(--sa-surface);
  box-shadow:0 10px 26px rgba(15,23,42,.06);
}

.superadmin-module-placeholder h3{
  margin:4px 0 6px;
  color:var(--sa-text);
  font-size:22px;
}

.superadmin-module-placeholder p{
  margin:0;
  color:var(--sa-muted);
}

.superadmin-placeholder-grid{
  display:grid;
  grid-template-columns:repeat(3, minmax(0, 1fr));
  gap:10px;
}

.superadmin-placeholder-grid div{
  min-height:82px;
  display:grid;
  align-content:center;
  gap:4px;
  padding:12px;
  border:1px solid var(--sa-border);
  border-radius:14px;
  background:var(--sa-surface-soft);
}

.superadmin-placeholder-grid strong{
  color:var(--sa-text);
  font-size:20px;
}

.superadmin-secondary-shortcuts{
  display:grid;
  grid-template-columns:repeat(auto-fit, minmax(150px, 1fr));
  gap:10px;
  margin-bottom:14px;
}

.superadmin-secondary-shortcuts button{
  min-width:0;
  min-height:76px;
  display:grid;
  grid-template-columns:34px minmax(0, 1fr);
  grid-template-areas:"icon title" "icon text";
  align-items:center;
  gap:2px 10px;
  padding:10px;
  border:1px solid var(--sa-border);
  border-radius:14px;
  color:var(--sa-text);
  background:var(--sa-surface-soft);
  text-align:left;
}

.superadmin-secondary-shortcuts button > span{
  grid-area:icon;
  width:34px;
  height:34px;
  display:grid;
  place-items:center;
  border-radius:12px;
  color:var(--sa-primary);
  background:#e2f6f3;
}

.superadmin-secondary-shortcuts strong{
  grid-area:title;
  min-width:0;
  overflow:hidden;
  text-overflow:ellipsis;
  white-space:nowrap;
}

.superadmin-secondary-shortcuts small{
  grid-area:text;
  min-width:0;
  overflow:hidden;
  text-overflow:ellipsis;
  white-space:nowrap;
}

.superadmin-maintenance-console{
  display:grid;
  gap:12px;
}

.superadmin-maintenance-hero{
  display:flex;
  align-items:flex-start;
  justify-content:space-between;
  gap:14px;
  padding:18px;
  border:1px solid var(--sa-border);
  border-radius:18px;
  background:
    linear-gradient(135deg, rgba(15,92,100,.08), rgba(37,99,235,.05)),
    var(--sa-surface);
  box-shadow:0 8px 22px rgba(15,23,42,.055);
}

.superadmin-maintenance-hero h3{
  margin:4px 0 6px;
  color:var(--sa-text);
  font-size:24px;
}

.superadmin-maintenance-hero p{
  max-width:720px;
  margin:0;
  color:var(--sa-muted);
}

.superadmin-maintenance-list{
  display:grid;
  gap:10px;
}

.superadmin-maintenance-row{
  min-width:0;
  display:grid;
  grid-template-columns:44px minmax(180px, 1fr) auto auto minmax(210px, auto);
  align-items:center;
  gap:10px;
  padding:12px;
  border:1px solid var(--sa-border);
  border-radius:16px;
