}

.superadmin-maintenance-row strong,
.superadmin-maintenance-row small{
  display:block;
  min-width:0;
  overflow:hidden;
  text-overflow:ellipsis;
  white-space:nowrap;
}

.superadmin-platform-mobile-nav{
  display:none;
}

body.mobile-mode .superadmin-mobile-only .superadmin-platform-mobile-nav,
body[data-ui-profile="web_pwa"].mobile-mode .superadmin-mobile-only .superadmin-platform-mobile-nav,
body[data-ui-profile="android_apk"].mobile-mode .superadmin-mobile-only .superadmin-platform-mobile-nav{
  position:fixed;
  left:0;
  right:0;
  bottom:0;
  z-index:180;
  min-height:calc(64px + env(safe-area-inset-bottom));
  display:grid;
  grid-template-columns:repeat(5, minmax(0, 1fr));
  gap:4px;
  padding:6px 8px calc(6px + env(safe-area-inset-bottom));
  background:color-mix(in srgb, var(--surface) 96%, transparent);
  border-top:1px solid var(--line);
  box-shadow:0 -12px 30px rgba(15,23,42,.14);
  transform:translateZ(0);
}

body.mobile-mode .superadmin-mobile-only .superadmin-platform-shell,
body[data-ui-profile="web_pwa"].mobile-mode .superadmin-mobile-only .superadmin-platform-shell,
body[data-ui-profile="android_apk"].mobile-mode .superadmin-mobile-only .superadmin-platform-shell{
  min-height:var(--app-viewport-height, var(--viewport-height, 100dvh));
  padding-bottom:calc(78px + env(safe-area-inset-bottom));
}

body.mobile-mode .superadmin-mobile-only .superadmin-platform-content,
body[data-ui-profile="web_pwa"].mobile-mode .superadmin-mobile-only .superadmin-platform-content,
body[data-ui-profile="android_apk"].mobile-mode .superadmin-mobile-only .superadmin-platform-content{
  padding-bottom:calc(96px + env(safe-area-inset-bottom));
  scroll-padding-bottom:calc(96px + env(safe-area-inset-bottom));
}

body.mobile-mode .superadmin-mobile-only .superadmin-platform-mobile-nav button,
body[data-ui-profile="web_pwa"].mobile-mode .superadmin-mobile-only .superadmin-platform-mobile-nav button,
body[data-ui-profile="android_apk"].mobile-mode .superadmin-mobile-only .superadmin-platform-mobile-nav button{
  min-width:0;
  min-height:50px;
  display:grid;
  place-items:center;
  gap:2px;
  border:0;
  border-radius:14px;
  color:var(--sa-muted);
  background:transparent;
}

body.mobile-mode .superadmin-mobile-only .superadmin-platform-mobile-nav button.active,
body[data-ui-profile="web_pwa"].mobile-mode .superadmin-mobile-only .superadmin-platform-mobile-nav button.active,
body[data-ui-profile="android_apk"].mobile-mode .superadmin-mobile-only .superadmin-platform-mobile-nav button.active{
  color:var(--sa-primary);
  background:color-mix(in srgb, var(--primary) 16%, var(--surface));
}

body.mobile-mode .superadmin-mobile-only .superadmin-platform-mobile-nav strong,
body[data-ui-profile="web_pwa"].mobile-mode .superadmin-mobile-only .superadmin-platform-mobile-nav strong,
body[data-ui-profile="android_apk"].mobile-mode .superadmin-mobile-only .superadmin-platform-mobile-nav strong{
  font-size:10px;
}

.superadmin-platform-inline-back{
  justify-self:start;
  width:auto;
}

.superadmin-platform-shell .clients-saas-panel{
  display:grid;
  gap:16px;
  padding:18px;
  border-radius:18px;
}

.superadmin-company-head{
  display:flex;
  align-items:flex-start;
  justify-content:space-between;
  gap:14px;
}

.superadmin-company-head h2{
  display:flex;
  align-items:center;
  gap:10px;
  margin:4px 0 6px;
  color:var(--sa-text);
  font-size:26px;
}

.superadmin-company-head h2 svg{
  width:24px;
  height:24px;
}

.superadmin-company-head p{
  max-width:680px;
  margin:0;
}

.superadmin-company-metrics{
  display:grid;
  grid-template-columns:repeat(4, minmax(0, 1fr));
  gap:10px;
}

.superadmin-company-metric{
  min-width:0;
  min-height:98px;
  display:grid;
  grid-template-columns:42px minmax(0, 1fr);
  align-items:center;
  gap:12px;
  padding:14px;
  border:1px solid var(--sa-border);
  border-radius:16px;
  background:var(--sa-surface-soft);
}

.superadmin-company-metric > span{
  width:42px;
  height:42px;
  display:grid;
  place-items:center;
  border-radius:14px;
  color:var(--sa-primary);
  background:#e2f6f3;
}

.superadmin-company-metric svg{
  width:20px;
  height:20px;
}

.superadmin-company-metric small,
.client-admin-row small,
.client-admin-table-head span{
  color:var(--sa-muted);
  font-size:11px;
  font-weight:900;
  text-transform:uppercase;
}

.superadmin-company-metric strong{
  display:block;
  color:var(--sa-text);
  font-size:28px;
  line-height:1.05;
}

.superadmin-company-metric em,
.client-admin-plan em{
  display:block;
  overflow:hidden;
  color:var(--sa-muted);
  font-size:12px;
  font-style:normal;
  text-overflow:ellipsis;
  white-space:nowrap;
}

.superadmin-company-metric.success > span{
  color:#087b35;
  background:#dcfce7;
}

.superadmin-company-metric.warning > span{
  color:#a15c03;
  background:#fef3c7;
}

.superadmin-company-toolbar{
  display:grid;
  grid-template-columns:repeat(4, minmax(0, 1fr));
  gap:10px;
  padding:12px;
  border:1px solid var(--sa-border);
  border-radius:16px;
  background:var(--sa-surface-soft);
}

.superadmin-company-actions{
  display:grid;
  grid-template-columns:repeat(auto-fit, minmax(min(160px, 100%), 1fr));
  justify-content:stretch;
  width:100%;
}

.superadmin-company-actions .btn{
  min-width:0;
  width:100%;
  white-space:normal;
}

.superadmin-platform-shell .client-admin-table-head,
.superadmin-platform-shell .client-admin-row{
  display:grid;
  grid-template-columns:minmax(220px, 1.35fr) minmax(120px, .68fr) minmax(106px, .54fr) minmax(132px, .68fr) minmax(112px, .55fr) minmax(250px, .95fr);
  gap:10px;
  align-items:center;
}

.superadmin-platform-shell .client-admin-table-head{
  padding:0 12px 2px;
}

.superadmin-platform-shell .client-admin-row{
  padding:12px;
  border:1px solid var(--sa-border);
  border-radius:16px;
  background:var(--sa-surface);
  box-shadow:0 8px 22px rgba(15,23,42,.05);
}

.superadmin-platform-shell .client-admin-row:hover,
.superadmin-platform-shell .client-admin-row.selected{
  border-color:rgba(15,92,100,.34);
  box-shadow:0 14px 34px rgba(15,92,100,.11);
}

.client-admin-main,
.client-admin-plan,
.client-admin-status,
.client-admin-billing,
.client-meta{
  min-width:0;
  display:grid;
  gap:4px;
}

.client-admin-main strong,
.client-admin-billing strong{
  min-width:0;
  overflow:hidden;
  color:var(--sa-text);
  text-overflow:ellipsis;
  white-space:nowrap;
}

.client-admin-main .muted,
.client-admin-billing .muted,
.client-meta span{
  min-width:0;
  overflow:hidden;
  text-overflow:ellipsis;
  white-space:nowrap;
}

.superadmin-platform-shell .client-admin-status .status-badge{
  justify-self:start;
}

.superadmin-platform-shell .client-admin-row .row-actions{
  display:grid;
  grid-template-columns:repeat(2, minmax(0, 1fr)) auto;
  gap:8px;
}

.superadmin-platform-shell .client-admin-row .row-actions .btn{
  min-width:0;
  min-height:38px;
  padding-inline:10px;
}

.superadmin-platform-profile-shell .superadmin-platform-content{
  max-width:none;
}

.superadmin-platform-shell .superadmin-profile-screen{
  max-width:1040px;
  width:100%;
  padding-bottom:24px;
}

.superadmin-platform-shell .superadmin-profile-hero,
.superadmin-platform-shell .superadmin-profile-status-grid,
.superadmin-platform-shell .superadmin-profile-card{
  color:var(--sa-text);
  background:var(--sa-surface);
  background-image:none;
  border-color:var(--sa-border);
  box-shadow:0 8px 22px rgba(15,23,42,.055);
}

.superadmin-platform-shell .superadmin-profile-hero{
  grid-template-columns:96px minmax(0, 1fr) auto;
  padding:18px;
  border:1px solid var(--sa-border);
  border-radius:18px;
}

.superadmin-profile-hero-actions{
  display:flex;
  align-items:center;
  justify-content:flex-end;
  gap:8px;
}

.superadmin-platform-shell .superadmin-profile-avatar{
  background:linear-gradient(145deg, #0f5c64, #123a42);
  border-color:var(--sa-border);
  box-shadow:0 14px 30px rgba(15,92,100,.18);
}

.superadmin-platform-shell .superadmin-profile-avatar i{
  border-color:#ffffff;
}

.superadmin-platform-shell .superadmin-profile-avatar span{
  color:#ffffff;
}

.superadmin-platform-shell .superadmin-profile-row{
  border-top-color:var(--sa-border);
}

.superadmin-platform-shell .superadmin-profile-row span,
.superadmin-platform-shell .superadmin-profile-row strong,
.superadmin-platform-shell .profile-action-row{
  color:var(--sa-text);
}

.superadmin-company-tabs{
  display:flex;
  gap:8px;
  overflow:auto;
  padding:4px 0 2px;
}

.superadmin-company-tabs button{
  min-height:38px;
  padding:0 14px;
  border:1px solid var(--sa-border);
  border-radius:999px;
  color:var(--sa-muted);
  background:var(--sa-surface);
  font-weight:900;
  white-space:nowrap;
}

.superadmin-company-tabs button.active{
  color:#ffffff;
  background:var(--sa-primary);
  border-color:var(--sa-primary);
}

.superadmin-company-tab-panel{
  display:grid;
  grid-template-columns:repeat(2, minmax(0, 1fr));
  gap:14px;
  align-items:start;
}

.superadmin-company-tab-panel .superadmin-profile-card:first-child:last-child,
.superadmin-company-tab-panel .superadmin-profile-empty-card{
  grid-column:1 / -1;
}

.superadmin-profile-empty-card p{
  margin:0;
  padding:14px 16px 16px;
}

.superadmin-profile-list{
  display:grid;
}

.superadmin-store-admin,
.superadmin-ads-admin{
  display:grid;
  gap:16px;
}

.superadmin-store-hero{
  display:flex;
  align-items:flex-start;
  justify-content:space-between;
  gap:14px;
  padding:18px;
  border:1px solid var(--sa-border);
  border-radius:18px;
  background:
    linear-gradient(135deg, rgba(15,92,100,.08), rgba(37,99,235,.06)),
    var(--sa-surface);
}

.superadmin-store-hero h3{
  margin:4px 0 6px;
  color:var(--sa-text);
  font-size:24px;
}

.superadmin-store-hero p{
  max-width:720px;
  margin:0;
  color:var(--sa-muted);
}

.superadmin-store-checklist,
.superadmin-store-list,
.superadmin-ads-card{
  display:grid;
  gap:10px;
  padding:16px;
  border:1px solid var(--sa-border);
  border-radius:18px;
  background:var(--sa-surface);
  box-shadow:0 8px 22px rgba(15,23,42,.055);
}

.superadmin-store-checklist h4,
.superadmin-ads-card h4{
  margin:0;
  color:var(--sa-text);
  font-size:17px;
}

.superadmin-store-checklist > div,
.superadmin-ads-rule{
  min-width:0;
  display:grid;
  grid-template-columns:34px minmax(0, 1fr);
  grid-template-areas:"icon title" "icon text";
  align-items:center;
  gap:2px 10px;
  padding:10px;
  border:1px solid var(--sa-border);
  border-radius:14px;
  background:var(--sa-surface-soft);
}

.superadmin-store-checklist > div > span,
.superadmin-ads-rule > span{
  grid-area:icon;
  width:34px;
  height:34px;
  display:grid;
  place-items:center;
  border-radius:12px;
  color:var(--sa-primary);
  background:#e2f6f3;
}

.superadmin-store-checklist strong,
.superadmin-ads-rule strong{
  grid-area:title;
  color:var(--sa-text);
}

.superadmin-store-checklist small,
.superadmin-ads-rule small{
  grid-area:text;
}

.superadmin-store-row{
  display:grid;
  grid-template-columns:minmax(220px, 1.2fr) minmax(120px, .55fr) minmax(120px, .62fr) minmax(128px, .62fr) minmax(210px, .82fr);
  gap:10px;
  align-items:center;
  padding:12px;
  border:1px solid var(--sa-border);
  border-radius:16px;
  background:var(--sa-surface-soft);
}

.superadmin-store-row > div{
  min-width:0;
  display:grid;
  gap:4px;
}

.superadmin-store-row strong,
.superadmin-store-row span:not(.status-badge){
  min-width:0;
  overflow:hidden;
  text-overflow:ellipsis;
  white-space:nowrap;
}

.superadmin-store-row small{
  color:var(--sa-muted);
  font-size:11px;
  font-weight:900;
  text-transform:uppercase;
}

.superadmin-store-row .row-actions{
  display:grid;
  grid-template-columns:repeat(2, minmax(0, 1fr));
  gap:8px;
}

.superadmin-ads-grid{
  display:grid;
  grid-template-columns:minmax(0, .9fr) minmax(0, 1.1fr);
  gap:12px;
}

.superadmin-ads-card .superadmin-profile-row{
  border-color:var(--sa-border);
}

.superadmin-ads-card p{
  margin:0;
}

@media(min-width:1181px) and (max-width:1360px){
  .superadmin-platform-shell{
    grid-template-columns:244px minmax(0, 1fr);
  }

  .superadmin-platform-sidebar{
    padding-inline:12px;
  }

  .superadmin-platform-topbar{
    grid-template-columns:minmax(190px, .8fr) minmax(180px, 1fr) auto auto;
    gap:10px;
    padding-inline:14px;
  }

  .superadmin-platform-content{
    padding:14px;
  }
}

@media(max-width:1180px){
  .superadmin-platform-shell{
    grid-template-columns:1fr;
    border-radius:0;
    border-inline:0;
    padding-bottom:72px;
  }

  .superadmin-platform-sidebar{
    display:none;
  }

  .superadmin-platform-topbar{
    grid-template-columns:minmax(0, 1fr) auto auto;
    grid-template-areas:
      "title erp actions"
      "search search search";
  }

  .superadmin-platform-page-title{grid-area:title}
  .superadmin-platform-search{grid-area:search}
  .superadmin-platform-erp{grid-area:erp}
  .superadmin-platform-actions{grid-area:actions}

  .superadmin-platform-search{
    grid-column:auto;
    order:initial;
  }

  .superadmin-platform-content{
    padding-bottom:92px;
    scroll-padding-bottom:92px;
  }

  .superadmin-platform-mobile-nav{
    position:fixed;
    left:0;
    right:0;
    bottom:0;
    z-index:70;
    min-height:64px;
    display:grid;
    grid-template-columns:repeat(5, minmax(0, 1fr));
    gap:4px;
    padding:6px 8px calc(6px + env(safe-area-inset-bottom));
    background:color-mix(in srgb, var(--surface) 94%, transparent);
    border-top:1px solid var(--line);
    box-shadow:0 -12px 30px rgba(15,23,42,.12);
  }

  .superadmin-platform-mobile-nav button{
    min-width:0;
    min-height:50px;
    display:grid;
    place-items:center;
    gap:2px;
    border:0;
    border-radius:14px;
    color:var(--sa-muted);
    background:transparent;
  }

  .superadmin-platform-mobile-nav button.active{
    color:var(--sa-primary);
    background:color-mix(in srgb, var(--primary) 16%, var(--surface));
  }

  .superadmin-platform-mobile-nav strong{font-size:10px}

  .superadmin-system-row strong{
    overflow-wrap:anywhere;
    text-overflow:clip;
    white-space:normal;
  }

  .superadmin-platform-content .actions:not(.row-actions):not(.superadmin-platform-actions){
    display:grid;
    grid-template-columns:repeat(auto-fit, minmax(min(180px, 100%), 1fr));
    width:100%;
  }

  .superadmin-platform-content .actions:not(.row-actions):not(.superadmin-platform-actions) .btn{
    min-width:0;
    width:100%;
    white-space:normal;
  }

  .superadmin-plan-card :where(p, .muted){
    overflow-wrap:anywhere;
    white-space:normal;
  }

  .superadmin-company-metrics,
  .superadmin-company-toolbar{
    grid-template-columns:repeat(2, minmax(0, 1fr));
  }

  .superadmin-platform-shell .client-admin-table-head{
    display:none;
  }

  .superadmin-platform-shell .client-admin-row{
    grid-template-columns:1fr;
  }

  .superadmin-platform-shell .client-admin-row .row-actions{
    grid-template-columns:repeat(2, minmax(0, 1fr));
  }

  .superadmin-platform-shell .superadmin-profile-hero{
    grid-template-columns:86px minmax(0, 1fr);
  }

  .superadmin-profile-hero-actions{
    grid-column:1 / -1;
    justify-content:flex-start;
  }

  .superadmin-store-row,
  .superadmin-ads-grid,
  .superadmin-company-tab-panel{
    grid-template-columns:1fr;
  }
}

@media(max-width:760px){
  .superadmin-platform-shell{
    min-height:var(--viewport-height, 100vh);
