  }

  .superadmin-platform-content{
    gap:12px;
    padding:12px;
  }

  .superadmin-platform-section-header{
    align-items:flex-start;
    flex-direction:column;
    padding:14px;
    border-radius:16px;
  }

  .superadmin-platform-section-header h1{
    font-size:24px;
  }

  .superadmin-placeholder-grid{
