  }

  .superadmin-platform-shell .superadmin-profile-hero{
    grid-template-columns:72px minmax(0, 1fr);
    padding:14px;
  }

  .superadmin-profile-hero-actions{
    display:grid;
    grid-template-columns:1fr 1fr;
    width:100%;
  }

  .superadmin-profile-hero-actions .btn{
    min-width:0;
  }

  .superadmin-company-tabs{
    margin-inline:-2px;
  }

  .superadmin-store-hero{
    flex-direction:column;
    padding:14px;
  }

  .superadmin-store-hero .btn{
    width:100%;
  }

  .superadmin-store-checklist,
  .superadmin-store-list,
