    padding:12px;
  }

  .superadmin-store-row .row-actions{
    grid-template-columns:1fr;
  }

  .superadmin-maintenance-hero{
    flex-direction:column;
    padding:14px;
  }

  .superadmin-maintenance-hero .btn{
    width:100%;
    justify-content:center;
  }

  .superadmin-maintenance-row{
    grid-template-columns:42px minmax(0, 1fr);
  }

  .superadmin-maintenance-row .status-badge{
    justify-self:start;
    grid-column:2;
  }

  .superadmin-maintenance-row .row-actions{
    grid-column:1 / -1;
    display:grid;
    grid-template-columns:1fr 1fr;
    gap:8px;
  }

  .superadmin-platform-mobile-nav{
    position:fixed;
    left:0;
    right:0;
    bottom:0;
    z-index:70;
    min-height:64px;
    display:grid;
    grid-template-columns:repeat(5, minmax(0, 1fr));
    gap:4px;
    padding:6px 8px calc(6px + env(safe-area-inset-bottom));
    background:color-mix(in srgb, var(--surface) 94%, transparent);
    border-top:1px solid var(--line);
    box-shadow:0 -12px 30px rgba(15,23,42,.12);
