/* Profile and plans: mobile premium profile/cards */
.profile-modern-screen,
.plans-modern-screen{
  width:100%;
  max-width:620px;
  margin:0 auto;
  display:grid;
  gap:14px;
  padding-bottom:calc(86px + env(safe-area-inset-bottom));
}

.profile-modern-header,
.plans-modern-header{
  display:grid;
  grid-template-columns:42px minmax(0, 1fr) 42px;
  align-items:center;
  gap:10px;
  min-height:52px;
}

.profile-modern-header h2,
.plans-modern-header h2{
  margin:0;
  text-align:center;
  font-size:var(--font-title);
}

.profile-modern-user-card,
.profile-modern-card,
.plans-current-modern,
.plan-modern-option,
.plans-help-card{
  border:1px solid rgba(255,255,255,.09);
  border-radius:18px;
  background:
    radial-gradient(circle at 14% 8%, rgba(255,255,255,.06), transparent 34%),
    linear-gradient(145deg, rgba(28,31,52,.76), rgba(10,13,27,.94));
  box-shadow:var(--shadow-soft), inset 0 1px 0 rgba(255,255,255,.04);
}

.profile-modern-avatar{
  position:relative;
  width:84px;
  height:84px;
  display:grid;
  place-items:center;
  border-radius:50%;
  overflow:hidden;
  background:linear-gradient(145deg, #7c3dff, #291658);
}

.profile-modern-avatar img{
  width:100%;
  height:100%;
  object-fit:cover;
}

.profile-modern-avatar i{
  font-size:28px;
  font-style:normal;
  font-weight:900;
}

.profile-modern-avatar em{
  position:absolute;
  right:2px;
  bottom:2px;
  width:26px;
  height:26px;
  display:grid;
  place-items:center;
  border-radius:50%;
  color:#dfe8ff;
  background:rgba(16,20,38,.88);
  border:1px solid rgba(255,255,255,.16);
}

.profile-modern-avatar em svg{
  width:14px;
  height:14px;
}

.profile-modern-card{
  overflow:hidden;
  padding:16px;
}

.profile-inline-edit-card{
  display:grid;
  gap:12px;
  margin-bottom:4px;
  padding:14px;
  border:1px solid color-mix(in srgb, var(--color-primary, #00BFA6) 24%, var(--color-border, rgba(255,255,255,.12)));
  border-radius:16px;
  background:color-mix(in srgb, var(--color-primary, #00BFA6) 8%, transparent);
}

.profile-section-title.compact{
  margin-bottom:0;
}

.profile-inline-grid{
  display:grid;
  grid-template-columns:repeat(2, minmax(0, 1fr));
  gap:10px;
}

.profile-inline-actions{
  display:flex;
  flex-wrap:wrap;
  gap:10px;
}

.profile-inline-actions .btn{
  min-width:150px;
  flex:1 1 150px;
}

.profile-section-title{
  display:flex;
  align-items:center;
  justify-content:space-between;
  gap:10px;
  margin-bottom:12px;
}

.profile-section-title strong{
  display:flex;
  align-items:center;
  gap:8px;
}

.profile-section-title svg{
  width:20px;
  height:20px;
  color:#9b6cff;
}

.profile-plan-summary h3{
  margin:0 0 12px;
  font-size:18px;
}

.profile-plan-summary h3 small{
  color:#9b6cff;
}

.profile-active-dot{
  width:8px;
  height:8px;
  display:inline-block;
  margin:0 4px;
