}

.profile-usage-grid{
  display:grid;
  grid-template-columns:repeat(4, minmax(0, 1fr));
  gap:10px;
}

.profile-usage-tile{
  min-width:0;
  min-height:100px;
  display:grid;
  align-content:center;
  gap:7px;
  padding:10px;
  border-radius:13px;
  border:1px solid rgba(255,255,255,.08);
  background:rgba(255,255,255,.035);
}

.profile-usage-tile span{
  color:#b9c3db;
}

.profile-usage-tile svg{
