  gap:14px;
  padding:16px;
}

.plans-current-modern h3,
.plan-modern-option h3{
  margin:0 0 4px;
  font-size:19px;
}

.plans-current-modern h3 small{
  color:#9b6cff;
  font-size:13px;
}

.plan-modern-badge{
  min-width:54px;
  min-height:50px;
  display:grid;
  place-items:center;
  gap:2px;
  padding:4px 8px;
  border-radius:10px;
  font-weight:900;
}

.plan-modern-badge svg{
  width:16px;
  height:16px;
}

.plans-current-stats{
  display:grid;
  grid-template-columns:repeat(3, minmax(0, 1fr));
  padding:12px 0;
  border-top:1px solid rgba(255,255,255,.08);
  border-bottom:1px solid rgba(255,255,255,.08);
}

.plans-current-stats span{
  display:grid;
  place-items:center;
  gap:4px;
  text-align:center;
}

.plans-current-stats span + span{
  border-left:1px solid rgba(255,255,255,.08);
}

.plans-current-stats small,
.plans-current-bottom small{
  color:var(--muted);
}

.plans-current-bottom{
  display:grid;
  grid-template-columns:minmax(0, 1fr) auto;
  align-items:center;
  gap:12px;
}

.plans-current-bottom strong,
.plan-modern-body strong{
  color:#36e66a;
  font-size:18px;
}

.plans-current-bottom .btn{
  min-height:42px;
  width:auto;
  display:inline-flex;
  align-items:center;
  gap:8px;
}

.plans-current-bottom .btn svg{
  width:18px;
  height:18px;
}

.plans-modern-section-title{
  margin:8px 0 0;
  font-size:var(--font-md);
}

.plans-modern-list{
  display:grid;
  gap:12px;
}

.plan-modern-option{
  position:relative;
}

.plan-modern-option.current{
  border-color:#8d4fff;
  box-shadow:0 0 0 1px rgba(141,79,255,.38), var(--shadow-soft);
}

.plan-current-ribbon{
  position:absolute;
  top:-1px;
  left:116px;
  min-height:22px;
  padding:0 8px;
  display:grid;
  place-items:center;
  border-radius:0 0 8px 8px;
  background:#8d4fff;
  color:#fff;
  font-size:11px;
  font-weight:900;
}

.plan-modern-body{
  display:grid;
  grid-template-columns:minmax(0, 1fr) auto;
  align-items:end;
  gap:12px;
}

.plan-modern-body ul{
  display:grid;
  gap:7px;
  margin:0;
  padding:0;
  list-style:none;
  color:#c8d2e3;
  font-size:var(--font-sm);
}

.plan-modern-body li{
  display:flex;
  align-items:center;
  gap:8px;
}

.plan-modern-body li::before{
  content:"";
  width:10px;
  height:10px;
  border-radius:50%;
  background:#34df65;
  box-shadow:inset 0 0 0 2px rgba(255,255,255,.24);
}

.plan-modern-option.featured .plan-modern-body li::before{
  background:#8d4fff;
}

.plan-modern-body > div{
  display:grid;
  justify-items:end;
  gap:10px;
}

.plan-modern-body .btn{
  min-height:42px;
  min-width:126px;
}

.plans-help-card{
  min-height:74px;
  display:grid;
  grid-template-columns:38px minmax(0, 1fr) 18px;
  align-items:center;
  gap:12px;
  padding:14px 16px;
  color:var(--text);
  text-align:left;
}

.plans-help-card svg{
  width:30px;
  height:30px;
  color:#aeb8cc;
}

.plans-help-card small{
  display:block;
  margin-top:3px;
  color:var(--muted);
}

@media (max-width: 640px){
  .profile-modern-screen,
  .plans-modern-screen{
    gap:13px;
  }

  .profile-modern-avatar{
    width:76px;
    height:76px;
  }

  .profile-usage-grid{
    grid-template-columns:repeat(4, minmax(0, 1fr));
    gap:8px;
  }

  .profile-usage-tile{
    min-height:92px;
    padding:8px;
  }

  .profile-usage-tile strong{
    font-size:15px;
  }

  .profile-inline-grid{
    grid-template-columns:1fr;
  }

  .profile-inline-actions .btn{
    width:100%;
    flex-basis:100%;
  }

  .plans-current-stats{
    grid-template-columns:repeat(2, minmax(0, 1fr));
    gap:10px;
    padding:10px 0;
  }

  .plans-current-stats span{
    min-height:66px;
    padding:8px;
    border:1px solid rgba(255,255,255,.08);
    border-radius:12px;
    background:rgba(255,255,255,.035);
  }

  .plans-current-stats span + span{
    border-left:1px solid rgba(255,255,255,.08);
  }

  .plans-current-modern .row-title{
    align-items:start;
    gap:12px;
  }

  .plan-tier-card .plan-current-ribbon{
    position:static;
    justify-self:start;
    width:max-content;
    max-width:100%;
    min-height:28px;
    margin-bottom:0;
    padding:6px 10px;
    border-radius:999px;
  }

  .plan-modern-body{
    grid-template-columns:minmax(0, 1fr) minmax(116px, auto);
  }
}

body[data-ui-profile="android_apk"].mobile-mode .profile-modern-avatar{
  width:60px;
  height:60px;
}

body[data-ui-profile="android_apk"].mobile-mode .profile-modern-card{
  padding:12px;
}

body[data-ui-profile="android_apk"].mobile-mode .profile-usage-grid{
  grid-template-columns:repeat(2, minmax(0, 1fr));
  gap:8px;
}

body[data-ui-profile="android_apk"].mobile-mode .profile-usage-tile{
  min-height:82px;
}

@media (max-width: 390px){
  .profile-usage-grid{
    grid-template-columns:repeat(2, minmax(0, 1fr));
  }

  .plans-current-stats{
    grid-template-columns:1fr;
  }

  .plans-current-stats span + span{
    border-left:1px solid rgba(255,255,255,.08);
  }

  .plans-current-bottom,
  .plan-modern-body{
    grid-template-columns:1fr;
  }

  .plans-current-bottom .btn,
  .plan-modern-body .btn{
    width:100%;
  }
}
