  background:color-mix(in srgb, var(--color-primary) 12%, var(--color-surface));
  border-color:color-mix(in srgb, var(--color-primary) 24%, var(--color-border));
}

body.theme-light :where(
  .app-badge,
  .status-badge,
  .order-status-badge,
  [class$="-badge"],
  [class*="-badge "],
  [class$="-pill"],
  [class*="-pill "]
){
  color:var(--color-text-secondary);
  background:rgba(255,255,255,.72);
  border-color:var(--glass-border);
}

body.theme-light :where(.badge-ativo,.badge-pago,.badge-trial,.badge-superadmin,.badge-ok,.badge-success,.app-badge.success){
  color:var(--color-success);
  background:color-mix(in srgb, var(--color-success) 12%, var(--color-surface));
  border-color:color-mix(in srgb, var(--color-success) 30%, var(--color-border));
}

body.theme-light :where(.badge-alerta,.badge-expirado,.badge-acao,.badge-atencao,.badge-warning,.app-badge.warning){
  color:var(--color-warning);
  background:color-mix(in srgb, var(--color-warning) 12%, var(--color-surface));
  border-color:color-mix(in srgb, var(--color-warning) 30%, var(--color-border));
}

body.theme-light :where(.badge-bloqueado,.badge-cancelado,.badge-anonymized,.badge-danger,.app-badge.danger){
  color:var(--color-danger);
  background:color-mix(in srgb, var(--color-danger) 10%, var(--color-surface));
  border-color:color-mix(in srgb, var(--color-danger) 30%, var(--color-border));
}

body.theme-light :where(.badge-gratis,.badge-aberto,.badge-producao,.badge-info,.app-badge.info){
  color:var(--color-info);
  background:color-mix(in srgb, var(--color-info) 11%, var(--color-surface));
  border-color:color-mix(in srgb, var(--color-info) 30%, var(--color-border));
}

