.app-card.glass,
.card.glass,
.ui-section,
.technical-glass-panel,
.home-premium-header,
.dashboard-search,
.mobile-bottom-nav,
.side-menu,
.mobile-panel-bar,
.topbar{
  border:var(--effect-border-glass);
  background:var(--glass-bg);
  backdrop-filter:var(--effect-blur-glass);
  -webkit-backdrop-filter:var(--effect-blur-glass);
}

.app-card.compact,
.card.compact,
.compact-mode .card{
  padding:calc(var(--card-padding-token) * .82);
  gap:calc(var(--section-gap) * .82);
}

.app-card.clickable,
.clickable-row,
.order-list-card,
.reports-kpi-card,
.reports-quick-tile,
.quick-action,
.profile-list-row{
  cursor:pointer;
  transition:transform 180ms var(--motion-ease), border-color 180ms ease, box-shadow 220ms var(--motion-ease), background 180ms ease;
}

@media (hover:hover){
  .app-card.clickable:hover,
  .clickable-row:hover,
  .profile-list-row:hover,
  .reports-kpi-card:hover,
  .reports-quick-tile:hover{
    transform:var(--effect-hover);
    border-color:color-mix(in srgb, var(--color-primary) 42%, var(--color-border));
    box-shadow:var(--effect-shadow-lg), var(--effect-glow-primary);
  }
}

.app-button,
.btn{
  min-height:var(--size-button-height);
  border-radius:var(--radius-button);
  padding:calc(var(--space-sm) * .9) var(--space-md);
  font-size:var(--type-button);
  font-weight:800;
  letter-spacing:0;
  color:#ffffff;
  background:linear-gradient(145deg, color-mix(in srgb, var(--color-primary) 92%, #ffffff), color-mix(in srgb, var(--color-primary) 70%, #042f2e));
  border:1px solid color-mix(in srgb, var(--color-primary) 45%, rgba(255,255,255,.16));
  box-shadow:var(--effect-shadow-sm);
}

.app-button.primary,
.btn.primary{
  background:linear-gradient(145deg, color-mix(in srgb, var(--color-primary) 94%, #ffffff), var(--color-primary));
}

.app-button[data-ui-variant="primary"]{
  color:var(--s3d-button-primary-text, var(--color-on-primary));
  background:var(--s3d-button-primary-bg, var(--color-primary));
  border-color:var(--s3d-button-primary-border, var(--color-primary));
}

.app-button[data-ui-variant="secondary"]{
  color:var(--s3d-button-secondary-text, var(--color-text-primary, var(--text-primary)));
  background:var(--s3d-button-secondary-bg, color-mix(in srgb, var(--color-primary) 10%, var(--color-surface)));
  border-color:var(--s3d-button-secondary-border, color-mix(in srgb, var(--color-primary) 38%, var(--color-border)));
}

.app-button[data-ui-variant="ghost"],
.app-button[data-ui-variant="outline"]{
  color:var(--s3d-button-ghost-text);
  background:var(--s3d-button-ghost-bg);
  border-color:var(--s3d-button-ghost-border);
}

.app-button[data-ui-variant="danger"]{
  color:var(--s3d-button-danger-text);
  background:var(--s3d-button-danger-bg);
  border-color:var(--s3d-button-danger-border);
}

.app-button[data-ui-variant="success"]{
  color:var(--s3d-button-success-text);
  background:var(--s3d-button-success-bg);
  border-color:var(--s3d-button-success-border);
}

.app-button.secondary,
.btn.secondary{
  color:var(--color-text-primary);
  background:color-mix(in srgb, var(--color-primary) 12%, transparent);
  border-color:color-mix(in srgb, var(--color-primary) 38%, var(--color-border));
  box-shadow:inset 0 1px 0 var(--glass-highlight);
}

.app-button.outline,
.btn.outline{
  color:var(--color-primary);
  background:transparent;
  border-color:color-mix(in srgb, var(--color-primary) 58%, var(--color-border));
  box-shadow:none;
}

.app-button.ghost,
.btn.ghost{
  color:var(--color-text-secondary);
  background:color-mix(in srgb, var(--color-surface) 22%, transparent);
  border-color:var(--color-border);
  box-shadow:inset 0 1px 0 var(--glass-highlight);
}

.app-button.danger,
.btn.danger{
  color:#ffe4e6;
  background:color-mix(in srgb, var(--color-danger) 18%, transparent);
  border-color:color-mix(in srgb, var(--color-danger) 56%, var(--color-border));
}

.app-button.success,
.btn.success{
  color:#ecfdf5;
  background:linear-gradient(145deg, color-mix(in srgb, var(--color-success) 76%, #0f172a), color-mix(in srgb, var(--color-success) 48%, #064e3b));
  border-color:color-mix(in srgb, var(--color-success) 46%, var(--color-border));
}

.app-button.full-width,
.btn.full-width{
  width:100%;
}

.app-button.loading,
.btn.loading,
.btn[aria-busy="true"]{
  pointer-events:none;
  position:relative;
}

.app-button.loading::after,
.btn.loading::after,
.btn[aria-busy="true"]::after{
  content:"";
  width:1em;
  height:1em;
  border-radius:50%;
  border:2px solid currentColor;
  border-right-color:transparent;
  animation:sync-spin .78s linear infinite;
}

.app-icon-button,
.icon-button,
.icon-action-button,
.mobile-bottom-nav-button span,
.side-nav-button span,
.menu-button span,
.quick-action span,
.kpi-icon,
.reports-kpi-icon,
.reports-quick-tile span{
  color:var(--color-icon-primary);
  border-color:var(--color-border);
}

.app-input,
.app-select,
.app-textarea,
input,
select,
textarea{
  min-height:var(--size-input-height);
  border-radius:var(--radius-input);
  background:var(--color-input);
  color:var(--color-text-primary);
  border-color:var(--color-border);
  font-size:var(--type-body);
}

textarea,
.app-textarea{
  min-height:calc(var(--size-input-height) * 2);
}

input::placeholder,
textarea::placeholder{
  color:var(--input-placeholder, var(--color-text-muted));
}

.field,
.app-form-group{
  gap:calc(var(--form-gap) * .45);
}

.auth-form{
  gap:var(--form-gap);
}

.field span,
.app-form-group label,
.auth-field span{
  color:var(--color-text-muted);
  font-size:var(--type-label);
  font-weight:700;
}

input:focus-visible,
select:focus-visible,
textarea:focus-visible,
button:focus-visible,
a:focus-visible,
.app-button:focus-visible,
.app-card.clickable:focus-visible{
  outline:none;
  border-color:color-mix(in srgb, var(--color-primary) 58%, var(--color-border));
  box-shadow:var(--effect-focus-ring), inset 0 1px 0 var(--glass-highlight);
}

.app-input.error,
.app-select.error,
.app-textarea.error,
input[aria-invalid="true"],
select[aria-invalid="true"],
textarea[aria-invalid="true"]{
  border-color:color-mix(in srgb, var(--color-danger) 64%, var(--color-border));
  box-shadow:0 0 0 3px color-mix(in srgb, var(--color-danger) 18%, transparent);
}

.app-field-error{
  color:var(--color-danger);
  font-size:var(--type-caption);
  font-weight:700;
}

.app-badge,
.status-badge,
.order-status-badge{
  min-height:calc(var(--size-input-height) * .68);
  border-radius:var(--radius-pill);
  border-color:var(--color-border);
  background:color-mix(in srgb, var(--color-surface) 24%, transparent);
  color:var(--color-text-secondary);
  font-size:var(--type-caption);
  font-weight:800;
  line-height:1;
}

.badge-ativo,
.badge-pago,
.badge-trial,
.badge-superadmin,
.badge-ok,
.badge-success,
.app-badge.success{
  background:color-mix(in srgb, var(--color-success) 18%, transparent);
  color:color-mix(in srgb, var(--color-success) 74%, #ffffff);
  border-color:color-mix(in srgb, var(--color-success) 42%, var(--color-border));
}

.badge-alerta,
.badge-expirado,
.badge-acao,
.badge-atencao,
.badge-warning,
.app-badge.warning{
  background:color-mix(in srgb, var(--color-warning) 18%, transparent);
  color:color-mix(in srgb, var(--color-warning) 72%, #ffffff);
  border-color:color-mix(in srgb, var(--color-warning) 44%, var(--color-border));
}

.badge-bloqueado,
.badge-cancelado,
.badge-anonymized,
.badge-danger,
.app-badge.danger{
  background:color-mix(in srgb, var(--color-danger) 16%, transparent);
  color:color-mix(in srgb, var(--color-danger) 68%, #ffffff);
  border-color:color-mix(in srgb, var(--color-danger) 44%, var(--color-border));
}

.badge-gratis,
.badge-aberto,
.badge-producao,
.badge-info,
.app-badge.info{
  background:color-mix(in srgb, var(--color-info) 16%, transparent);
  color:color-mix(in srgb, var(--color-info) 70%, #ffffff);
  border-color:color-mix(in srgb, var(--color-info) 42%, var(--color-border));
}

.modal-backdrop,
.popup,
.side-drawer-backdrop{
  background:var(--color-backdrop);
  backdrop-filter:var(--effect-blur-glass);
  -webkit-backdrop-filter:var(--effect-blur-glass);
}

.app-modal,
.modal-card,
.popup-box,
.side-drawer{
  width:min(var(--size-modal-width), 100%);
  max-height:calc(100dvh - var(--space-2xl));
  overflow:auto;
  border-radius:var(--radius-modal);
  background:var(--card-gradient-strong);
  border-color:var(--color-border);
  color:var(--color-text-primary);
  box-shadow:var(--effect-shadow-xl);
}

.modal-header,
.card-header,
.mobile-panel-bar,
.app-header{
  min-height:var(--mobile-header-height);
  border-bottom-color:var(--color-divider);
}

.mobile-panel{
  background:var(--app-body-background, var(--color-background));
}

.mobile-panel-content{
  padding:var(--page-padding);
  padding-bottom:calc(var(--size-bottom-nav-height) + var(--space-xl));
}

body.mobile-mode :where(
  .storefront-admin-page,
  .store-public-shell[data-storefront-source="v2"],
  .store-public-main
){
  padding-bottom:calc(var(--size-bottom-nav-height) + var(--space-2xl));
}

body.mobile-mode .store-public-menu-toggle{
  width:52px;
  min-width:52px;
  padding-inline:0;
  justify-content:center;
}

body.mobile-mode .store-public-menu-toggle span{
  display:none;
}

.mobile-bottom-nav{
  min-height:var(--size-bottom-nav-height);
  background:var(--color-bottom-navigation);
  border-color:var(--color-border);
  box-shadow:var(--effect-shadow-lg);
}

.mobile-bottom-nav-button{
  min-height:calc(var(--size-bottom-nav-height) - 24px);
  color:var(--color-text-muted);
}

.mobile-bottom-nav-button.active{
  color:var(--color-primary);
  border-color:color-mix(in srgb, var(--color-primary) 28%, var(--color-border));
  background:color-mix(in srgb, var(--color-primary) 14%, transparent);
  box-shadow:var(--effect-shadow-sm), var(--effect-glow-primary);
}

.empty,
.app-empty-state,
.order-empty-state,
.chart-empty-state,
.compact-empty{
  display:grid;
  gap:var(--space-sm);
  align-content:center;
  justify-items:center;
  min-height:96px;
  margin:0;
  padding:var(--space-lg);
  border:1px dashed color-mix(in srgb, var(--color-border) 72%, var(--color-primary) 28%);
  border-radius:var(--radius-card);
  background:color-mix(in srgb, var(--color-surface) 32%, transparent);
  color:var(--color-text-muted);
  text-align:center;
}

.app-loading-state,
.skeleton-loading,
.skeleton-block{
  border-radius:var(--radius-medium);
  background:linear-gradient(90deg, color-mix(in srgb, var(--color-surface) 20%, transparent), color-mix(in srgb, var(--color-primary) 13%, transparent), color-mix(in srgb, var(--color-surface) 20%, transparent));
}

.app-error-state,
.danger-zone{
  border-color:color-mix(in srgb, var(--color-danger) 42%, var(--color-border));
  background:color-mix(in srgb, var(--color-danger) 10%, transparent);
}

.app-toast,
.sync-indicator{
  background:var(--chart-tooltip-bg);
  color:var(--chart-tooltip-text);
  border-color:var(--color-border);
  border-radius:var(--radius-medium);
  box-shadow:var(--effect-shadow-lg);
}

.auth-card{
  color:var(--color-text-primary);
  background:var(--card-gradient-strong);
  border-color:var(--color-border);
  box-shadow:var(--effect-shadow-xl);
}

.auth-tabs{
  background:color-mix(in srgb, var(--color-surface) 36%, transparent);
  border-color:var(--color-border);
}

.auth-tabs button{
  color:var(--color-text-muted);
}

.auth-tabs button.active{
  color:#ffffff;
  background:linear-gradient(145deg, color-mix(in srgb, var(--color-primary) 90%, #ffffff), var(--color-primary));
  box-shadow:var(--effect-shadow-sm);
}

.auth-field span,
.auth-brand p,
.auth-checkline,
.auth-footer-text{
  color:var(--color-text-muted);
}

.auth-field input{
  background:var(--color-input);
  color:var(--color-text-primary);
  border-color:var(--color-border);
}

.auth-field input:focus{
  background:var(--color-input);
}

.auth-link{
  color:var(--color-primary);
}

.reports-line-stroke{
  stroke:var(--chart-line);
}

.reports-line-area{
  fill:var(--chart-fill);
}

.reports-grid-lines line{
  stroke:var(--chart-grid);
}

.reports-axis-label{
  fill:var(--chart-axis);
}

.reports-line-dot{
  fill:var(--chart-line);
}

.reports-delta.up{
  color:var(--chart-positive);
}

.reports-delta.down{
  color:var(--chart-negative);
}

.money-value,
.financial-value,
.total-line strong,
.metric strong,
.kpi-card strong,
.reports-kpi-copy strong{
  font-variant-numeric:tabular-nums;
}

.period-custom-bar{
  display:grid;
  grid-template-columns:repeat(2, minmax(0, 1fr)) auto;
  align-items:end;
  gap:var(--space-sm);
  padding:var(--space-sm);
  border:1px solid var(--color-border);
  border-radius:var(--radius-card);
  background:color-mix(in srgb, var(--color-surface) 64%, transparent);
}

.period-custom-bar .field{
  margin:0;
}

.cash-view-tabs,
.cash-period-tabs{
  margin-bottom:var(--space-sm);
}

.statement-panel{
  display:grid;
  gap:var(--space-md);
  margin-top:var(--space-md);
  padding:var(--space-md);
  border:1px solid var(--color-border);
  border-radius:var(--radius-card);
  background:var(--card-gradient);
  box-shadow:var(--effect-shadow-md);
}

.statement-head{
  display:flex;
  align-items:flex-start;
  justify-content:space-between;
  gap:var(--space-md);
}

.statement-head h3{
  margin:0;
  font-size:var(--font-xl);
}

.statement-head p{
  margin:4px 0 0;
}

.statement-actions{
  justify-content:flex-end;
}

.statement-filter-grid{
  display:grid;
  grid-template-columns:1.1fr repeat(2, minmax(0, 1fr));
  gap:var(--space-sm);
}

.statement-filter-grid .field{
  margin:0;
}

.statement-summary-grid{
  display:grid;
  grid-template-columns:repeat(4, minmax(0, 1fr));
  gap:var(--space-sm);
}

.statement-summary-card{
  min-height:72px;
}

.statement-list{
  display:grid;
  gap:var(--space-sm);
}

.statement-row{
  display:grid;
  gap:6px;
  padding:var(--space-sm);
  border:1px solid var(--color-border);
  border-left:3px solid color-mix(in srgb, var(--color-primary) 52%, var(--color-border));
  border-radius:var(--radius-card);
  background:color-mix(in srgb, var(--color-surface) 66%, transparent);
  box-shadow:var(--effect-shadow-sm);
}

.statement-row.statement-saida{
  border-left-color:color-mix(in srgb, var(--color-danger) 58%, var(--color-border));
}

.statement-row.statement-entrada{
  border-left-color:color-mix(in srgb, var(--color-success) 58%, var(--color-border));
}

.statement-row-main{
  min-width:0;
  display:grid;
  gap:6px;
}

.statement-value{
  font-weight:900;
  white-space:nowrap;
}

.statement-value.positive{
  color:var(--color-success);
}

.statement-value.negative{
  color:var(--color-danger);
}

.statement-value.neutral{
  color:var(--color-text-muted);
}

.statement-meta{
  display:flex;
  flex-wrap:wrap;
  gap:6px 10px;
  color:var(--color-text-secondary);
  font-size:var(--font-xs);
}

.statement-meta span{
  min-width:0;
}

.statement-locked .pro-lock-panel{
  display:grid;
  gap:var(--space-sm);
  justify-items:start;
  padding:var(--space-md);
  border:1px solid color-mix(in srgb, var(--color-primary) 34%, var(--color-border));
  border-radius:var(--radius-card);
  background:color-mix(in srgb, var(--color-primary) 10%, var(--color-surface));
}

.statement-locked .pro-lock-panel h3,
.statement-locked .pro-lock-panel p{
  margin:0;
}

.backup-readonly-notice{
  justify-items:start;
  min-height:auto;
  text-align:left;
}

body.theme-light .home-premium-header,
body.theme-light .technical-glass-panel,
body.theme-light .order-mini-summary,
body.theme-light .order-list-card,
body.theme-light .order-item-card,
body.theme-light .stock-detail-card,
body.theme-light .cash-row,
body.theme-light .cash-cancel-summary,
body.theme-light .danger-auth-card,
body.theme-light .order-cancel-info,
body.theme-light .superadmin-kpi-card,
body.theme-light .superadmin-plan-card,
body.theme-light .superadmin-recent-row,
body.theme-light .statement-panel,
body.theme-light .statement-row{
  background:var(--card-gradient);
  color:var(--color-text-primary);
  border-color:var(--color-border);
  box-shadow:var(--effect-shadow-md);
}

body.theme-light .superadmin-panel :where(.superadmin-titlebar,.superadmin-tabs,.superadmin-overview-card,.superadmin-profile-card,.superadmin-profile-status-grid,.user-row,.sync-grid,.history-list){
  color:var(--color-text-primary);
  background:var(--color-surface) !important;
  background-image:none !important;
  border-color:var(--color-border) !important;
  box-shadow:var(--effect-shadow-sm);
}

body.theme-light .superadmin-panel :where(.superadmin-profile-row span,.superadmin-profile-row strong,.superadmin-status-legend strong,.profile-action-row){
  color:var(--color-text-primary);
}

body.theme-light .superadmin-panel :where(.muted,.superadmin-profile-status-grid small,.superadmin-profile-row small){
  color:var(--color-text-muted);
}

.superadmin-row{
  min-width:0;
}

.superadmin-row > div:first-child,
.superadmin-row .row-actions{
  min-width:0;
}

.superadmin-row .row-actions .btn{
  min-width:0;
  overflow:hidden;
  text-overflow:ellipsis;
  white-space:nowrap;
}

@media (max-width:640px){
  .superadmin-row .row-actions{
    grid-template-columns:repeat(2,minmax(0,1fr));
  }
}

/* Super Admin claro: superfície final sem herdar painéis escuros ou estourar ações. */
body.theme-light .superadmin-panel :where(
  .superadmin-overview-card,
  .superadmin-profile-card,
  .superadmin-profile-status-grid,
  .superadmin-kpi-card,
  .superadmin-plan-card,
  .superadmin-recent-row,
  .user-row
){
  color:var(--color-text-primary) !important;
  background:var(--color-surface) !important;
  background-image:none !important;
  border-color:var(--color-border) !important;
}

body.theme-light .superadmin-panel :where(.profile-status-icon,.superadmin-kpi-icon,.superadmin-crown){
  background:color-mix(in srgb,var(--color-accent) 10%,var(--color-surface)) !important;
  background-image:none !important;
  border-color:color-mix(in srgb,var(--color-accent) 28%,var(--color-border)) !important;
}

.superadmin-row .row-actions{
  grid-template-columns:repeat(2,minmax(0,1fr));
}

body.theme-light .reports-title-row p,
body.theme-light .reports-chart-note,
body.theme-light .reports-kpi-copy small,
body.theme-light .reports-kpi-copy em,
body.theme-light .reports-category-row em,
body.theme-light .client-compact-main small,
body.theme-light .client-compact-status small,
body.theme-light .cash-row-date,
body.theme-light .statement-meta,
body.theme-light .statement-meta.muted{
  color:var(--color-text-muted);
}

body.theme-light .home-account-strip > div,
body.theme-light .dashboard-search,
body.theme-light .infographic-flow,
body.theme-light .infographic-node,
body.theme-light .insight-card,
body.theme-light .kpi-icon,
body.theme-light .reports-period-tabs,
body.theme-light .period-custom-bar,
body.theme-light .statement-filter-grid input,
body.theme-light .statement-filter-grid select{
  background:color-mix(in srgb, var(--color-surface) 78%, transparent);
  color:var(--color-text-primary);
  border-color:var(--color-border);
}

body.theme-light .side-menu,
body.theme-light[data-ui-profile="web_pwa"] .side-menu{
  color:var(--color-text-primary);
  border-color:var(--color-border);
  background:
    radial-gradient(circle at 18% 0%, rgba(13,148,136,.10), transparent 34%),
    linear-gradient(180deg, rgba(251,253,255,.96), rgba(232,240,245,.94));
  box-shadow:var(--effect-shadow-md);
}

body.theme-light .side-brand,
body.theme-light .side-profile-card{
  color:var(--color-text-primary);
  border-color:var(--color-border);
  background:linear-gradient(145deg, rgba(251,253,255,.94), rgba(232,240,245,.86));
  box-shadow:var(--effect-shadow-sm);
}

body.theme-light .side-profile-card::before{
  background:
    linear-gradient(90deg, transparent, rgba(13,148,136,.16), transparent) -120% 0 / 55% 100% no-repeat,
    linear-gradient(180deg, rgba(255,255,255,.58), transparent 48%);
