body.theme-light .btn:not(.secondary):not(.ghost):not(.danger):not(.warning):not(.outline):not(.icon) :where(span,strong,small,svg),
body.theme-light .app-button:not(.secondary):not(.ghost):not(.danger):not(.warning):not(.outline):not(.icon) :where(span,strong,small,svg),
