}

body.theme-light .profile-usage-tile span{
  width:32px;
  height:32px;
  display:grid;
  place-items:center;
  justify-self:start;
  border-radius:10px;
}

body.theme-light.mobile-mode .profile-usage-grid,
body.theme-light[data-ui-profile="android_apk"] .profile-usage-grid,
body.theme-light[data-ui-profile="web_pwa"].mobile-mode .profile-usage-grid{
