}

body.theme-light.mobile-mode .mobile-panel-calculator .calc-quick-fees,
body.theme-light[data-ui-profile="android_apk"] .mobile-panel-calculator .calc-quick-fees,
body.theme-light[data-ui-profile="web_pwa"].mobile-mode .mobile-panel-calculator .calc-quick-fees{
  grid-template-columns:repeat(4, minmax(0, 1fr));
}

body.theme-light.mobile-mode .mobile-panel-calculator .calc-quick-fees button,
body.theme-light[data-ui-profile="android_apk"] .mobile-panel-calculator .calc-quick-fees button,
body.theme-light[data-ui-profile="web_pwa"].mobile-mode .mobile-panel-calculator .calc-quick-fees button{
