}

@media (max-width: 640px){
  :root{
    --page-padding:calc(10px * var(--spacing-scale));
    --section-gap:calc(10px * var(--spacing-scale));
    --card-padding-token:calc(10px * var(--spacing-scale));
    --size-modal-width:100%;
  }

  .desktop-focus,
  .desktop-main,
  .mobile-home,
  .mobile-panel-content{
    max-width:100%;
  }

  .actions,
  .legal-actions,
  .modal-card .actions{
    grid-template-columns:1fr;
  }

  .modal-backdrop{
    align-items:end;
    padding:var(--space-sm);
  }

  .modal-card,
  .app-modal,
  .popup-box{
    width:100%;
    max-height:calc(100dvh - var(--space-lg) - var(--safe-area-inset-top, env(safe-area-inset-top, 0px)));
    border-radius:var(--radius-modal) var(--radius-modal) calc(var(--radius-modal) * .72) calc(var(--radius-modal) * .72);
  }

  .period-custom-bar,
  .statement-filter-grid{
    grid-template-columns:1fr;
  }

  .cash-main-summary,
  .cash-session-panel .compact-metrics,
  .cash-payment-summary,
  .statement-summary-grid{
    display:flex;
    gap:8px;
    overflow-x:auto;
    overscroll-behavior-x:contain;
    scroll-snap-type:x mandatory;
    padding:2px 2px 8px;
    scrollbar-width:none;
  }

  .cash-main-summary::-webkit-scrollbar,
  .cash-session-panel .compact-metrics::-webkit-scrollbar,
  .cash-payment-summary::-webkit-scrollbar,
  .statement-summary-grid::-webkit-scrollbar{
    display:none;
  }

  .cash-main-summary-card,
  .cash-session-panel .metric,
  .cash-payment-summary span,
  .statement-summary-card{
    flex:0 0 min(82%, 220px);
    scroll-snap-align:start;
  }

  .cash-session-panel{
    margin:10px 0 12px;
    padding:10px;
  }

  .cash-session-head{
    display:grid;
  }

  .cash-top-search{
    position:sticky;
    top:8px;
    z-index:4;
    margin:8px 0 10px;
  }

  .cash-movement-history,
  .statement-list{
    max-height:min(58dvh, 520px);
    overflow-y:auto;
    overscroll-behavior:contain;
    padding-right:2px;
  }

  .statement-head{
    display:grid;
  }

  .statement-actions{
    display:grid;
    grid-template-columns:1fr;
    width:100%;
  }

  .statement-row .row-title{
    display:grid;
    gap:4px;
  }
}

@media (min-width: 768px){
  .app-page,
  .organized-page,
  .dashboard-pro,
  .premium-dashboard{
    gap:var(--space-lg);
  }
}

@media (min-width: 1200px){
  .desktop-main{
    padding-inline:var(--page-padding);
  }
}

/* ERP/PWA visual foundation - fase 1 */
body[data-ui-profile="web_pwa"]:not(.mobile-mode){
  --desktop-sidebar-width:218px;
  --desktop-content-max:1360px;
  --erp-card-radius:16px;
  --erp-control-height:42px;
}

body[data-ui-profile="web_pwa"]:not(.mobile-mode) #app{
  height:100dvh;
  min-height:100dvh;
  padding:0;
  overflow:hidden;
  background:var(--color-background);
}

body[data-ui-profile="web_pwa"]:not(.mobile-mode) .desktop-shell{
  width:100%;
  max-width:none;
  height:100dvh;
  min-height:100dvh;
  gap:0;
  grid-template-columns:var(--desktop-sidebar-width) minmax(0, 1fr);
}

body[data-ui-profile="web_pwa"]:not(.mobile-mode) .desktop-shell.sidebar-collapsed{
  grid-template-columns:64px minmax(0, 1fr);
}

body[data-ui-profile="web_pwa"]:not(.mobile-mode) .desktop-main{
  height:100dvh;
  min-height:0;
  overflow-y:auto;
  overflow-x:hidden;
  align-content:start;
  gap:18px;
  padding:16px clamp(18px, 2vw, 32px) 32px;
  scroll-behavior:smooth;
}

body[data-ui-profile="web_pwa"]:not(.mobile-mode) .desktop-main > :not(.app-topbar){
  width:min(100%, var(--desktop-content-max));
  justify-self:center;
}

body[data-ui-profile="web_pwa"]:not(.mobile-mode) .desktop-main:has(> .settings-page){
  padding:0 0 0 0;
  gap:0;
}

body[data-ui-profile="web_pwa"]:not(.mobile-mode) .desktop-main > .settings-page{
  width:100%;
  max-width:none;
  min-height:100dvh;
  justify-self:stretch;
  border:0;
  border-radius:0;
  box-shadow:none;
}

body[data-ui-profile="web_pwa"]:not(.mobile-mode) .desktop-main > .settings-page > .card-header,
body[data-ui-profile="web_pwa"]:not(.mobile-mode) .desktop-main > .settings-page > p.muted{
  margin-right:clamp(16px, 2vw, 28px);
}

body[data-ui-profile="web_pwa"]:not(.mobile-mode) .desktop-focus{
  width:min(100%, var(--desktop-content-max));
}

body[data-ui-profile="web_pwa"]:not(.mobile-mode) .app-topbar{
  position:sticky;
  top:0;
  z-index:30;
  min-height:var(--topbar-height);
  width:min(100%, var(--desktop-content-max));
  justify-self:center;
  grid-template-columns:minmax(0, 1fr) auto auto;
  border-radius:0 0 var(--radius-lg) var(--radius-lg);
  border-color:var(--border-primary);
  background:color-mix(in srgb, var(--header-bg) 88%, transparent);
  box-shadow:var(--shadow-sm);
}

body[data-ui-profile="web_pwa"]:not(.mobile-mode) .app-topbar strong{
  color:var(--color-text-primary);
}

body[data-ui-profile="web_pwa"]:not(.mobile-mode) .topbar-user{
  display:flex;
  align-items:center;
  gap:10px;
}

.topbar-avatar-button{
  height:42px;
  display:inline-flex;
  align-items:center;
  gap:9px;
  padding:4px 10px 4px 5px;
  border:1px solid var(--border-primary);
  border-radius:var(--radius-pill);
  color:var(--text-primary);
  background:color-mix(in srgb, var(--color-surface) 78%, transparent);
  box-shadow:var(--shadow-sm);
}

.topbar-avatar{
  width:32px;
  height:32px;
  min-width:32px;
  display:grid;
  place-items:center;
  border-radius:999px;
  object-fit:cover;
  color:#fff;
  font-size:12px;
  font-weight:900;
  background:linear-gradient(145deg, var(--color-accent), var(--color-primary));
}

.topbar-profile-backdrop{
  position:fixed;
  inset:0;
  z-index:220;
  background:transparent;
}

.topbar-profile-menu{
  position:fixed;
  top:74px;
  right:clamp(16px, 2vw, 34px);
  width:min(320px, calc(100vw - 24px));
  display:grid;
  gap:8px;
  padding:12px;
  border:1px solid var(--color-border);
  border-radius:var(--radius-modal);
  background:var(--color-modal);
  color:var(--color-text-primary);
  box-shadow:var(--effect-shadow-xl);
  backdrop-filter:var(--effect-blur-glass);
}

.topbar-profile-head{
  display:grid;
  grid-template-columns:42px minmax(0, 1fr) auto;
  align-items:center;
  gap:10px;
  padding:4px 4px 10px;
  border-bottom:1px solid var(--color-divider);
}

.topbar-profile-avatar{
  width:42px;
  height:42px;
  display:grid;
  place-items:center;
  border-radius:999px;
  object-fit:cover;
  color:#fff;
  font-weight:900;
  background:linear-gradient(145deg, var(--color-accent), var(--color-primary));
}

.topbar-profile-head strong,
.topbar-profile-head small{
  display:block;
  overflow:hidden;
  text-overflow:ellipsis;
  white-space:nowrap;
}

.topbar-profile-head small{
  color:var(--color-text-muted);
  font-size:var(--font-xs);
}

.topbar-profile-menu > button{
  min-height:42px;
  display:flex;
  align-items:center;
  gap:10px;
  padding:9px 10px;
  border:1px solid transparent;
  border-radius:12px;
  color:var(--color-text-primary);
  background:transparent;
  text-align:left;
}

.topbar-profile-menu > button svg{
  width:18px;
  height:18px;
  flex:0 0 18px;
}

.topbar-profile-menu > button span{
  min-width:0;
  overflow:hidden;
  text-overflow:ellipsis;
  white-space:nowrap;
}

.topbar-profile-menu > button small{
  margin-left:auto;
  color:var(--color-text-muted, var(--text-muted));
  font-size:var(--font-xs);
  font-weight:700;
  white-space:nowrap;
}

.topbar-profile-menu > button:hover,
.topbar-profile-menu > button:focus-visible{
  background:color-mix(in srgb, var(--color-primary) 10%, var(--color-surface));
  border-color:color-mix(in srgb, var(--color-primary) 24%, var(--color-border));
  outline:none;
}

.topbar-profile-menu > button.danger{
  color:var(--color-danger);
}

body[data-ui-profile="web_pwa"]:not(.mobile-mode) .side-menu{
  position:sticky;
  top:0;
  height:100dvh;
  min-height:0;
  align-content:start;
  gap:8px;
  overflow-y:auto;
  overflow-x:hidden;
  padding:12px 10px;
  border-radius:0;
  border-block:0;
  border-left:0;
  background:var(--sidebar-bg);
}

body[data-ui-profile="web_pwa"]:not(.mobile-mode) .side-brand{
  min-height:54px;
  padding:8px;
  border-radius:14px;
}

.side-section-header{
  width:100%;
  min-height:30px;
  display:flex;
  align-items:center;
  justify-content:space-between;
  gap:8px;
  padding:5px 8px;
  border:0;
  border-radius:10px;
  color:var(--color-text-muted);
  background:transparent;
  font-size:var(--font-xs);
  font-weight:900;
  letter-spacing:.02em;
  text-transform:uppercase;
}

.side-section-header i{
  font-style:normal;
}

.side-section.is-closed .side-section-header i{
  transform:none;
}

.expand-toggle-indicator{
  width:22px;
  height:22px;
  display:grid;
  place-items:center;
  flex:0 0 22px;
  color:currentColor;
  border:1px solid color-mix(in srgb, currentColor 24%, transparent);
  border-radius:7px;
  font-size:0;
  line-height:1;
}

.expand-toggle-indicator::before{
  content:"−";
  font-size:16px;
  font-weight:900;
}

[aria-expanded="false"] > .expand-toggle-indicator::before{
  content:"+";
}

.side-section-items{
  display:grid;
  grid-template-columns:minmax(0,1fr);
  grid-auto-flow:row;
  gap:4px;
}

.side-menu .side-nav-button{
  width:100%;
  min-width:0;
}

.side-menu:not(.is-collapsed) .side-nav-button{
  display:flex;
  grid-template-columns:none;
  flex-direction:row;
  align-items:center;
  justify-content:flex-start;
}

.side-menu:not(.is-collapsed) .side-nav-button > span{
  flex:0 0 30px;
}

.side-menu:not(.is-collapsed) .side-nav-button > strong{
  min-width:0;
}

/* A navegação não pode herdar um flex horizontal de layouts externos. */
.side-menu{
  display:grid!important;
  grid-template-columns:minmax(0,1fr)!important;
  grid-auto-flow:row!important;
  align-content:start;
}

.side-menu :is(.side-section,.side-section-items){
  width:100%;
  min-width:0;
}

.side-section.is-closed .side-section-items{
  display:none;
}

body[data-ui-profile="web_pwa"]:not(.mobile-mode) .side-nav-button{
  min-height:42px;
  grid-template-columns:28px minmax(0, 1fr);
  gap:8px;
  padding:8px 10px;
  border-radius:12px;
}

body[data-ui-profile="web_pwa"]:not(.mobile-mode) .side-nav-button strong{
  font-size:14px;
}

body[data-ui-profile="web_pwa"]:not(.mobile-mode) .side-menu.is-collapsed .side-section-header{
  display:none;
}

body[data-ui-profile="web_pwa"]:not(.mobile-mode) .side-menu.is-collapsed .side-section-items{
  display:grid;
}

body[data-ui-profile="web_pwa"]:not(.mobile-mode) :where(.card,.modal-card,.metric-card,.settings-row,.ui-section,.desktop-dashboard-card,.dashboard-recent-orders,.dashboard-chart-card,.dashboard-insights,.analytics-module){
  border-radius:var(--erp-card-radius);
}

body[data-ui-profile="web_pwa"]:not(.mobile-mode) :where(.btn,.icon-button,input,select,textarea,.ui-tab,.tab){
  border-radius:12px;
}

body[data-ui-profile="web_pwa"]:not(.mobile-mode) :where(input,select,.btn){
  min-height:var(--erp-control-height);
}

body[data-ui-profile="web_pwa"]:not(.mobile-mode) .desktop-dashboard-hero{
  display:none;
}

body[data-ui-profile="web_pwa"]:not(.mobile-mode) .desktop-dashboard-grid{
  gap:18px;
}

body[data-ui-profile="web_pwa"]:not(.mobile-mode) .desktop-dashboard-metrics{
  grid-template-columns:repeat(4, minmax(0, 1fr));
  gap:12px;
}

body[data-ui-profile="web_pwa"]:not(.mobile-mode) .desktop-dashboard-metric{
  min-height:112px;
  padding:16px;
  grid-template-columns:minmax(0, 1fr) 38px;
}

body[data-ui-profile="web_pwa"]:not(.mobile-mode) .desktop-dashboard-metric-copy strong{
  font-size:clamp(26px, 2.35vw, 38px);
}

body[data-ui-profile="web_pwa"]:not(.mobile-mode) .desktop-dashboard-metric-copy small{
  font-size:13px;
}

body[data-ui-profile="web_pwa"]:not(.mobile-mode) .desktop-dashboard-metric-copy em{
  font-size:14px;
}

body[data-ui-profile="web_pwa"]:not(.mobile-mode) .desktop-dashboard-actions,
body[data-ui-profile="web_pwa"]:not(.mobile-mode) .desktop-dashboard-grid .dashboard-recent-orders{
  min-height:auto;
  padding:16px;
}

body[data-ui-profile="web_pwa"]:not(.mobile-mode) .desktop-dashboard-actions .quick-actions{
  grid-template-columns:repeat(auto-fit, minmax(130px, 1fr));
  gap:12px;
}

body[data-ui-profile="web_pwa"]:not(.mobile-mode) .desktop-dashboard-actions .quick-action{
  min-height:84px;
}

.store-preview-container{
  display:grid;
  gap:14px;
  padding:16px;
  border:1px solid var(--color-border);
  border-radius:var(--erp-card-radius, var(--radius-card));
  background:linear-gradient(145deg, color-mix(in srgb, var(--color-surface) 92%, transparent), color-mix(in srgb, var(--color-surface) 72%, transparent));
  box-shadow:var(--effect-shadow-md);
}

.editable-container{
  display:grid;
  gap:8px;
}

.editable-container > span{
  color:var(--color-text-muted);
  font-size:var(--font-xs);
  font-weight:800;
  text-transform:uppercase;
}

.store-header-preview{
  display:flex;
  align-items:center;
  gap:10px;
}

.store-header-preview img,
.store-header-logo{
  width:40px;
  height:40px;
  border-radius:12px;
  object-fit:cover;
}

.store-banner-section{
  min-height:150px;
  position:relative;
  overflow:hidden;
  display:grid;
  align-items:end;
  padding:18px;
  border-radius:18px;
  color:#fff;
  background:
    radial-gradient(circle at 18% 12%, color-mix(in srgb, var(--store-primary) 46%, transparent), transparent 40%),
    linear-gradient(135deg, color-mix(in srgb, var(--store-primary) 86%, #08242b), color-mix(in srgb, var(--store-accent) 52%, #0f172a));
}

.store-banner-section img{
  position:absolute;
  inset:0;
  width:100%;
  height:100%;
  object-fit:cover;
  opacity:.28;
}

.store-banner-section > div{
  position:relative;
  display:grid;
  gap:4px;
  max-width:520px;
}

.store-section{
  display:grid;
  gap:10px;
}

.store-section h4{
  margin:0;
  font-size:16px;
}

.store-category-row,
.store-product-grid{
  display:grid;
  gap:10px;
}

.store-category-row{
  grid-template-columns:repeat(auto-fit, minmax(118px, 1fr));
}

.store-category-row span{
  min-height:38px;
  display:grid;
  place-items:center;
  gap:2px;
  padding:8px 10px;
  border:1px solid var(--color-border);
  border-radius:999px;
  background:color-mix(in srgb, var(--color-primary) 10%, var(--color-surface));
  color:var(--color-text-primary);
  font-weight:800;
}

.store-category-row span em{
