  color:var(--color-text-muted);
  font-style:normal;
  text-transform:uppercase;
}

.store-product-grid{
  grid-template-columns:repeat(auto-fit, minmax(132px, 1fr));
}

.store-product-card{
  display:grid;
  gap:7px;
  padding:10px;
  border:1px solid var(--color-border);
  border-radius:14px;
  background:var(--color-card);
  color:var(--color-text-primary);
}

.store-product-card .status-badge{
  justify-self:start;
}

.store-product-media{
  aspect-ratio:4 / 3;
  display:grid;
  place-items:center;
  overflow:hidden;
  border-radius:12px;
  background:var(--color-background-secondary);
  color:var(--color-primary);
}

.store-product-media img{
  width:100%;
  height:100%;
  object-fit:cover;
}

body.theme-light .app-topbar,
body.theme-light .topbar-profile-menu{
  background:color-mix(in srgb, var(--color-surface) 92%, transparent);
  color:var(--color-text-primary);
  border-color:var(--color-border);
}

body.theme-light .topbar-avatar-button,
.storefront-root[data-store-theme="light"] .store-preview-container,
.storefront-root[data-store-theme="light"] .store-product-card{
  background:var(--color-surface);
  color:var(--color-text-primary);
  border-color:var(--color-border);
}

body.theme-light .side-section-header{
  color:var(--color-text-muted);
