/* Fase 2C - fluxo operacional rapido do ERP */
.operational-card-actions{
  display:flex;
  align-items:center;
  justify-content:flex-end;
  gap:10px;
  flex-wrap:wrap;
}

.operational-drawer{
  width:min(980px, calc(100vw - 18px));
  max-height:var(--app-viewport-height, 100dvh);
  height:var(--app-viewport-height, 100dvh);
  padding:0;
  border-radius:24px 0 0 24px;
  display:grid;
  grid-template-rows:auto minmax(0, 1fr);
  gap:0;
  overflow:hidden;
}

body[data-ui-profile="web_pwa"] .operational-drawer{
  width:min(980px, calc(100vw - 18px)) !important;
  max-width:none !important;
  max-height:var(--app-viewport-height, 100dvh) !important;
  height:var(--app-viewport-height, 100dvh) !important;
  padding:0 !important;
  overflow:hidden !important;
}

body[data-ui-profile="web_pwa"] .operational-drawer > .modal-header{
  position:relative !important;
  top:auto !important;
  box-sizing:border-box;
  width:100%;
  margin:0 !important;
  padding:16px;
}

.quick-order-layout{
  min-height:0;
  height:100%;
  max-height:100%;
  display:grid;
  grid-template-columns:minmax(0, 1.25fr) minmax(320px, .75fr);
  gap:16px;
  overflow-x:hidden;
  overflow-y:auto;
  overscroll-behavior:contain;
  -webkit-overflow-scrolling:touch;
  touch-action:pan-y;
  padding:16px;
}

.quick-order-form,
.quick-order-summary{
  min-width:0;
  display:grid;
  align-content:start;
  gap:14px;
}

.quick-order-section{
  display:grid;
  gap:12px;
  padding:14px;
  border:1px solid var(--color-border);
  border-radius:var(--radius-card);
  background:color-mix(in srgb, var(--color-surface) 54%, transparent);
  box-shadow:var(--effect-shadow-sm);
}

.quick-order-drawer .customer-suggestion-box{
  max-height:180px;
  overflow:auto;
  overscroll-behavior:contain;
}

.quick-order-section-title{
  display:flex;
  align-items:center;
  gap:10px;
  color:var(--color-text-primary);
}

.quick-order-section-title span,
.quick-order-items article > span{
  width:30px;
  height:30px;
  display:grid;
  place-items:center;
  border-radius:999px;
  background:color-mix(in srgb, var(--color-primary) 14%, transparent);
  color:var(--color-primary);
  font-weight:900;
}

.quick-item-grid,
.quick-operation-grid{
  display:grid;
  grid-template-columns:repeat(4, minmax(0, 1fr));
  gap:10px;
}

.quick-item-grid .quick-item-name,
.quick-item-grid .quick-item-half{
  grid-column:span 2;
}

.quick-operation-grid{
  grid-template-columns:repeat(auto-fit, minmax(170px, 1fr));
}

.quick-order-inline-actions{
  justify-content:flex-start;
}

.quick-order-summary{
  position:sticky;
  top:0;
  padding:14px;
  border:1px solid color-mix(in srgb, var(--color-primary) 22%, var(--color-border));
  border-radius:var(--radius-card);
  background:
    radial-gradient(circle at 20% 0%, color-mix(in srgb, var(--color-primary) 10%, transparent), transparent 38%),
    color-mix(in srgb, var(--color-surface) 68%, transparent);
  box-shadow:var(--effect-shadow-md);
}

.quick-order-summary h3{
  margin:8px 0 2px;
  color:var(--color-text-primary);
}

.quick-order-command-panel{
  display:grid;
  gap:10px;
  padding:12px;
  border:1px solid color-mix(in srgb, var(--color-primary) 24%, var(--color-border));
  border-radius:var(--radius-card);
  background:color-mix(in srgb, var(--color-primary) 7%, var(--color-surface));
}

.quick-order-command-panel > strong{
  color:var(--color-text-primary);
  font-size:13px;
}

.quick-order-command-panel ul{
  display:grid;
  gap:7px;
  margin:0;
  padding:0;
  list-style:none;
}

.quick-order-command-panel li{
  display:flex;
  align-items:center;
  gap:6px;
  color:var(--color-text-muted);
  font-size:12px;
}

.quick-order-command-panel li span{
  margin-left:auto;
  text-align:right;
}

.quick-order-command-panel kbd{
  min-width:34px;
  padding:4px 6px;
  border:1px solid var(--color-border);
  border-bottom-width:2px;
  border-radius:6px;
  background:var(--color-surface);
  color:var(--color-text-primary);
  font:700 11px/1 system-ui, sans-serif;
  text-align:center;
}

.quick-order-command-panel b{
  color:var(--color-text-muted);
  font-size:10px;
}

.quick-order-items{
  display:grid;
  gap:9px;
}

.quick-order-items article{
  min-width:0;
  display:grid;
  grid-template-columns:auto minmax(0, 1fr) auto auto auto;
  align-items:center;
  gap:10px;
  padding:10px;
  border:1px solid var(--color-border);
  border-radius:14px;
  background:color-mix(in srgb, var(--color-surface) 64%, transparent);
}

.quick-order-items article.is-selected,
.order-item-card.is-multi-selected{
  border-color:color-mix(in srgb, var(--color-primary) 46%, var(--color-border));
  background:color-mix(in srgb, var(--color-primary) 10%, var(--color-surface));
  box-shadow:0 10px 28px color-mix(in srgb, var(--color-primary) 12%, transparent);
}

.quick-order-item-select,
.order-item-multi-select{
  width:30px;
  height:30px;
  position:relative;
  display:grid;
  place-items:center;
  cursor:pointer;
}

.quick-order-item-select input,
.order-item-multi-select input{
  position:absolute;
  inset:0;
  opacity:0;
  cursor:pointer;
}

.quick-order-item-select span,
.order-item-multi-select span{
  width:30px;
  height:30px;
  display:grid;
  place-items:center;
  border:1px solid color-mix(in srgb, var(--color-primary) 20%, var(--color-border));
  border-radius:999px;
  background:color-mix(in srgb, var(--color-primary) 14%, transparent);
  color:var(--color-primary);
  font-weight:900;
  transition:background-color .18s ease, color .18s ease, border-color .18s ease, transform .18s ease;
}

.quick-order-item-select input:checked + span,
.order-item-multi-select input:checked + span{
  border-color:var(--color-primary);
  background:var(--color-primary);
  color:var(--color-on-primary, #fff);
  transform:scale(1.04);
}

.quick-order-bulkbar,
.order-bulkbar{
  display:grid;
  gap:10px;
  padding:10px;
  border:1px solid var(--color-border);
  border-radius:16px;
  background:color-mix(in srgb, var(--color-surface) 56%, transparent);
}

.quick-order-bulkbar.is-active,
.order-bulkbar.is-active{
  border-color:color-mix(in srgb, var(--color-primary) 34%, var(--color-border));
  background:linear-gradient(135deg, color-mix(in srgb, var(--color-primary) 12%, transparent), color-mix(in srgb, var(--color-surface) 72%, transparent));
}

.quick-order-bulkbar strong,
.quick-order-bulkbar small,
.order-bulkbar strong,
.order-bulkbar small{
  display:block;
}

.quick-order-bulkbar small,
.order-bulkbar small{
  margin-top:2px;
  color:var(--color-text-muted);
  font-size:12px;
}

.quick-order-bulk-actions,
.order-bulk-actions{
  display:grid;
  grid-template-columns:repeat(auto-fit, minmax(96px, 1fr));
  gap:8px;
}

.quick-order-bulk-actions .btn,
.order-bulk-actions .btn{
  min-height:38px;
  padding-inline:10px;
}

.bulk-qty-field{
  min-width:0;
  display:grid;
  grid-template-columns:auto minmax(46px, 1fr);
  align-items:center;
  gap:6px;
  min-height:38px;
  padding:0 10px;
  border:1px solid var(--color-border);
  border-radius:var(--radius-button);
  background:color-mix(in srgb, var(--color-surface) 72%, transparent);
  color:var(--color-text-muted);
  font-size:12px;
  font-weight:800;
}

.bulk-qty-field input{
  width:100%;
  min-width:0;
  height:28px;
  padding:0 6px;
  border:0;
  border-radius:8px;
  background:transparent;
  color:var(--color-text-primary);
  font-weight:900;
  text-align:center;
}

.quick-order-items strong,
.quick-order-items small{
  display:block;
  min-width:0;
