.quick-order-items small{
  color:var(--color-text-muted);
}

.quick-order-finance{
  margin:0;
}

.quick-order-final-actions{
  display:grid;
  grid-template-columns:repeat(3, minmax(0, 1fr));
  gap:8px;
}

.order-operational-timeline{
  display:grid;
  grid-template-columns:repeat(5, minmax(0, 1fr));
