@media (max-width: 900px){

  .operational-drawer{
    width:100%;
    height:min(calc(var(--app-viewport-height, 100dvh) - 8px), 860px);
    max-height:calc(var(--app-viewport-height, 100dvh) - 8px);
    border-radius:24px 24px 0 0;
  }

  .operational-drawer > .modal-header{
    box-sizing:border-box;
    width:100%;
    margin:0 !important;
    padding:18px max(22px, env(safe-area-inset-right)) 14px max(22px, env(safe-area-inset-left)) !important;
  }

  body[data-ui-profile="web_pwa"] .operational-drawer{
    width:100% !important;
    height:min(calc(var(--app-viewport-height, 100dvh) - 8px), 860px) !important;
    max-height:calc(var(--app-viewport-height, 100dvh) - 8px) !important;
    border-radius:24px 24px 0 0;
  }

  .quick-order-layout{
    grid-template-columns:1fr;
    padding-bottom:calc(16px + var(--keyboard-inset, 0px) + env(safe-area-inset-bottom));
    scroll-padding-bottom:calc(88px + var(--keyboard-inset, 0px) + env(safe-area-inset-bottom));
  }

  .quick-order-summary{
    position:relative;
    padding-bottom:calc(14px + env(safe-area-inset-bottom));
  }

  .quick-order-items article{
    grid-template-columns:auto minmax(0, 1fr) auto;
  }

  .quick-order-bulk-actions,
  .order-bulk-actions{
    grid-template-columns:repeat(2, minmax(0, 1fr));
  }

  .quick-order-items article .icon-action-button{
    width:40px;
    height:40px;
  }

  .quick-item-grid{
    grid-template-columns:repeat(2, minmax(0, 1fr));
  }

  .quick-item-grid .quick-item-name{
    grid-column:1 / -1;
  }

  .quick-item-grid .quick-item-half{
    grid-column:auto;
  }

  .quick-order-final-actions{
    grid-template-columns:1fr;
  }

  .quick-order-final-actions{
    position:sticky;
    bottom:calc(8px + var(--keyboard-inset, 0px) + env(safe-area-inset-bottom));
    z-index:3;
    padding:8px;
    border:1px solid var(--color-border);
    border-radius:var(--radius-card);
    background:color-mix(in srgb, var(--color-surface) 88%, transparent);
    box-shadow:var(--effect-shadow-md);
    backdrop-filter:blur(14px);
    -webkit-backdrop-filter:blur(14px);
  }
}

