  cursor:not-allowed;
}

.store-product-admin-grid{
  display:grid;
  grid-template-columns:repeat(auto-fit, minmax(280px, 1fr));
  gap:12px;
}

.store-product-admin-card{
  min-width:0;
  display:grid;
  grid-template-rows:auto 1fr auto auto;
  gap:12px;
  padding:12px;
  border:1px solid var(--color-border);
  border-radius:var(--radius-card);
  background:color-mix(in srgb, var(--color-surface) 78%, transparent);
  box-shadow:var(--effect-shadow-sm);
}

.store-product-admin-card:hover,
.store-admin-row:hover{
  border-color:color-mix(in srgb, var(--color-primary) 24%, var(--color-border));
  transform:translateY(-1px);
}

.store-product-admin-media{
  aspect-ratio:16 / 10;
  display:grid;
  place-items:center;
  overflow:hidden;
  border-radius:14px;
  background:var(--color-background-secondary);
  color:var(--color-primary);
}

.store-product-admin-media img{
  width:100%;
  height:100%;
  object-fit:cover;
}

.store-product-admin-body{
  min-width:0;
  display:grid;
  gap:5px;
}

.store-badge-row{
  display:flex;
  flex-wrap:wrap;
  gap:6px;
}

.store-lead-row{
  grid-template-columns:minmax(0, 1.2fr) minmax(140px, .45fr) minmax(320px, .9fr);
}

.store-empty-state{
  grid-column:1 / -1;
  min-height:150px;
  display:grid;
  align-content:center;
  justify-items:center;
  gap:8px;
  padding:20px;
  border:1px dashed color-mix(in srgb, var(--color-border) 70%, var(--color-primary));
  border-radius:var(--radius-card);
  background:color-mix(in srgb, var(--color-surface) 36%, transparent);
  color:var(--color-text-muted);
  text-align:center;
}

.store-empty-state span{
  width:42px;
  height:42px;
  display:grid;
  place-items:center;
  border-radius:14px;
  background:color-mix(in srgb, var(--color-primary) 12%, transparent);
  color:var(--color-primary);
}

.store-empty-state strong{
  color:var(--color-text-primary);
}

.store-qr-layout{
  display:grid;
  grid-template-columns:minmax(0, 1fr) minmax(220px, 300px);
  gap:18px;
  align-items:center;
}

.store-qr-label{
  display:block;
  margin-bottom:8px;
  color:var(--color-text-muted);
  font-size:var(--type-label);
  font-weight:800;
}

.store-qr-panel{
  display:grid;
  justify-items:center;
  gap:10px;
  padding:18px;
  border:1px solid var(--color-border);
  border-radius:var(--radius-card);
  background:color-mix(in srgb, var(--color-surface) 76%, transparent);
}

.qr-preview{
  width:180px;
  height:180px;
  display:grid;
  place-items:center;
  border-radius:18px;
  background:var(--color-surface);
}

.qr-preview img{
  width:160px;
  height:160px;
  border-radius:16px;
  background:#fff;
  padding:10px;
}

.storefront-root[data-store-theme="light"] :where(.store-status-card,.store-admin-row,.store-product-admin-card,.store-qr-panel,.store-preview-device){
  background:var(--color-card);
  border-color:var(--color-border);
  color:var(--color-text-primary);
}

.storefront-root[data-store-theme="light"] .storefront-beta-banner{
  background:color-mix(in srgb, var(--color-info) 8%, var(--color-surface));
}

.storefront-root[data-store-theme="light"] .storefront-demo-banner{
  background:color-mix(in srgb, var(--color-warning) 10%, var(--color-surface));
}

/* Loja Online beta - preview funcional e experiencia premium */
.store-preview-device{
  overflow:hidden;
  background:
    radial-gradient(circle at 12% 0%, color-mix(in srgb, var(--color-primary) 13%, transparent), transparent 34%),
    linear-gradient(145deg, color-mix(in srgb, var(--color-surface) 90%, transparent), color-mix(in srgb, var(--color-background-secondary) 84%, transparent));
}

.editable-container{
  position:relative;
  border-radius:18px;
}

.editable-container::after{
  content:"";
  position:absolute;
  inset:-1px;
  pointer-events:none;
  border:1px solid transparent;
  border-radius:inherit;
  transition:var(--premium-transition, border-color .18s ease);
}

.editable-container:hover::after{
  border-color:color-mix(in srgb, var(--color-primary) 18%, transparent);
}

.store-header-preview{
  min-height:74px;
  justify-content:space-between;
  padding:12px;
  border:1px solid color-mix(in srgb, var(--color-border) 84%, var(--color-primary));
  border-radius:18px;
  background:color-mix(in srgb, var(--color-surface) 78%, transparent);
  box-shadow:inset 0 1px 0 var(--glass-highlight);
}

.store-header-brand{
  min-width:0;
  display:flex;
  align-items:center;
  gap:11px;
}

.store-header-brand > div{
  min-width:0;
  display:grid;
  gap:2px;
}

.store-header-brand strong,
.store-header-brand small{
  min-width:0;
  overflow:hidden;
  text-overflow:ellipsis;
  white-space:nowrap;
}

.store-header-brand small{
  color:var(--color-text-muted);
  font-size:12px;
}

.store-header-actions{
  display:flex;
  align-items:center;
  justify-content:flex-end;
  gap:8px;
  flex-wrap:wrap;
}

.store-header-actions .btn{
  min-height:34px;
  padding:0 10px;
  border-radius:999px;
  font-size:12px;
}

.store-banner-section{
  min-height:220px;
  padding:22px;
  align-items:end;
  box-shadow:inset 0 1px 0 rgba(255,255,255,.14), 0 18px 36px rgba(0,0,0,.18);
}

.store-banner-section::before{
  content:"";
  position:absolute;
  inset:0;
  background:
    linear-gradient(180deg, transparent 0%, rgba(0,0,0,.18) 52%, rgba(0,0,0,.48) 100%),
    radial-gradient(circle at 86% 12%, color-mix(in srgb, var(--store-accent) 42%, transparent), transparent 34%);
  pointer-events:none;
}

.store-banner-section > div{
  z-index:1;
  gap:7px;
}

.store-banner-section span{
  width:max-content;
  max-width:100%;
  padding:5px 9px;
  border:1px solid rgba(255,255,255,.22);
  border-radius:999px;
  background:rgba(255,255,255,.12);
  font-size:11px;
  font-weight:900;
  text-transform:uppercase;
  letter-spacing:.04em;
}

.store-banner-section strong{
  font-size:clamp(28px, 3.3vw, 44px);
  line-height:1;
  max-width:12ch;
}

.store-banner-section small{
  max-width:48ch;
  color:rgba(255,255,255,.84);
  font-size:14px;
  line-height:1.45;
}

.store-banner-section .btn{
  width:max-content;
  margin-top:6px;
  color:#073b4b;
  background:rgba(255,255,255,.92);
  border-color:rgba(255,255,255,.34);
}

.store-section{
  padding:2px;
}

.store-section-head{
  min-width:0;
  display:flex;
  align-items:end;
  justify-content:space-between;
  gap:10px;
}

.store-section-head small{
  color:var(--color-text-muted);
  font-size:12px;
}

.store-category-row{
  display:flex;
  gap:9px;
  overflow-x:auto;
  padding:1px 1px 6px;
  scrollbar-width:none;
}

.store-category-row::-webkit-scrollbar{
  display:none;
}

.store-category-row button{
  flex:0 0 auto;
  min-height:42px;
  display:flex;
  align-items:center;
  gap:8px;
  padding:8px 12px;
  border:1px solid var(--color-border);
  border-radius:999px;
  background:color-mix(in srgb, var(--color-surface) 72%, transparent);
  color:var(--color-text-primary);
  box-shadow:var(--effect-shadow-sm);
  opacity:1;
  cursor:default;
  transition:var(--premium-transition, background-color .18s ease);
}

.store-category-row button > span{
  width:24px;
  height:24px;
  min-height:24px;
  display:grid;
  place-items:center;
  padding:0;
  border:0;
  border-radius:999px;
  background:color-mix(in srgb, var(--color-primary) 12%, transparent);
  color:var(--color-primary);
  box-shadow:none;
}

.store-category-row button strong{
  font-size:12px;
  white-space:nowrap;
}

.store-category-row button em{
  color:var(--color-text-muted);
  font-size:9px;
  font-style:normal;
  text-transform:uppercase;
}

.store-category-row button.active{
  border-color:color-mix(in srgb, var(--color-primary) 38%, var(--color-border));
  background:color-mix(in srgb, var(--color-primary) 14%, var(--color-surface));
}

.store-product-grid{
  grid-template-columns:repeat(auto-fit, minmax(190px, 1fr));
  gap:12px;
}

.store-product-card{
  position:relative;
  min-width:0;
  gap:10px;
  padding:12px;
  border-radius:18px;
  background:
    linear-gradient(145deg, color-mix(in srgb, var(--color-card) 94%, transparent), color-mix(in srgb, var(--color-surface) 78%, transparent));
  box-shadow:var(--effect-shadow-sm);
  transition:var(--premium-transition, transform .18s ease);
}

.store-product-media{
  aspect-ratio:1 / .78;
  position:relative;
  border-radius:16px;
  background:
    radial-gradient(circle at 30% 18%, color-mix(in srgb, var(--color-primary) 18%, transparent), transparent 38%),
    var(--color-background-secondary);
}

.store-product-media svg{
  width:34px;
  height:34px;
}

.store-product-floating-badge{
  position:absolute;
  top:9px;
  left:9px;
  max-width:calc(100% - 18px);
  overflow:hidden;
  text-overflow:ellipsis;
  white-space:nowrap;
  padding:5px 8px;
  border:1px solid color-mix(in srgb, var(--color-primary) 26%, rgba(255,255,255,.18));
  border-radius:999px;
  background:color-mix(in srgb, var(--color-surface) 78%, transparent);
  color:var(--color-text-primary);
  font-size:10px;
  font-weight:900;
  box-shadow:var(--effect-shadow-sm);
}

.store-product-copy{
  min-width:0;
  display:grid;
  gap:4px;
}

.store-product-copy span{
  color:var(--color-primary);
  font-size:11px;
  font-weight:900;
  text-transform:uppercase;
}

.store-product-copy strong{
  color:var(--color-text-primary);
  line-height:1.2;
}

.store-product-copy small{
  display:-webkit-box;
  overflow:hidden;
  -webkit-line-clamp:2;
  -webkit-box-orient:vertical;
  color:var(--color-text-muted);
  line-height:1.35;
}

.store-product-meta{
  display:grid;
  gap:3px;
}

.store-product-meta strong{
  color:var(--color-text-primary);
  font-size:18px;
}

.store-product-meta small{
  color:var(--color-text-secondary);
  font-size:12px;
}

.store-product-actions{
  display:flex;
  align-items:center;
  justify-content:space-between;
  gap:8px;
  flex-wrap:wrap;
}

.store-product-actions .btn{
  min-height:36px;
  padding:0 12px;
  border-radius:999px;
}

.store-product-actions .btn:disabled,
.store-header-actions .btn:disabled,
.store-banner-section .btn:disabled{
  opacity:1;
  cursor:default;
}

.store-preview-footer{
  display:flex;
  align-items:center;
  justify-content:space-between;
  gap:12px;
  padding:12px 14px;
  border:1px solid color-mix(in srgb, var(--color-border) 80%, transparent);
  border-radius:16px;
  background:color-mix(in srgb, var(--color-surface) 62%, transparent);
  color:var(--color-text-muted);
  font-size:12px;
}

.store-preview-footer strong{
  color:var(--color-text-primary);
}

.store-admin-row,
.store-product-admin-card,
.store-status-card,
.store-qr-panel{
  transition:var(--premium-transition, transform .18s ease);
}

@media (hover:hover) and (pointer:fine){
  .store-product-card:hover,
  .store-product-admin-card:hover,
  .store-admin-row:hover,
  .store-status-card:hover,
  .store-qr-panel:hover{
    transform:translateY(-2px);
    border-color:color-mix(in srgb, var(--color-primary) 22%, var(--color-border));
    box-shadow:var(--effect-shadow-md);
  }

  .store-category-row button:hover{
    border-color:color-mix(in srgb, var(--color-primary) 28%, var(--color-border));
    background:color-mix(in srgb, var(--color-primary) 12%, var(--color-surface));
  }
}

.store-lead-row{
  position:relative;
}

.store-lead-row::before{
  content:"";
  position:absolute;
  left:32px;
  top:18px;
  bottom:18px;
  width:2px;
  border-radius:999px;
  background:color-mix(in srgb, var(--color-primary) 22%, transparent);
  opacity:.55;
}

.store-lead-row .store-admin-main,
.store-lead-row .store-admin-meta,
.store-lead-row .store-admin-actions{
  position:relative;
  z-index:1;
}

.store-qr-panel{
  background:
    radial-gradient(circle at 50% 0%, color-mix(in srgb, var(--color-primary) 10%, transparent), transparent 44%),
    color-mix(in srgb, var(--color-surface) 76%, transparent);
}

.storefront-root[data-store-theme="light"] .store-preview-device{
  background:
    radial-gradient(circle at 12% 0%, color-mix(in srgb, var(--color-primary) 8%, transparent), transparent 34%),
    linear-gradient(145deg, rgba(255,255,255,.96), rgba(238,244,247,.88));
}

.storefront-root[data-store-theme="light"] .store-header-preview,
.storefront-root[data-store-theme="light"] .store-preview-footer,
.storefront-root[data-store-theme="light"] .store-category-row button,
.storefront-root[data-store-theme="light"] .store-product-card{
  background:rgba(255,255,255,.92);
  border-color:var(--color-border);
  color:var(--color-text-primary);
}

.storefront-root[data-store-theme="light"] .store-product-floating-badge{
  background:rgba(255,255,255,.88);
}

/* Fase 3A - loja publica integrada */
.store-public-shell{
  --store-bg:#090b10;
  --store-bg-soft:#101217;
  --store-surface:rgba(28, 31, 38, .88);
  --store-surface-strong:rgba(42, 47, 58, .76);
  --store-surface-muted:rgba(255,255,255,.07);
  --store-text:#f8fbff;
  --store-text-soft:#e8eef8;
  --store-muted:#a8b3c1;
  --store-muted-2:#7d8794;
  --store-border:rgba(255,255,255,.07);
  --store-border-soft:rgba(255,255,255,.045);
  --store-radius:18px;
  --store-radius-lg:28px;
  --store-radius-xl:34px;
  --store-shadow:0 26px 74px rgba(0,0,0,.34);
  --store-shadow-soft:0 14px 34px rgba(0,0,0,.24);
  --store-button-bg:color-mix(in srgb, var(--store-primary, var(--color-primary)) 92%, #ffffff 8%);
  --store-button-hover:color-mix(in srgb, var(--store-primary, var(--color-primary)) 86%, #ffffff);
  --store-button-radius:14px;
  --store-button-height:44px;
  --store-button-shadow:0 12px 26px color-mix(in srgb, var(--store-primary, var(--color-primary)) 18%, transparent);
  --store-transition:background-color .18s ease, border-color .18s ease, color .18s ease, transform .18s ease, box-shadow .18s ease, opacity .18s ease;
  min-height:100svh;
  width:100%;
  max-width:100%;
  overflow-x:hidden;
  overflow-y:visible;
  overscroll-behavior-y:auto;
  touch-action:auto;
  color:var(--store-text);
  background:
    radial-gradient(circle at top left, color-mix(in srgb, var(--store-primary, var(--color-primary)) 9%, transparent), transparent 34%),
    radial-gradient(circle at top right, rgba(255,255,255,.045), transparent 30%),
    var(--store-bg);
  padding:18px clamp(14px, 3vw, 34px) 28px;
}

body:has(.store-public-shell){
  width:100%;
  max-width:100%;
  overscroll-behavior-y:auto;
  touch-action:auto;
}

body[data-ui-profile="web_pwa"]:not(.mobile-mode) #app:has(.store-public-shell),
body[data-ui-profile="android_apk"] #app:has(.store-public-shell){
  height:auto;
  min-height:100dvh;
  overflow:visible;
  overflow-x:clip;
  padding:0;
  touch-action:auto;
}

body[data-ui-profile="web_pwa"]:not(.mobile-mode):has(.store-public-shell),
body[data-ui-profile="android_apk"]:has(.store-public-shell){
  overflow-y:auto;
  touch-action:auto;
}

.store-public-shell.store-public-admin-mode{
  padding:0;
  background:var(--store-bg-soft);
}

.storefront-admin-standalone,
.store-public-shell,
.store-visual-editor-canvas{
  scroll-behavior:smooth;
}

.storefront-admin-standalone,
.store-public-shell{
  height:auto;
  max-height:none;
}

.store-preview-device{
  max-height:none;
  overflow:visible;
}

.store-preview-container{
  position:sticky;
  top:88px;
}

.store-visual-editor-frame{
  width:100%;
  max-width:100%;
  min-height:100svh;
  display:grid;
  grid-template-columns:292px minmax(0, 1fr);
  background:var(--store-bg-soft);
  overflow-x:hidden;
}

.store-visual-editor-main{
  min-width:0;
  display:grid;
  grid-template-rows:66px minmax(0, 1fr);
  border-left:1px solid var(--store-border);
}

.store-visual-editor-topbar{
  position:sticky;
  top:0;
  z-index:38;
  min-width:0;
  display:grid;
  grid-template-columns:1fr auto 1fr;
  align-items:center;
  gap:14px;
  padding:10px 18px;
  border-bottom:1px solid var(--store-border);
  background:rgba(12,16,22,.94);
  backdrop-filter:blur(18px);
}

.store-visual-top-context{
  min-width:0;
  display:grid;
  gap:2px;
}

.store-visual-top-context strong{
  color:var(--store-text);
  font-size:14px;
}

.store-visual-top-context span{
  color:var(--store-muted-2);
  font-size:12px;
  font-weight:700;
}

.store-visual-top-actions{
  display:flex;
  justify-content:flex-end;
  align-items:center;
  gap:8px;
}

.store-visual-top-actions :where(button,a){
  min-height:var(--store-button-height);
  display:inline-flex;
  align-items:center;
  justify-content:center;
  gap:8px;
  padding:0 16px;
  border:1px solid color-mix(in srgb, var(--store-border) 100%, #ffffff 8%);
  border-radius:var(--store-button-radius);
  background:rgba(255,255,255,.045);
  color:var(--store-text-soft);
  text-decoration:none;
  font-weight:850;
  cursor:pointer;
  transition:var(--store-transition);
}

.store-visual-top-actions :where(button,a):hover{
  border-color:color-mix(in srgb, var(--store-primary, var(--color-primary)) 28%, var(--store-border));
  background:rgba(255,255,255,.075);
  transform:translateY(-1px);
}

.store-visual-top-actions .publish{
  border-color:color-mix(in srgb, var(--store-primary, var(--color-primary)) 70%, transparent);
  background:var(--store-button-bg);
  color:#fff;
  box-shadow:var(--store-button-shadow);
}

.store-mobile-admin-actions{
  display:none;
}

.store-visual-editor-layout{
  width:min(1680px, 100%);
  margin:0 auto;
  display:grid;
  grid-template-columns:minmax(260px, 310px) minmax(0, 1fr);
  gap:20px;
  align-items:start;
}

.store-visual-editor-sidebar{
  position:sticky;
  top:0;
  height:100svh;
  overflow-y:auto;
  overscroll-behavior:auto;
  min-width:0;
  display:grid;
  align-content:start;
  gap:16px;
  padding:18px 18px 22px;
  border:0;
  border-radius:0;
  background:linear-gradient(180deg, #151a20, #101419);
  box-shadow:none;
  z-index:20;
}

.store-visual-editor-brand{
  min-width:0;
  display:grid;
  grid-template-columns:32px minmax(0, 1fr) 32px;
  align-items:center;
  gap:8px;
  padding-bottom:18px;
  border-bottom:1px solid var(--store-border);
}

.store-visual-editor-brand strong{
  color:var(--store-text);
  font-size:16px;
  white-space:nowrap;
  overflow:hidden;
  text-overflow:ellipsis;
}

.store-visual-editor-brand button{
  width:32px;
  height:32px;
  border:0;
  border-radius:10px;
  background:transparent;
  color:var(--store-muted);
  cursor:pointer;
}

.store-visual-mode-switch{
  display:grid;
  grid-template-columns:1fr 1fr;
  gap:6px;
  padding:4px;
  border:1px solid var(--store-border);
  border-radius:999px;
  background:rgba(255,255,255,.045);
}

.store-visual-mode-switch button{
  min-height:34px;
  border:0;
  border-radius:999px;
  background:transparent;
  color:var(--store-muted);
  font-weight:900;
  cursor:pointer;
  transition:var(--store-transition);
}

.store-visual-mode-switch button.active,
.store-visual-mode-switch button:hover{
  background:color-mix(in srgb, var(--store-primary, var(--color-primary)) 18%, rgba(255,255,255,.10));
  color:var(--store-text);
}

.store-visual-editor-state .storefront-save-state{
  align-items:flex-start;
}

.store-visual-sidebar-title{
  color:var(--store-text);
  font-size:15px;
  margin-top:4px;
}

.store-visual-home-button{
  min-height:44px;
  display:grid;
  grid-template-columns:28px minmax(0, 1fr) auto;
  align-items:center;
  gap:10px;
  border:1px solid var(--store-border);
  border-radius:10px;
  background:rgba(255,255,255,.075);
  color:var(--store-text);
  text-align:left;
  padding:0 10px;
  cursor:pointer;
