.store-share-preview-card small{
  color:var(--color-text-muted);
  overflow-wrap:anywhere;
}

.store-share-preview-actions{
  display:flex;
  gap:10px;
  flex-wrap:wrap;
  margin-top:18px;
}

.store-ad-slot{
  border:1px solid var(--color-border);
  border-radius:18px;
  background:var(--color-surface-soft);
  color:var(--color-text-secondary);
  padding:14px;
}

.store-ad-slot[hidden]{
  display:none !important;
}

.store-cart-backdrop{
  align-items:stretch;
  justify-content:flex-end;
}

.store-cart-drawer{
  width:min(520px, calc(100vw - 18px));
  max-height:calc(100dvh - 18px);
  margin:9px;
  overflow:auto;
}

.store-cart-items{
  display:grid;
  gap:10px;
}

.store-cart-item{
  display:grid;
  grid-template-columns:58px minmax(0, 1fr) auto auto;
  gap:10px;
  align-items:center;
  padding:12px;
  border:1px solid var(--color-border);
  border-radius:16px;
  background:var(--color-surface-soft);
}

.store-cart-thumb{
  width:58px;
  height:58px;
  display:grid;
  place-items:center;
  overflow:hidden;
  border:1px solid var(--store-border-soft);
  border-radius:16px;
  background:color-mix(in srgb, var(--store-primary, var(--color-primary)) 8%, var(--color-surface));
  color:var(--store-primary, var(--color-primary));
}

.store-cart-thumb img{
  width:100%;
  height:100%;
  object-fit:cover;
}

.store-cart-thumb svg{
  width:22px;
  height:22px;
}

.store-cart-item div:nth-child(2){
  display:grid;
  gap:4px;
  min-width:0;
}

.store-cart-item span{
  color:var(--color-text-secondary);
  font-size:12px;
  font-weight:800;
}

.store-cart-stepper{
  display:inline-grid;
  grid-template-columns:34px 34px 34px;
  align-items:center;
  overflow:hidden;
  border:1px solid var(--color-border);
  border-radius:999px;
}

.store-cart-stepper button{
  width:34px;
  height:34px;
  border:0;
  background:transparent;
  color:var(--color-text-primary);
  font-size:18px;
  font-weight:900;
  cursor:pointer;
}

.store-cart-stepper strong{
  text-align:center;
}

.store-cart-total{
  display:flex;
  align-items:center;
  justify-content:space-between;
  gap:14px;
  padding:14px;
  border-radius:18px;
  background:color-mix(in srgb, var(--store-primary, var(--color-primary)) 10%, var(--color-surface));
}

.store-cart-total span{
  color:var(--color-text-secondary);
  font-weight:900;
}

.store-cart-total strong{
  color:var(--color-text-primary);
  font-size:24px;
}

