/* Fase 3.8 - auditoria visual premium: superficies, contraste e profundidade */
body.theme-light{
  --background-primary:#f2f5f4;
  --background-secondary:#f4f6f5;
  --background-tertiary:#eef2f1;
  --bg-primary:var(--background-primary);
  --bg-secondary:var(--background-secondary);
  --bg-tertiary:var(--background-tertiary);
  --surface-primary:#fcfdfc;
  --surface-secondary:#eef2f1;
  --surface-elevated:#ffffff;
  --surface-input:#f8faf9;
  --surface-hover:#f1f5f4;
  --sidebar-bg:#f8faf9;
  --header-bg:#f8faf9;
  --card-bg:#fcfdfc;
  --card-hover:#f1f5f4;
  --border-soft:#dfe6e4;
  --border-strong:#d5dedb;
  --text-primary:#1f2d2b;
  --text-secondary:#52635f;
  --text-muted:#71817e;
  --accent-primary:var(--color-primary);
  --accent-secondary:var(--color-accent);
  --success:var(--color-success);
  --warning:var(--color-warning);
  --danger:var(--color-danger);
}

body:not(.theme-light){
  --background-primary:#0c1118;
  --background-secondary:#111a25;
  --bg-primary:var(--background-primary);
  --bg-secondary:var(--background-secondary);
  --surface-primary:#151d27;
  --surface-secondary:#202832;
  --surface-hover:#1e2936;
  --sidebar-bg:#101923;
  --header-bg:#0d141d;
  --card-bg:#151d27;
  --card-hover:#1e2936;
  --border-soft:rgba(255,255,255,.13);
  --border-strong:rgba(255,255,255,.22);
  --text-primary:#f5f7fb;
  --text-secondary:#dbe7ef;
  --text-muted:#aeb8c6;
  --accent-primary:var(--color-primary);
  --accent-secondary:var(--color-accent);
  --success:var(--color-success);
  --warning:var(--color-warning);
  --danger:var(--color-danger);
}

body.theme-light,
body.theme-light .desktop-shell,
body.theme-light .mobile-shell{
  background:var(--app-body-background, var(--background-primary));
  color:var(--text-primary);
}

body.theme-light :where(.card,.app-card,.modal-card,.popup-box,.ui-section,.technical-glass-panel,.dashboard-chart-card,.reports-panel,.settings-group){
  background-color:var(--card-bg);
  background-image:none;
  border-color:var(--border-soft);
  color:var(--text-primary);
  box-shadow:0 1px 3px rgba(20,40,36,.05), 0 10px 24px rgba(20,40,36,.04);
}

body.theme-light :where(.card,.app-card,.modal-card,.popup-box,.ui-section,.technical-glass-panel,.dashboard-chart-card,.reports-panel,.settings-group) :where(p,small,em,label,.muted){
  color:var(--text-secondary);
}

body.theme-light :where(input,select,textarea,.input-field,.form-control){
  background:var(--surface-input);
  color:var(--text-primary);
  border-color:var(--border-soft);
  box-shadow:none;
}

body.theme-light :where(input,select,textarea,.input-field,.form-control):focus{
  border-color:color-mix(in srgb, var(--accent-primary) 48%, var(--border-strong));
  box-shadow:0 0 0 3px color-mix(in srgb, var(--accent-primary) 18%, transparent);
}

body.theme-light :where(.btn,.app-button):not(.danger):not(.warning){
  border-color:color-mix(in srgb, var(--accent-primary) 34%, var(--border-soft));
}

body.theme-light :where(.btn.secondary,.app-button.secondary,.btn.ghost,.app-button.ghost){
  background:color-mix(in srgb, var(--surface-primary) 86%, var(--background-secondary));
  color:var(--text-primary);
  border-color:var(--border-soft);
  box-shadow:0 2px 8px rgba(20,40,36,.05);
}

body.theme-light :where(.btn.secondary,.app-button.secondary,.btn.ghost,.app-button.ghost):hover{
  background:var(--surface-hover);
  border-color:color-mix(in srgb, var(--accent-primary) 32%, var(--border-strong));
  box-shadow:0 4px 12px rgba(20,40,36,.07);
}

body.theme-light :where(.icon-button,.icon-action-button,.topbar-avatar-button){
  background:color-mix(in srgb, var(--surface-primary) 84%, var(--accent-primary) 6%);
  color:var(--text-primary);
  border-color:var(--border-soft);
}

body.theme-light .side-menu,
body.theme-light[data-ui-profile="web_pwa"] .side-menu{
  background-color:var(--sidebar-bg);
  background-image:none;
  border-color:var(--border-soft);
  box-shadow:14px 0 34px rgba(20,40,36,.07);
}

body.theme-light .side-nav-button{
  color:var(--text-secondary);
  border-color:transparent;
}

body.theme-light .side-nav-button:hover,
body.theme-light .side-nav-button:focus-visible{
  color:var(--text-primary);
  background:color-mix(in srgb, var(--surface-hover) 82%, var(--accent-primary) 8%);
  border-color:color-mix(in srgb, var(--accent-primary) 26%, var(--border-soft));
}

body.theme-light .side-nav-button.active,
body.theme-light[data-ui-profile="web_pwa"] .side-nav-button.active{
  background:color-mix(in srgb, var(--accent-primary) 13%, var(--surface-primary));
  border-color:color-mix(in srgb, var(--accent-primary) 38%, var(--border-soft));
  box-shadow:inset 3px 0 0 var(--accent-primary), 0 12px 26px rgba(15,23,42,.10);
}

.theme-palette-grid{
  display:grid;
  grid-template-columns:repeat(auto-fit, minmax(132px, 1fr));
  gap:10px;
  width:100%;
}

.theme-palette-chip{
  min-height:58px;
  display:grid;
  grid-template-columns:34px minmax(0, 1fr);
  align-items:center;
  gap:10px;
  padding:10px 12px;
  border:1px solid var(--border-soft, var(--color-border));
  border-radius:14px;
  background:var(--surface-primary, var(--color-surface));
  color:var(--text-primary, var(--color-text-primary));
  text-align:left;
  font-weight:850;
  cursor:pointer;
  transition:background-color .18s ease, border-color .18s ease, transform .18s ease, box-shadow .18s ease;
}

.theme-palette-chip i{
  width:34px;
  height:34px;
  display:block;
  border-radius:12px;
  background:
    linear-gradient(135deg, var(--palette-primary) 0 52%, var(--palette-secondary) 52% 100%);
  border:1px solid color-mix(in srgb, var(--palette-primary) 34%, var(--border-soft, var(--color-border)));
  box-shadow:inset 0 1px 0 rgba(255,255,255,.26);
}

.theme-palette-chip i b{
  display:block;
  width:13px;
  height:13px;
  margin:10px auto;
  border-radius:999px;
  background:var(--palette-surface);
}

.theme-palette-chip span{
  overflow:hidden;
  text-overflow:ellipsis;
  white-space:nowrap;
}

.theme-palette-chip:hover,
.theme-palette-chip.active{
  transform:translateY(-1px);
  border-color:color-mix(in srgb, var(--accent-primary, var(--color-primary)) 42%, var(--border-soft, var(--color-border)));
  box-shadow:0 12px 26px rgba(15,23,42,.10);
}

.theme-palette-chip.active{
  background:color-mix(in srgb, var(--surface-hover, var(--color-surface-soft)) 78%, var(--accent-primary, var(--color-primary)) 10%);
}

