/* Hotfix 4B.1 - escala responsiva controlada da Storefront V2 */
.store-public-shell[data-storefront-source="v2"]{
  --store-stage-max:clamp(1120px, 84vw, 1440px);
  --store-button-height:clamp(38px, 1.8vw, 44px);
  --store-button-radius:clamp(10px, .8vw, 14px);
  font-size:clamp(14px, .9vw, 16px);
}

.store-public-shell[data-storefront-source="v2"] .store-public-header{
  min-height:clamp(58px, 4.6vw, 74px);
  padding:clamp(10px, 1vw, 16px) clamp(14px, 1.8vw, 28px);
  gap:clamp(10px, 1.4vw, 20px);
}

.store-public-shell[data-storefront-source="v2"] .store-public-brand{
  gap:clamp(8px, .9vw, 12px);
}

.store-public-shell[data-storefront-source="v2"] :where(.store-public-brand img,.store-public-logo){
  width:clamp(32px, 2.4vw, 42px);
  height:clamp(32px, 2.4vw, 42px);
}

.store-public-shell[data-storefront-source="v2"] .store-public-brand strong{
  font-size:clamp(15px, 1.15vw, 20px);
}

.store-public-shell[data-storefront-source="v2"] .store-public-main-nav{
  gap:clamp(10px, 1.1vw, 18px);
}

.store-public-shell[data-storefront-source="v2"] .store-public-main-nav a{
  font-size:clamp(13px, .82vw, 15px);
}

.store-public-shell[data-storefront-source="v2"] :where(.btn,.store-public-icon-action,.store-public-menu-toggle){
  min-height:var(--store-button-height);
  max-height:46px;
  padding-inline:clamp(10px, 1vw, 16px);
  font-size:clamp(12px, .78vw, 14px);
}

.store-public-shell[data-storefront-source="v2"] .store-public-icon-action{
  width:clamp(38px, 2.4vw, 44px);
  height:clamp(38px, 2.4vw, 44px);
  padding:0;
}

.store-public-shell[data-storefront-source="v2"] .store-public-connection-badge{
  min-height:32px;
  max-width:min(240px, calc(100vw - 24px));
  padding:7px 11px;
  border-radius:999px;
  font-size:12px;
}

.store-public-shell[data-storefront-source="v2"] .store-public-connection-badge i{
  width:7px;
  height:7px;
}

.store-public-shell[data-storefront-source="v2"] .store-public-banner{
  min-height:clamp(360px, 32vw, 520px);
  border-radius:clamp(20px, 2vw, 30px);
}

.store-public-shell[data-storefront-source="v2"] .store-public-banner-copy{
  max-width:min(650px, 58%);
  padding:clamp(30px, 4.6vw, 72px) clamp(28px, 5vw, 82px);
}

.store-public-shell[data-storefront-source="v2"] .store-public-banner-copy h1{
  font-size:clamp(38px, 3.25vw, 60px);
  line-height:1.02;
}

.store-public-shell[data-storefront-source="v2"] .store-public-banner-copy p{
  font-size:clamp(15px, 1vw, 18px);
  line-height:1.55;
}

.store-public-shell[data-storefront-source="v2"] .store-public-section{
  padding-block:clamp(22px, 2.2vw, 38px);
}

.store-public-shell[data-storefront-source="v2"] .store-public-section-head h2,
.store-public-shell[data-storefront-source="v2"] .store-public-contact h2{
  font-size:clamp(24px, 2vw, 36px);
}

.store-public-shell[data-storefront-source="v2"] .store-public-product-grid{
  grid-template-columns:repeat(auto-fill, minmax(220px, 1fr));
  gap:clamp(14px, 1.2vw, 22px);
}

.store-public-shell[data-storefront-source="v2"] .store-public-product-card{
  border-radius:clamp(18px, 1.4vw, 24px);
}

.store-public-shell[data-storefront-source="v2"] .store-public-product-media{
  min-height:clamp(180px, 14vw, 240px);
}

.store-public-shell[data-storefront-source="v2"].store-public-admin-mode{
  padding:0;
}

.store-public-shell[data-storefront-source="v2"] .store-visual-editor-frame{
  grid-template-columns:clamp(236px, 18vw, 292px) minmax(0, 1fr);
}

.store-public-shell[data-storefront-source="v2"] .store-visual-editor-main{
  grid-template-rows:clamp(52px, 4.2vw, 64px) minmax(0, 1fr);
}

.store-public-shell[data-storefront-source="v2"] .store-visual-editor-topbar{
  min-height:clamp(52px, 4.2vw, 64px);
  padding:8px clamp(12px, 1.4vw, 20px);
}

.store-public-shell[data-storefront-source="v2"] .store-visual-top-context strong{
  font-size:clamp(13px, .86vw, 15px);
}

.store-public-shell[data-storefront-source="v2"] .store-visual-top-context span{
  font-size:clamp(11px, .72vw, 12px);
}

.store-public-shell[data-storefront-source="v2"] .store-visual-top-actions :where(button,a),
.store-public-shell[data-storefront-source="v2"] .store-visual-device-switcher button{
  min-height:clamp(34px, 2.4vw, 40px);
  padding-inline:clamp(9px, .9vw, 14px);
  font-size:clamp(11px, .75vw, 13px);
}

.store-public-shell[data-storefront-source="v2"] .store-visual-editor-sidebar{
  gap:clamp(10px, 1vw, 14px);
  padding:clamp(12px, 1.2vw, 18px);
}

.store-public-shell[data-storefront-source="v2"] .store-visual-editor-brand strong{
  font-size:clamp(13px, .9vw, 16px);
}

.store-public-shell[data-storefront-source="v2"] .store-visual-section-list button{
  min-height:clamp(34px, 2.6vw, 42px);
  padding:7px 9px;
  font-size:clamp(12px, .78vw, 14px);
}

.store-public-shell[data-storefront-source="v2"] .store-mobile-admin-actions{
  max-height:74px;
}

@media (min-width:1024px){
  .store-public-shell[data-storefront-source="v2"] .store-public-menu-toggle{
    display:none;
  }

  .store-public-shell[data-storefront-source="v2"] .store-mobile-admin-actions{
