/* Stabilization pass: light plans, avatar rings and storefront editor scroll */
body.theme-light .plans-pricing-screen{
  color:#10202b;
}

body.theme-light .plans-pricing-screen .plan-tier-card{
  color:#1f2d2b !important;
  border-color:color-mix(in srgb, var(--plan-accent, #0ea5a3) 48%, rgba(15,23,42,.22)) !important;
  box-shadow:0 12px 32px color-mix(in srgb, var(--plan-accent, #0ea5a3) 13%, rgba(20,40,36,.10)) !important;
}

body.theme-light .plans-pricing-screen .plan-tier-free{
  background-color:#f2fbf5 !important;
  background-image:none !important;
}

body.theme-light .plans-pricing-screen .plan-tier-start{
  background-color:#f6f3ff !important;
  background-image:none !important;
}

body.theme-light .plans-pricing-screen .plan-tier-pro{
  background-color:#fff8e7 !important;
  background-image:none !important;
}

body.theme-light .plans-pricing-screen .plan-tier-card :where(h1,h2,h3,h4,strong,b,.row-title,.plan-tier-section > strong,.plan-tier-price,.plan-tier-price small,.plan-tier-price span,.plan-tier-list li,.plan-tier-note,.plan-tier-button,.plan-tier-badge){
  color:#1f2d2b !important;
}

body.theme-light .plans-pricing-screen .plan-tier-card :where(p,small,span,.muted,.plan-tier-list.blocked li){
  color:#52635f !important;
}

body.theme-light .plans-pricing-screen .plan-tier-highlights b{
  color:#1f2d2b !important;
  background:#f8faf9 !important;
  border-color:rgba(31,45,43,.14) !important;
}

/* Fase 7C: editor guiado sobre a loja pública */
.store-guided-editor-sidebar{
  width:100%;
  max-width:330px;
  gap:14px;
  background:linear-gradient(180deg, color-mix(in srgb, var(--store-surface) 96%, #07131a), color-mix(in srgb, var(--store-bg) 94%, #061017));
}

.store-guided-close{
  visibility:hidden;
}

.store-guided-context-panel{
  min-width:0;
  display:grid;
  gap:14px;
  outline:0;
}

.store-guided-panel-copy,
.store-guided-form{
  min-width:0;
  display:grid;
  gap:12px;
}

.store-guided-panel-copy > span,
.store-guided-form header span{
  color:var(--store-primary, var(--color-primary));
  font-size:11px;
  font-weight:950;
  text-transform:uppercase;
}

.store-guided-panel-copy h2,
.store-guided-form h2{
  margin:0;
  color:var(--store-text);
  font-size:20px;
  line-height:1.15;
}

.store-guided-panel-copy p,
.store-guided-form header p,
.store-guided-hint{
  margin:0;
  color:var(--store-muted);
  font-size:13px;
  line-height:1.45;
}

.store-guided-target-hint{
  margin:0;
  padding:10px 12px;
  border:1px solid color-mix(in srgb, var(--store-primary, var(--color-primary)) 34%, var(--store-border));
  border-radius:12px;
  background:color-mix(in srgb, var(--store-primary, var(--color-primary)) 9%, var(--store-surface));
  color:var(--store-text);
  font-size:12px;
  font-weight:750;
  line-height:1.45;
}

.store-guided-shortcuts{
  display:grid;
  gap:8px;
}

.store-guided-shortcuts button{
  min-width:0;
  display:grid;
  grid-template-columns:30px minmax(0, 1fr);
  gap:2px 9px;
  padding:10px;
  border:1px solid var(--store-border);
  border-radius:12px;
  background:rgba(255,255,255,.045);
  color:var(--store-text-soft);
  text-align:left;
  cursor:pointer;
  transition:var(--store-transition);
}

.store-guided-shortcuts button:hover{
  border-color:color-mix(in srgb, var(--store-primary, var(--color-primary)) 38%, var(--store-border));
  background:color-mix(in srgb, var(--store-primary, var(--color-primary)) 9%, rgba(255,255,255,.06));
  transform:translateY(-1px);
}

.store-guided-shortcuts i{
  grid-row:span 2;
  width:30px;
  height:30px;
  display:grid;
  place-items:center;
  border-radius:9px;
  background:color-mix(in srgb, var(--store-primary, var(--color-primary)) 14%, transparent);
  color:var(--store-primary, var(--color-primary));
  font-style:normal;
}

.store-guided-shortcuts strong{
  color:var(--store-text);
  font-size:13px;
}

.store-guided-shortcuts small{
  overflow:hidden;
  color:var(--store-muted-2);
  font-size:11px;
  text-overflow:ellipsis;
  white-space:nowrap;
}

.store-guided-form > header{
  position:static;
  top:auto;
  z-index:auto;
  display:grid;
  grid-template-columns:minmax(0, 1fr);
  align-items:start;
  gap:4px;
  padding:0;
  border:0;
  background:transparent;
  box-shadow:none;
  text-align:left;
  backdrop-filter:none;
}

.store-guided-form label{
  min-width:0;
  display:grid;
  gap:5px;
  color:var(--store-text-soft);
  font-size:12px;
  font-weight:850;
}

.store-guided-target-field{
  border-radius:12px;
  outline:2px solid color-mix(in srgb, var(--store-primary, var(--color-primary)) 55%, transparent);
  outline-offset:3px;
}

.store-guided-form :where(input,textarea,select){
  width:100%;
  min-width:0;
  padding:9px 10px;
  border:1px solid var(--store-border);
  border-radius:10px;
  background:color-mix(in srgb, var(--store-surface) 88%, var(--store-bg));
  color:var(--store-text);
  font:inherit;
}

.store-guided-form input[type="color"]{
  min-height:40px;
  padding:4px;
}

.store-guided-grid{
  display:grid;
  grid-template-columns:repeat(2, minmax(0, 1fr));
  gap:8px;
}

.store-guided-upload{
  padding:10px;
  border:1px dashed color-mix(in srgb, var(--store-primary, var(--color-primary)) 42%, var(--store-border));
  border-radius:12px;
  background:color-mix(in srgb, var(--store-primary, var(--color-primary)) 7%, transparent);
  cursor:pointer;
}

.store-guided-upload-button{
  display:grid;
  gap:5px;
  min-height:48px;
  place-items:center;
  color:#ffffff;
  background:var(--store-primary, #078f86);
  border-style:solid;
  border-color:var(--store-primary, #078f86);
  font-size:14px;
  font-weight:900;
  text-align:center;
  box-shadow:0 10px 22px rgba(20,127,120,.16);
}

.store-guided-upload input{
  width:100%;
  max-width:100%;
  min-width:0;
  overflow:hidden;
  padding:0;
  border:0;
  background:transparent;
}

.store-guided-upload input[type="file"]{
  position:absolute;
  width:1px;
  height:1px;
  opacity:0;
  pointer-events:none;
}

.store-guided-upload span{
  color:var(--store-muted);
  font-size:11px;
}

.store-guided-upload-button span{
  color:rgba(255,255,255,.86);
  font-weight:700;
}

.store-guided-actions{
  display:flex;
  flex-wrap:wrap;
  gap:8px;
}

.store-guided-actions .btn{
  min-height:38px;
  padding-inline:12px;
  font-size:12px;
}

.store-guided-link{
  overflow-wrap:anywhere;
  padding:10px;
  border:1px solid var(--store-border);
  border-radius:10px;
  background:rgba(255,255,255,.045);
  color:var(--store-text-soft);
  font-size:12px;
  line-height:1.4;
}

.store-guided-sidebar-footer{
  display:grid;
  gap:8px;
  padding-top:12px;
  border-top:1px solid var(--store-border);
}

.store-guided-review-action{
  width:100%;
  min-height:48px;
  display:grid;
  gap:2px;
  padding:9px 12px;
  border:1px solid color-mix(in srgb, var(--store-primary, #2f6f73) 34%, var(--store-border));
  border-radius:12px;
  background:var(--store-primary, #2f6f73);
  color:#ffffff;
  text-align:left;
  cursor:pointer;
}

.store-guided-review-action[hidden]{
  display:none !important;
}

.store-guided-review-action strong,
.store-guided-review-action span{
  color:inherit;
}

.store-guided-review-action span{
  overflow:hidden;
  font-size:11px;
  font-weight:700;
  opacity:.84;
  text-overflow:ellipsis;
  white-space:nowrap;
}

.store-guided-banner-preview{
  min-width:0;
  margin:0;
  overflow:hidden;
  border:1px solid var(--store-border);
  border-radius:14px;
  background:var(--store-surface, #ffffff);
}

.store-guided-banner-preview img{
  display:block;
  width:100%;
  aspect-ratio:16 / 7;
  object-fit:cover;
  background:#eef4f4;
}

.store-guided-banner-preview figcaption{
  display:grid;
  gap:2px;
  padding:9px 11px;
  border-top:1px solid var(--store-border);
}

.store-guided-banner-preview strong{
  color:var(--store-text);
  font-size:12px;
}

.store-guided-banner-preview span{
  color:var(--store-muted);
  font-size:11px;
}

.store-guided-editable{
  cursor:pointer;
}

.store-guided-editable:hover{
  border-color:color-mix(in srgb, var(--store-primary, var(--color-primary)) 44%, var(--store-border)) !important;
}

@media (min-width:1024px){
  .store-public-shell[data-storefront-source="v2"] .store-visual-editor-frame{
    grid-template-columns:clamp(292px, 22vw, 330px) minmax(0, 1fr);
  }

  .store-public-shell[data-storefront-source="v2"] .store-guided-editor-sidebar{
    position:sticky;
    top:0;
    height:100svh;
    max-height:100svh;
  }
}

@media (max-width:860px){
  .store-public-shell[data-storefront-source="v2"] .store-guided-editor-sidebar{
    position:fixed;
    z-index:82;
    left:10px;
    right:10px;
    bottom:calc(84px + env(safe-area-inset-bottom));
    width:auto;
    max-width:none;
    max-height:min(72dvh, 620px);
    margin:0;
    overflow-y:auto;
    border:1px solid var(--store-border);
    border-radius:20px;
    box-shadow:0 24px 64px rgba(0,0,0,.30);
    transform:translateY(calc(100% + 110px));
    opacity:0;
    pointer-events:none;
    transition:transform .24s ease, opacity .2s ease;
  }

  .store-public-shell[data-storefront-source="v2"] .store-guided-editor-sidebar.is-open{
    transform:translateY(0);
    opacity:1;
    pointer-events:auto;
  }

  .store-guided-close{
    visibility:visible;
  }

  .store-context-edit-fab{
    bottom:calc(92px + env(safe-area-inset-bottom));
  }
}

/* Fase 7C.2: experiencia mobile propria, com preview principal e edicao por toque */
.store-context-admin-bar,
.store-mobile-admin-actions{
  display:none !important;
}

.store-context-edit-fab{
  display:none;
}

.store-visual-top-context{
  display:flex;
  align-items:center;
  gap:12px;
}

.store-visual-top-context > div{
  min-width:0;
  display:grid;
  gap:2px;
}

.store-visual-back{
  min-height:38px;
  padding:0 12px;
  border:1px solid var(--store-border);
  border-radius:10px;
  background:rgba(255,255,255,.045);
  color:var(--store-text-soft);
  font-size:12px;
  font-weight:900;
  cursor:pointer;
}

.store-visual-publish-status{
  min-height:34px;
  display:inline-flex;
  align-items:center;
  padding:0 10px;
  border:1px solid var(--store-border);
  border-radius:999px;
  color:var(--store-muted);
  font-size:11px;
  font-weight:950;
  white-space:nowrap;
}

.store-visual-publish-status.is-online{
  border-color:rgba(34,197,94,.34);
  background:rgba(34,197,94,.11);
  color:#86efac;
}

.store-visual-publish-status.is-dirty{
  border-color:rgba(245,158,11,.34);
  background:rgba(245,158,11,.11);
  color:#fcd34d;
}

.store-visual-top-actions :where(button,a):disabled{
  opacity:.52;
  cursor:not-allowed;
  transform:none;
}

.store-guided-palette{
  display:grid;
  gap:7px;
}

.store-guided-palette > strong{
  color:var(--store-text-soft);
  font-size:12px;
}

.store-guided-palette > small{
  color:var(--store-muted);
  font-size:11px;
  line-height:1.4;
}

.store-guided-palette .theme-palette-grid{
  grid-template-columns:repeat(3, minmax(0, 1fr));
  gap:6px;
}

.store-guided-palette .theme-palette-chip{
  min-height:58px;
  padding:5px;
  font-size:10px;
}

@media (min-width:861px){
  .store-public-shell[data-storefront-source="v2"].store-public-admin-mode{
    --store-stage-max:min(100%, 1760px);
  }

  .store-public-shell[data-storefront-source="v2"] .store-visual-editor-frame{
    grid-template-columns:clamp(300px, 21vw, 340px) minmax(0, 1fr);
  }

  .store-public-shell[data-storefront-source="v2"] .store-visual-editor-topbar{
    grid-template-columns:minmax(220px, 1fr) auto minmax(430px, auto);
  }

  .store-public-shell[data-storefront-source="v2"] .store-visual-editor-canvas{
    width:100%;
    max-width:100%;
    padding:18px clamp(12px, 1.4vw, 26px) 42px;
  }
}

@media (max-width:860px){
  .store-public-shell[data-storefront-source="v2"] .store-public-brand{
