/* Fase 2C - App Shell, scroll principal e zonas responsivas */
:root{
  --breakpoint-mobile:767px;
  --breakpoint-tablet:1023px;
  --breakpoint-desktop:1439px;
  --breakpoint-ultrawide:1440px;
  --sidebar-width:var(--desktop-sidebar-width);
  --sidebar-width-collapsed:64px;
  --layout-shell-max:var(--desktop-max-width);
}

html,
body{
  min-height:100%;
}

body.app-shell-ready{
  height:var(--app-viewport-height, 100dvh);
  overflow:hidden;
}

body.app-shell-ready #app-shell{
  height:var(--app-viewport-height, 100dvh);
  min-height:var(--app-viewport-height, 100dvh);
  overflow:hidden;
}

body.app-shell-ready #app-content{
  height:var(--app-viewport-height, 100dvh);
  min-height:0;
  overflow-y:auto;
  overflow-x:clip;
  overscroll-behavior:contain;
  -webkit-overflow-scrolling:touch;
  scrollbar-gutter:stable;
}

/* O shell controla viewport e scroll. No tema claro ele nao pode herdar o
   tratamento de vidro dos cards, pois backdrop-filter muda a referencia de
   elementos fixed como a navegacao inferior mobile. */
body.theme-light.app-shell-ready #app-shell,
body.theme-light.app-shell-ready #app-content{
  -webkit-backdrop-filter:none;
  backdrop-filter:none;
  box-shadow:none;
}

body.theme-light.app-shell-ready #app-shell{
  background:var(--bg-primary);
}

body.theme-light.app-shell-ready #app-content{
  background:transparent;
}

body.app-shell-ready.app-layer-open #app-content{
  overflow:hidden;
}

.layout-shell,
.layout-admin,
.layout-storefront,
.layout-auth,
.layout-editor{
  width:100%;
  max-width:100%;
  min-width:0;
}

body.app-shell-ready #app,
body.app-shell-ready .desktop-shell,
body.app-shell-ready .desktop-main,
body.app-shell-ready .app-page,
body.app-shell-ready .desktop-focus{
  min-width:0;
  max-width:100%;
}

body[data-ui-profile="web_pwa"]:not(.mobile-mode).app-shell-ready #app{
  height:auto;
  min-height:100%;
  overflow:visible;
}

body[data-ui-profile="web_pwa"]:not(.mobile-mode).app-shell-ready .desktop-shell{
  min-height:var(--app-viewport-height, 100dvh);
  height:auto;
  grid-template-columns:var(--sidebar-width) minmax(0, 1fr);
  overflow:visible;
}

body[data-ui-profile="web_pwa"]:not(.mobile-mode).app-shell-ready .desktop-shell.sidebar-collapsed{
  grid-template-columns:var(--sidebar-width-collapsed) minmax(0, 1fr);
}

body[data-ui-profile="web_pwa"]:not(.mobile-mode).app-shell-ready .desktop-main{
  height:auto;
  min-height:var(--app-viewport-height, 100dvh);
  overflow:visible;
}

body[data-ui-profile="web_pwa"]:not(.mobile-mode).app-shell-ready .side-menu:not(.side-drawer){
  width:var(--sidebar-width);
  max-width:var(--sidebar-width);
  position:sticky;
  top:0;
  height:var(--app-viewport-height, 100dvh);
  max-height:var(--app-viewport-height, 100dvh);
  overflow-y:auto;
  overflow-x:hidden;
  overscroll-behavior:contain;
  scrollbar-gutter:stable;
}

body[data-ui-profile="web_pwa"]:not(.mobile-mode).app-shell-ready .desktop-shell.sidebar-collapsed .side-menu:not(.side-drawer){
  width:var(--sidebar-width-collapsed);
  max-width:var(--sidebar-width-collapsed);
}

body.app-shell-ready .app-overlay-layer,
body.app-shell-ready .app-drawer-layer,
body.app-shell-ready .app-modal-layer,
body.app-shell-ready .app-toast-layer{
  position:fixed;
  inset:0;
}

body.app-shell-ready .app-drawer-layer .side-drawer{
  max-height:calc(var(--app-viewport-height, 100dvh) - max(16px, var(--safe-area-inset-top, env(safe-area-inset-top, 0px))) - max(16px, var(--safe-area-inset-bottom, env(safe-area-inset-bottom, 0px))));
  overflow-y:auto;
  overscroll-behavior:contain;
  -webkit-overflow-scrolling:touch;
}

@media (max-width: 767px){
  body.app-shell-ready #app-content{
    scrollbar-gutter:auto;
  }

  body.app-shell-ready #app{
    min-height:100%;
    overflow:visible;
  }

  body.app-shell-ready .desktop-shell{
    display:block;
    width:100%;
    min-height:100%;
  }

  body.app-shell-ready .desktop-main,
  body.app-shell-ready .mobile-panel-content,
  body.app-shell-ready .mobile-home{
    overflow:visible;
  }
}

@media (min-width: 768px) and (max-width: 1023px){
  body[data-ui-profile="web_pwa"]:not(.mobile-mode).app-shell-ready{
    --sidebar-width:min(210px, var(--desktop-sidebar-width));
  }
}

@media (min-width: 1440px){
  body.app-shell-ready{
  --layout-shell-max:min(1680px, calc(100vw - 48px));
  }
}

/* Fase 3B - contratos visuais ativos para componentes base */
.ds-button,
.app-button{
  min-height:var(--size-button-height);
  display:inline-flex;
  align-items:center;
  justify-content:center;
  gap:var(--space-sm);
  padding:0 var(--space-lg);
  border:1px solid var(--border-primary);
  border-radius:var(--radius-button);
  background:var(--card-bg);
  color:var(--text-primary);
  box-shadow:var(--shadow-sm);
  font-size:var(--type-button);
  font-weight:var(--font-weight-semibold);
  line-height:1;
  transition:transform .18s var(--motion-ease), box-shadow .18s var(--motion-ease), border-color .18s var(--motion-ease), background .18s var(--motion-ease);
}

.s3d-button{
  min-width:0;
  min-height:var(--s3d-button-height-standard);
  padding-inline:var(--s3d-button-padding-inline);
}

.s3d-button[data-ui-size="compact"]{
  min-height:var(--s3d-button-height-compact);
}

.s3d-button[data-ui-size="large"]{
  min-height:var(--s3d-button-height-large);
}

.ds-button.primary,
.app-button.primary{
  border-color:color-mix(in srgb, var(--accent-primary) 62%, var(--border-primary));
  background:linear-gradient(135deg, var(--accent-primary), color-mix(in srgb, var(--accent-primary) 72%, var(--accent-secondary)));
  color:#fff;
  box-shadow:var(--shadow-md);
}

.ds-button.secondary,
.app-button.secondary{
  background:var(--surface-secondary);
}

.ds-button.ghost,
.app-button.ghost{
  background:transparent;
  box-shadow:none;
}

.ds-button.danger,
.app-button.danger{
  border-color:color-mix(in srgb, var(--danger) 46%, var(--border-primary));
  color:var(--danger);
}

.ds-button.success,
.app-button.success{
  border-color:color-mix(in srgb, var(--success) 46%, var(--border-primary));
  color:var(--success);
}

.ds-icon-button,
.app-icon-button{
  width:var(--icon-button-size);
  min-width:var(--icon-button-size);
  height:var(--icon-button-size);
  min-height:var(--icon-button-size);
  padding:0;
  border-radius:var(--radius-md);
}

.ds-card,
.app-card{
  min-width:0;
  border:1px solid var(--border-primary);
  border-radius:var(--radius-card);
  background:var(--card-bg);
  color:var(--text-primary);
  box-shadow:var(--shadow-sm);
  padding:var(--space-lg);
}

.s3d-card{
  min-width:0;
  min-height:var(--s3d-card-min-height-standard);
  max-width:100%;
  padding:var(--s3d-card-padding-standard);
}

.s3d-card[data-ui-size="compact"]{
  min-height:var(--s3d-card-min-height-compact);
  padding:var(--s3d-card-padding-compact);
}

.s3d-card[data-ui-size="large"]{
  min-height:var(--s3d-card-min-height-large);
  padding:var(--s3d-card-padding-large);
}

.ds-card.elevated,
.app-card.elevated{
  box-shadow:var(--shadow-lg);
}

.ds-card.compact,
.app-card.compact{
  padding:var(--space-md);
  border-radius:var(--radius-md);
}

.ds-card.interactive,
.app-card.interactive{
  cursor:pointer;
  transition:transform .18s var(--motion-ease), box-shadow .18s var(--motion-ease), border-color .18s var(--motion-ease);
}

.ds-card.premium,
.app-card.premium{
  border-color:color-mix(in srgb, var(--accent-primary) 34%, var(--border-primary));
  box-shadow:var(--shadow-lg), var(--effect-glow-primary);
}

.ds-input,
.ds-select,
.ds-textarea{
  width:100%;
  min-height:var(--size-input-height);
  border:1px solid var(--border-primary);
  border-radius:var(--radius-input);
  background:var(--color-input);
  color:var(--text-primary);
  padding:0 var(--space-md);
  font-size:var(--type-body);
  line-height:var(--line-height-body);
}

.ds-textarea{
  min-height:calc(var(--size-input-height) * 2);
  padding-block:var(--space-sm);
  resize:vertical;
}

.ds-field{
  display:grid;
  gap:var(--space-xs);
}

.ds-field label{
  color:var(--text-muted);
  font-size:var(--type-label);
  font-weight:var(--font-weight-semibold);
}

.ds-modal{
  width:min(var(--size-modal-width), 100%);
  max-height:calc(var(--app-viewport-height, 100dvh) - var(--space-2xl));
  display:grid;
  grid-template-rows:auto minmax(0, 1fr) auto;
  overflow:hidden;
  border:1px solid var(--border-primary);
  border-radius:var(--radius-modal);
  background:var(--color-modal);
  color:var(--text-primary);
  box-shadow:var(--shadow-xl);
}

.ds-modal-header,
.ds-modal-footer{
  padding:var(--space-lg);
}

.ds-modal-body{
  min-height:0;
  overflow:auto;
  padding:var(--space-lg);
}

.ds-badge{
  min-height:calc(var(--size-input-height) * .68);
  display:inline-flex;
  align-items:center;
  justify-content:center;
  gap:var(--space-xs);
  padding:0 var(--space-sm);
  border:1px solid var(--border-primary);
  border-radius:var(--radius-pill);
  background:var(--surface-secondary);
  color:var(--text-secondary);
  font-size:var(--type-caption);
  font-weight:var(--font-weight-semibold);
  line-height:1;
}

.ds-badge.success{ color:var(--success); border-color:color-mix(in srgb, var(--success) 42%, var(--border-primary)); }
.ds-badge.warning{ color:var(--warning); border-color:color-mix(in srgb, var(--warning) 42%, var(--border-primary)); }
.ds-badge.danger{ color:var(--danger); border-color:color-mix(in srgb, var(--danger) 42%, var(--border-primary)); }
.ds-badge.premium{ color:var(--accent-secondary); border-color:color-mix(in srgb, var(--accent-secondary) 48%, var(--border-primary)); }

.ds-table{
  width:100%;
  min-width:0;
  border-collapse:separate;
  border-spacing:0;
  overflow:hidden;
  border:1px solid var(--border-primary);
  border-radius:var(--radius-card);
  background:var(--card-bg);
  color:var(--text-primary);
}

.ds-table th{
  color:var(--text-secondary);
  font-size:var(--type-caption);
  font-weight:var(--font-weight-bold);
  text-align:left;
}

.ds-table th,
.ds-table td{
  padding:var(--space-sm) var(--space-md);
  border-bottom:1px solid var(--border-primary);
}

.ds-nav-item,
.app-nav-item{
  min-height:var(--menu-button-height);
  display:flex;
  align-items:center;
  gap:var(--space-sm);
  padding:var(--space-sm) var(--space-md);
  border:1px solid transparent;
  border-radius:var(--radius-md);
  color:var(--text-secondary);
  background:transparent;
}

.ds-nav-item.active,
.app-nav-item.active{
  color:var(--accent-primary);
  border-color:color-mix(in srgb, var(--accent-primary) 28%, var(--border-primary));
  background:color-mix(in srgb, var(--accent-primary) 12%, transparent);
  box-shadow:var(--shadow-xs);
}

.ds-topbar-action,
.app-topbar-action{
  min-height:var(--topbar-height);
  display:inline-flex;
  align-items:center;
  gap:var(--space-sm);
}

.ds-empty-state,
.app-empty-state{
  min-height:160px;
  display:grid;
  place-items:center;
  gap:var(--space-sm);
  padding:var(--space-xl);
  border:1px dashed var(--border-primary);
  border-radius:var(--radius-card);
  background:color-mix(in srgb, var(--card-bg) 82%, transparent);
  color:var(--text-secondary);
  text-align:center;
}

.ds-error-state,
.app-error-state{
  border-color:color-mix(in srgb, var(--danger) 36%, var(--border-primary));
  color:var(--danger);
}

.ds-skeleton,
.app-skeleton{
  min-height:1em;
  border-radius:var(--radius-sm);
  background:linear-gradient(90deg, var(--surface-secondary), var(--card-bg-hover), var(--surface-secondary));
  background-size:200% 100%;
  animation:skeleton-shimmer 1.2s ease-in-out infinite;
}

.ds-loader,
.app-loader{
  width:32px;
  height:32px;
  border:3px solid color-mix(in srgb, var(--accent-primary) 20%, transparent);
  border-top-color:var(--accent-primary);
  border-radius:var(--radius-pill);
  animation:sync-spin .8s linear infinite;
}

/* Fase 3C - microinteracoes, densidade e UX empresarial */
.ds-button,
.app-button,
.ds-icon-button,
.app-icon-button,
.ds-nav-item,
.app-nav-item,
.ds-topbar-action,
.app-topbar-action{
  touch-action:manipulation;
  will-change:transform;
}

@media (hover:hover) and (pointer:fine){
  .ds-button:hover,
  .app-button:hover,
  .ds-icon-button:hover,
  .app-icon-button:hover,
  .ds-nav-item:hover,
  .app-nav-item:hover,
  .ds-topbar-action:hover,
  .app-topbar-action:hover{
    transform:var(--interaction-hover-lift);
    border-color:color-mix(in srgb, var(--accent-primary) 34%, var(--border-primary));
    background:var(--card-bg-hover);
    box-shadow:var(--shadow-md);
  }

  .ds-card.interactive:hover,
  .app-card.interactive:hover{
    transform:var(--interaction-card-lift);
    border-color:color-mix(in srgb, var(--accent-primary) 28%, var(--border-primary));
    box-shadow:var(--shadow-lg);
  }

  .ds-table tbody tr:hover,
  .app-table tbody tr:hover{
    background:color-mix(in srgb, var(--accent-primary) 7%, transparent);
  }

  body[data-ui-profile="web_pwa"]:not(.mobile-mode) .side-nav-button:hover,
  body[data-ui-profile="web_pwa"]:not(.mobile-mode) .side-menu-toggle:hover{
    transform:var(--interaction-hover-lift);
    border-color:color-mix(in srgb, var(--accent-primary) 24%, var(--border-primary));
    background:color-mix(in srgb, var(--accent-primary) 9%, transparent);
  }
}

.ds-button:active,
.app-button:active,
.ds-icon-button:active,
.app-icon-button:active,
.ds-nav-item:active,
.app-nav-item:active,
.ds-card.interactive:active,
.app-card.interactive:active,
.side-nav-button:active,
.mobile-bottom-nav-button:active{
  transform:var(--interaction-active-scale);
  filter:brightness(.98);
}

.ds-button:focus-visible,
.app-button:focus-visible,
.ds-icon-button:focus-visible,
.app-icon-button:focus-visible,
.ds-input:focus-visible,
.ds-select:focus-visible,
.ds-textarea:focus-visible,
.ds-nav-item:focus-visible,
.app-nav-item:focus-visible,
.ds-card.interactive:focus-visible,
.app-card.interactive:focus-visible{
  outline:none;
  border-color:color-mix(in srgb, var(--accent-primary) 58%, var(--border-primary));
  box-shadow:var(--effect-focus-ring), var(--shadow-sm);
}

.ds-button:disabled,
.app-button:disabled,
.ds-icon-button:disabled,
.app-icon-button:disabled{
  cursor:not-allowed;
  opacity:.58;
  transform:none;
  filter:none;
  box-shadow:none;
}

.ds-card,
.app-card,
.ds-modal,
.app-modal,
.ds-table,
.app-table,
.ds-empty-state,
.app-empty-state{
  transition:border-color var(--transition-base), background var(--transition-base), box-shadow var(--transition-base), transform var(--transition-base);
}

.ds-modal,
.app-modal,
.app-modal-stage,
.side-drawer{
  animation:ds-enter-soft var(--transition-base) both;
}

.ds-table th,
.app-table th{
  position:sticky;
  top:0;
  z-index:1;
  background:var(--card-bg);
}

.ds-table tbody tr:nth-child(even),
.app-table tbody tr:nth-child(even){
  background:color-mix(in srgb, var(--surface-secondary) 28%, transparent);
}

.ds-empty-state strong,
.app-empty-state strong{
  color:var(--text-primary);
  font-size:var(--font-lg);
  line-height:var(--line-height-heading);
}

.ds-empty-state p,
.app-empty-state p{
  max-width:46ch;
  margin:0;
  color:var(--text-muted);
  line-height:var(--line-height-body);
}

.ds-skeleton,
.app-skeleton,
.skeleton-block,
.skeleton-loading{
  overflow:hidden;
  position:relative;
}

.ds-skeleton::after,
.app-skeleton::after{
  content:"";
  position:absolute;
  inset:0;
  transform:translateX(-100%);
  background:linear-gradient(90deg, transparent, color-mix(in srgb, var(--text-primary) 10%, transparent), transparent);
  animation:ds-skeleton-sweep 1.35s var(--motion-ease) infinite;
}

.toast-area{
  transition:transform var(--transition-base), opacity var(--transition-base);
}

.toast{
  border-color:var(--border-primary);
  box-shadow:var(--shadow-lg);
  animation:ds-toast-in var(--transition-base) both;
}

body[data-ui-profile="web_pwa"]:not(.mobile-mode) .side-menu,
body[data-ui-profile="web_pwa"]:not(.mobile-mode) .side-nav-button,
.mobile-bottom-nav,
.mobile-bottom-nav-button{
  transition:background var(--transition-base), border-color var(--transition-base), box-shadow var(--transition-base), transform var(--transition-fast), color var(--transition-base);
}

body[data-ui-profile="web_pwa"]:not(.mobile-mode) .desktop-main,
body[data-ui-profile="web_pwa"]:not(.mobile-mode) .app-page,
.dashboard-grid,
.desktop-grid{
  gap:clamp(var(--space-md), 1.4vw, var(--space-xl));
}

@keyframes ds-enter-soft{
  from{
    opacity:0;
    transform:translate3d(0, 6px, 0) scale(.992);
  }
  to{
    opacity:1;
    transform:translate3d(0, 0, 0) scale(1);
  }
}

@keyframes ds-toast-in{
  from{
    opacity:0;
    transform:translate3d(0, 8px, 0);
  }
  to{
    opacity:1;
    transform:translate3d(0, 0, 0);
  }
}

@keyframes ds-skeleton-sweep{
  to{
    transform:translateX(100%);
  }
}

@media (prefers-reduced-motion: reduce){
  .ds-button,
  .app-button,
  .ds-icon-button,
  .app-icon-button,
  .ds-card,
  .app-card,
  .ds-modal,
  .app-modal,
  .app-modal-stage,
  .side-drawer,
  .toast,
  .ds-skeleton,
  .app-skeleton,
  .ds-skeleton::after,
  .app-skeleton::after{
    animation:none !important;
    transition:none !important;
  }
}

/* Fase 4A - arquitetura modular da storefront/editor/preview */
.store-layout-zone,
.store-header,
.store-sidebar,
.store-content,
.store-products,
.store-filters,
.store-cart,
.store-footer,
.store-editor-zone,
.store-editor-panel,
.store-editor-content,
.store-editor-actions,
.store-preview-zone,
.store-preview-frame,
.store-preview-scroll,
:where(.store-public-shell,.storefront-admin-standalone,.store-preview-container,.store-preview-device,.store-visual-editor-canvas){
  min-width:0;
  max-width:100%;
}

:where(.store-public-shell,.storefront-admin-standalone){
  overflow-x:clip;
  overscroll-behavior-y:auto;
}

:where(.store-public-header,.store-header){
  min-width:0;
  max-width:100%;
}

:where(.store-public-main,.store-public-section,.store-content){
  min-width:0;
  max-width:min(100%, var(--store-stage-max, var(--content-max-width)));
}

:where(.store-products,.store-product-grid,.store-public-product-grid){
  display:grid;
  grid-template-columns:repeat(auto-fit, minmax(min(100%, 220px), 1fr));
  gap:clamp(var(--space-md), 1.6vw, var(--space-xl));
  align-items:stretch;
}

.store-preview-zone,
.store-preview-frame,
:where(.store-preview-container,.store-preview-device){
  contain:layout paint;
}

.store-preview-scroll,
:where(.store-preview-container,.store-preview-device){
  overscroll-behavior:contain;
  -webkit-overflow-scrolling:touch;
}

.store-preview-scroll{
  overflow:auto;
}

.store-preview-frame > .store-preview-scroll{
  width:100%;
  height:100%;
}

.store-public-shell[data-storefront-source="v2"],
.storefront-admin-page[data-storefront-source="v2"],
.store-preview-container[data-storefront-source="v2"]{
  isolation:isolate;
}

.store-editor-content,
.store-editor-panel,
:where(.storefront-admin-content,.storefront-editor-panel){
  display:grid;
  gap:var(--space-lg);
  min-width:0;
}

.store-layer,
.store-public-modal,
.store-cart-drawer,
.store-filter-drawer,
.store-preview-overlay{
  z-index:var(--z-drawer);
}

@media (max-width: 767px){
  :where(.store-products,.store-product-grid,.store-public-product-grid){
    grid-template-columns:1fr;
  }
}

@media (min-width: 768px) and (max-width: 1023px){
  :where(.store-products,.store-product-grid,.store-public-product-grid){
    grid-template-columns:repeat(2, minmax(0, 1fr));
  }
}

@media (min-width: 1024px){
  :where(.store-products,.store-product-grid,.store-public-product-grid){
    grid-template-columns:repeat(auto-fit, minmax(220px, 1fr));
  }
}

@media (min-width: 1440px){
  :where(.store-products,.store-product-grid,.store-public-product-grid){
    grid-template-columns:repeat(auto-fit, minmax(230px, 1fr));
  }
}

@media (min-width: 1800px){
  :where(.store-products,.store-product-grid,.store-public-product-grid){
    grid-template-columns:repeat(auto-fit, minmax(240px, 1fr));
  }
}

@media (max-width: 900px){
  .storefront-admin-standalone{
    min-height:100dvh;
    height:auto;
    padding:10px;
  }

  .storefront-admin-standalone .storefront-editor-layout{
    grid-template-columns:1fr !important;
  }

  .storefront-admin-standalone .store-preview-container{
    position:relative;
    top:auto;
  }
}

/* Fase 4C - editor profissional da loja */
.store-editor-shell{
  min-width:0;
  width:100%;
  display:grid;
  gap:var(--space-lg);
  align-items:start;
}

.store-editor-sidebar,
.store-editor-workspace,
.store-editor-main,
.store-editor-sections{
  min-width:0;
}

.store-editor-sidebar{
  display:grid;
  gap:var(--space-md);
}

.store-editor-sidebar-card{
  display:grid;
  gap:var(--space-sm);
  padding:var(--space-lg);
  border:1px solid var(--border-soft, var(--color-border));
  border-radius:var(--radius-lg, var(--radius-card));
  background:var(--surface-primary, var(--color-surface));
  box-shadow:var(--shadow-sm, var(--effect-shadow-sm));
}

.store-editor-sidebar-card strong{
  color:var(--text-primary, var(--color-text-primary));
  font-size:var(--font-lg, 1.125rem);
  line-height:1.2;
}

.store-editor-sidebar-card small{
  color:var(--text-secondary, var(--color-text-secondary));
}

.store-editor-sidebar .storefront-save-state{
  margin-top:var(--space-xs);
}

.store-editor-sidebar .storefront-admin-tabs{
  position:sticky;
  top:var(--space-lg);
  z-index:var(--z-sidebar, 100);
}

.store-editor-workspace{
  display:grid;
  gap:var(--space-lg);
}

.store-editor-header{
  width:100%;
  position:sticky;
  top:0;
  z-index:calc(var(--z-header, 80) + 1);
  grid-template-columns:minmax(0, 1fr) auto;
  padding:var(--space-lg);
  border:1px solid var(--border-soft, var(--color-border));
  border-radius:var(--radius-xl, var(--radius-card));
  background:color-mix(in srgb, var(--surface-primary, var(--color-surface)) 94%, transparent);
  box-shadow:var(--shadow-sm, var(--effect-shadow-sm));
  backdrop-filter:blur(14px);
}

.store-editor-title{
  min-width:0;
  display:grid;
  gap:var(--space-xs);
}

.store-editor-title h2{
  margin:0;
  font-size:var(--font-2xl, 1.5rem);
  line-height:1.15;
}

.store-editor-title p{
  margin:0;
  max-width:64ch;
}

.store-editor-action-groups{
  min-width:0;
  display:flex;
  flex-wrap:wrap;
  align-items:center;
  justify-content:flex-end;
  gap:var(--space-sm);
}

.ui-action-bar{
  min-width:0;
  display:flex;
  flex-wrap:wrap;
  align-items:center;
  gap:var(--space-sm);
}

.ui-icon-button{
  width:40px;
  min-width:40px;
  max-width:40px;
  padding:0 !important;
  display:inline-grid;
  place-items:center;
  font-size:20px;
  line-height:1;
}

.ui-context-menu{
  position:relative;
}

.ui-context-menu > summary{
  list-style:none;
  cursor:pointer;
}

.ui-context-menu > summary::-webkit-details-marker{
  display:none;
}

.ui-context-menu-panel{
  position:absolute;
  right:0;
  top:calc(100% + var(--space-xs));
  min-width:210px;
  max-width:min(320px, calc(100vw - 24px));
  max-height:calc(var(--app-viewport-height, 100dvh) - var(--app-safe-bottom, 0px) - 24px);
  overflow-y:auto;
  overscroll-behavior:contain;
  display:grid;
  gap:var(--space-xs);
  padding:var(--space-sm);
  border:1px solid var(--border-soft, var(--color-border));
  border-radius:var(--radius-lg, var(--radius-card));
  background:var(--surface-primary, var(--color-surface));
  box-shadow:var(--shadow-lg, var(--effect-shadow-md));
  z-index:var(--z-drawer, 500);
}

.ui-context-menu-panel .btn{
  width:100%;
  justify-content:flex-start;
  text-align:left;
}

.ui-context-menu-panel :where(button,a,[role="menuitem"]){
  min-height:44px;
}

@media (hover:none), (pointer:coarse){
  .ui-context-menu-panel{
    position:fixed;
    top:auto;
    right:12px;
    bottom:calc(var(--app-safe-bottom, 0px) + 12px);
    left:12px;
    width:auto;
    max-height:calc(var(--app-viewport-height, 100dvh) - var(--app-safe-bottom, 0px) - 16px);
    scroll-padding-bottom:var(--app-safe-bottom, 0px);
  }
}

.store-editor-actions-primary,
.store-editor-actions-secondary,
.store-editor-actions-system{
  display:flex;
  flex-wrap:wrap;
  align-items:center;
  justify-content:flex-end;
  gap:var(--space-sm);
}

.store-editor-action-groups .btn{
  min-height:40px;
  padding:0 var(--space-md);
  font-size:var(--font-sm);
  white-space:nowrap;
}

.store-editor-more-actions{
  position:relative;
  display:block;
}

.store-editor-more-actions summary{
  list-style:none;
  cursor:pointer;
}

.store-editor-more-actions summary::-webkit-details-marker{
  display:none;
}

.store-editor-more-menu{
  position:absolute;
  right:0;
  top:calc(100% + var(--space-sm));
  min-width:210px;
  display:grid;
  gap:var(--space-xs);
  padding:var(--space-sm);
  border:1px solid var(--border-soft, var(--color-border));
  border-radius:var(--radius-lg, var(--radius-card));
  background:var(--surface-primary, var(--color-surface));
  box-shadow:var(--shadow-lg, var(--effect-shadow-md));
  z-index:var(--z-drawer, 500);
}

.store-editor-main{
  display:grid;
  gap:var(--space-lg);
}

.store-editor-notices{
  display:grid;
  gap:var(--space-sm);
}

.store-editor-sections{
  display:grid;
  gap:var(--space-lg);
}

.store-editor-shell .storefront-overview-layout,
.store-editor-shell .storefront-workspace{
  display:grid;
  grid-template-columns:minmax(0, 1fr) minmax(360px, min(420px, 32vw));
  gap:var(--space-lg);
  align-items:start;
}

.store-preview-panel{
  width:min(420px, 32vw);
  min-width:360px;
  max-width:480px;
  position:sticky;
  top:var(--space-lg);
  align-self:start;
}

.store-editor-shell .store-preview-device{
  max-height:min(720px, calc(100dvh - 180px));
}

@media (min-width: 1024px){
  .store-editor-shell{
    grid-template-columns:minmax(220px, 260px) minmax(0, 1fr);
  }
}

@media (min-width: 1440px){
  .store-editor-shell{
    grid-template-columns:260px minmax(0, 1fr);
  }

  .store-editor-workspace{
    max-width:calc(100vw - 320px);
  }
}

@media (max-width: 1280px){
  .store-editor-more-actions{
    display:block;
  }
}

@media (max-width: 1180px){
  .store-editor-header{
    position:relative;
    top:auto;
    grid-template-columns:1fr;
  }

  .store-editor-action-groups,
  .store-editor-actions-primary{
    justify-content:flex-start;
  }

  .store-editor-shell .storefront-overview-layout,
  .store-editor-shell .storefront-workspace{
    grid-template-columns:1fr;
  }

  .store-preview-panel{
    width:100%;
    min-width:0;
    max-width:none;
    position:relative;
    top:auto;
  }

  .store-editor-shell .store-preview-device{
    max-height:72dvh;
  }
}

@media (max-width: 767px){
  .store-editor-shell{
    display:block;
  }

  .store-editor-sidebar{
    margin-bottom:var(--space-md);
  }

  .store-editor-sidebar .storefront-admin-tabs{
    position:relative;
    top:auto;
    display:flex;
    gap:var(--space-sm);
    overflow-x:auto;
    padding:var(--space-sm);
    scroll-snap-type:x proximity;
  }

  .store-editor-sidebar .storefront-admin-tabs .tab{
    flex:0 0 auto;
    min-width:132px;
    scroll-snap-align:start;
  }

  .store-editor-header{
    padding:var(--space-md);
  }

  .store-editor-action-groups{
    width:100%;
  }

  .store-editor-actions-primary{
    width:100%;
  }

  .store-editor-actions-primary .btn,
  .store-editor-more-actions,
  .store-editor-more-actions summary{
    flex:1 1 0;
  }

  .store-editor-more-menu{
    left:0;
    right:0;
    min-width:0;
  }

  .store-editor-shell .store-preview-device{
    max-height:68dvh;
  }
}

/* Fase 4D - refinamento e migracao do editor da loja */
.store-editor-tab-panel{
  min-width:0;
  display:grid;
  gap:var(--space-lg);
}

.store-editor-tab-panel.has-preview-panel{
  grid-template-columns:minmax(0, 1fr) minmax(360px, min(420px, 32vw));
  align-items:start;
}

.store-editor-tab-main{
  min-width:0;
  display:grid;
  gap:var(--space-lg);
}

.store-editor-tab-panel.has-inline-preview :where(.storefront-overview-layout,.storefront-workspace){
  margin:0;
}

.store-editor-tab-panel > .store-preview-panel{
  justify-self:end;
}

.store-preview-panel{
  justify-self:end;
}

.store-preview-panel .store-preview-toolbar{
  align-items:flex-start;
}

.store-preview-panel .store-preview-toolbar .status-badge{
  flex:0 0 auto;
}

.store-preview-panel .store-preview-device{
  width:min(100%, 390px);
  min-height:560px;
  max-height:min(760px, calc(100dvh - 190px));
  margin-inline:auto;
  overflow:hidden;
}

.store-preview-panel .store-preview-scroll{
  height:100%;
  max-height:inherit;
  overflow:auto;
}

.store-preview-panel.expanded{
  width:min(760px, 100%);
  max-width:760px;
}

.store-preview-panel.expanded .store-preview-device{
  width:min(100%, 430px);
  max-height:min(820px, calc(100dvh - 160px));
}

.store-products-summary{
  display:grid;
  grid-template-columns:minmax(0, 1fr) minmax(260px, 420px);
  gap:var(--space-lg);
  align-items:center;
}

.store-products-summary > .actions{
  grid-column:1 / -1;
  justify-content:flex-start;
}

.store-products-summary-grid{
  display:grid;
  grid-template-columns:repeat(3, minmax(0, 1fr));
  gap:var(--space-sm);
}

.store-products-summary-grid .store-status-card{
  min-height:92px;
  padding:var(--space-md);
}

.store-product-editor-panel .card-header,
.store-product-list-panel .card-header{
  align-items:flex-start;
}

.store-editor-save-inline .storefront-save-state{
  margin:0;
  justify-content:flex-end;
}

.store-product-list-panel .store-empty-state .btn{
  margin-top:var(--space-sm);
}

.store-product-admin-grid{
  grid-template-columns:1fr;
  gap:var(--space-md);
}

.store-product-admin-card{
  grid-template-columns:112px minmax(0, 1fr);
  grid-template-rows:auto auto;
  align-items:start;
  padding:var(--space-md);
}

.store-product-admin-card .store-product-admin-media{
  grid-row:1 / -1;
  aspect-ratio:1;
}

.store-product-admin-card .storefront-image-row{
  grid-column:2 / -1;
}

.store-product-admin-card .store-admin-actions{
  justify-content:flex-end;
}

.store-product-admin-card .store-admin-actions .btn{
  min-height:38px;
}

.store-product-admin-body{
  min-width:0;
  display:grid;
  gap:var(--space-xs);
}

.store-product-admin-title,
.store-product-admin-summary,
.store-product-admin-stock{
  min-width:0;
  overflow-wrap:anywhere;
}

.store-product-admin-title{
  display:-webkit-box;
  overflow:hidden;
  -webkit-line-clamp:2;
  -webkit-box-orient:vertical;
}

.store-product-card-actions{
  flex-wrap:nowrap;
  margin-top:var(--space-xs);
}

.store-product-mobile-actions{
  display:none;
}

.store-product-mobile-flow-header,
.store-product-mobile-sticky-actions{
  display:none;
}

.store-product-form-step{
  display:grid;
  gap:var(--space-md);
}

.store-product-quantity-control{
  display:grid;
  grid-template-columns:40px minmax(0, 1fr) 40px;
  gap:var(--space-xs);
  align-items:center;
}

.store-product-quantity-control button{
  min-height:40px;
  border:1px solid var(--border-soft, var(--color-border));
  border-radius:var(--radius-md, 8px);
  background:var(--surface-secondary, var(--color-surface-subtle));
  color:var(--text-primary, var(--color-text));
  font:inherit;
  font-size:20px;
  cursor:pointer;
}

.store-product-form-photo-grid,
.store-product-review-grid{
  display:grid;
  grid-template-columns:repeat(auto-fit, minmax(132px, 1fr));
  gap:var(--space-sm);
}

.store-product-form-photo-grid .storefront-thumb{
  width:84px;
  height:84px;
}

.store-product-form-photo-add{
  min-height:44px;
  align-self:center;
  justify-self:start;
}

.store-product-review-grid article{
  min-width:0;
  display:grid;
  gap:var(--space-xxs, 4px);
  padding:var(--space-sm);
  border:1px solid var(--border-soft, var(--color-border));
  border-radius:var(--radius-md, 8px);
  background:var(--surface-secondary, var(--color-surface-subtle));
}

.store-product-review-grid strong{
  min-width:0;
  overflow-wrap:anywhere;
}

.store-product-field-error{
  display:block;
  margin-top:4px;
  color:var(--danger, var(--color-danger));
  font-size:12px;
}

.store-product-admin-card .ui-context-menu-panel{
  right:0;
  left:auto;
}

.store-admin-more-actions.open-up .ui-context-menu-panel{
  top:auto;
  bottom:calc(100% + var(--space-xs));
}

.store-product-action-sheet{
  position:absolute;
  right:0;
  bottom:0;
  left:0;
  width:min(100%, 520px);
  max-height:min(78dvh, 680px);
  margin-inline:auto;
  overflow-y:auto;
  overscroll-behavior:contain;
  padding:var(--space-sm) var(--space-md) calc(var(--space-md) + env(safe-area-inset-bottom));
  border:1px solid var(--border-soft, var(--color-border));
  border-bottom:0;
  border-radius:var(--radius-xl, 18px) var(--radius-xl, 18px) 0 0;
  background:var(--surface-primary, var(--color-surface));
  box-shadow:var(--shadow-xl, var(--effect-shadow-md));
  color:var(--text-primary, var(--color-text));
}

.store-product-sheet-handle{
  width:42px;
  height:4px;
  display:block;
  margin:0 auto var(--space-sm);
  border-radius:var(--radius-pill);
  background:var(--border-strong, var(--color-border));
}

.store-product-action-sheet header{
  display:flex;
  align-items:center;
  justify-content:space-between;
  gap:var(--space-sm);
  margin-bottom:var(--space-sm);
}

.store-product-action-sheet header h3,
.store-product-action-sheet header small{
  margin:0;
}

.store-product-sheet-actions{
  display:grid;
  grid-template-columns:repeat(2, minmax(0, 1fr));
  gap:var(--space-xs);
}

.store-product-sheet-action{
  min-height:44px;
  padding:var(--space-sm);
  border:1px solid var(--border-soft, var(--color-border));
  border-radius:var(--radius-md, 8px);
  background:var(--surface-secondary, var(--color-surface-subtle));
  color:var(--text-primary, var(--color-text));
  text-align:left;
  font:inherit;
  font-size:var(--font-sm);
  cursor:pointer;
}

.store-product-sheet-action:hover,
.store-product-sheet-action:focus-visible{
  border-color:var(--accent-primary, var(--color-primary));
  outline:2px solid color-mix(in srgb, var(--accent-primary, var(--color-primary)) 32%, transparent);
  outline-offset:1px;
}

.store-product-sheet-action.danger{
  color:var(--danger, var(--color-danger));
}

.store-product-sheet-cancel{
  width:100%;
  margin-top:var(--space-sm);
}

@media (max-width: 1180px){
  .store-editor-tab-panel.has-preview-panel{
    grid-template-columns:1fr;
  }

  .store-editor-tab-panel > .store-preview-panel,
  .store-preview-panel{
    width:100%;
    min-width:0;
    max-width:none;
    justify-self:stretch;
    position:relative;
    top:auto;
  }

  .store-preview-panel .store-preview-device{
    min-height:520px;
    max-height:72dvh;
  }

  .store-products-summary{
    grid-template-columns:1fr;
  }
}

@media (max-width: 768px){
  .store-product-form{
    padding-bottom:68px;
  }

  .store-product-mobile-flow-header{
    position:sticky;
    top:0;
    z-index:var(--z-sidebar, 100);
    display:grid;
    grid-template-columns:minmax(0, 1fr) auto;
    gap:var(--space-sm);
    padding:var(--space-sm);
    border:1px solid var(--border-soft, var(--color-border));
    border-radius:var(--radius-lg, 12px);
    background:var(--surface-primary, var(--color-surface));
    box-shadow:var(--shadow-sm, var(--effect-shadow-sm));
  }

  .store-product-mobile-flow-header > div:first-child{
    min-width:0;
    display:grid;
    gap:2px;
  }

  .store-product-mobile-flow-header span{
    color:var(--text-secondary, var(--color-text-muted));
    font-size:12px;
  }

  .store-product-mobile-flow-header .btn{
    min-height:34px;
    padding-inline:var(--space-sm);
    font-size:12px;
  }

  .store-product-stepper{
    grid-column:1 / -1;
    display:grid;
    grid-template-columns:repeat(4, minmax(0, 1fr));
    gap:4px;
  }

  .store-product-step-dot{
    position:relative;
    min-width:0;
    display:grid;
    place-items:center;
    gap:3px;
    color:var(--text-muted, var(--color-text-muted));
    font-size:10px;
    text-align:center;
  }

  .store-product-step-dot::before{
    position:absolute;
    top:5px;
    right:50%;
    left:-50%;
    height:2px;
    content:"";
    background:var(--border-soft, var(--color-border));
  }

  .store-product-step-dot:first-child::before{
    display:none;
  }

  .store-product-step-dot i{
    position:relative;
    z-index:1;
    width:12px;
    height:12px;
    display:block;
    border:2px solid var(--border-strong, var(--color-border));
    border-radius:50%;
    background:var(--surface-primary, var(--color-surface));
  }

  .store-product-step-dot.is-complete::before,
  .store-product-step-dot.is-active::before{
    background:var(--accent-primary, var(--color-primary));
  }

  .store-product-step-dot.is-complete i,
  .store-product-step-dot.is-active i{
    border-color:var(--accent-primary, var(--color-primary));
    background:var(--accent-primary, var(--color-primary));
  }

  .store-product-step-dot.is-active{
    color:var(--text-primary, var(--color-text));
    font-weight:700;
  }

  .store-product-form-step{
    display:none;
  }

  .store-product-form-step.is-active{
    display:grid;
    gap:var(--space-md);
  }

  .store-product-form-step :where(input, select, textarea){
    min-height:48px;
    font-size:16px;
  }

  .store-product-form-step .checkbox-row{
    min-height:48px;
  }

  .store-product-quantity-control{
    grid-template-columns:44px minmax(0, 1fr) 44px;
  }

  .store-product-quantity-control button{
    min-height:48px;
  }

  .store-product-desktop-save-actions{
    display:none !important;
  }

  .store-product-mobile-sticky-actions{
    position:sticky;
    bottom:0;
    z-index:var(--z-sidebar, 100);
    display:grid;
    grid-template-columns:minmax(0, 1fr) minmax(0, 1.45fr);
    gap:var(--space-xs);
    min-height:62px;
    margin-top:var(--space-sm);
    padding:var(--space-sm) 0 calc(var(--space-sm) + env(safe-area-inset-bottom));
    background:var(--surface-primary, var(--color-surface));
    box-shadow:0 -8px 18px color-mix(in srgb, var(--text-primary, var(--color-text)) 8%, transparent);
  }

  .store-product-mobile-sticky-actions .btn{
    width:100%;
    min-width:0;
    min-height:44px;
    padding-inline:var(--space-xs);
    font-size:13px;
    white-space:normal;
  }

  .store-products-summary-grid{
    grid-template-columns:1fr;
  }

  .store-editor-save-inline .storefront-save-state{
    justify-content:flex-start;
  }

  .store-product-admin-card{
    grid-template-columns:72px minmax(0, 1fr);
    grid-template-rows:auto auto;
    gap:10px;
    padding:10px;
  }

  .store-product-admin-card .store-product-admin-media{
    grid-row:auto;
    width:72px;
    height:72px;
  }

  .store-product-admin-card .storefront-image-row{
    grid-column:1 / -1;
  }

  .store-product-admin-card .storefront-image-row{
    display:none;
  }

  .store-product-admin-description,
  .store-demo-product-note,
  .store-product-admin-stock{
    display:none;
  }

  .store-product-admin-card .store-badge-row{
    gap:4px;
  }

  .store-product-admin-card .status-badge{
    padding:2px 6px;
    font-size:10px;
  }

  .store-product-card-actions{
    gap:6px;
  }

  .store-product-edit-action{
    width:auto !important;
    min-height:34px !important;
    padding:0 12px !important;
    font-size:12px !important;
  }

  .store-product-desktop-actions{
    display:none;
  }

  .store-product-mobile-actions{
    width:34px;
    min-width:34px;
    max-width:34px;
    min-height:34px !important;
    display:inline-grid;
    font-size:18px;
  }

  .store-editor-action-groups{
    display:grid;
    grid-template-columns:minmax(0, 1fr) 36px;
    gap:6px;
  }

  .store-editor-actions-primary{
    display:grid;
    grid-template-columns:repeat(2, minmax(0, 1fr));
    gap:6px;
    width:auto;
  }

  .store-editor-actions-primary .btn{
    min-width:0;
    min-height:36px;
    padding:0 6px;
    font-size:11px;
    overflow:hidden;
    text-overflow:ellipsis;
  }

  .store-editor-more-actions,
  .store-editor-more-actions summary{
    width:36px;
    min-width:36px;
    max-width:36px;
    min-height:36px;
  }

  .store-preview-panel .store-preview-actions{
    grid-template-columns:1fr;
  }

  .store-preview-panel .store-preview-device{
    width:100%;
    min-height:480px;
    max-height:68dvh;
  }
}

@media (max-width: 359px){
  .store-product-sheet-actions{
    grid-template-columns:1fr;
  }

  .store-product-admin-card{
    grid-template-columns:64px minmax(0, 1fr);
  }

  .store-product-admin-card .store-product-admin-media{
    width:64px;
    height:64px;
  }
}

/* Hotfix global - escala visual segura do ERP e Storefront */
html{
  font-size:16px;
}

body{
  font-size:1rem;
  line-height:1.5;
}

#app,
#app-shell,
#app-content{
  font-size:inherit;
}

:root{
  --font-xs:0.75rem;
  --font-sm:0.875rem;
  --font-md:1rem;
  --font-lg:1.125rem;
  --font-xl:1.25rem;
  --font-2xl:1.5rem;
  --font-3xl:1.875rem;
  --space-xs:0.25rem;
  --space-sm:0.5rem;
  --space-md:0.75rem;
  --space-lg:1rem;
  --space-xl:1.5rem;
  --space-2xl:2rem;
}

body[data-ui-profile="web_pwa"]:not(.mobile-mode) :where(.side-menu,.app-sidebar){
  font-size:var(--font-sm);
}

body[data-ui-profile="web_pwa"]:not(.mobile-mode) :where(.topbar,.app-topbar){
  min-height:56px;
}

body[data-ui-profile="web_pwa"]:not(.mobile-mode) :where(.side-nav-button,.ds-nav-item,.app-nav-item){
  min-height:44px;
  padding:0.5rem 0.75rem;
  font-size:var(--font-sm);
}

body[data-ui-profile="web_pwa"]:not(.mobile-mode) :where(.side-nav-button span,.side-menu-toggle,.icon-button,.icon-action-button,.ds-icon-button,.app-icon-button){
  width:40px;
  min-width:40px;
  height:40px;
  min-height:40px;
}

body[data-ui-profile="web_pwa"]:not(.mobile-mode) :where(.btn,.app-button,.ds-button){
  min-height:40px;
  padding:0 var(--space-md);
  font-size:var(--font-sm);
}

body[data-ui-profile="web_pwa"]:not(.mobile-mode) :where(input,select,textarea,.ds-input,.ds-select,.ds-textarea){
  font-size:var(--font-md);
}

.auth-password-row .password-visibility-button,
.password-confirm-card .auth-password-row .password-visibility-button{
  color:var(--primary);
  background:transparent !important;
  border:0 !important;
  box-shadow:none !important;
  backdrop-filter:none !important;
}

body[data-ui-profile="web_pwa"]:not(.mobile-mode) :where(.card,.app-card,.ds-card,.ui-section,.panel-card,.desktop-dashboard-card){
  padding:var(--space-lg);
}

body[data-ui-profile="web_pwa"]:not(.mobile-mode) :where(.desktop-main,.app-page,.dashboard-grid,.desktop-grid){
  gap:var(--space-lg);
}

/* Hotfix global 2 - modo desktop/tablet/mobile explicito */
body.viewport-desktop .bottom-nav,
body.viewport-desktop .mobile-bottom-nav,
body.viewport-desktop .app-bottom-nav,
body.viewport-desktop .app-bottom-navigation,
body.viewport-desktop .menu,
body.viewport-tablet .bottom-nav,
body.viewport-tablet .mobile-bottom-nav,
body.viewport-tablet .app-bottom-nav,
body.viewport-tablet .app-bottom-navigation,
body.viewport-tablet .menu{
  display:none !important;
}

body.viewport-desktop .desktop-shell{
  display:grid !important;
  grid-template-columns:var(--sidebar-width, var(--desktop-sidebar-width)) minmax(0, 1fr);
  width:100%;
  max-width:none;
}

body.viewport-desktop .desktop-shell.sidebar-collapsed{
  grid-template-columns:var(--sidebar-width-collapsed, 64px) minmax(0, 1fr);
}

body.viewport-desktop :where(.desktop-sidebar,.app-sidebar,.side-menu:not(.side-drawer)){
  display:flex !important;
}

body.viewport-mobile :where(.desktop-sidebar,.app-sidebar,.side-menu:not(.side-drawer)){
  display:none !important;
}

body.viewport-mobile .desktop-shell{
  display:block;
}

body.viewport-desktop :where(.dashboard-menu-trigger,.dashboard-search-trigger){
  width:40px;
  min-width:40px;
  height:40px;
  min-height:40px;
  padding:0;
  font-size:var(--font-sm);
}

body.viewport-desktop .mobile-home,
body.viewport-desktop .mobile-panel,
body.viewport-desktop .mobile-panel-content{
  display:none !important;
}

body.viewport-desktop.app-shell-ready #app-shell{
  display:grid;
  grid-template-columns:minmax(0, 1fr);
}

body.viewport-desktop.app-shell-ready #app-content{
  overflow-y:auto;
  overflow-x:clip;
}

body.viewport-mobile.app-shell-ready #app-shell{
  display:block;
}

@media (min-width: 1024px){
  body:not(.viewport-mobile) .bottom-nav,
  body:not(.viewport-mobile) .mobile-bottom-nav,
  body:not(.viewport-mobile) .app-bottom-nav,
  body:not(.viewport-mobile) .app-bottom-navigation,
  body:not(.viewport-mobile) .menu{
    display:none !important;
  }

  body:not(.viewport-mobile) .side-menu:not(.side-drawer){
    display:flex !important;
  }
}

/* Hotfix menu loja - evita sobreposicao dos links no editor */
@media (max-width: 1180px){
  .store-public-shell .store-public-header{
    grid-template-columns:minmax(0, 1fr) auto !important;
    align-items:center;
    overflow:visible;
  }

  .store-public-shell .store-public-header .store-public-brand{
    grid-column:1;
    grid-row:1;
    min-width:0;
  }

  .store-public-shell .store-public-header .store-public-menu-toggle{
    grid-column:2;
    grid-row:1;
    display:inline-flex !important;
    max-width:128px;
  }

  .store-public-shell .store-public-header .store-public-main-nav,
  .store-public-shell .store-public-header .store-public-actions{
    display:none !important;
    grid-column:1 / -1;
    grid-row:auto;
    width:100%;
    min-width:0;
  }

  .store-public-shell .store-public-header.mobile-open .store-public-main-nav{
    display:flex !important;
    justify-content:flex-start;
    flex-wrap:wrap;
    gap:10px 14px;
    overflow:visible;
    padding-top:10px;
  }

  .store-public-shell .store-public-header.mobile-open .store-public-actions{
    display:flex !important;
    justify-content:flex-start;
    flex-wrap:wrap;
    gap:8px;
    padding-top:10px;
  }

  .store-public-shell .store-public-header.mobile-open .store-public-actions :where(.btn, a.btn){
    flex:0 1 auto;
    min-width:120px;
  }
}

@media (max-width: 1360px){
  .store-public-shell.store-public-admin-mode .store-public-header{
    grid-template-columns:minmax(0, 1fr) auto !important;
    align-items:center;
    overflow:visible;
  }

  .store-public-shell.store-public-admin-mode .store-public-header .store-public-brand{
    grid-column:1;
    grid-row:1;
    min-width:0;
  }

  .store-public-shell.store-public-admin-mode .store-public-header .store-public-menu-toggle{
    grid-column:2;
    grid-row:1;
    display:inline-flex !important;
    max-width:128px;
  }

  .store-public-shell.store-public-admin-mode .store-public-header .store-public-main-nav,
  .store-public-shell.store-public-admin-mode .store-public-header .store-public-actions{
    display:none !important;
    grid-column:1 / -1;
    grid-row:auto;
    width:100%;
    min-width:0;
  }

  .store-public-shell.store-public-admin-mode .store-public-header.mobile-open .store-public-main-nav{
    display:flex !important;
    justify-content:flex-start;
    flex-wrap:wrap;
    gap:10px 14px;
    overflow:visible;
    padding-top:10px;
  }

  .store-public-shell.store-public-admin-mode .store-public-header.mobile-open .store-public-actions{
    display:flex !important;
    justify-content:flex-start;
    flex-wrap:wrap;
    gap:8px;
    padding-top:10px;
  }
}

/* Hotfix sidebar desktop - separa menu ERP de drawer/mobile */
body.viewport-desktop{
  --sidebar-width:clamp(240px, 15vw, 300px);
}

body.viewport-desktop .desktop-shell,
body.viewport-desktop .desktop-shell.sidebar-collapsed,
body.viewport-desktop.app-shell-ready .desktop-shell,
body.viewport-desktop.app-shell-ready .desktop-shell.sidebar-collapsed,
body[data-ui-profile="web_pwa"].viewport-desktop:not(.mobile-mode) .desktop-shell,
body[data-ui-profile="web_pwa"].viewport-desktop:not(.mobile-mode) .desktop-shell.sidebar-collapsed,
body[data-ui-profile="web_pwa"].viewport-desktop:not(.mobile-mode).app-shell-ready .desktop-shell,
body[data-ui-profile="web_pwa"].viewport-desktop:not(.mobile-mode).app-shell-ready .desktop-shell.sidebar-collapsed{
  display:grid !important;
  grid-template-columns:var(--sidebar-width) minmax(0, 1fr) !important;
}

body.viewport-desktop :where(.app-sidebar,.desktop-sidebar,.side-menu:not(.side-drawer)){
  display:flex !important;
  flex-direction:column !important;
  align-items:stretch !important;
  width:var(--sidebar-width) !important;
  min-width:240px !important;
  max-width:300px !important;
}

body.viewport-desktop :where(.app-sidebar,.desktop-sidebar,.side-menu:not(.side-drawer)).is-collapsed,
body.viewport-desktop .desktop-shell.sidebar-collapsed :where(.app-sidebar,.desktop-sidebar,.side-menu:not(.side-drawer)){
  width:var(--sidebar-width) !important;
  min-width:240px !important;
  max-width:300px !important;
  padding:14px 12px !important;
}

body.viewport-desktop .side-menu.is-collapsed .side-brand{
  grid-template-columns:auto 38px minmax(0, 1fr) auto !important;
  justify-items:stretch !important;
  padding:10px !important;
}

body.viewport-desktop .side-menu.is-collapsed :where(.side-brand-text,.side-brand-copy,.side-brand-logo,.side-brand-mark,.side-profile-meta,.side-profile-card .status-badge,.side-plan-pill,.side-section > span,.side-nav-button strong,.side-section-header){
  display:revert !important;
  opacity:1 !important;
  max-width:none !important;
}

body.viewport-desktop .side-menu.is-collapsed .side-section-header{
  display:flex !important;
}

body.viewport-desktop .side-menu.is-collapsed .side-profile-card{
  min-height:84px !important;
  grid-template-columns:46px minmax(0, 1fr) !important;
