/* Checkpoint 2026-06-01 - auditoria pesada do tema claro da loja.
   Mantem a imagem real do banner com cor preservada e usa protecao local apenas
   atras do texto, evitando a aparencia cinzenta causada por overlays globais. */
.storefront-root[data-storefront-source="v2"][data-store-theme="light"],
.store-public-shell[data-storefront-source="v2"][data-store-theme="light"]{
  --store-bg:#f2f5f4;
  --store-bg-soft:#f4f6f5;
  --store-surface:#fcfdfc;
  --store-surface-strong:#ffffff;
  --store-card:#fcfdfc;
  --store-text:#1f2d2b;
  --store-text-soft:#52635f;
  --store-muted:#71817e;
  --store-border:rgba(11, 46, 56, .16);
  --store-border-soft:rgba(11, 46, 56, .10);
  --store-header-bg:rgba(248,250,249,.96);
  --store-banner-overlay:none;
  color:var(--store-text);
}

.storefront-root[data-storefront-source="v2"][data-store-theme="light"].store-public-admin-mode,
.storefront-root[data-storefront-source="v2"][data-store-theme="light"] .store-visual-editor-frame,
.storefront-root[data-storefront-source="v2"][data-store-theme="light"] .store-visual-editor-canvas{
  background-color:#f2f5f4;
  background-image:none;
}

.storefront-root[data-storefront-source="v2"][data-store-theme="light"] :where(
  .store-public-header,
  .store-public-category-bar a,
  .store-public-product-card,
  .store-public-contact,
  .store-public-inner-head,
  .store-public-benefits article,
  .store-visual-editor-sidebar,
  .store-visual-editor-topbar,
  .store-editor-shell,
  .store-editor-sidebar,
  .store-editor-workspace,
  .store-editor-panel,
  .store-preview-panel,
  .store-preview-device,
  .store-product-admin-card,
  .store-status-card
){
  background-color:var(--store-card);
  background-image:none;
  border-color:var(--store-border);
  color:var(--store-text);
  box-shadow:0 14px 36px rgba(13, 45, 55, .08);
}

.storefront-root[data-storefront-source="v2"][data-store-theme="light"] :where(
  .store-public-banner-copy h1,
  .store-public-brand strong,
  .store-public-section-head h2,
  .store-public-product-card strong,
  .store-editor-title h2,
  .store-editor-panel h3,
  .store-product-admin-title,
  .store-status-card strong
){
  color:var(--store-text);
}

.storefront-root[data-storefront-source="v2"][data-store-theme="light"] :where(
  .store-public-banner-copy p,
  .store-public-section-head p,
  .store-public-product-card p,
  .store-editor-title p,
  .store-editor-panel .muted,
  .store-product-admin-summary,
  .store-product-admin-stock,
  .store-status-card span
){
  color:var(--store-muted);
}

.storefront-root[data-storefront-source="v2"][data-store-theme="light"] .store-public-banner{
  background:#f8faf9;
  background-image:none;
  border-color:rgba(11, 46, 56, .14);
  box-shadow:0 18px 46px rgba(13, 45, 55, .12);
}

.storefront-root[data-storefront-source="v2"][data-store-theme="light"] .store-public-banner.store-banner-has-image,
.storefront-root[data-storefront-source="v2"][data-store-theme="light"] .store-public-banner:has(> img){
