}

.storefront-root[data-storefront-source="v2"][data-store-theme="light"] .store-public-banner.store-banner-has-image::after,
.storefront-root[data-storefront-source="v2"][data-store-theme="light"] .store-public-banner:has(> img)::after{
  content:none !important;
  display:none !important;
  opacity:0 !important;
  background:transparent !important;
  background-image:none !important;
}

.storefront-root[data-storefront-source="v2"][data-store-theme="light"] .store-public-banner.store-banner-has-image .store-public-banner-copy,
.storefront-root[data-storefront-source="v2"][data-store-theme="light"] .store-public-banner:has(> img) .store-public-banner-copy{
