.storefront-root[data-storefront-source="v2"][data-store-theme="light"] .store-public-banner.store-banner-has-image .store-public-banner-copy h1,
.storefront-root[data-storefront-source="v2"][data-store-theme="light"] .store-public-banner.store-banner-has-image .store-public-banner-copy p,
.storefront-root[data-storefront-source="v2"][data-store-theme="light"] .store-public-banner:has(> img) .store-public-banner-copy h1,
.storefront-root[data-storefront-source="v2"][data-store-theme="light"] .store-public-banner:has(> img) .store-public-banner-copy p{
  text-shadow:none;
}

.storefront-root[data-storefront-source="v2"][data-store-theme="light"] :where(input,select,textarea){
  background:#f8faf9;
  border-color:rgba(11,46,56,.18);
  color:var(--store-text);
}

.storefront-root[data-storefront-source="v2"][data-store-theme="light"] :where(input,select,textarea)::placeholder{
  color:#70818a;
}

@media (max-width: 767px){
  .storefront-root[data-storefront-source="v2"][data-store-theme="light"] .store-public-banner.store-banner-has-image::after,
  .storefront-root[data-storefront-source="v2"][data-store-theme="light"] .store-public-banner:has(> img)::after{
    opacity:0 !important;
    background:transparent !important;
    background-image:none !important;
  }

  .storefront-root[data-storefront-source="v2"][data-store-theme="light"] .store-public-banner.store-banner-has-image .store-public-banner-copy,
  .storefront-root[data-storefront-source="v2"][data-store-theme="light"] .store-public-banner:has(> img) .store-public-banner-copy{
