/* Hotfix 2026-06-01 - loja clara sem estouro lateral no editor guiado.
   A barra de categorias antiga usava 6 colunas fixas; no mobile/editor isso
   vazava para fora da loja. Mantemos a loja clara contida mesmo quando o
   atributo data-store-theme ainda nao foi aplicado no primeiro render. */
.storefront-root[data-storefront-source="v2"]:not([data-store-theme="dark"]){
  --store-bg:#f2f5f4;
  --store-bg-soft:#f4f6f5;
  --store-surface:#fcfdfc;
  --store-surface-strong:#ffffff;
  --store-card:#fcfdfc;
  --store-text:#1f2d2b;
  --store-text-soft:#52635f;
  --store-muted:#71817e;
  --store-border:rgba(11, 46, 56, .16);
  --store-border-soft:rgba(11, 46, 56, .10);
  --store-header-bg:rgba(248,250,249,.96);
  --store-input-bg:#f8faf9;
  --store-banner-overlay:none;
  color:var(--store-text);
  background-color:var(--store-bg);
  background-image:none;
}

.storefront-root[data-storefront-source="v2"] .store-public-banner.store-banner-has-image,
.storefront-root[data-storefront-source="v2"] .store-public-banner:has(> img){
  isolation:isolate;
  background:transparent !important;
  background-image:none !important;
}

.storefront-root[data-storefront-source="v2"] .store-public-banner.store-banner-has-image::before,
.storefront-root[data-storefront-source="v2"] .store-public-banner.store-banner-has-image::after,
.storefront-root[data-storefront-source="v2"] .store-public-banner:has(> img)::before,
.storefront-root[data-storefront-source="v2"] .store-public-banner:has(> img)::after{
  content:none !important;
  display:none !important;
  opacity:0 !important;
  background:transparent !important;
  background-image:none !important;
}

.storefront-root[data-storefront-source="v2"] .store-public-banner.store-banner-has-image > img,
.storefront-root[data-storefront-source="v2"] .store-public-banner:has(> img) > img{
  z-index:0;
  opacity:1 !important;
  filter:none !important;
  mix-blend-mode:normal !important;
  transform:none !important;
}

.storefront-root[data-storefront-source="v2"] .store-public-banner.store-banner-has-image .store-public-banner-copy,
.storefront-root[data-storefront-source="v2"] .store-public-banner:has(> img) .store-public-banner-copy,
.storefront-root[data-storefront-source="v2"] .store-public-banner.store-banner-has-image .store-context-controls-header,
.storefront-root[data-storefront-source="v2"] .store-public-banner:has(> img) .store-context-controls-header{
  position:relative;
  z-index:2;
}

.storefront-root[data-store-theme="light"] .store-banner-section img{
  opacity:1 !important;
  filter:none !important;
  mix-blend-mode:normal !important;
}

.store-public-shell[data-storefront-source="v2"] .store-public-category-bar{
  box-sizing:border-box;
  width:min(var(--store-stage-max, 100%), 100%);
  min-width:0;
  max-width:100%;
  display:grid;
  grid-template-columns:repeat(auto-fit, minmax(118px, 1fr));
  overflow-x:hidden;
  overflow-y:visible;
}

.store-public-shell[data-storefront-source="v2"] .store-public-category-bar a{
  box-sizing:border-box;
  width:100%;
  min-width:0;
  max-width:100%;
  overflow:hidden;
}

.store-public-shell[data-storefront-source="v2"] .store-public-category-bar a :where(strong, small){
  max-width:100%;
  overflow:hidden;
  text-overflow:ellipsis;
  white-space:nowrap;
}

@media (max-width: 860px){
  .store-public-shell[data-storefront-source="v2"] .store-public-category-bar{
    width:calc(100% - 24px) !important;
    margin-inline:12px !important;
    padding-inline:0 !important;
    grid-template-columns:repeat(2, minmax(0, 1fr));
    gap:9px;
  }
}

@media (max-width: 359px){
  .store-public-shell[data-storefront-source="v2"] .store-public-category-bar{
    grid-template-columns:1fr;
  }
}

/* Safe Area 2026-06-05: autoridade unica para barras inferiores, PWA e APK. */
:root{
  --app-safe-bottom:env(safe-area-inset-bottom, 0px);
  --safe-area-bottom-offset:var(--app-safe-bottom);
  --keyboard-inset:0px;
  --bottom-nav-height:72px;
  --content-ad-banner-space:0px;
  --native-ad-banner-space:0px;
}

body.mobile-mode,
body[data-ui-profile="android_apk"],
body[data-ui-profile="web_pwa"]{
  --android-navigation-safe-bottom:var(--app-safe-bottom);
  --size-bottom-nav-height:var(--bottom-nav-height);
  --s3d-button-height-compact:34px;
  --s3d-button-height-standard:40px;
  --s3d-button-height-large:44px;
  --s3d-button-padding-inline:12px;
  --s3d-card-min-height-compact:52px;
  --s3d-card-min-height-standard:64px;
  --s3d-card-min-height-large:84px;
  --s3d-card-padding-compact:7px;
  --s3d-card-padding-standard:10px;
  --s3d-card-padding-large:12px;
}

body.mobile-mode :where(
  #app-content,
  .mobile-panel-content,
  .page-content,
  .main-content,
  .storefront-admin-page,
  .store-public-shell[data-storefront-source="v2"],
  .store-public-main,
  .store-content,
  .editor-content
){
  padding-bottom:calc(var(--bottom-nav-height) + var(--app-safe-bottom) + var(--content-ad-banner-space) + 16px) !important;
  scroll-padding-bottom:calc(var(--bottom-nav-height) + var(--app-safe-bottom) + var(--content-ad-banner-space) + 16px);
}

body.mobile-mode .mobile-bottom-nav,
body[data-ui-profile="android_apk"] .mobile-bottom-nav,
body[data-ui-profile="web_pwa"].mobile-mode .mobile-bottom-nav,
.bottom-nav,
.app-bottom-nav,
.store-bottom-bar,
.editor-bottom-actions{
  bottom:var(--native-ad-banner-space) !important;
  padding-bottom:var(--app-safe-bottom) !important;
}

body.keyboard-visible.mobile-mode .mobile-bottom-nav{
  transform:translateY(calc(100% + var(--app-safe-bottom) + 16px));
  pointer-events:none;
}

.floating-actions,
.fab-container,
.toast-bottom,
.modal-bottom,
.toast-area,
.store-context-edit-fab{
  bottom:calc(var(--app-safe-bottom) + 16px) !important;
}

.bottom-sheet{
  bottom:var(--app-safe-bottom) !important;
}

.store-context-sheet,
.store-product-action-sheet{
  bottom:var(--app-safe-bottom) !important;
  padding-bottom:calc(var(--space-md) + var(--app-safe-bottom)) !important;
}

body.keyboard-visible :where(.store-context-sheet,.store-product-action-sheet){
  bottom:var(--keyboard-inset, 0px) !important;
}

/* Storefront isolation 2026-06-05: tema da loja separado do ERP, safe area compartilhada. */
.storefront-root{
  color-scheme:light;
  padding-bottom:var(--app-safe-bottom);
  background:var(--store-bg);
  color:var(--store-text);
}

.storefront-root[data-store-theme="light"]{
  --store-bg:#f2f5f4;
  --store-bg-soft:#f4f6f5;
  --store-surface:#fcfdfc;
  --store-surface-soft:#f6f8f7;
  --store-surface-strong:#ffffff;
  --store-card:#fcfdfc;
  --store-text:#1f2d2b;
  --store-text-soft:#52635f;
  --store-muted:#71817e;
  --store-muted-2:#8a9996;
  --store-border:rgba(11, 46, 56, .16);
  --store-border-soft:rgba(11, 46, 56, .10);
  --store-input-bg:#f8faf9;
  --store-input-text:#1f2d2b;
  --store-input-placeholder:#70818a;
  --store-header-bg:rgba(248,250,249,.96);
  --store-banner-overlay:none;
  color-scheme:light;
