  .store-public-product-title,
  .store-public-product-card strong,
  .store-public-product-info h1,
  .store-public-price-line strong,
  .store-cart-total strong,
  .store-cart-stepper button
){
  color:var(--store-text);
}

.storefront-root[data-store-theme] :where(
  .store-public-banner-copy p,
  .store-public-section-head p,
  .store-public-product-card p,
  .store-public-product-info p,
  .store-public-spec-grid span,
  .store-public-note,
  .store-cart-item span,
  .store-cart-total span,
  .store-lead-modal .muted
){
  color:var(--store-muted);
}

.storefront-root[data-store-theme] :where(input, select, textarea){
  color:var(--store-input-text);
  background:var(--store-input-bg);
  border-color:var(--store-border);
}

.storefront-root[data-store-theme] :where(input, select, textarea)::placeholder{
  color:var(--store-input-placeholder);
}

.storefront-root[data-store-theme="light"] .store-public-banner.store-banner-has-image,
.storefront-root[data-store-theme="light"] .store-public-banner:has(> img){
  isolation:isolate;
  background:transparent !important;
  background-image:none !important;
}

.storefront-root[data-store-theme="light"] .store-public-banner.store-banner-has-image::before,
.storefront-root[data-store-theme="light"] .store-public-banner.store-banner-has-image::after,
.storefront-root[data-store-theme="light"] .store-public-banner:has(> img)::before,
.storefront-root[data-store-theme="light"] .store-public-banner:has(> img)::after{
  content:none !important;
  display:none !important;
  opacity:0 !important;
  background:transparent !important;
  background-image:none !important;
}

.storefront-root[data-store-theme="light"] .store-public-banner.store-banner-has-image > img,
.storefront-root[data-store-theme="light"] .store-public-banner:has(> img) > img,
.storefront-root[data-store-theme="light"] .store-banner-section img{
  opacity:1 !important;
  filter:none !important;
  mix-blend-mode:normal !important;
  transform:none !important;
}

.storefront-root :where(
  .storefront-content,
  .store-public-main,
  .store-public-product-page,
  .store-category-page,
  .store-public-category-page,
  .store-cart-content,
  .store-editor-preview,
  .store-preview-scroll
){
  padding-bottom:calc(var(--app-safe-bottom) + 96px);
  scroll-padding-bottom:calc(var(--app-safe-bottom) + 96px);
}

.storefront-bottom-bar,
.store-cart-bar,
.store-product-actions,
.store-public-product-actions,
.store-bottom-sheet,
.store-modal-bottom,
.store-cart-drawer,
.store-lead-modal,
.store-guided-editor-sidebar.is-open{
  bottom:var(--app-safe-bottom) !important;
}

.store-floating-actions,
.store-whatsapp-fab,
.store-cart-fab,
.store-public-floating-cart,
.store-public-whatsapp-floating,
.store-context-edit-fab{
  bottom:calc(var(--app-safe-bottom) + 16px) !important;
}

