  --text-primary:#263537;
  --text-secondary:#596b6d;
  --text-muted:#7b8b8d;
  --text-disabled:#9ca9aa;
  --primary:#0f8f88;
  --color-primary:#0f8f88;
  --accent-primary:#0f8f88;
  --accent-primary-hover:#0b746f;
  --accent-primary-active:#085f5b;
  --accent-soft:#e7f6f4;
  --accent-soft-hover:#d8eeeb;
