  content:"";
  position:absolute;
  inset:0 0 auto;
  height:7px;
  background:linear-gradient(90deg, var(--plan-accent, #0ea5a3), color-mix(in srgb, var(--plan-accent, #0ea5a3) 36%, #ffffff));
  opacity:.95;
  pointer-events:none;
}

