  gap:3px;
  min-width:0;
  padding:9px;
  border:1px solid color-mix(in srgb, var(--plan-accent, #0ea5a3) 24%, rgba(255,255,255,.14));
  border-radius:13px;
  background:rgba(255,255,255,.06);
}

.plan-card-brochure-grid small,
.plan-card-brochure-trust small{
  color:var(--muted, #94a3b8);
  font-size:10px;
  line-height:1.2;
}

.plan-card-brochure-grid strong,
.plan-card-brochure-trust strong{
  color:var(--text, #f8fafc);
  font-size:11px;
  line-height:1.2;
}

.plan-card-brochure-strip{
  position:relative;
  display:flex;
  flex-wrap:wrap;
  gap:6px;
}

.plan-card-brochure-strip b{
  display:inline-flex;
  align-items:center;
  min-height:28px;
  padding:6px 9px;
  border-radius:999px;
  color:#fff;
  background:linear-gradient(135deg, color-mix(in srgb, var(--plan-accent, #0ea5a3) 74%, #111827), var(--plan-accent, #0ea5a3));
  font-size:10px;
  font-weight:900;
}

.plan-tier-pro .plan-card-brochure-strip b{
  color:#2a1600;
  background:linear-gradient(135deg, #fff0b8, #f6b51d);
}

.plan-tier-start .plan-card-brochure-strip b{
  color:#ffffff;
  background:linear-gradient(135deg, #5b21b6, #8b5cf6);
}

.plan-tier-free .plan-card-brochure-strip b{
  color:#ffffff;
  background:linear-gradient(135deg, #047857, #10b981);
}

.plan-tier-card.is-selected .plan-card-brochure-strip b{
  animation:planBrochurePulse 2.8s ease-in-out infinite;
}

.plan-tier-card.is-selected .plan-card-brochure-strip b:nth-child(2){
  animation-delay:.18s;
}

.plan-tier-card.is-selected .plan-card-brochure-strip b:nth-child(3){
  animation-delay:.36s;
}

@keyframes planBrochurePulse{
  0%, 100%{ transform:translateY(0); filter:saturate(1); }
  50%{ transform:translateY(-1px); filter:saturate(1.16); }
}

.plan-card-brochure-trust{
  position:relative;
  display:grid;
  grid-template-columns:repeat(3, minmax(0, 1fr));
  gap:8px;
}

body.theme-light .plans-pricing-screen .plan-card-brochure{
  background:
    radial-gradient(circle at 12% 0, color-mix(in srgb, var(--plan-accent, #0ea5a3) 18%, transparent), transparent 42%),
    rgba(255,255,255,.72);
  border-color:color-mix(in srgb, var(--plan-accent, #0ea5a3) 32%, rgba(15,23,42,.12));
}

body.theme-light .plans-pricing-screen .plan-card-brochure-grid span,
body.theme-light .plans-pricing-screen .plan-card-brochure-trust span{
  background:rgba(255,255,255,.88);
  border-color:color-mix(in srgb, var(--plan-accent, #0ea5a3) 32%, rgba(15,23,42,.16));
  box-shadow:inset 0 1px 0 rgba(255,255,255,.78);
}

body.theme-light .plans-pricing-screen .plan-card-brochure-grid strong,
body.theme-light .plans-pricing-screen .plan-card-brochure-trust strong{
  color:#1f2d2b;
}

body.theme-light .plans-pricing-screen .plan-card-brochure-grid small,
body.theme-light .plans-pricing-screen .plan-card-brochure-trust small{
  color:#415450;
}

.plan-mobile-tabs{
