  background:linear-gradient(180deg, rgba(15,23,42,.78), rgba(15,23,42,.58));
  box-shadow:0 18px 46px rgba(15,23,42,.16);
}

.superadmin-plan-remote-panel > .row-title,
.superadmin-plan-remote-card .row-title{
