.storefront-root[data-store-theme="light"]{
  --store-bg:#ffffff;
  --store-bg-soft:#f3f7f7;
  --store-surface:#ffffff;
  --store-surface-soft:#f3f7f7;
  --store-surface-strong:#ffffff;
  --store-card:#ffffff;
  --store-text:#1f2d2f;
  --store-text-soft:#667a7d;
  --store-muted:#667a7d;
  --store-border:#dde7e8;
  --store-border-soft:#e8eff0;
  --store-input-bg:#ffffff;
  --store-input-text:#1f2d2f;
  --store-input-placeholder:#667a7d;
  --store-header-bg:#ffffff;
  --store-banner-overlay:none;
  background-color:var(--store-bg);
  background-image:none !important;
}

.storefront-root[data-store-theme="light"] :where(
  .store-public-header,.store-public-category-bar a,.store-public-product-card,.store-public-contact,
  .store-public-inner-head,.store-public-benefits article,.store-public-product-hero,.store-public-promo,
  .store-visual-editor-sidebar,.store-visual-editor-topbar,.store-visual-panel,.store-editor-panel,
  .store-preview-panel,.store-preview-device,.store-cart-drawer,.store-lead-modal,.store-bottom-sheet
){
  background-color:var(--store-card) !important;
  background-image:none !important;
  border-color:var(--store-border) !important;
  box-shadow:0 4px 14px rgba(31,51,53,.07);
  filter:none;
  backdrop-filter:none;
  -webkit-backdrop-filter:none;
}

.storefront-root[data-store-theme="light"] :where(.btn,.store-public-icon-action,.store-public-menu-toggle,.store-context-edit-fab){
  background-image:none !important;
  filter:none;
}

.storefront-root[data-store-theme="light"] :where(.store-public-banner,.store-banner-section){
  background-color:var(--store-surface) !important;
  background-image:none;
}

.storefront-root[data-store-theme="light"] :where(.store-public-banner,.store-banner-section)::before,
.storefront-root[data-store-theme="light"] :where(.store-public-banner,.store-banner-section)::after{
  background-image:none !important;
  filter:none !important;
}

@media (max-width:860px){
  .store-public-shell[data-storefront-source="v2"] .store-context-edit-fab{
