.store-guided-selected{
  position:relative;
  scroll-margin-top:88px;
  scroll-margin-bottom:calc(44vh + 110px + var(--app-safe-bottom, 0px));
  outline:3px solid var(--store-primary, #078f86);
  outline-offset:3px;
  box-shadow:0 0 0 6px color-mix(in srgb, var(--store-primary, #078f86) 18%, transparent), var(--store-shadow-soft) !important;
}

.store-guided-selected::after{
  position:absolute;
  z-index:4;
  top:10px;
  right:10px;
  display:inline-flex;
  align-items:center;
  min-height:28px;
