/* Perceived performance: feedback real, não bloqueante e compartilhado pelo ERP. */
.smart-loader-layer{
  position:fixed;
  top:calc(var(--topbar-height,56px) + var(--space-md,12px));
  right:var(--space-lg,16px);
  z-index:var(--z-toast,1400);
  width:min(360px,calc(100vw - 24px));
  display:grid;
  gap:var(--space-sm,8px);
  pointer-events:none;
}

.smart-loader-panel{
  padding:var(--space-lg,16px);
  border:1px solid var(--border-primary,#d8e1e7);
  border-radius:var(--radius-lg,8px);
  background:var(--card-bg,#fff);
  color:var(--text-primary,#14232c);
  box-shadow:var(--shadow-lg,0 16px 36px rgba(20,35,44,.16));
