  line-height:1.3;
}

.smart-loader-panel-head p{
  margin:3px 0 0;
  color:var(--text-secondary,#50636f);
  font-size:var(--font-sm,.875rem);
  line-height:1.4;
}

.smart-loader-spinner,
.smart-loader-button-spinner{
