  border:2px solid color-mix(in srgb,var(--accent-primary,#147f78) 20%,transparent);
  border-top-color:var(--accent-primary,#147f78);
  border-radius:50%;
  animation:smart-loader-spin .75s linear infinite;
}

.smart-loader-spinner{
  width:22px;
  height:22px;
}

.smart-loader-button-spinner{
  width:15px;
  height:15px;
}

button.is-processing,
.btn.is-processing{
