@keyframes systemScreenCrossfade{
  from{
    opacity:0;
    transform:translate3d(var(--screen-motion-x, 0), var(--screen-motion-y, 0), 0) scale(.992);
    filter:saturate(.98);
  }
  to{
    opacity:1;
    transform:translate3d(0, 0, 0) scale(1);
    filter:saturate(1);
  }
}

body.motion-forward{
  --screen-motion-x:var(--space-sm);
  --screen-motion-y:0;
}

body.motion-back{
  --screen-motion-x:calc(var(--space-sm) * -1);
  --screen-motion-y:0;
}

body.motion-down{
  --screen-motion-x:0;
  --screen-motion-y:calc(var(--space-md) * -1);
}

body.motion-up{
  --screen-motion-x:0;
  --screen-motion-y:var(--space-md);
}

body.motion-forward :where(.desktop-main,.mobile-panel,.mobile-home,.desktop-focus,.app-page),
body.motion-back :where(.desktop-main,.mobile-panel,.mobile-home,.desktop-focus,.app-page),
body.motion-down :where(.desktop-main,.mobile-panel,.mobile-home,.desktop-focus,.app-page),
body.motion-up :where(.desktop-main,.mobile-panel,.mobile-home,.desktop-focus,.app-page),
body.motion-refresh :where(.desktop-main,.mobile-panel,.mobile-home,.desktop-focus,.app-page){
  animation:systemScreenCrossfade var(--transition-base) both !important;
  transform-origin:center top;
  will-change:opacity, transform;
}

body:where(.motion-forward,.motion-back,.motion-up,.motion-down) .superadmin-platform-shell{
  animation:systemScreenCrossfade 340ms var(--motion-ease) both !important;
  transform-origin:center top;
  will-change:opacity, transform;
}


/* Atualizações de dados do Superadmin não devem parecer uma nova abertura da tela. */
body.motion-refresh :where(.desktop-main,.mobile-panel,.mobile-home,.desktop-focus,.app-page):has(.superadmin-platform-shell){
  animation:none !important;
  will-change:auto;
}

.motion-stagger-item{
  animation:systemStaggerIn var(--transition-slow) both;
  animation-delay:calc(min(var(--motion-index, 0), 10) * 24ms);
  will-change:opacity, transform;
}

@keyframes systemStaggerIn{
  from{
    opacity:0;
    transform:translate3d(var(--screen-motion-x, 0), var(--screen-motion-y, 10px), 0) scale(.992);
  }
  to{
    opacity:1;
    transform:translate3d(0, 0, 0) scale(1);
  }
}

@supports (view-transition-name:root){
  ::view-transition-old(root),
  ::view-transition-new(root){
    animation-duration:220ms;
    animation-timing-function:var(--motion-ease);
    mix-blend-mode:normal;
  }

  ::view-transition-old(root){
    z-index:1;
    animation-name:systemViewUnderFade;
  }

  ::view-transition-new(root){
    z-index:2;
    animation-name:systemViewOverFade;
  }
}

@keyframes systemViewUnderFade{
  from{
    opacity:1;
    transform:translate3d(0, 0, 0) scale(1);
  }
  to{
    opacity:.72;
    transform:translate3d(calc(var(--screen-motion-x, 0) * -0.35), -2px, 0) scale(.998);
  }
}

@keyframes systemViewOverFade{
  from{
    opacity:0;
    transform:translate3d(var(--screen-motion-x, 0), var(--screen-motion-y, 0), 0) scale(.992);
  }
  to{
    opacity:1;
    transform:translate3d(0, 0, 0) scale(1);
  }
}

@media(prefers-reduced-motion:reduce){
  ::view-transition-old(root),
  ::view-transition-new(root),
  body.motion-forward :where(.desktop-main,.mobile-panel,.mobile-home),
  body.motion-back :where(.desktop-main,.mobile-panel,.mobile-home),
  body.motion-down :where(.desktop-main,.mobile-panel,.mobile-home),
  body.motion-up :where(.desktop-main,.mobile-panel,.mobile-home),
  body.motion-refresh :where(.desktop-main,.mobile-panel,.mobile-home),
  .motion-stagger-item,
  body.mobile-mode .ui-section.ui-subscreen-active{
    animation:none !important;
    transition:none !important;
  }
}

/* Telas estáveis: atualizações de dados não devem piscar ou reanimar a estrutura. */
body :where(.desktop-main,.desktop-focus,.mobile-home,.mobile-panel,.app-page),
body.motion-forward :where(.desktop-main,.desktop-focus,.mobile-home,.mobile-panel,.app-page),
