.interface-mode-options{
  display:grid;
  gap:8px;
}

.interface-mode-option{
  width:100%;
  min-height:52px;
  display:grid;
  grid-template-columns:36px minmax(0, 1fr) 24px;
  align-items:center;
  gap:10px;
  padding:8px 10px;
  border:1px solid var(--line);
  border-radius:8px;
  background:var(--surface);
  color:var(--text);
  text-align:left;
}

.interface-mode-option:hover{
  border-color:color-mix(in srgb, var(--primary) 48%, var(--line));
  background:color-mix(in srgb, var(--surface) 92%, var(--primary) 8%);
}

.interface-mode-option.active{
  border-color:var(--primary);
  background:color-mix(in srgb, var(--surface) 88%, var(--primary) 12%);
}

.interface-mode-option-icon{
  width:36px;
  height:36px;
  display:grid;
  place-items:center;
  color:var(--primary);
}

.interface-mode-option-icon svg{
  width:20px;
  height:20px;
}

.interface-mode-option > span:nth-child(2){
  display:grid;
  gap:2px;
  min-width:0;
}

.interface-mode-option small{
  color:var(--text-muted);
}

.interface-mode-option-check{
  visibility:hidden;
  color:var(--primary);
  font-weight:800;
  text-align:center;
