/* Printer monitoring: read-only operational surface */
.printer-screen {
  display: grid;
  gap: var(--space-4, 16px);
}

.printer-pilot-card {
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(220px, 280px);
  align-items: center;
  gap: 18px;
  padding: 16px;
  border: 1px solid color-mix(in srgb, var(--warning, #f59e0b) 38%, var(--border));
  border-radius: 8px;
  background: color-mix(in srgb, var(--warning, #f59e0b) 7%, var(--card-bg));
}

.printer-pilot-card-copy,
.printer-pilot-progress,
.printer-pilot-summary,
.printer-pilot-checklist,
.printer-pilot-data-note {
  display: grid;
  gap: 8px;
}

.printer-pilot-card h3,
.printer-pilot-card p,
.printer-pilot-card small,
.printer-pilot-summary p {
  margin: 0;
}

.printer-pilot-card .app-badge {
  justify-self: start;
  width: fit-content;
  max-width: 100%;
}

.printer-pilot-card p,
.printer-pilot-card small,
.printer-pilot-summary p,
.printer-pilot-data-note span {
  color: var(--text-muted);
}

.printer-pilot-progress > div {
  height: 9px;
  overflow: hidden;
  border-radius: 999px;
  background: color-mix(in srgb, var(--warning, #f59e0b) 16%, var(--surface-subtle));
}

.printer-pilot-progress > div i {
  display: block;
  width: var(--progress);
  height: 100%;
  border-radius: inherit;
  background: var(--warning, #f59e0b);
}

.printer-pilot-modal {
  width: min(720px, calc(100vw - 28px));
  max-height: min(90vh, 880px);
  overflow: auto;
}

.printer-pilot-summary,
.printer-pilot-checklist,
.printer-pilot-data-note {
  padding: 14px;
  border: 1px solid var(--border);
  border-radius: 8px;
  background: var(--surface-subtle);
}

.printer-pilot-checklist {
  margin: 0;
}

.printer-pilot-checklist legend {
  padding: 0 6px;
  font-weight: 800;
}

.printer-pilot-checklist label {
  display: flex;
  align-items: flex-start;
  gap: 10px;
  cursor: pointer;
}

.printer-pilot-checklist input {
  margin-top: 3px;
}

.printer-pilot-data-note {
  grid-template-columns: auto minmax(0, 1fr);
  align-items: start;
}

.printer-pilot-data-note svg {
  width: 20px;
  height: 20px;
  color: var(--accent);
}

.printer-pilot-data-note div {
  display: grid;
  gap: 4px;
}

.printer-bambu-agent-note {
  display: grid;
  grid-template-columns: auto minmax(0, 1fr);
  align-items: start;
  gap: 10px;
  padding: 12px;
  border: 1px solid color-mix(in srgb, var(--accent) 32%, var(--border));
  border-radius: 8px;
  background: color-mix(in srgb, var(--accent) 7%, var(--card-bg));
}

.printer-bambu-agent-note[hidden] {
  display: none;
}

.printer-bambu-agent-note svg {
  width: 20px;
  height: 20px;
  color: var(--accent);
}

.printer-bambu-agent-note div {
  display: grid;
  gap: 4px;
}

.printer-bambu-agent-note span {
  color: var(--text-muted);
}

.printer-setup-choice,
.printer-order-queue {
  display: grid;
  gap: 14px;
}

.printer-setup-choice {
  padding: clamp(14px, 2.5vw, 20px);
  border: 1px solid var(--border);
  border-radius: 12px;
  background: color-mix(in srgb, var(--accent) 4%, var(--card-bg));
}

.printer-setup-choice > div:first-child {
  display: grid;
  gap: 4px;
}

.printer-setup-choice h3,
.printer-setup-choice p,
.printer-order-queue h3,
.printer-order-queue p {
  margin: 0;
}

.printer-setup-choice p,
.printer-order-queue p,
.printer-order-row-main span,
.printer-order-row-main small {
  color: var(--text-muted);
}

.printer-setup-choice-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 10px;
}

.printer-setup-summary,.printer-waste-summary{
  display:grid;
  gap:6px;
  padding:10px 12px;
  border:1px solid color-mix(in srgb,var(--accent) 30%,var(--border));
  border-radius:10px;
  background:color-mix(in srgb,var(--accent) 7%,var(--card-bg));
}
.printer-setup-summary strong{font-size:.82rem}
.printer-setup-summary span{color:var(--text-muted);font-size:.75rem}
.printer-waste-summary{grid-template-columns:minmax(130px,1.5fr) repeat(3,minmax(88px,1fr));align-items:center;margin:0 0 12px}
.printer-waste-summary div{display:grid;gap:2px;min-width:0}
.printer-waste-summary span{color:var(--text-muted);font-size:.7rem}
.printer-waste-summary strong{font-size:.82rem}
.printer-waste-inputs{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:10px}
.printer-waste-estimate{color:var(--text-muted);font-size:.82rem}

.printer-cadastro-progress{
  display:grid;
  grid-template-columns:repeat(3,minmax(0,1fr));
  gap:8px;
  margin:0;
  padding:0 0 12px;
  list-style:none;
  border-bottom:1px solid var(--border);
}

.printer-cadastro-progress li{
  min-width:0;
  display:flex;
  align-items:center;
  gap:7px;
  color:var(--text-muted);
  font-size:11px;
}

.printer-cadastro-progress li > span{
  width:26px;
  height:26px;
  flex:0 0 26px;
  display:grid;
  place-items:center;
  border:1px solid var(--border);
  border-radius:50%;
  font-size:11px;
  font-weight:800;
}

.printer-cadastro-progress li strong{overflow:hidden;text-overflow:ellipsis;white-space:nowrap;}
.printer-cadastro-progress li.active,.printer-cadastro-progress li.done{color:var(--accent);}
.printer-cadastro-progress li.active > span,.printer-cadastro-progress li.done > span{background:var(--accent);border-color:var(--accent);color:#fff;}

.printer-cadastro-step{min-width:0;}
.printer-cadastro-step[hidden]{display:none !important;}

.printer-cadastro-tabs{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));overflow:visible;padding:0 0 10px;}
.printer-cadastro-tabs .ui-tab{min-width:0;padding:0 8px;font-size:12px;}
.printer-bambu-account-fields{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:10px;padding:12px;border:1px solid color-mix(in srgb,var(--accent) 34%,var(--border));border-radius:var(--radius);background:color-mix(in srgb,var(--accent) 6%,var(--card-bg));}
.printer-bambu-account-fields small{grid-column:1 / -1;color:var(--text-muted);font-size:11px;}
.printer-lan-fields{display:grid;gap:8px;padding:12px;border:1px solid var(--border);border-radius:var(--radius);background:var(--card-bg);}
.printer-lan-fields small{color:var(--text-muted);font-size:11px;}
.printer-lan-guide{padding:10px;border-radius:10px;background:color-mix(in srgb,var(--primary) 7%,var(--card-bg));color:var(--text-muted);font-size:12px;line-height:1.4;}
.printer-bambu-account-fields[hidden],.printer-lan-fields[hidden],.printer-bambu-review[hidden]{display:none !important;}
.printer-bambu-review{display:flex;align-items:center;gap:12px;padding:14px;border:1px solid color-mix(in srgb,var(--accent) 34%,var(--border));border-radius:var(--radius);background:color-mix(in srgb,var(--accent) 6%,var(--card-bg));}
.printer-bambu-review > span{display:grid;place-items:center;width:42px;height:42px;border-radius:12px;color:var(--accent);background:var(--card-bg);}
.printer-bambu-review > div{display:grid;gap:3px;min-width:0;}
.printer-bambu-review small{color:var(--text-muted);}

/* Cadastro de impressora: mesma largura compacta dos formulários operacionais. */
.ui3-dialog:has(.printer-wizard){width:min(640px,calc(100vw - 24px)) !important;}
.ui3-dialog:has(.printer-wizard) .printer-wizard{width:100% !important;max-width:100% !important;box-sizing:border-box;}
@media(max-width:767px){.printer-cadastro-tabs .ui-tab{min-height:44px;font-size:11px;padding:4px;white-space:normal;}.printer-bambu-account-fields{grid-template-columns:1fr;}.printer-wizard-actions{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));}.printer-wizard-actions .btn{width:100%;}}

/* Cadastro de impressora no celular: painel começa logo abaixo da barra do aparelho. */
@media(max-width:767px){
  .printer-waste-summary{grid-template-columns:repeat(2,minmax(0,1fr));gap:8px;padding:9px}
  .printer-waste-inputs{grid-template-columns:1fr}
  [data-ui-version="v3"] .ui3-dialog-portal:has(.printer-wizard){
    place-items:start stretch;
    padding:0;
  }
  [data-ui-version="v3"] .ui3-dialog:has(.printer-wizard){
    width:100% !important;
    height:100% !important;
    max-height:none !important;
    border-radius:0 !important;
    padding:18px 16px calc(18px + env(safe-area-inset-bottom)) !important;
  }
  [data-ui-version="v3"] .ui3-dialog:has(.printer-wizard) .printer-wizard-actions .btn{
    min-height:48px !important;
    font-size:15px !important;
    font-weight:800;
  }
  [data-ui-version="v3"] .ui3-dialog:has(.printer-wizard) .printer-cadastro-tabs .ui-tab{
    min-height:48px;
    font-size:12px;
  }
}

.printer-setup-option {
  position: relative;
  display: grid;
  grid-template-columns: 42px minmax(0, 1fr);
  align-items: center;
  gap: 3px 10px;
  min-width: 0;
  padding: 15px;
  border: 1px solid var(--border);
  border-radius: 10px;
  color: var(--text);
  background: var(--card-bg);
  text-align: left;
  cursor: pointer;
  overflow: hidden;
  white-space: normal;
  transition: border-color 160ms ease, background 160ms ease, box-shadow 160ms ease, transform 160ms ease;
}

.printer-setup-option > span {
  grid-row: 1 / span 3;
  display: grid;
  place-items: center;
  width: 42px;
  height: 42px;
  color: var(--accent);
  border-radius: 8px;
  background: color-mix(in srgb, var(--accent) 10%, var(--card-bg));
}

.printer-setup-option small,
.printer-setup-option b {
  grid-column: 2;
}

.printer-setup-option small {
  color: var(--text-muted);
  font-weight: 500;
  overflow-wrap: anywhere;
  white-space: normal;
}

.printer-setup-option b {
  color: var(--accent);
  font-size: 0.72rem;
}

.printer-setup-option:hover,
.printer-setup-option.selected {
  border-color: var(--accent);
  background: color-mix(in srgb, var(--accent) 6%, var(--card-bg));
  box-shadow: 0 0 0 2px color-mix(in srgb, var(--accent) 14%, transparent);
}

.printer-setup-option:hover {
  transform: translateY(-1px);
}

.printer-form-simple.is-bambu-quick .printer-technical-field,
.printer-form-simple.is-bambu-quick .printer-identification-section,
.printer-form-simple.is-bambu-quick .printer-connection-mode-field,
.printer-form-simple.is-bambu-quick .printer-costs-section {
