.printer-order-queue {
  padding: 16px;
  border: 1px solid var(--border);
  border-radius: 8px;
  background: var(--card-bg);
}

.printer-order-queue-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
}

.printer-order-stages {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 8px;
}

.printer-order-stages button {
