}

.printer-page-header,
.printer-card-header,
.printer-card-actions,
.printer-wizard-actions {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--space-3, 12px);
}

.printer-page-header {
  padding: 4px 0 8px;
}

.printer-page-header > .actions {
  margin-left: auto;
  justify-content: flex-end;
}

.printer-screen-simple > .card-header {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  align-items: center;
}

.printer-screen-simple > .card-header > .app-button {
  justify-self: end;
}

.printer-page-header h2,
.printer-card h3 {
