}

.printer-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(min(100%, 340px), 1fr));
  gap: var(--space-4, 16px);
}

.printer-grid.is-empty {
  grid-template-columns: minmax(0, 1fr);
}

.printer-card,
.printer-empty {
  min-width: 0;
  padding: var(--space-4, 16px);
  border: 1px solid var(--border);
  border-radius: 8px;
  background: var(--card-bg);
  box-shadow: var(--shadow-sm);
}

.printer-card {
  display: grid;
  gap: var(--space-3, 12px);
  transition:
    transform var(--motion-duration-fast, 160ms) var(--motion-easing-standard, ease),
    border-color var(--motion-duration-fast, 160ms) var(--motion-easing-standard, ease),
    box-shadow var(--motion-duration-fast, 160ms) var(--motion-easing-standard, ease);
