.printer-card-header {
  align-items: flex-start;
}

.printer-card-header > div {
  min-width: 0;
  flex: 1;
}

.printer-card-header p,
.printer-current-file {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.printer-device-icon,
.printer-summary-icon,
.printer-empty > svg,
.printer-loading > svg {
