  padding: 5px 8px;
  border: 1px solid var(--border);
  border-radius: 999px;
  color: var(--text);
  background: var(--surface-subtle);
  font-size: 0.78rem;
  font-weight: 700;
}

.printer-status-badge i {
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: currentColor;
}

.printer-status-badge.status-success { color: var(--success, #15803d); }
.printer-status-badge.status-warning { color: var(--warning, #b45309); }
.printer-status-badge.status-danger { color: var(--danger, #dc2626); }
.printer-status-badge.status-muted { color: var(--text-muted); }

.printer-progress {
  position: relative;
