}

.printer-progress span {
  position: relative;
  z-index: 1;
  display: grid;
  place-items: center;
  height: 100%;
  font-size: 0.78rem;
  font-weight: 800;
}

.printer-metrics {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 8px;
}

.printer-metrics > div {
  min-width: 0;
  padding: 9px;
  border: 1px solid var(--border);
  border-radius: 6px;
  background: var(--surface-subtle);
}

.printer-metrics span,
.printer-metrics strong {
  display: block;
}

.printer-metrics span {
  color: var(--text-muted);
  font-size: 0.72rem;
}

.printer-metrics strong {
  margin-top: 3px;
  overflow: hidden;
  font-size: 0.88rem;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.printer-card-meta {
