  flex-wrap: wrap;
  padding-top: 4px;
  border-top: 1px solid var(--border);
}

.printer-plan-note,
.printer-error,
.printer-read-only-notice {
  margin: 0;
  padding: 10px 12px;
  border: 1px solid color-mix(in srgb, var(--warning, #f59e0b) 35%, var(--border));
  border-radius: 6px;
  color: var(--text);
  background: color-mix(in srgb, var(--warning, #f59e0b) 8%, var(--card-bg));
}

.printer-error {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  border-color: color-mix(in srgb, var(--danger, #dc2626) 35%, var(--border));
  background: color-mix(in srgb, var(--danger, #dc2626) 7%, var(--card-bg));
}

.printer-read-only-notice {
  display: flex;
  align-items: center;
  gap: 8px;
