  background: color-mix(in srgb, var(--accent) 7%, var(--card-bg));
}

.printer-read-only-notice svg {
  width: 18px;
  height: 18px;
}

.printer-empty,
.printer-loading {
  display: grid;
  justify-items: center;
  gap: 10px;
  min-height: 220px;
  align-content: center;
  text-align: center;
}

.printer-empty p {
