  padding: 10px;
  border: 1px solid var(--border);
  border-radius: 7px;
  background: var(--surface-subtle);
}

.printer-summary-main {
  display: grid;
  gap: 4px;
  min-width: 0;
  flex: 1;
}

.printer-summary-main > strong {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.printer-summary-main small {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 8px;
  color: var(--text-muted);
}

.printer-summary-progress {
  flex: 0 0 auto;
}

.printer-summary-actions {
  display: flex;
  flex: 0 0 auto;
  flex-wrap: wrap;
  justify-content: flex-end;
  gap: 6px;
}

.printer-summary-actions .btn,
.printer-card-actions .btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  min-height: 44px;
  padding-inline: 14px;
}

.printer-device-panel-actions .btn {
  min-height: 44px;
  padding-inline: 14px;
}

.printer-summary-actions svg,
.printer-card-actions .btn svg {
  width: 17px;
  height: 17px;
}

.printer-action-menu {
