.printer-device-metric-grid article > i svg { width: 23px; height: 23px; }
.printer-device-metric-grid article > div { display: grid; gap: 2px; min-width: 0; }

.printer-device-metric-grid span,
.printer-device-metric-grid small,
.printer-ams-grid span,
.printer-ams-grid small {
  color: var(--text-muted);
}

.printer-device-metric-grid strong {
  font-size: 1.25rem;
}

.printer-ams-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(120px, 1fr));
  gap: 10px;
}

.printer-ams-grid article {
  display: grid;
  justify-items: center;
  gap: 4px;
  padding: 12px;
  border: 1px solid var(--border);
  border-radius: 8px;
  background: var(--surface-subtle);
  text-align: center;
}

.printer-ams-grid i {
  display: block;
  width: 46px;
  height: 58px;
  border: 7px solid #3d434a;
  border-radius: 8px 8px 14px 14px;
  background: var(--filament-color);
  box-shadow: inset 0 0 0 2px color-mix(in srgb, #fff 30%, transparent);
}

.printer-device-panel-actions {
  flex-wrap: wrap;
  padding-top: 4px;
}

.printer-more-button {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
}

.printer-actions-sheet {
  width: min(460px, calc(100vw - 24px));
  max-width: 100%;
}

.printer-actions-sheet-list {
  display: grid;
  gap: 4px;
}

.printer-actions-sheet-list button {
  width: 100%;
  min-height: 44px;
  padding: 10px 12px;
  border: 0;
  border-radius: 8px;
  color: var(--text);
  background: var(--surface-subtle);
  font: inherit;
  text-align: left;
}

.printer-actions-sheet-list button.danger {
  color: var(--danger, #dc2626);
}

.printer-lan-modal {
  width: min(620px, calc(100vw - 24px));
  max-width: 100%;
}

.printer-lan-modal .form-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 12px;
}

.printer-lan-modal .field-wide {
  grid-column: 1 / -1;
}

.printer-lan-note {
  display: flex;
  align-items: flex-start;
  gap: 9px;
  padding: 10px 12px;
  border: 1px solid color-mix(in srgb, var(--accent) 28%, var(--border));
  border-radius: 8px;
  color: var(--text-muted);
  background: color-mix(in srgb, var(--accent) 7%, var(--card-bg));
}

.printer-lan-note svg {
  flex: 0 0 18px;
  width: 18px;
  height: 18px;
}

.printer-wizard {
  width: min(780px, calc(100vw - 28px));
  max-height: min(88vh, 860px);
  overflow: auto;
}

.printer-form-simple{
  display:grid;
  gap:16px;
}

.printer-simple-fields{
  display:grid;
  grid-template-columns:repeat(2, minmax(0, 1fr));
  gap:12px;
}

.printer-simple-fields .field-wide{
  grid-column:1 / -1;
}

.printer-advanced-settings{
  overflow:hidden;
  border:1px solid var(--color-border);
  border-radius:8px;
  background:var(--color-surface-soft);
}

.printer-advanced-settings > summary{
  min-height:56px;
  display:grid;
  grid-template-columns:36px minmax(0, 1fr);
  align-items:center;
  gap:4px 10px;
  padding:10px 12px;
  cursor:pointer;
  list-style:none;
}

.printer-advanced-settings > summary::-webkit-details-marker{
  display:none;
}

.printer-advanced-settings > summary > span{
  grid-row:1 / span 2;
  width:36px;
  height:36px;
  display:grid;
  place-items:center;
  color:var(--accent-primary);
  background:var(--accent-soft);
  border:1px solid var(--accent-border);
  border-radius:8px;
}

.printer-advanced-settings > summary svg{
  width:19px;
  height:19px;
}

.printer-advanced-settings > summary small{
  color:var(--color-text-muted);
}

.printer-advanced-content{
  display:grid;
  gap:18px;
  padding:14px;
  border-top:1px solid var(--color-divider);
  background:var(--color-card);
}

.printer-advanced-content > section{
  display:grid;
  gap:10px;
}

.printer-advanced-content h3{
  margin:0;
  font-size:var(--font-md);
}

.printer-stepper {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 6px;
  margin-bottom: 14px;
}

.printer-stepper span {
  display: flex;
  align-items: center;
  gap: 7px;
  min-width: 0;
  padding: 7px;
  color: var(--text-muted);
  border-bottom: 2px solid var(--border);
  font-size: 0.78rem;
  font-weight: 700;
}

.printer-stepper i {
  display: grid;
  place-items: center;
  flex: 0 0 24px;
  width: 24px;
  height: 24px;
  border: 1px solid currentColor;
  border-radius: 50%;
  font-style: normal;
}

.printer-stepper span.active,
.printer-stepper span.done {
  color: var(--accent);
  border-bottom-color: var(--accent);
}

.printer-wizard-step {
  display: none;
  min-height: 330px;
}

.printer-wizard-step.active {
  display: block;
  animation: printer-step-enter var(--motion-duration-medium, 240ms) var(--motion-easing-standard, ease);
}

.printer-wizard .form-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 12px;
}

.printer-wizard .field-wide {
  grid-column: 1 / -1;
}

.printer-wizard textarea {
  min-height: 86px;
  resize: vertical;
}

.printer-wizard-actions {
  position: sticky;
  bottom: -1px;
  display:flex;
  justify-content:flex-end;
  gap:8px;
  padding-top: 12px;
  background: var(--card-bg);
  border-top: 1px solid var(--border);
}

.printer-review {
  display: grid;
  justify-items: center;
  gap: 12px;
  max-width: 560px;
  margin: 34px auto 0;
  text-align: center;
}

.printer-review > svg {
  width: 44px;
  height: 44px;
  color: var(--accent);
}

.printer-review ul {
  width: 100%;
  margin: 0;
  padding: 12px 12px 12px 32px;
  text-align: left;
  color: var(--text-muted);
  border: 1px solid var(--border);
  border-radius: 7px;
  background: var(--surface-subtle);
}

.printer-history-modal {
  width: min(820px, calc(100vw - 28px));
  max-height: 85vh;
  overflow: auto;
}

.printer-history-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 16px;
}

.printer-history-grid section {
  min-width: 0;
}

.calc-printer-selector {
  margin-bottom: 12px;
}

.calc-printer-selector small {
  color: var(--text-muted);
}

@keyframes printer-step-enter {
  from { opacity: 0; transform: translateY(8px); }
  to { opacity: 1; transform: translateY(0); }
}

