/* Controle único de tema ligado aos tokens de botão do sistema. */
.theme-mode-toggle {
  width: 34px;
  height: 34px;
  min-width: 34px;
  min-height: 34px;
  max-width: 34px;
  max-height: 34px;
  padding: 0;
  display: inline-grid;
  place-items: center;
  flex: 0 0 34px;
  border-color: var(--s3d-button-secondary-border);
  background: var(--s3d-button-secondary-bg);
  color: var(--s3d-button-secondary-text);
}

.theme-mode-disc {
  position: relative;
  display: block;
  width: 17px;
  height: 17px;
  overflow: hidden;
  border: 2px solid var(--text-primary);
  border-radius: 50%;
  background: var(--surface-base);
}

.theme-mode-disc::before {
  content: "";
  position: absolute;
  inset: 0 50% 0 0;
  background: var(--text-primary);
}

.theme-mode-toggle[data-theme-preference="system"] .theme-mode-disc::after {
  content: "";
  position: absolute;
  inset: 4px;
  border: 2px solid var(--color-primary);
  border-radius: 50%;
  background: var(--surface-base);
}

.theme-mode-toggle.is-pressing {
  transform: scale(.92);
}

.theme-selector-modal {
  width: min(360px, calc(100vw - 32px));
  border-radius: 8px;
}

.theme-selector-options {
  display: grid;
  gap: var(--space-2);
}

.theme-selector-option {
  width: 100%;
  min-height: 52px;
  display: grid;
  grid-template-columns: 28px minmax(0, 1fr) 20px;
  align-items: center;
  gap: var(--space-3);
  padding: var(--space-2) var(--space-3);
  border: 1px solid var(--color-border, var(--border-soft));
  border-radius: 8px;
  background: var(--surface-primary);
  color: var(--text-primary);
  text-align: left;
}

.theme-selector-option > span:nth-child(2) {
  display: grid;
  gap: 2px;
  min-width: 0;
}

.theme-selector-option small {
  color: var(--text-muted);
}

.theme-selector-option.active {
  border-color: var(--color-primary);
  background: var(--accent-soft);
}

.theme-selector-option b {
  color: var(--accent-text);
}

.dashboard-simplifica-header-actions,
.mobile-panel-actions {
  display: flex;
  align-items: center;
  gap: var(--space-2);
  min-width: 0;
}

.dashboard-interface-mode-button {
  flex: 0 0 var(--size-control-md, 40px);
  width: var(--size-control-md, 40px);
  min-width: var(--size-control-md, 40px);
  height: var(--size-control-md, 40px);
  min-height: var(--size-control-md, 40px);
  padding: 0;
}

.dashboard-interface-mode-button svg {
  width: var(--size-icon-md, 20px);
  height: var(--size-icon-md, 20px);
}

.mobile-panel-actions {
  justify-content: flex-end;
}

.mobile-quick-controls {
  display: flex;
  justify-content: flex-end;
  align-items: center;
  gap: var(--space-2);
  margin: 0 0 var(--space-3);
}

.mobile-quick-controls .mobile-theme-toggle {
  flex: 0 0 34px;
}

.mobile-interface-mode-button {
  min-height: 34px;
  display: inline-flex;
  align-items: center;
  gap: 7px;
  padding: 6px 10px;
  border: 1px solid var(--s3d-button-secondary-border, var(--color-border));
  border-radius: 8px;
  background: var(--s3d-button-secondary-bg, var(--surface-primary));
  color: var(--s3d-button-secondary-text, var(--text-primary));
  font: inherit;
  font-size: var(--font-sm);
  font-weight: 800;
}

.mobile-interface-mode-button svg {
  width: 16px;
  height: 16px;
}

.dashboard-mobile-advanced-panel {
  display: grid;
  gap: var(--space-3);
}

.dashboard-mobile-advanced-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: var(--space-2);
}

.dashboard-mobile-advanced-card {
  position: relative;
  overflow: hidden;
  min-height: 86px;
  display: grid;
  grid-template-columns: 32px minmax(0, 1fr);
  align-items: center;
  gap: 10px;
  padding: 10px;
  border: 1px solid var(--color-border, var(--border-soft));
  border-radius: 8px;
  background: var(--surface-primary, #fff);
  background-image: none;
  color: var(--text-primary);
  text-align: left;
  box-shadow: var(--shadow-sm);
  transition: border-color var(--motion-duration-fast, 160ms) var(--motion-easing-standard, ease), box-shadow var(--motion-duration-fast, 160ms) var(--motion-easing-standard, ease);
}

.dashboard-mobile-advanced-card:hover,
.dashboard-mobile-advanced-card:focus-visible {
  border-color: var(--color-primary, var(--accent-primary));
  box-shadow: var(--shadow-md);
  outline: none;
}

.dashboard-mobile-advanced-icon {
  width: 32px;
  height: 32px;
  display: grid;
  place-items: center;
  color: var(--accent-text, var(--color-primary));
  background: var(--accent-soft);
  border-radius: 8px;
}

.dashboard-mobile-advanced-card svg {
  width: 18px;
  height: 18px;
}

.dashboard-mobile-advanced-copy {
  min-width: 0;
  display: grid;
  justify-items: start;
  align-content: center;
  gap: 3px;
  text-align: left;
}

.dashboard-mobile-advanced-card strong,
.dashboard-mobile-advanced-card small,
.dashboard-live-values {
  min-width: 0;
  width: 100%;
  text-align: left;
}

.dashboard-mobile-advanced-card strong {
  display: block;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  line-height: 1.1;
  font-size: var(--font-md);
  word-break: normal;
}

.dashboard-mobile-advanced-card small {
  display: block;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  color: var(--text-muted);
  font-size: var(--font-xs);
}

.dashboard-live-values {
  position: relative;
  display: block;
  height: 18px;
  color: var(--accent-text, var(--color-primary));
  font-size: var(--font-xs);
  font-weight: 800;
}

.dashboard-live-values em {
  position: absolute;
  inset: 0 auto auto 0;
  max-width: 100%;
  overflow: hidden;
  opacity: 0;
  font-style: normal;
  text-overflow: ellipsis;
  white-space: nowrap;
  animation: dashboard-live-card-cycle 15s infinite;
}

.dashboard-live-values em:nth-child(2) {
  animation-delay: 5s;
}

.dashboard-live-values em:nth-child(3) {
  animation-delay: 10s;
}

@keyframes dashboard-live-card-cycle {
  0%, 28% { opacity: 1; transform: translateY(0); }
  33%, 100% { opacity: 0; transform: translateY(-4px); }
}

@media (prefers-reduced-motion: reduce) {
  .dashboard-live-values em {
    animation: none;
  }

  .dashboard-live-values em:first-child {
    opacity: 1;
  }
}

body.theme-light .reports-header :where(h1,h2,p,small,strong,span) {
  color: inherit;
}

body.theme-light .reports-title-row {
  min-width: 0;
  flex: 1 1 auto;
  background: var(--surface-primary, #fff);
  background-image: none;
  border-color: var(--color-border, var(--border-soft));
}

body.theme-light .reports-title-row > div {
  min-width: 0;
}

body.theme-light .reports-title-row h2,
body.theme-light .reports-title-row p {
  overflow: hidden;
  text-overflow: ellipsis;
}

body.theme-light .reports-search-compact,
body.theme-light .reports-filter-button {
  flex: 0 0 auto;
}

.topbar-profile-context {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: var(--space-2);
  padding: var(--space-2) var(--space-3);
  border-top: 1px solid var(--color-border, var(--border-soft));
  border-bottom: 1px solid var(--color-border, var(--border-soft));
}

.topbar-profile-context span {
  display: grid;
  min-width: 0;
}

.topbar-profile-context small,
.topbar-profile-context strong {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.context-advanced-toggle {
  min-height: 34px;
  padding: 5px 9px;
  font-size: var(--font-sm);
}

.administration-page {
  display: grid;
  gap: var(--space-lg);
}

/* Layouts registrados do Design System V3. */
.ui3-form-grid-single {
  display: grid;
  grid-template-columns: minmax(0, 1fr) !important;
}

.ui3-form-grid-single > :where(.field, .ui3-field-full) {
  grid-column: 1 / -1;
  width: 100%;
}

.ui3-action-row :where(.btn, .app-button),
.app-button[data-ui-component="Button"] {
  min-height: 44px !important;
  padding: 0 var(--space-lg, 16px) !important;
  display: inline-flex !important;
  align-items: center;
  justify-content: center;
  gap: var(--space-sm, 8px);
  border-width: 1px !important;
  border-style: solid !important;
  border-radius: var(--radius-md, 10px) !important;
  font-weight: 800;
  line-height: 1.15;
  text-decoration: none;
}

.ui3-action-row {
  display: grid !important;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  align-items: stretch;
  gap: var(--space-sm, 8px);
}

.ui3-action-row > :where(.btn, .app-button) {
  width: 100%;
  min-width: 0;
}

.ui3-action-row > :only-child {
  grid-column: 1 / -1;
}

.stock-wizard-actions:has(> :nth-child(3)) > :last-child {
  grid-column: 1 / -1;
}

body.mobile-mode .administration-page .administration-subpage > .ui3-action-row :where(.btn, .app-button) { width: 100%; }

.administration-page > .app-header {
  min-height: auto;
  padding: 0;
  border: 0;
  background: transparent;
  background-image: none;
  box-shadow: none;
  backdrop-filter: none;
}

.administration-page > .app-header h2 {
  color: var(--text-primary);
}

.administration-summary {
  display: flex;
  align-items: center;
  gap: var(--space-md);
  padding: var(--space-md);
  border: 1px solid var(--color-border, var(--border-soft));
  border-radius: 8px;
  background: var(--surface-primary);
}

.administration-summary > span {
  width: 36px;
  height: 36px;
  display: grid;
  place-items: center;
  color: var(--accent-text);
}

.administration-summary > div,
.administration-module-row > span:nth-child(2) {
  display: grid;
  gap: 2px;
  min-width: 0;
}

.administration-summary small,
.administration-module-row small {
  color: var(--text-muted);
}

.administration-module-list {
  display: grid;
  border: 1px solid var(--color-border, var(--border-soft));
  border-radius: 8px;
  overflow: hidden;
  background: var(--surface-primary);
}

.administration-module-row {
  width: 100%;
  min-height: 64px;
  display: grid;
  grid-template-columns: 36px minmax(0, 1fr) 20px;
  align-items: center;
  gap: var(--space-md);
  padding: var(--space-md);
  border: 0;
  border-bottom: 1px solid var(--color-border, var(--border-soft));
  background: transparent;
  color: var(--text-primary);
  text-align: left;
  font-size: var(--font-sm);
  font-weight: 700;
}

.administration-module-row:last-child {
  border-bottom: 0;
}

.administration-module-icon {
  width:36px;
  height:36px;
  display:grid;
  place-items:center;
  color: var(--accent-text);
  border:1px solid var(--accent-border, var(--color-border));
  border-radius:8px;
  background:var(--accent-soft, var(--surface-secondary));
}

.administration-module-row strong{
  font-size:var(--font-sm);
  line-height:1.15;
}

.administration-module-row small{
  font-size:var(--font-xs);
  line-height:1.25;
}

.profile-modern-screen,
.profile-modern-card,
.profile-list-card,
.profile-inline-edit-card,
.account-security-panel,
.security-online-grid,
.security-settings-card {
  min-width: 0;
  max-width: 100%;
}

.profile-modern-screen,
.account-security-panel {
  overflow-x: hidden;
}

.profile-list-row span,
.security-card-heading > div,
.security-summary-item > span {
  min-width: 0;
  overflow-wrap: anywhere;
}

.storefront-plan-notice {
  display: grid;
  gap: 2px;
  padding: var(--space-sm) var(--space-md);
  border: 1px solid var(--color-border, var(--border-soft));
  border-radius: 8px;
  background: var(--surface-secondary);
  color: var(--text-primary);
}

.storefront-plan-notice span {
  color: var(--text-muted);
  font-size: var(--font-sm);
}

.storefront-plan-notice.is-blocked {
  border-color: color-mix(in srgb, var(--warning) 36%, var(--color-border, var(--border-soft)));
  background: color-mix(in srgb, var(--warning) 9%, var(--surface-primary));
}

.security-account-online-section {
  margin-top: var(--space-xl);
  padding-top: var(--space-xl);
  border-top: 1px solid var(--color-border, var(--border-soft));
}

.security-section-title {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: var(--space-md);
  margin-bottom: var(--space-lg);
}

.security-section-title h3,
.security-section-title p {
  margin: 0;
}

.security-section-title p {
  margin-top: var(--space-xs);
  color: var(--text-muted);
}

@media (max-width: 767px) {

  .theme-selector-modal {
    width: 100%;
    max-height: min(82dvh, 680px);
    margin: 0;
    overflow-y: auto;
    border-radius: 8px 8px 0 0;
  }

  .mobile-panel-content,
  .profile-modern-screen,
  .account-security-panel {
    overscroll-behavior-y: contain;
    -webkit-overflow-scrolling: touch;
  }

  .profile-inline-actions .app-button {
    width: 100%;
  }

  .app-main,
  .mobile-panel-content {
    padding-bottom: calc(80px + env(safe-area-inset-bottom));
  }
}

/* UI contract guard: scroll must remain available inside the active app surface. */
html,
body,
#app,
#app-shell,
#app-content,
.app-content-shell{
  min-width:0;
}

#app-content,
.app-content-shell,
.desktop-main,
.desktop-focus,
.mobile-panel,
.mobile-panel-content,
.mobile-home{
  min-height:0;
  overscroll-behavior-y:contain;
}

#app-content,
.app-content-shell{
  overflow-x:hidden;
  overflow-y:auto;
  -webkit-overflow-scrolling:touch;
  scroll-padding-bottom:calc(var(--bottom-nav-height, 72px) + var(--app-safe-bottom, 0px) + 20px);
}

.mobile-panel{
  overflow:hidden;
}

.mobile-panel-content{
  overflow-x:hidden;
  overflow-y:auto;
  -webkit-overflow-scrolling:touch;
  scroll-padding-bottom:calc(var(--bottom-nav-height, 72px) + var(--app-safe-bottom, 0px) + 24px);
}

.desktop-main,
.desktop-focus{
  overflow:visible;
}

.app-page,
.organized-page,
.settings-page,
.reports-page,
.stock-page,
.clients-compact-screen,
.profile-modern-screen,
.account-security-panel,
.printer-screen{
  min-width:0;
  max-width:100%;
  overflow-x:hidden;
  overflow-y:visible;
}

/* UI contract guard: common controls use compact Lucide-style icons. */
:where(.btn,.app-button,.s3d-button,.context-advanced-toggle) > svg,
:where(.btn,.app-button,.s3d-button,.context-advanced-toggle) > span > svg{
  width:18px;
  height:18px;
  flex:0 0 18px;
  stroke-width:1.85;
}

:where(.icon-button,.s3d-icon-button) > svg,
:where(.icon-button,.s3d-icon-button) > span > svg{
  width:20px;
  height:20px;
  flex:0 0 20px;
  stroke-width:1.85;
}

:where(.quick-action,.action-tile,.profile-list-row,.administration-module-row) svg{
  max-width:22px;
  max-height:22px;
  stroke-width:1.85;
}

:where(.ui-section-icon,.action-symbol,.administration-summary > span,.security-summary-icon,.security-card-icon) svg{
  width:22px;
  height:22px;
  max-width:22px;
  max-height:22px;
  stroke-width:1.85;
}

:where(.card,.app-card,.s3d-card,.reports-kpi-card,.cash-summary-card) :where(h1,h2,h3,strong,p,span,small){
  min-width:0;
}

/* Mobile dashboard advanced operation: full-width rows avoid clipped labels. */
@media (max-width: 767px){
  body.mobile-mode .dashboard-mobile-advanced-panel .dashboard-mobile-advanced-grid{
    grid-template-columns:1fr !important;
    gap:8px !important;
  }

  body.mobile-mode .dashboard-mobile-advanced-panel .dashboard-mobile-advanced-card{
    min-height:64px !important;
    grid-template-columns:36px minmax(0, 1fr) !important;
    align-items:center !important;
    justify-items:stretch !important;
    gap:10px !important;
    padding:10px 12px !important;
    text-align:left !important;
  }

  body.mobile-mode .dashboard-mobile-advanced-panel .dashboard-mobile-advanced-icon{
    width:36px !important;
    height:36px !important;
    justify-self:start !important;
  }

  body.mobile-mode .dashboard-mobile-advanced-panel .dashboard-mobile-advanced-copy{
    min-width:0 !important;
    width:100% !important;
    justify-items:start !important;
    text-align:left !important;
  }

  body.mobile-mode .dashboard-mobile-advanced-panel .dashboard-mobile-advanced-copy strong{
    display:block !important;
    width:100% !important;
    overflow:visible !important;
    text-align:left !important;
    text-overflow:clip !important;
    white-space:normal !important;
  }

  body.mobile-mode .dashboard-mobile-advanced-panel .dashboard-mobile-advanced-copy small,
  body.mobile-mode .dashboard-mobile-advanced-panel .dashboard-live-values{
    width:100% !important;
    text-align:left !important;
  }
}

/* Cash mobile rails need horizontal touch gestures even when the app shell locks page swipes. */
body.mobile-mode .mobile-panel:has(.cash-experience) .mobile-panel-content,
body.mobile-mode .mobile-panel:has(.cash-mobile-flow) .mobile-panel-content{
  touch-action:pan-x pan-y !important;
}

body.mobile-mode :where(
  .cash-quick-actions-grid,
  .cash-day-grid,
  .cash-payment-cards,
  .cash-filter-chips,
  .cash-period-tabs,
  .cash-view-tabs
){
  overflow-x:auto !important;
  overflow-y:hidden;
  overscroll-behavior-x:contain;
  touch-action:pan-x pan-y !important;
  -webkit-overflow-scrolling:touch;
  scroll-snap-type:x mandatory;
}

body.mobile-mode :where(
  .cash-quick-action,
  .cash-day-card,
  .cash-payment-card,
  .cash-filter-chips > *,
  .cash-period-tabs > *,
  .cash-view-tabs > *
){
  touch-action:pan-x pan-y !important;
  scroll-snap-align:start;
}

/* Estoque compacto: métricas, lista curta e ações contextuais. */
.stock-summary-grid{
  display:grid;
  grid-template-columns:repeat(4, minmax(0, 1fr));
  gap:10px;
  margin:4px 0 12px;
}

.stock-summary-card{
  position:relative;
  min-width:0;
  min-height:104px;
  display:grid;
  align-content:center;
  justify-items:start;
  gap:4px;
  padding:14px 54px 14px 14px;
  overflow:hidden;
  border:1px solid var(--color-border, rgba(148,163,184,.22));
  border-radius:var(--radius-sm, 8px);
  color:var(--color-text-primary, #0f172a);
  background:var(--color-surface, #fff);
  text-align:left;
  box-shadow:var(--effect-shadow-sm, 0 4px 14px rgba(15,23,42,.06));
}

.stock-summary-card > span,
.stock-summary-card > small{
  color:var(--color-text-secondary, #64748b);
  font-size:12px;
}

.stock-summary-card > strong{
  max-width:100%;
  overflow:hidden;
  font-size:21px;
  line-height:1.1;
  text-overflow:ellipsis;
  white-space:nowrap;
}

.stock-summary-card > i{
  position:absolute;
  right:14px;
  top:50%;
  width:34px;
  height:34px;
  display:grid;
  place-items:center;
  border-radius:8px;
  color:var(--color-primary, #0f8f87);
  background:color-mix(in srgb, var(--color-primary, #0f8f87) 10%, transparent);
  transform:translateY(-50%);
}

.stock-summary-card > i svg,
.stock-type-icon svg{
  width:22px;
  height:22px;
}

.stock-summary-card > i.warn{ color:#d97706; background:#fff7ed; }
.stock-summary-card > i.danger{ color:#dc2626; background:#fff1f2; }

.stock-search-row{
  display:grid;
  grid-template-columns:minmax(0, 1fr) minmax(116px, 154px) 42px;
  align-items:center;
  gap:8px;
}

.stock-search-row .stock-search-field{
  margin:8px 0 10px;
}

.stock-sort-field{
  min-width:0;
  display:grid;
  gap:2px;
}

.stock-sort-field > span{
  color:var(--color-text-muted);
  font-size:9px;
  font-weight:800;
  letter-spacing:.05em;
  text-transform:uppercase;
}

.stock-sort-field select{
  width:100%;
  min-width:0;
  height:38px;
  padding:0 28px 0 9px;
  border:1px solid var(--color-border);
  border-radius:9px;
  color:var(--color-text-primary);
  background:var(--color-surface);
}

.stock-row-title-line{
  min-width:0;
  display:flex;
  align-items:center;
  gap:7px;
}

.stock-row-title-line > strong{
  min-width:0;
  overflow:hidden;
  text-overflow:ellipsis;
  white-space:nowrap;
}

.stock-code-badge{
  flex:0 0 auto;
  padding:2px 6px;
  border:1px solid color-mix(in srgb,var(--color-primary) 26%,var(--color-border));
  border-radius:999px;
  color:var(--color-primary);
  background:color-mix(in srgb,var(--color-primary) 8%,var(--color-surface));
  font-size:9px;
  font-variant-numeric:tabular-nums;
  letter-spacing:.03em;
}

.stock-list{
  display:grid;
  gap:6px;
}

.smart-stock-row{
  grid-template-columns:42px minmax(0, 1fr) auto 36px;
  min-height:76px;
  padding:9px 10px;
  border-radius:var(--radius-sm, 8px);
}

.stock-type-icon{
  width:38px;
  height:38px;
  display:grid;
  place-items:center;
  flex:0 0 38px;
  border-radius:8px;
  color:var(--color-primary, #0f8f87);
  background:color-mix(in srgb, var(--color-primary, #0f8f87) 9%, var(--color-surface, #fff));
}

.stock-percent-box strong{
  font-size:14px;
}

.stock-item-menu{
  position:relative;
  justify-self:end;
}

.stock-item-menu > summary{
  display:grid;
  place-items:center;
  list-style:none;
  cursor:pointer;
}

.stock-item-menu > summary::-webkit-details-marker{
  display:none;
}

.stock-item-menu > summary svg{
  width:18px;
  height:18px;
}

.stock-item-menu-popover{
  position:absolute;
  z-index:80;
  top:calc(100% + 5px);
  right:0;
  width:190px;
  display:grid;
  gap:2px;
  padding:6px;
  border:1px solid var(--color-border, #dce7ea);
  border-radius:8px;
  background:var(--color-surface, #fff);
  box-shadow:0 16px 36px rgba(15,23,42,.16);
}

.stock-item-menu-popover button{
  min-height:34px;
  display:flex;
  align-items:center;
  gap:8px;
  padding:7px 9px;
  border:0;
  border-radius:6px;
  color:var(--color-text-primary, #0f172a);
  background:transparent;
  font-size:12px;
  text-align:left;
}

.stock-item-menu-popover button:hover{
  background:color-mix(in srgb, var(--color-primary, #0f8f87) 8%, transparent);
}

.stock-item-menu-popover button.danger{
  color:var(--color-danger, #dc2626);
}

.stock-item-menu-popover svg{
  width:16px;
  height:16px;
  flex:0 0 16px;
}

.stock-list-toggle{
  min-height:38px;
  display:flex;
  align-items:center;
  justify-content:center;
  gap:6px;
  margin:8px auto 0;
  padding:6px 14px;
  border:0;
  color:var(--color-primary, #0f8f87);
  background:transparent;
  font-size:12px;
  font-weight:700;
}

.stock-list-toggle svg{
  width:18px;
  height:18px;
}

.stock-add-fab{
  position:fixed !important;
  z-index:60;
  right:24px;
  left:auto !important;
  bottom:94px;
  width:54px;
  height:54px;
  display:grid;
  place-items:center;
  border:0;
  border-radius:50%;
  color:#fff;
  background:var(--color-primary, #0f8f87);
  box-shadow:0 14px 30px color-mix(in srgb, var(--color-primary, #0f8f87) 32%, transparent);
}

.stock-add-fab svg{
  width:24px;
  height:24px;
}

.stock-add-fab span{
  position:absolute;
  top:calc(100% + 4px);
  right:0;
  color:var(--color-text-secondary, #64748b);
