.stock-batch-section-head > div{
  display:grid;
  gap:2px;
}

.stock-batch-section-head small{
  color:var(--color-text-secondary, #64748b);
}

.stock-batch-list{
  display:grid;
  gap:6px;
}

.stock-batch-row{
