/* Central responsive layout authority: one vertical scroll owner per screen. */
:root {
  --ui-icon-stroke-width: 1.85;
  --ui-icon-box-compact: 32px;
  --ui-icon-box-standard: 40px;
  --ui-icon-radius: 10px;
}

:where(
  .metric-card__icon,
  .quick-action-card > span,
  .dashboard-shortcut-grid button > span,
  .side-nav-button > span,
  .dashboard-mobile-advanced-icon,
  .stock-type-icon,
  .reports-kpi-icon,
  .cash-recent-icon,
  .ui-section-icon,
  .administration-module-icon,
  .security-card-icon
) {
  display: grid;
  place-items: center;
  border-radius: var(--ui-icon-radius) !important;
  box-shadow: none !important;
}

:where(
  .metric-card__icon,
  .quick-action-card > span,
  .dashboard-shortcut-grid button > span,
  .side-nav-button > span,
  .dashboard-mobile-advanced-icon,
  .stock-type-icon,
  .reports-kpi-icon,
  .cash-recent-icon,
  .ui-section-icon,
  .administration-module-icon,
  .security-card-icon
) svg {
  stroke-width: var(--ui-icon-stroke-width) !important;
}

body[data-ui-profile="web_pwa"]:not(.mobile-mode) .metric-card__icon {
  width: 42px !important;
  height: 42px !important;
  border-radius: var(--ui-icon-radius) !important;
}

