.ds-template {
  width: 100%;
  min-width: 0;
  max-width: var(--page-max-width);
  margin-inline: auto;
}

.ds-template-content {
  width: 100%;
  min-width: 0;
  display: grid;
  align-content: start;
  grid-template-columns: repeat(12, minmax(0, 1fr));
  gap: var(--page-gap-desktop);
  padding-inline: var(--page-padding-desktop);
}

.ds-template-content > * {
  min-width: 0;
}

.ds-template-footer {
  min-width: 0;
  padding: var(--page-gap-desktop) var(--page-padding-desktop) 0;
}

@media (max-width: 1024px) {
  .ds-template-content {
    grid-template-columns: repeat(8, minmax(0, 1fr));
    gap: var(--page-gap-tablet);
    padding-inline: var(--page-padding-tablet);
  }

  .ds-template-footer {
    padding: var(--page-gap-tablet) var(--page-padding-tablet) 0;
  }
}

@media (max-width: 640px) {
  .ds-template-content {
    grid-template-columns: repeat(4, minmax(0, 1fr));
    gap: var(--page-gap-mobile);
    padding-inline: var(--page-padding-mobile);
