  letter-spacing:.08em;
  text-transform:uppercase;
}

/* Estoque: botão flutuante móvel sem bloquear o restante da interface. */
.stock-fab-layer{
  position:fixed !important;
  inset:0 !important;
  z-index:70;
  pointer-events:none !important;
}

.stock-fab-layer .stock-add-fab{
  pointer-events:auto !important;
  touch-action:none;
  user-select:none;
  -webkit-user-select:none;
  cursor:grab;
  transition:box-shadow .18s ease, transform .18s ease;
}

.stock-fab-layer .stock-add-fab.is-positioned{
  right:auto !important;
  bottom:auto !important;
}

.stock-fab-layer .stock-add-fab.is-dragging{
  cursor:grabbing;
  transform:scale(1.06);
  box-shadow:0 18px 38px color-mix(in srgb,var(--color-primary,#0f8f87) 44%,transparent);
}

.stock-add-header{
  min-height:38px;
  display:inline-flex;
  align-items:center;
  gap:7px;
}

@media(max-width:767px){
  body.mobile-mode .stock-add-header{display:none !important;}
}

/* Cadastro de estoque em três etapas. */
.stock-wizard-modal{
  width:100%;
  min-width:0;
  max-width:100%;
  box-sizing:border-box;
  max-height:min(820px,calc(100dvh - 24px));
  overflow:hidden;
  display:grid;
  grid-template-rows:auto auto minmax(0,1fr) auto;
}

.stock-wizard-modal .modal-header > div{
  min-width:0;
  display:grid;
  gap:2px;
}

.stock-wizard-modal .modal-header small{
  color:var(--color-text-muted);
  font-size:10px;
  font-weight:800;
  letter-spacing:.08em;
  text-transform:uppercase;
}

.stock-wizard-modal .modal-header h2{
  display:flex;
  align-items:center;
  gap:8px;
  margin:0;
}

.stock-wizard-progress{
  display:grid;
  grid-template-columns:repeat(3,minmax(0,1fr));
  gap:8px;
  margin:0;
  padding:10px 0 14px;
  list-style:none;
  border-bottom:1px solid var(--color-border);
}

.stock-wizard-progress li{
  min-width:0;
  display:flex;
  align-items:center;
  gap:7px;
  color:var(--color-text-muted);
}

.stock-wizard-progress li::after{
  content:"";
  height:2px;
  flex:1;
  border-radius:2px;
  background:var(--color-border);
}

.stock-wizard-progress li:last-child::after{display:none;}

.stock-wizard-progress li > span{
  width:28px;
  height:28px;
  flex:0 0 28px;
  display:grid;
  place-items:center;
  border:1px solid var(--color-border);
  border-radius:50%;
  background:var(--color-surface);
  font-size:11px;
  font-weight:800;
}

.stock-wizard-progress li strong{
  font-size:11px;
  white-space:nowrap;
}

.stock-wizard-progress li.active,
.stock-wizard-progress li.done{color:var(--color-primary);}

.stock-wizard-progress li.active > span,
.stock-wizard-progress li.done > span{
  color:#fff;
  border-color:var(--color-primary);
  background:var(--color-primary);
}

.stock-wizard-progress li.done::after{background:var(--color-primary);}

.stock-wizard-body{
  min-width:0;
  max-width:100%;
  overflow-y:auto;
  overflow-x:hidden;
  overscroll-behavior:contain;
  padding:14px 2px 10px;
}

.stock-wizard-code-preview{
  display:grid;
  grid-template-columns:minmax(0,1fr) auto;
  align-items:center;
  gap:2px 10px;
  margin-bottom:12px;
  padding:10px 12px;
  border:1px solid color-mix(in srgb,var(--color-primary) 25%,var(--color-border));
  border-radius:12px;
  background:color-mix(in srgb,var(--color-primary) 7%,var(--color-surface));
}

.stock-wizard-code-preview > span{font-size:11px;font-weight:800;color:var(--color-text-secondary);}
.stock-wizard-code-preview > strong{grid-row:1 / span 2;grid-column:2;font-size:18px;color:var(--color-primary);font-variant-numeric:tabular-nums;}
.stock-wizard-code-preview > small{color:var(--color-text-muted);font-size:10px;}

.stock-duplicate-warning{
  display:grid;
  grid-template-columns:28px minmax(0,1fr) auto;
  align-items:center;
  gap:9px;
  margin-bottom:12px;
  padding:10px;
  border:1px solid color-mix(in srgb,var(--color-warning,#d97706) 38%,var(--color-border));
  border-radius:12px;
  color:var(--color-text-primary);
  background:color-mix(in srgb,var(--color-warning,#d97706) 10%,var(--color-surface));
}

.stock-duplicate-warning > span{color:var(--color-warning,#d97706);}
.stock-duplicate-warning > span svg{width:22px;height:22px;}
.stock-duplicate-warning > div{min-width:0;display:grid;gap:2px;}
.stock-duplicate-warning small{color:var(--color-text-secondary);font-size:10px;overflow-wrap:anywhere;}

.stock-wizard-grid{
  display:grid;
  grid-template-columns:repeat(2,minmax(0,1fr));
  gap:10px;
}

.stock-wizard-wide{grid-column:1 / -1;}

.stock-wizard-visual{
  min-width:0;
  display:grid;
  gap:10px;
  margin-top:14px;
  padding-top:12px;
  border-top:1px solid var(--color-border);
}

.stock-wizard-section-head > div{
  display:grid;
  gap:2px;
}

.stock-wizard-section-head small{
  color:var(--color-text-muted);
  font-size:11px;
}

.stock-icon-picker{
  position:relative;
  min-width:0;
}

.stock-icon-picker > summary{
  min-height:62px;
  display:grid;
  grid-template-columns:42px minmax(0,1fr) auto;
  align-items:center;
  gap:10px;
  padding:9px 10px;
  border:1px solid var(--color-border);
  border-radius:12px;
  color:var(--color-text-primary);
  background:var(--color-surface);
  cursor:pointer;
  list-style:none;
}

.stock-icon-picker > summary::-webkit-details-marker{display:none;}
.stock-icon-picker > summary > span:nth-child(2){min-width:0;display:grid;gap:2px;}
.stock-icon-picker > summary small{color:var(--color-text-muted);font-size:9px;text-transform:uppercase;letter-spacing:.05em;}
.stock-icon-picker-current{width:42px;height:42px;display:grid;place-items:center;border-radius:11px;color:var(--color-primary);background:color-mix(in srgb,var(--color-primary) 10%,var(--color-surface));}
.stock-icon-picker-current svg{width:22px;height:22px;}
.stock-icon-picker-action{padding:7px 9px;border-radius:9px;color:var(--color-primary);background:color-mix(in srgb,var(--color-primary) 9%,var(--color-surface));font-size:10px;font-weight:800;white-space:nowrap;}
.stock-icon-picker-panel{margin-top:7px;padding:9px;border:1px solid var(--color-border);border-radius:13px;background:var(--color-surface);box-shadow:0 16px 34px rgba(0,0,0,.18);}
.stock-icon-picker-heading{display:grid;gap:2px;margin-bottom:8px;}
.stock-icon-picker-heading small{color:var(--color-text-muted);font-size:10px;}

.stock-icon-options{
  display:grid;
  grid-template-columns:repeat(4,minmax(0,1fr));
  gap:7px;
}

.stock-icon-option{
  min-width:0;
  min-height:64px;
  display:grid;
  place-items:center;
  gap:3px;
  padding:7px 4px;
  border:1px solid var(--color-border);
  border-radius:11px;
  color:var(--color-text-primary);
  background:var(--color-surface);
}

.stock-icon-option span{
  width:28px;
  height:28px;
  display:grid;
  place-items:center;
  color:var(--color-primary);
}

.stock-icon-option svg{width:20px;height:20px;}
.stock-icon-option small{font-size:9px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;max-width:100%;}

.stock-icon-option.active{
  border-color:var(--color-primary);
  background:color-mix(in srgb,var(--color-primary) 11%,var(--color-surface));
  box-shadow:0 0 0 2px color-mix(in srgb,var(--color-primary) 15%,transparent);
}

.stock-photo-picker{
  min-width:0;
  display:grid;
  grid-template-columns:42px minmax(0,1fr) auto;
  align-items:center;
  gap:7px;
  padding:7px;
  border:1px dashed var(--color-border);
  border-radius:12px;
  background:color-mix(in srgb,var(--color-surface) 94%,var(--color-primary) 6%);
}

.stock-photo-picker.has-photo{grid-template-columns:42px minmax(0,1fr) auto auto;}
.stock-photo-picker > div:nth-child(2){min-width:0;display:grid;gap:2px;}
.stock-photo-picker small{color:var(--color-text-muted);font-size:10px;overflow-wrap:anywhere;}
.stock-photo-picker > div:nth-child(2) > span{color:var(--color-text-secondary);font-size:10px;overflow-wrap:anywhere;}
.stock-photo-preview{width:42px;height:42px;display:grid;place-items:center;overflow:hidden;border-radius:9px;color:var(--color-primary);background:var(--color-surface);}
.stock-photo-preview img{width:100%;height:100%;object-fit:cover;}
.stock-photo-preview svg{width:20px;height:20px;}
.stock-photo-button{position:relative;overflow:hidden;}
.stock-photo-button{display:inline-flex !important;align-items:center;justify-content:center;flex-direction:row !important;gap:4px;white-space:nowrap;}
.stock-photo-button svg{width:15px;height:15px;}
.stock-photo-button input{position:absolute;inline-size:1px;block-size:1px;opacity:0;pointer-events:none;}

.stock-wizard-review{
  min-width:0;
  max-width:100%;
  display:grid;
  grid-template-columns:64px repeat(3,minmax(0,1fr));
  align-items:center;
  gap:10px;
  margin-bottom:14px;
  padding:12px;
  border:1px solid var(--color-border);
  border-radius:14px;
  background:color-mix(in srgb,var(--color-surface) 95%,var(--color-primary) 5%);
}

.stock-wizard-review > div{min-width:0;display:grid;gap:2px;}
.stock-wizard-review small,.stock-wizard-review span{color:var(--color-text-muted);font-size:10px;overflow-wrap:anywhere;}
.stock-wizard-review strong{font-size:13px;overflow-wrap:anywhere;}
.stock-wizard-review-media{width:64px;height:64px;display:grid;place-items:center;overflow:hidden;border-radius:13px;color:var(--color-primary);background:var(--color-surface);}
.stock-wizard-review-media img{width:100%;height:100%;object-fit:cover;}
.stock-wizard-review-media svg{width:28px;height:28px;}
.stock-wizard-safe-note{display:flex;align-items:center;gap:7px;margin:10px 0 0;padding:9px;border-radius:10px;color:var(--color-text-secondary);background:color-mix(in srgb,var(--color-success,#16a34a) 9%,var(--color-surface));font-size:11px;}
.stock-wizard-safe-note svg{width:17px;height:17px;color:var(--color-success,#16a34a);}

.stock-wizard-actions{
  margin-top:0;
  padding-top:12px;
  border-top:1px solid var(--color-border);
}

.stock-type-icon.has-photo{padding:0;overflow:hidden;}
.stock-type-icon.has-photo img{width:100%;height:100%;object-fit:cover;display:block;}

@media(max-width:640px){
  .superadmin-platform-shell .superadmin-user-card{
    grid-template-columns:minmax(0,1fr) auto 36px !important;
    padding:10px !important;
  }
  .superadmin-platform-shell .superadmin-user-actions{width:36px;min-width:36px;}
  .stock-wizard-modal{width:100%;max-width:100%;max-height:calc(100dvh - 12px);padding:12px;}
  .stock-wizard-grid{grid-template-columns:minmax(0,1fr);}
  .stock-wizard-wide{grid-column:auto;}
  .stock-icon-options{grid-template-columns:repeat(4,minmax(0,1fr));}
  .stock-icon-option{min-height:58px;padding:5px 2px;}
  .stock-photo-picker,
  .stock-photo-picker.has-photo{grid-template-columns:40px minmax(0,1fr) auto;padding:7px;}
  .stock-photo-picker.has-photo .stock-photo-preview{justify-self:start;}
  .stock-photo-picker .stock-photo-button{grid-column:auto;width:auto;height:32px !important;min-height:32px !important;padding:5px 7px !important;}
  .stock-photo-picker > .btn.ghost{grid-column:2 / -1;width:100%;min-height:30px !important;}
  .stock-photo-preview{width:40px;height:40px;}
  .stock-duplicate-warning{grid-template-columns:24px minmax(0,1fr);}
  .stock-duplicate-warning > .btn{grid-column:2;width:100%;}
  .stock-wizard-review{grid-template-columns:56px minmax(0,1fr);align-items:start;}
  .stock-wizard-review-media{width:56px;height:56px;grid-row:1 / span 3;}
  .stock-wizard-progress li strong{font-size:9px;}
  .stock-wizard-progress li > span{width:24px;height:24px;flex-basis:24px;}
  .stock-wizard-actions{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));}
  .stock-wizard-actions .btn{width:100%;min-width:0;}
}

/* Superadmin: substitui o carrossel horizontal por quatro widgets operacionais. */
.superadmin-module-widget-section{
  min-width:0;
  display:grid;
  gap:10px;
  margin-bottom:14px;
  padding:12px;
  border:1px solid var(--sa-border,var(--color-border));
  border-radius:16px;
  color:var(--sa-text,var(--color-text-primary));
  background:var(--sa-surface,var(--color-surface));
}

.superadmin-module-widget-head{
  min-width:0;
  display:flex;
  align-items:center;
  justify-content:space-between;
  gap:10px;
}

.superadmin-module-widget-head > div{min-width:0;display:grid;gap:2px;}
.superadmin-module-widget-head strong{font-size:15px;}
.superadmin-module-widget-head small{color:var(--sa-muted,var(--color-text-muted));font-size:10px;}

.superadmin-module-widgets{
  min-width:0;
  display:grid;
  grid-template-columns:repeat(4,minmax(0,1fr));
  gap:8px;
  overflow:visible;
}

.superadmin-module-widget{
  min-width:0;
  min-height:104px;
  display:grid;
  grid-template-columns:38px minmax(0,1fr) 16px;
  align-items:center;
  gap:8px;
  padding:10px;
  border:1px solid var(--sa-border,var(--color-border));
  border-radius:13px;
  color:var(--sa-text,var(--color-text-primary));
  background:var(--sa-surface-soft,var(--color-surface-secondary));
  text-align:left;
  transition:transform .16s ease,border-color .16s ease,box-shadow .16s ease;
}

.superadmin-module-widget:hover,
.superadmin-module-widget:focus-visible{
  transform:translateY(-2px);
  border-color:color-mix(in srgb,var(--sa-primary,var(--color-primary)) 50%,var(--sa-border,var(--color-border)));
  box-shadow:0 10px 22px rgba(2,8,23,.16);
}

.superadmin-module-widget-icon{
  width:38px;
  height:38px;
  display:grid;
  place-items:center;
  border-radius:12px;
  color:var(--sa-primary,var(--color-primary));
  background:color-mix(in srgb,var(--sa-primary,var(--color-primary)) 14%,var(--sa-surface,var(--color-surface)));
}

.superadmin-module-widget-icon svg{width:20px;height:20px;}
.superadmin-module-widget-copy{min-width:0;display:grid;gap:1px;}
.superadmin-module-widget-copy small{color:var(--sa-muted,var(--color-text-muted));font-size:10px;font-weight:700;}
.superadmin-module-widget-copy strong{font-size:23px;line-height:1;color:var(--sa-text,var(--color-text-primary));}
.superadmin-module-widget-copy em{overflow:hidden;text-overflow:ellipsis;white-space:nowrap;color:var(--sa-muted,var(--color-text-muted));font-size:9px;font-style:normal;}
.superadmin-module-widget > b{color:var(--sa-muted,var(--color-text-muted));font-size:20px;font-weight:500;}
.superadmin-module-widget.danger .superadmin-module-widget-icon{color:#ef4444;background:rgba(239,68,68,.12);}
.superadmin-module-widget.warning .superadmin-module-widget-icon{color:#f59e0b;background:rgba(245,158,11,.12);}
.superadmin-module-widget.success .superadmin-module-widget-icon{color:#16a34a;background:rgba(22,163,74,.12);}

.superadmin-more-links{
  border-top:1px solid var(--sa-border,var(--color-border));
  padding-top:8px;
}

.superadmin-more-links > summary{
  min-height:36px;
  display:flex;
  align-items:center;
  justify-content:space-between;
  gap:8px;
  padding:0 4px;
  color:var(--sa-text,var(--color-text-primary));
  font-size:11px;
  font-weight:800;
  list-style:none;
  cursor:pointer;
}

.superadmin-more-links > summary::-webkit-details-marker{display:none;}
.superadmin-more-links[open] > summary span{transform:rotate(90deg);}

.superadmin-more-links > div{
  display:grid;
  grid-template-columns:repeat(3,minmax(0,1fr));
  gap:6px;
  padding-top:6px;
}

.superadmin-more-links button{
  min-width:0;
  min-height:38px;
  display:flex;
  align-items:center;
  gap:7px;
  padding:7px 9px;
  border:1px solid var(--sa-border,var(--color-border));
  border-radius:10px;
  color:var(--sa-text,var(--color-text-primary));
  background:var(--sa-surface-soft,var(--color-surface-secondary));
}

.superadmin-more-links button span{width:18px;height:18px;display:grid;place-items:center;color:var(--sa-primary,var(--color-primary));}
.superadmin-more-links button svg{width:16px;height:16px;}
.superadmin-more-links button strong{min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;font-size:10px;}

@media(max-width:900px){
  .superadmin-module-widgets{grid-template-columns:repeat(2,minmax(0,1fr));}
}

@media(max-width:540px){
  .superadmin-module-widget-section{padding:9px;}
  .superadmin-module-widget-head .status-badge{display:none;}
  .superadmin-module-widgets{
    width:100%;
    grid-template-columns:repeat(2,minmax(0,1fr));
    gap:7px;
    overflow:visible !important;
    touch-action:auto !important;
  }
  .superadmin-module-widget{
    width:100% !important;
    max-width:none !important;
    min-height:92px;
    grid-template-columns:32px minmax(0,1fr) 12px;
    gap:6px;
    padding:8px;
    scroll-snap-align:none !important;
  }
  .superadmin-module-widget-icon{width:32px;height:32px;border-radius:10px;}
  .superadmin-module-widget-icon svg{width:17px;height:17px;}
  .superadmin-module-widget-copy strong{font-size:20px;}
  .superadmin-more-links > div{grid-template-columns:repeat(2,minmax(0,1fr));}
}

@media(max-width:760px){
  .superadmin-platform-profile-shell .superadmin-profile-screen{
    width:100% !important;
    overflow-x:hidden;
  }

  .superadmin-platform-profile-shell .superadmin-profile-hero{
    grid-template-columns:54px minmax(0,1fr) !important;
  }

  .superadmin-platform-profile-shell .superadmin-profile-hero-actions{
    grid-column:1 / -1;
    width:100%;
    display:grid;
    grid-template-columns:repeat(3,minmax(0,1fr));
  }

  .superadmin-platform-profile-shell .superadmin-profile-hero-actions .btn{
    min-width:0;
    padding-inline:6px;
  }

  .superadmin-platform-profile-shell .superadmin-company-tab-panel{
    grid-template-columns:minmax(0,1fr) !important;
  }

  .superadmin-platform-profile-shell .superadmin-company-tabs{
    width:100%;
    max-width:100%;
    overscroll-behavior-x:contain;
  }

  body.mobile-mode .ui3-orders .smart-order-row,
  body[data-ui-profile="android_apk"] .ui3-orders .smart-order-row,
  body[data-ui-profile="web_pwa"].mobile-mode .ui3-orders .smart-order-row{
    grid-template-columns:minmax(0,1fr) !important;
  }

  .ui3-orders .smart-order-side{
    width:100%;
    justify-items:end;
  }
}

/* Design System V3 - autoridade final de botões nas telas internas. */
body:not(.visitor-public-screen) .ui3-real-screen :where(.btn, .app-button) {
  min-height: var(--s3d-button-height-standard, 44px) !important;
  padding: 0 var(--space-lg, 16px) !important;
  display: inline-flex !important;
  align-items: center;
  justify-content: center;
  gap: var(--space-sm, 8px);
  border-width: 1px !important;
  border-style: solid !important;
  border-radius: var(--radius-md, 10px) !important;
  font-size: var(--type-button, 14px);
  font-weight: 800;
  line-height: 1.15;
  text-decoration: none;
}

body:not(.visitor-public-screen) .ui3-real-screen :where(
  .btn.primary,
  .app-button.primary,
  .app-button[data-ui-variant="primary"],
  .btn:not(.secondary):not(.ghost):not(.danger):not(.warning):not(.outline):not(.icon)
) {
  color: var(--s3d-button-primary-text, var(--color-on-primary)) !important;
  background: var(--s3d-button-primary-bg, var(--color-primary)) !important;
  border-color: var(--s3d-button-primary-border, var(--color-primary)) !important;
  box-shadow: 0 6px 14px color-mix(in srgb, var(--color-primary) 22%, transparent) !important;
}

body:not(.visitor-public-screen) .ui3-real-screen :where(.btn.secondary, .app-button.secondary, .app-button[data-ui-variant="secondary"]) {
  color: var(--s3d-button-secondary-text, var(--color-text-primary, var(--text-primary))) !important;
  background: var(--s3d-button-secondary-bg, color-mix(in srgb, var(--color-primary) 10%, var(--color-surface))) !important;
  border-color: var(--s3d-button-secondary-border, color-mix(in srgb, var(--color-primary) 38%, var(--color-border))) !important;
  box-shadow: none !important;
}

body:not(.visitor-public-screen) .ui3-real-screen :where(.btn.ghost, .app-button.ghost, .app-button[data-ui-variant="ghost"]) {
  color: var(--s3d-button-ghost-text, var(--color-text-secondary, var(--text-secondary))) !important;
  background: var(--s3d-button-ghost-bg, transparent) !important;
  border-color: var(--s3d-button-ghost-border, var(--color-border, var(--border-soft))) !important;
  box-shadow: none !important;
}

body:not(.visitor-public-screen) .ui3-real-screen :where(.btn.danger, .app-button.danger, .app-button[data-ui-variant="danger"]) {
  color: var(--s3d-button-danger-text, var(--color-on-danger)) !important;
  background: var(--s3d-button-danger-bg, var(--color-danger)) !important;
  border-color: var(--s3d-button-danger-border, var(--color-danger)) !important;
}

body:not(.visitor-public-screen) .ui3-real-screen :where(.btn, .app-button):focus-visible {
  outline: 3px solid color-mix(in srgb, var(--color-primary) 28%, transparent);
  outline-offset: 2px;
}

body:not(.visitor-public-screen) .ui3-real-screen :where(.btn, .app-button):disabled {
  opacity: .55;
  cursor: not-allowed;
  box-shadow: none !important;
}

/* Autoridade V3 para menus contextuais, PDF salvo e ações compactas internas. */
body:not(.visitor-public-screen) .ui-context-menu-trigger,
body:not(.visitor-public-screen) .smart-order-more-button {
  width:36px !important;
  min-width:36px !important;
  height:36px !important;
  min-height:36px !important;
  padding:0 !important;
  display:inline-grid !important;
  place-items:center;
  border:1px solid var(--color-border, var(--border-soft)) !important;
  border-radius:var(--radius-md, 10px) !important;
  background:var(--surface-secondary, var(--surface-primary)) !important;
  color:var(--text-secondary, var(--text-primary)) !important;
}

body:not(.visitor-public-screen) :where(.ui-context-menu-trigger,.smart-order-more-button) svg { width:18px; height:18px; }
.pdf-saved-preview-note,.pdf-settings-group { display:grid; gap:var(--space-sm, 8px); }
.pdf-saved-preview-note { margin-bottom:var(--space-md, 12px); }
.pdf-saved-preview-note small,.pdf-model-preview-contact { color:var(--text-muted); }
.pdf-model-preview-contact { display:block; margin:0 0 8px; }
.pdf-settings-group { margin-top:var(--space-lg, 18px); padding-top:var(--space-md, 12px); border-top:1px solid var(--color-border, var(--border-soft)); }

.administration-module-row {
  grid-template-columns:36px minmax(0, 1fr) minmax(0, 76px);
  min-width:0;
  max-width:100%;
  overflow:hidden;
}
.administration-module-row > span:nth-child(2) small { overflow-wrap:anywhere; }
.administration-module-row > .status-badge {
  min-width:0;
  max-width:100%;
  justify-self:stretch;
  overflow:hidden;
  text-align:center;
  text-overflow:ellipsis;
}

.stock-detail-actions { gap:6px; }
.stock-detail-actions .btn {
  min-height:34px !important;
  padding:0 9px !important;
  border-radius:9px !important;
  font-size:11px;
  font-weight:700;
  box-shadow:none !important;
}

@media (max-width:600px) {
  .stock-detail-actions { grid-template-columns:repeat(2, minmax(0, 1fr)); }
  .stock-detail-actions .btn:last-child { grid-column:1 / -1; }
  .administration-subpage,.administration-module-list { min-width:0; max-width:100%; overflow-x:hidden; }
}

/* Fallback legado; a autoridade atual fica em styles/ui-v3/actions.css. */
@supports not (display:grid){
/* Autoridade final mobile: ações comuns compactas; cards e login ficam fora. */
body.mobile-mode button.btn:not(.auth-primary):not(.auth-google-button):not(.icon){
  height:auto !important;
  min-height:31px !important;
  padding:4px 8px !important;
